CREATE OR REPLACE FUNCTION "accounting"."sync_merchant_gct_registered"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'accounting', 'delivery', 'public'
    AS $$
BEGIN
  IF NEW.entity_type = 'merchant' THEN
    UPDATE delivery.merchants
    SET gct_registered = (NEW.registered = true AND NEW.trn IS NOT NULL AND length(trim(NEW.trn)) > 0),
        tax_id = COALESCE(NULLIF(trim(NEW.trn), ''), tax_id)
    WHERE id::text = NEW.entity_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "accounting"."sync_merchant_gct_registered"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."add_merchant_fault_balance"("p_merchant" "uuid", "p_period" "date", "p_amount" numeric) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  INSERT INTO delivery.merchant_performance_snapshots (merchant_id, period_start, chargeback_balance)
  VALUES (p_merchant, p_period, p_amount)
  ON CONFLICT (merchant_id, period_start)
  DO UPDATE SET
    chargeback_balance = delivery.merchant_performance_snapshots.chargeback_balance + EXCLUDED.chargeback_balance,
    updated_at = now();
$$;


ALTER FUNCTION "delivery"."add_merchant_fault_balance"("p_merchant" "uuid", "p_period" "date", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."admin_console_day_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  WITH day_orders AS (
    SELECT
      o.total,
      o.merchant_id,
      o.ready_at,
      o.delivered_at,
      EXTRACT(HOUR FROM (o.placed_at AT TIME ZONE 'America/Jamaica'))::int AS hour
    FROM delivery.orders o
    WHERE o.placed_at >= p_start
      AND o.placed_at < p_end
      AND o.status IS DISTINCT FROM 'cancelled'
  )
  SELECT jsonb_build_object(
    'orders', (SELECT count(*) FROM day_orders),
    'gmv', (SELECT COALESCE(sum(total), 0) FROM day_orders),
    'avg_eta_min', (
      SELECT ROUND(AVG(EXTRACT(EPOCH FROM (delivered_at - ready_at)) / 60.0))::int
      FROM day_orders
      WHERE ready_at IS NOT NULL
        AND delivered_at IS NOT NULL
        AND delivered_at > ready_at
    ),
    'by_hour', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('hour', hour, 'orders', orders) ORDER BY hour), '[]'::jsonb)
      FROM (
        SELECT hour, count(*) AS orders
        FROM day_orders
        GROUP BY hour
      ) hours
    ),
    'by_market', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'name', name,
        'orders', orders,
        'gmv', gmv
      ) ORDER BY orders DESC), '[]'::jsonb)
      FROM (
        SELECT
          COALESCE(m.name, 'Unassigned market') AS name,
          count(*) AS orders,
          COALESCE(sum(d.total), 0) AS gmv
        FROM day_orders d
        LEFT JOIN delivery.merchants mer ON mer.id = d.merchant_id
        LEFT JOIN delivery.service_markets m ON m.id = mer.market_id
        GROUP BY COALESCE(m.name, 'Unassigned market')
        ORDER BY count(*) DESC
        LIMIT 12
      ) markets
    )
  );
$$;


ALTER FUNCTION "delivery"."admin_console_day_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."admin_merchant_order_counts"("p_ids" "uuid"[], "p_since" timestamp with time zone) RETURNS TABLE("merchant_id" "uuid", "orders_7d" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT o.merchant_id, count(*)::bigint
  FROM delivery.orders o
  WHERE o.merchant_id = ANY(p_ids)
    AND o.placed_at >= p_since
    AND o.status IS DISTINCT FROM 'cancelled'
  GROUP BY o.merchant_id;
$$;


ALTER FUNCTION "delivery"."admin_merchant_order_counts"("p_ids" "uuid"[], "p_since" timestamp with time zone) OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "delivery"."courier_remittance_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "courier_id" "uuid" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "balance_before_minor" bigint NOT NULL,
    "balance_after_minor" bigint NOT NULL,
    "order_id" "uuid",
    "order_ref" "text",
    "bag_total_minor" bigint,
    "platform_due_minor" bigint,
    "merchant_due_minor" bigint,
    "courier_retained_minor" bigint,
    "settlement_id" "uuid",
    "reversal_of" "uuid",
    "actor_id" "uuid",
    "actor_type" "text" DEFAULT 'system'::"text" NOT NULL,
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "courier_remittance_events_actor_type_check" CHECK (("actor_type" = ANY (ARRAY['system'::"text", 'admin'::"text", 'courier'::"text", 'ops'::"text", 'migration'::"text"]))),
    CONSTRAINT "courier_remittance_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['collected'::"text", 'settled'::"text", 'adjustment'::"text", 'reversal'::"text", 'write_off'::"text"]))),
    CONSTRAINT "remittance_balance_arithmetic" CHECK (("balance_after_minor" = ("balance_before_minor" + "amount_minor"))),
    CONSTRAINT "remittance_collection_sign" CHECK ((("event_type" <> 'collected'::"text") OR ("amount_minor" >= 0))),
    CONSTRAINT "remittance_settlement_sign" CHECK ((("event_type" <> 'settled'::"text") OR ("amount_minor" <= 0))),
    CONSTRAINT "remittance_trial_balance" CHECK ((("event_type" <> 'collected'::"text") OR ("bag_total_minor" IS NULL) OR ("bag_total_minor" = (("platform_due_minor" + "merchant_due_minor") + "courier_retained_minor")))),
    CONSTRAINT "remittance_write_off_sign" CHECK ((("event_type" <> 'write_off'::"text") OR ("amount_minor" <= 0)))
);


ALTER TABLE "delivery"."courier_remittance_events" OWNER TO "postgres";


COMMENT ON CONSTRAINT "remittance_write_off_sign" ON "delivery"."courier_remittance_events" IS 'W-1: write_off amounts must be <= 0 (forgiveness); positive would invent debt.';



CREATE OR REPLACE FUNCTION "delivery"."apply_remittance_event"("p_courier_id" "uuid", "p_event_type" "text", "p_amount_minor" bigint, "p_idempotency_key" "text", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_bag_total_minor" bigint DEFAULT NULL::bigint, "p_platform_due_minor" bigint DEFAULT NULL::bigint, "p_merchant_due_minor" bigint DEFAULT NULL::bigint, "p_courier_retained_minor" bigint DEFAULT NULL::bigint, "p_settlement_id" "uuid" DEFAULT NULL::"uuid", "p_reversal_of" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_actor_type" "text" DEFAULT 'system'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_pause_threshold_minor" bigint DEFAULT NULL::bigint) RETURNS "delivery"."courier_remittance_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
DECLARE
  v_existing delivery.courier_remittance_events;
  v_before bigint;
  v_after bigint;
  v_row delivery.courier_remittance_events;
  v_threshold bigint;
BEGIN
  SELECT * INTO v_existing
  FROM delivery.courier_remittance_events
  WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN v_existing;
  END IF;

  v_threshold := coalesce(nullif(p_pause_threshold_minor, 0), 1000000);

  INSERT INTO delivery.courier_remittance_accounts (
    courier_id, pause_threshold_minor, threshold_source
  )
  VALUES (p_courier_id, v_threshold, 'seeded')
  ON CONFLICT (courier_id) DO NOTHING;

  SELECT balance_minor INTO v_before
  FROM delivery.courier_remittance_accounts
  WHERE courier_id = p_courier_id
  FOR UPDATE;

  v_after := v_before + p_amount_minor;

  IF v_after < 0 THEN
    RAISE EXCEPTION
      'remittance_overdraw: balance %, requested %', v_before, p_amount_minor
      USING ERRCODE = 'check_violation';
  END IF;

  BEGIN
    INSERT INTO delivery.courier_remittance_events (
      courier_id, idempotency_key, event_type, amount_minor,
      balance_before_minor, balance_after_minor, order_id, order_ref,
      bag_total_minor, platform_due_minor, merchant_due_minor,
      courier_retained_minor, settlement_id, reversal_of,
      actor_id, actor_type, notes, metadata
    ) VALUES (
      p_courier_id, p_idempotency_key, p_event_type, p_amount_minor,
      v_before, v_after, p_order_id, p_order_id::text,
      p_bag_total_minor, p_platform_due_minor, p_merchant_due_minor,
      p_courier_retained_minor, p_settlement_id, p_reversal_of,
      p_actor_id, p_actor_type, p_notes, coalesce(p_metadata, '{}'::jsonb)
    )
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_existing
    FROM delivery.courier_remittance_events
    WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN v_existing;
    END IF;
    IF p_order_id IS NOT NULL AND p_event_type = 'collected' THEN
      SELECT * INTO v_existing
      FROM delivery.courier_remittance_events
      WHERE order_id = p_order_id AND event_type = 'collected'
      LIMIT 1;
      IF FOUND THEN
        RETURN v_existing;
      END IF;
    END IF;
    RAISE;
  END;

  UPDATE delivery.courier_remittance_accounts SET
    balance_minor = v_after,
    lifetime_collected_minor = lifetime_collected_minor + GREATEST(p_amount_minor, 0),
    lifetime_settled_minor = lifetime_settled_minor + GREATEST(-p_amount_minor, 0),
    updated_at = now()
  WHERE courier_id = p_courier_id;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "delivery"."apply_remittance_event"("p_courier_id" "uuid", "p_event_type" "text", "p_amount_minor" bigint, "p_idempotency_key" "text", "p_order_id" "uuid", "p_bag_total_minor" bigint, "p_platform_due_minor" bigint, "p_merchant_due_minor" bigint, "p_courier_retained_minor" bigint, "p_settlement_id" "uuid", "p_reversal_of" "uuid", "p_actor_id" "uuid", "p_actor_type" "text", "p_notes" "text", "p_metadata" "jsonb", "p_pause_threshold_minor" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."coverage_parts_to_geom"("parts" "jsonb") RETURNS "public"."geometry"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  polys geometry[] := ARRAY[]::geometry[];
  part jsonb;
  outer_coords text := '';
  hole_coords text;
  ring jsonb;
  pt jsonb;
  i int;
  h int;
  poly geometry;
  holes geometry[];
BEGIN
  IF parts IS NULL OR jsonb_typeof(parts) <> 'array' OR jsonb_array_length(parts) = 0 THEN
    RETURN NULL;
  END IF;

  FOR i IN 0..jsonb_array_length(parts) - 1 LOOP
    part := parts->i;
    outer_coords := '';
    FOR pt IN SELECT * FROM jsonb_array_elements(COALESCE(part->'outer', '[]'::jsonb))
    LOOP
      IF outer_coords <> '' THEN outer_coords := outer_coords || ','; END IF;
      outer_coords := outer_coords || (pt->>'lng') || ' ' || (pt->>'lat');
    END LOOP;
    IF outer_coords = '' THEN CONTINUE; END IF;
    -- close ring
    pt := (part->'outer')->0;
    outer_coords := outer_coords || ',' || (pt->>'lng') || ' ' || (pt->>'lat');

    holes := ARRAY[]::geometry[];
    h := 0;
    FOR ring IN SELECT * FROM jsonb_array_elements(COALESCE(part->'holes', '[]'::jsonb))
    LOOP
      hole_coords := '';
      FOR pt IN SELECT * FROM jsonb_array_elements(ring)
      LOOP
        IF hole_coords <> '' THEN hole_coords := hole_coords || ','; END IF;
        hole_coords := hole_coords || (pt->>'lng') || ' ' || (pt->>'lat');
      END LOOP;
      IF hole_coords = '' THEN CONTINUE; END IF;
      pt := ring->0;
      hole_coords := hole_coords || ',' || (pt->>'lng') || ' ' || (pt->>'lat');
      holes := array_append(holes, ST_MakePolygon(ST_GeomFromText('LINESTRING(' || hole_coords || ')', 4326)));
      h := h + 1;
    END LOOP;

    IF array_length(holes, 1) IS NULL THEN
      poly := ST_MakePolygon(ST_GeomFromText('LINESTRING(' || outer_coords || ')', 4326));
    ELSE
      poly := ST_MakePolygon(
        ST_GeomFromText('LINESTRING(' || outer_coords || ')', 4326),
        (SELECT array_agg(ST_ExteriorRing(hh)) FROM unnest(holes) hh)
      );
    END IF;
    polys := array_append(polys, poly);
  END LOOP;

  IF array_length(polys, 1) IS NULL THEN RETURN NULL; END IF;
  RETURN ST_Multi(ST_Collect(polys));
END;
$$;


ALTER FUNCTION "delivery"."coverage_parts_to_geom"("parts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."create_inactive_town_from_boundary"("p_parish_id" "uuid", "p_pcode" "text", "p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  parish delivery.service_parishes%ROWTYPE;
  boundary record;
  market delivery.service_markets%ROWTYPE;
  existing_id uuid;
  zone_result jsonb;
BEGIN
  IF p_slug IS NULL OR btrim(p_slug) = '' THEN
    RAISE EXCEPTION 'SLUG_REQUIRED' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO parish FROM delivery.service_parishes WHERE id = p_parish_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PARISH_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO boundary FROM geo.current_boundary(p_pcode, 2);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOUNDARY_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF parish.pcode IS NOT NULL
     AND boundary.parent_pcode IS NOT NULL
     AND boundary.parent_pcode <> parish.pcode THEN
    RAISE EXCEPTION 'PARENT_MISMATCH:% vs %', boundary.parent_pcode, parish.pcode
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO existing_id
  FROM delivery.service_markets
  WHERE pcode = p_pcode
  LIMIT 1;
  IF existing_id IS NOT NULL THEN
    RAISE EXCEPTION 'TOWN_EXISTS:%', existing_id USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (SELECT 1 FROM delivery.service_markets WHERE slug = p_slug) THEN
    RAISE EXCEPTION 'SLUG_EXISTS:%', p_slug USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO delivery.service_markets (
    name, slug, parish_id, is_active, waitlist_enabled,
    pcode, parent_pcode, boundary_source, draft_dirty
  ) VALUES (
    boundary.name,
    p_slug,
    p_parish_id,
    false,
    true,
    p_pcode,
    boundary.parent_pcode,
    boundary.source,
    true
  )
  RETURNING * INTO market;

  zone_result := delivery.promote_boundary_to_market_zone(market.id, p_pcode, boundary.name);

  RETURN jsonb_build_object(
    'market', to_jsonb(market),
    'zone', zone_result
  );
EXCEPTION
  WHEN unique_violation THEN
    IF SQLERRM ILIKE '%pcode%' THEN
      RAISE EXCEPTION 'TOWN_EXISTS' USING ERRCODE = 'P0001';
    END IF;
    RAISE EXCEPTION 'SLUG_EXISTS:%', p_slug USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION "delivery"."create_inactive_town_from_boundary"("p_parish_id" "uuid", "p_pcode" "text", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."current_user_inventory_company_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT m.inventory_company_id FROM delivery.merchants m
  WHERE m.inventory_company_id IS NOT NULL
    AND m.id IN (SELECT delivery.current_user_inventory_merchant_ids())
  UNION
  SELECT g.company_id
  FROM delivery.inventory_nodes n
  JOIN delivery.inventory_groups grp ON grp.id = n.group_id
  JOIN delivery.inventory_regions g ON g.id = grp.region_id
  WHERE n.merchant_id IN (SELECT delivery.current_user_inventory_merchant_ids());
$$;


