CREATE OR REPLACE FUNCTION "delivery"."display_rings_json"("g" "public"."geometry") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  result jsonb := '[]'::jsonb;
  poly geometry;
  ring geometry;
  hole geometry;
  i int;
  coords jsonb;
BEGIN
  IF g IS NULL OR ST_IsEmpty(g) THEN
    RETURN '[]'::jsonb;
  END IF;

  FOR poly IN
    SELECT d.geom FROM ST_Dump(g) AS d
  LOOP
    IF ST_GeometryType(poly) <> 'ST_Polygon' THEN
      CONTINUE;
    END IF;

    ring := ST_ExteriorRing(poly);
    SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY idx)
    INTO coords
    FROM (
      SELECT
        ST_Y(ST_PointN(ring, gs)) AS lat,
        ST_X(ST_PointN(ring, gs)) AS lng,
        gs AS idx
      FROM generate_series(1, GREATEST(ST_NPoints(ring) - 1, 0)) AS gs
    ) q;

    IF coords IS NOT NULL AND jsonb_array_length(coords) >= 3 THEN
      result := result || jsonb_build_array(
        jsonb_build_object('kind', 'include', 'polygon', coords)
      );
    END IF;

    FOR i IN 1..COALESCE(ST_NumInteriorRings(poly), 0) LOOP
      hole := ST_InteriorRingN(poly, i);
      SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY idx)
      INTO coords
      FROM (
        SELECT
          ST_Y(ST_PointN(hole, gs)) AS lat,
          ST_X(ST_PointN(hole, gs)) AS lng,
          gs AS idx
        FROM generate_series(1, GREATEST(ST_NPoints(hole) - 1, 0)) AS gs
      ) q;

      IF coords IS NOT NULL AND jsonb_array_length(coords) >= 3 THEN
        result := result || jsonb_build_array(
          jsonb_build_object('kind', 'exclude', 'polygon', coords)
        );
      END IF;
    END LOOP;
  END LOOP;

  RETURN result;
END;
$$;


ALTER FUNCTION "delivery"."display_rings_json"("g" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."enforce_courier_vehicle_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'rush_config', 'public'
    AS $$
DECLARE
  allowed jsonb;
  vt text;
BEGIN
  vt := NEW.vehicle_type;
  IF vt IS NULL OR btrim(vt) = '' THEN
    RETURN NEW;
  END IF;

  SELECT sv.value INTO allowed
  FROM rush_config.setting_values sv
  WHERE sv.key = 'courier.signup.vehicle_types'
    AND sv.scope = 'platform'
    AND sv.scope_id = '00000000-0000-0000-0000-000000000000';

  IF allowed IS NULL THEN
    allowed := '["bicycle","motorcycle","car"]'::jsonb;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(allowed) AS elem(value)
    WHERE elem.value = vt
  ) THEN
    RAISE EXCEPTION 'vehicle_type % is not in courier.signup.vehicle_types', vt
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "delivery"."enforce_courier_vehicle_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "delivery"."enforce_courier_vehicle_type"() IS 'Rejects vehicle_type not listed in rush_config courier.signup.vehicle_types (default bicycle/motorcycle/car)';



CREATE OR REPLACE FUNCTION "delivery"."generate_order_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
DECLARE
  new_number text;
  year_part text;
  seq_part text;
BEGIN
  year_part := to_char(now(), 'YYYY');
  SELECT LPAD((COALESCE(MAX(SUBSTRING(order_number FROM 9)::integer), 0) + 1)::text, 6, '0')
  INTO seq_part
  FROM delivery.orders
  WHERE order_number LIKE 'RD-' || year_part || '-%';

  new_number := 'RD-' || year_part || '-' || seq_part;
  RETURN new_number;
END;
$$;


