CREATE OR REPLACE FUNCTION "delivery"."geojson_to_multipolygon"("gj" "jsonb") RETURNS "public"."geometry"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  g geometry;
BEGIN
  IF gj IS NULL THEN
    RETURN NULL;
  END IF;
  g := ST_SetSRID(ST_GeomFromGeoJSON(gj::text), 4326);
  IF g IS NULL THEN
    RETURN NULL;
  END IF;
  g := ST_MakeValid(g);
  IF ST_GeometryType(g) = 'ST_Polygon' THEN
    RETURN ST_Multi(g);
  ELSIF ST_GeometryType(g) = 'ST_MultiPolygon' THEN
    RETURN g;
  ELSE
    RETURN ST_Multi(ST_CollectionExtract(g, 3));
  END IF;
END;
$$;


ALTER FUNCTION "delivery"."geojson_to_multipolygon"("gj" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."geom_to_coverage_parts"("g" "public"."geometry") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  parts jsonb := '[]'::jsonb;
  n int;
  i int;
  poly geometry;
  outer_ring jsonb;
  holes jsonb;
  hole_n int;
  h int;
  hole_ring jsonb;
BEGIN
  IF g IS NULL OR ST_IsEmpty(g) THEN
    RETURN '[]'::jsonb;
  END IF;

  IF ST_GeometryType(g) = 'ST_Polygon' THEN
    g := ST_Multi(g);
  ELSIF ST_GeometryType(g) <> 'ST_MultiPolygon' THEN
    g := ST_Multi(ST_CollectionExtract(g, 3));
  END IF;

  n := ST_NumGeometries(g);
  FOR i IN 1..COALESCE(n, 0) LOOP
    poly := ST_GeometryN(g, i);
    outer_ring := delivery.ring_to_latlng_jsonb(ST_ExteriorRing(poly));
    holes := '[]'::jsonb;
    hole_n := ST_NumInteriorRings(poly);
    FOR h IN 1..COALESCE(hole_n, 0) LOOP
      hole_ring := delivery.ring_to_latlng_jsonb(ST_InteriorRingN(poly, h));
      holes := holes || jsonb_build_array(hole_ring);
    END LOOP;
    parts := parts || jsonb_build_array(jsonb_build_object(
      'outer', outer_ring,
      'holes', holes
    ));
  END LOOP;

  RETURN parts;
END;
$$;


ALTER FUNCTION "delivery"."geom_to_coverage_parts"("g" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."inactive_waitlist_at_point"("p_lat" double precision, "p_lng" double precision) RETURNS TABLE("market_id" "uuid", "name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT m.id, m.name
  FROM delivery.service_markets m
  JOIN delivery.service_zone_polygons z ON z.market_id = m.id
  WHERE m.is_active = false
    AND m.waitlist_enabled = true
    AND COALESCE(z.kind, 'include') = 'include'
