CREATE OR REPLACE FUNCTION "delivery"."inventory_append_entry_tx"("p_node_id" "uuid", "p_item_id" "uuid", "p_qty" numeric, "p_uom_id" "uuid", "p_quantity_base" numeric, "p_transaction_type" "text", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_unit_cost_base" numeric DEFAULT NULL::numeric, "p_idempotency_key" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
DECLARE
  new_id uuid;
BEGIN
  INSERT INTO delivery.inventory_ledger (
    node_id, item_id, quantity, uom_id, quantity_base,
    transaction_type, reference_type, reference_id,
    unit_cost_base, idempotency_key, created_by
  ) VALUES (
    p_node_id, p_item_id, p_qty, p_uom_id, p_quantity_base,
    p_transaction_type, p_reference_type, p_reference_id,
    p_unit_cost_base, p_idempotency_key, p_created_by
  )
  RETURNING id INTO new_id;

  RETURN new_id;
END;
$$;


ALTER FUNCTION "delivery"."inventory_append_entry_tx"("p_node_id" "uuid", "p_item_id" "uuid", "p_qty" numeric, "p_uom_id" "uuid", "p_quantity_base" numeric, "p_transaction_type" "text", "p_reference_type" "text", "p_reference_id" "uuid", "p_unit_cost_base" numeric, "p_idempotency_key" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."inventory_variance_report"("p_node_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("item_id" "uuid", "item_name" "text", "starting_qty_base" numeric, "received_qty_base" numeric, "transfer_in_qty_base" numeric, "wasted_qty_base" numeric, "transfer_out_qty_base" numeric, "theoretical_depletion_base" numeric, "theoretical_ending_base" numeric, "actual_count_base" numeric, "variance_qty_base" numeric, "variance_cost" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
  WITH bounds AS (
    SELECT p_node_id AS node_id, p_start AS start_at, p_end AS end_at
  ),
  ledger AS (
    SELECT l.* FROM delivery.inventory_ledger l, bounds b WHERE l.node_id = b.node_id
  ),
  starting AS (
    SELECT item_id, COALESCE(SUM(quantity_base), 0) AS qty
    FROM ledger, bounds b WHERE created_at < b.start_at GROUP BY item_id
  ),
  period AS (
    SELECT item_id,
      SUM(CASE WHEN transaction_type = 'receiving' THEN quantity_base ELSE 0 END) AS received,
      SUM(CASE WHEN transaction_type = 'transfer_in' THEN quantity_base ELSE 0 END) AS xfer_in,
      SUM(CASE WHEN transaction_type = 'waste' THEN ABS(quantity_base) ELSE 0 END) AS wasted,
      SUM(CASE WHEN transaction_type = 'transfer_out' THEN ABS(quantity_base) ELSE 0 END) AS xfer_out,
      SUM(CASE WHEN transaction_type = 'pos_depletion' THEN ABS(quantity_base) ELSE 0 END) AS theoretical_dep
    FROM ledger, bounds b
    WHERE created_at >= b.start_at AND created_at < b.end_at
    GROUP BY item_id
  ),
  latest_count AS (
    SELECT DISTINCT ON (pci.item_id)
      pci.item_id, pci.counted_base
    FROM delivery.physical_count_items pci
    JOIN delivery.physical_counts pc ON pc.id = pci.count_id
    JOIN bounds b ON pc.node_id = b.node_id
    WHERE pc.status = 'posted' AND pc.posted_at <= b.end_at
    ORDER BY pci.item_id, pc.posted_at DESC
  )
  SELECT
    im.id,
    im.name,
    COALESCE(s.qty, 0),
    COALESCE(p.received, 0),
    COALESCE(p.xfer_in, 0),
    COALESCE(p.wasted, 0),
    COALESCE(p.xfer_out, 0),
    COALESCE(p.theoretical_dep, 0),
    COALESCE(s.qty, 0) + COALESCE(p.received, 0) + COALESCE(p.xfer_in, 0)
      - COALESCE(p.wasted, 0) - COALESCE(p.xfer_out, 0) - COALESCE(p.theoretical_dep, 0),
    lc.counted_base,
    lc.counted_base - (
      COALESCE(s.qty, 0) + COALESCE(p.received, 0) + COALESCE(p.xfer_in, 0)
      - COALESCE(p.wasted, 0) - COALESCE(p.xfer_out, 0) - COALESCE(p.theoretical_dep, 0)
    ),
    0::numeric
  FROM delivery.item_master im
  JOIN delivery.inventory_nodes nd ON nd.id = p_node_id
  JOIN delivery.inventory_groups g ON g.id = nd.group_id
  JOIN delivery.inventory_regions r ON r.id = g.region_id
  LEFT JOIN starting s ON s.item_id = im.id
  LEFT JOIN period p ON p.item_id = im.id
  LEFT JOIN latest_count lc ON lc.item_id = im.id
  WHERE im.company_id = r.company_id;
$$;


ALTER FUNCTION "delivery"."inventory_variance_report"("p_node_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


