CREATE OR REPLACE FUNCTION "delivery"."legacy_jsonb_zone_drift"() RETURNS TABLE("pcode" "text", "name" "text", "drift" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  WITH live AS (
    SELECT DISTINCT ON (m.pcode) m.pcode, m.name
    FROM delivery.service_zone_polygons z
    JOIN delivery.service_markets m ON m.id = z.market_id
    WHERE m.pcode IS NOT NULL
      AND COALESCE(z.kind, 'include') = 'include'
      AND z.geom IS NOT NULL
      AND ST_NumGeometries(z.geom) > 1
      AND jsonb_typeof(z.polygon) = 'array'
      AND jsonb_array_length(z.polygon) < ST_NPoints(z.geom) - 1
    ORDER BY m.pcode, ST_Area(z.geom::geography) DESC
  )
  SELECT
    COALESCE(l.pcode, i.pcode) AS pcode,
    COALESCE(l.name, i.name) AS name,
    CASE WHEN l.pcode IS NULL THEN 'missing' ELSE 'unexpected' END AS drift
  FROM live l
  FULL OUTER JOIN delivery.legacy_jsonb_zone_inventory i ON i.pcode = l.pcode
  WHERE l.pcode IS NULL OR i.pcode IS NULL;
$$;


ALTER FUNCTION "delivery"."legacy_jsonb_zone_drift"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."market_launch_facts"("p_market_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
DECLARE
  zone delivery.service_zone_polygons%ROWTYPE;
  area_sqkm numeric;
  parts int;
  n int;
  lat float8;
  lng float8;
  full_covers boolean;
  short_covers boolean;
  failed boolean := false;
  tested int := 0;
  detail text;
BEGIN
  SELECT z.* INTO zone
  FROM delivery.service_zone_polygons z
  WHERE z.market_id = p_market_id
    AND COALESCE(z.kind, 'include') = 'include'
    AND z.geom IS NOT NULL
  ORDER BY ST_Area(z.geom::geography) DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'border_area_sqkm', NULL,
      'split_border', false,
      'split_border_ok', true,
      'split_border_detail', NULL
    );
  END IF;

  area_sqkm := round((ST_Area(zone.geom::geography) / 1000000)::numeric, 1);
  parts := ST_NumGeometries(zone.geom);

  IF parts <= 1
     OR zone.polygon IS NULL
     OR jsonb_typeof(zone.polygon) <> 'array'
     OR jsonb_array_length(zone.polygon) >= ST_NPoints(zone.geom) - 1 THEN
    RETURN jsonb_build_object(
      'border_area_sqkm', area_sqkm,
      'split_border', false,
      'split_border_ok', true,
      'split_border_detail', NULL
    );
  END IF;

  FOR n IN 2..parts LOOP
    tested := tested + 1;
    lat := ST_Y(ST_PointOnSurface(ST_GeometryN(zone.geom, n)));
    lng := ST_X(ST_PointOnSurface(ST_GeometryN(zone.geom, n)));
    full_covers := ST_Covers(zone.geom, ST_SetSRID(ST_MakePoint(lng, lat), 4326));
    short_covers := ST_Covers(
      delivery.jsonb_ring_to_multipolygon(zone.polygon),
      ST_SetSRID(ST_MakePoint(lng, lat), 4326)
    );
    IF full_covers IS DISTINCT FROM true OR short_covers IS DISTINCT FROM false THEN
      failed := true;
    END IF;
  END LOOP;

  IF failed THEN
    detail := 'Coverage is still using the short border. This town stays off until every extra piece is inside the full border and outside the short ring.';
  ELSE
    detail := format('Checked %s extra piece(s). Customers use the full border.', tested);
  END IF;

  RETURN jsonb_build_object(
    'border_area_sqkm', area_sqkm,
    'split_border', true,
    'split_border_ok', NOT failed,
    'split_border_detail', detail
  );
END;
$$;


ALTER FUNCTION "delivery"."market_launch_facts"("p_market_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."menu_library_merge_cuisine"("p_from" "text", "p_into" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
DECLARE
  from_row delivery.cuisines%ROWTYPE;
  into_label text;
BEGIN
  IF p_from = p_into THEN RAISE EXCEPTION 'same_cuisine'; END IF;
  SELECT * INTO from_row FROM delivery.cuisines WHERE id = p_from FOR UPDATE;
  SELECT label INTO into_label FROM delivery.cuisines WHERE id = p_into FOR UPDATE;
  IF from_row.id IS NULL OR into_label IS NULL THEN RAISE EXCEPTION 'cuisine_not_found'; END IF;

  -- Replace then de-duplicate, keeping first-seen order (the first cuisine is the primary).
  UPDATE delivery.merchants m
  SET cuisines = ARRAY(
    SELECT x FROM unnest(array_replace(m.cuisines, from_row.label, into_label)) WITH ORDINALITY t(x, o)
    GROUP BY x ORDER BY min(o)
  )
  WHERE from_row.label = ANY (m.cuisines);

  UPDATE delivery.merchants m
  SET cuisine_types = ARRAY(
    SELECT x FROM unnest(array_replace(m.cuisine_types, from_row.label, into_label)) WITH ORDINALITY t(x, o)
    GROUP BY x ORDER BY min(o)
  )
  WHERE from_row.label = ANY (m.cuisine_types);

  UPDATE delivery.merchants SET cuisine_type = into_label WHERE cuisine_type = from_row.label;

  UPDATE delivery.menu_kits k
  SET cuisine_ids = ARRAY(
    SELECT x FROM unnest(array_replace(k.cuisine_ids, p_from, p_into)) WITH ORDINALITY t(x, o)
    GROUP BY x ORDER BY min(o)
  ), updated_at = now()
  WHERE p_from = ANY (k.cuisine_ids);

  UPDATE delivery.menu_product_templates t
  SET cuisine_ids = ARRAY(
    SELECT x FROM unnest(array_replace(t.cuisine_ids, p_from, p_into)) WITH ORDINALITY u(x, o)
    GROUP BY x ORDER BY min(o)
  ), updated_at = now()
  WHERE p_from = ANY (t.cuisine_ids);

  -- Old spellings keep matching search and kits.
  UPDATE delivery.cuisines
  SET aliases = ARRAY(
    SELECT DISTINCT a FROM unnest(aliases || from_row.label || from_row.aliases) a
    WHERE lower(a) <> lower(into_label)
  ), updated_at = now()
  WHERE id = p_into;

  DELETE FROM delivery.cuisines WHERE id = p_from;
END;
$$;


ALTER FUNCTION "delivery"."menu_library_merge_cuisine"("p_from" "text", "p_into" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."menu_library_rename_cuisine"("p_id" "text", "p_label" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
DECLARE
  old_label text;
  new_label text := btrim(p_label);
BEGIN
  SELECT label INTO old_label FROM delivery.cuisines WHERE id = p_id FOR UPDATE;
  IF old_label IS NULL THEN RAISE EXCEPTION 'cuisine_not_found'; END IF;
  IF new_label = '' THEN RAISE EXCEPTION 'label_required'; END IF;
  IF old_label = new_label THEN RETURN; END IF;

  UPDATE delivery.cuisines
  SET label = new_label,
      aliases = CASE WHEN old_label = ANY (aliases) THEN aliases ELSE aliases || old_label END,
      updated_at = now()
  WHERE id = p_id;

  UPDATE delivery.merchants SET cuisines = array_replace(cuisines, old_label, new_label)
  WHERE old_label = ANY (cuisines);
  UPDATE delivery.merchants SET cuisine_types = array_replace(cuisine_types, old_label, new_label)
  WHERE old_label = ANY (cuisine_types);
  UPDATE delivery.merchants SET cuisine_type = new_label WHERE cuisine_type = old_label;
END;
$$;


ALTER FUNCTION "delivery"."menu_library_rename_cuisine"("p_id" "text", "p_label" "text") OWNER TO "postgres";


