CREATE OR REPLACE FUNCTION "delivery"."parish_foundation_parts"("p_parish_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT COALESCE(delivery.geom_to_coverage_parts(COALESCE(adopted_geom, foundation_geom)), '[]'::jsonb)
  FROM delivery.service_parishes WHERE id = p_parish_id;
$$;


ALTER FUNCTION "delivery"."parish_foundation_parts"("p_parish_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."point_covers_geom"("lat" double precision, "lng" double precision, "g" "public"."geometry") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT g IS NOT NULL
    AND ST_Covers(g, ST_SetSRID(ST_MakePoint(lng, lat), 4326));
$$;


ALTER FUNCTION "delivery"."point_covers_geom"("lat" double precision, "lng" double precision, "g" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."point_in_parish_foundation"("p_parish_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT CASE
    WHEN adopted_geom IS NOT NULL THEN ST_Covers(adopted_geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
    WHEN foundation_geom IS NOT NULL THEN ST_Covers(foundation_geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
    WHEN foundation_polygon IS NOT NULL THEN ST_Covers(delivery.jsonb_ring_to_multipolygon(foundation_polygon), ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
    ELSE true
  END
  FROM delivery.service_parishes WHERE id = p_parish_id;
$$;


ALTER FUNCTION "delivery"."point_in_parish_foundation"("p_parish_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."point_in_zone_geom"("p_zone_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  SELECT CASE
    WHEN geom IS NOT NULL THEN
      ST_Covers(geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
    ELSE
      ST_Covers(
        delivery.jsonb_ring_to_multipolygon(polygon),
        ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)
      )
  END
  FROM delivery.service_zone_polygons
  WHERE id = p_zone_id;
$$;


ALTER FUNCTION "delivery"."point_in_zone_geom"("p_zone_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."promote_boundary_to_market_zone"("p_market_id" "uuid", "p_pcode" "text", "p_zone_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  b record;
  ring jsonb;
  zone_id uuid;
  include_id uuid;
  exclude_ids uuid[] := ARRAY[]::uuid[];
  hole_geom geometry;
  hole_ring jsonb;
  i int;
  poly geometry;
  hole_n int;
  existing_count integer;
  next_ver integer;
  zones_snap jsonb;
BEGIN
  SELECT * INTO b FROM geo.current_boundary(p_pcode, 2);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'admin2 boundary % not found', p_pcode;
  END IF;

  -- Snapshot current zones into coverage versions before overwrite (OPEN-3)
  SELECT COUNT(*) INTO existing_count
  FROM delivery.service_zone_polygons
  WHERE market_id = p_market_id;

  IF existing_count > 0 THEN
    SELECT COALESCE(MAX(version), 0) + 1 INTO next_ver
    FROM delivery.service_coverage_versions
    WHERE market_id = p_market_id;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', z.id,
        'name', z.name,
        'kind', z.kind,
        'polygon', z.polygon,
        'source', z.source,
        'priority', z.priority,
        'boundary_pcode', z.boundary_pcode,
        'center_lat', z.center_lat,
        'center_lng', z.center_lng,
        'radius_m', z.radius_m
      ) ORDER BY z.priority DESC NULLS LAST, z.name
    ), '[]'::jsonb)
    INTO zones_snap
    FROM delivery.service_zone_polygons z
    WHERE z.market_id = p_market_id;

    INSERT INTO delivery.service_coverage_versions (
      market_id, version, label, notes, zones_json
    ) VALUES (
      p_market_id,
      next_ver,
      'Pre-promote snapshot',
      'Auto snapshot inside promote_boundary_to_market_zone for pcode ' || p_pcode,
      zones_snap
    );
  END IF;

  ring := (
    SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY idx)
    FROM (
      SELECT
        ST_Y(ST_PointN(r.ring, gs)) AS lat,
        ST_X(ST_PointN(r.ring, gs)) AS lng,
        gs AS idx
      FROM (
        SELECT ST_ExteriorRing(ST_GeometryN(b.geom, 1)) AS ring
      ) r
      CROSS JOIN generate_series(1, GREATEST(ST_NPoints(r.ring) - 1, 0)) AS gs
    ) s
  );

  SELECT id INTO zone_id
  FROM delivery.service_zone_polygons
  WHERE market_id = p_market_id
    AND boundary_pcode = p_pcode
    AND kind = 'include'
  LIMIT 1;

  IF zone_id IS NULL THEN
    INSERT INTO delivery.service_zone_polygons (
      market_id, name, polygon, geom, kind, source, priority, boundary_pcode, updated_at
    ) VALUES (
      p_market_id,
      COALESCE(p_zone_name, b.name),
      COALESCE(ring, '[]'::jsonb),
      b.geom,
      'include',
      'import',
      0,
      p_pcode,
      now()
    )
    RETURNING id INTO zone_id;
  ELSE
    UPDATE delivery.service_zone_polygons
    SET
      name = COALESCE(p_zone_name, b.name),
      polygon = COALESCE(ring, polygon),
      geom = b.geom,
      source = 'import',
      boundary_pcode = p_pcode,
      updated_at = now()
    WHERE id = zone_id;
  END IF;
  include_id := zone_id;

  -- Remove prior hole excludes for this pcode before re-materialising
  DELETE FROM delivery.service_zone_polygons
  WHERE market_id = p_market_id
    AND kind = 'exclude'
    AND boundary_pcode LIKE p_pcode || '-hole-%';

  poly := ST_GeometryN(b.geom, 1);
  hole_n := ST_NumInteriorRings(poly);
  FOR i IN 1..COALESCE(hole_n, 0) LOOP
    hole_geom := ST_MakePolygon(ST_InteriorRingN(poly, i));
    hole_ring := (
      SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY idx)
      FROM (
        SELECT
          ST_Y(ST_PointN(ST_ExteriorRing(hole_geom), gs)) AS lat,
          ST_X(ST_PointN(ST_ExteriorRing(hole_geom), gs)) AS lng,
          gs AS idx
        FROM generate_series(1, GREATEST(ST_NPoints(ST_ExteriorRing(hole_geom)) - 1, 0)) AS gs
      ) s
    );
    INSERT INTO delivery.service_zone_polygons (
      market_id, name, polygon, geom, kind, source, priority, boundary_pcode, updated_at
    ) VALUES (
      p_market_id,
      COALESCE(p_zone_name, b.name) || ' hole ' || i,
      COALESCE(hole_ring, '[]'::jsonb),
      ST_Multi(hole_geom),
      'exclude',
      'import',
      10 + i,
      p_pcode || '-hole-' || i,
      now()
    )
    RETURNING id INTO zone_id;
    exclude_ids := array_append(exclude_ids, zone_id);
  END LOOP;

  UPDATE delivery.service_markets
  SET
    pcode = p_pcode,
    parent_pcode = b.parent_pcode,
    boundary_source = b.source,
    draft_dirty = true
  WHERE id = p_market_id;

  RETURN jsonb_build_object(
    'zone_id', include_id,
    'exclude_ids', to_jsonb(exclude_ids),
    'snapshot_version', next_ver
  );
END;
$$;


ALTER FUNCTION "delivery"."promote_boundary_to_market_zone"("p_market_id" "uuid", "p_pcode" "text", "p_zone_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."promote_boundary_to_parish"("p_parish_id" "uuid", "p_pcode" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  b record;
  parish delivery.service_parishes%ROWTYPE;
  ring jsonb;
  next_ver integer;
BEGIN
  SELECT * INTO b FROM geo.current_boundary(p_pcode, 1);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'admin1 boundary % not found', p_pcode;
  END IF;

  SELECT * INTO parish
  FROM delivery.service_parishes
  WHERE id = p_parish_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'parish % not found', p_parish_id;
  END IF;

  -- Snapshot existing foundation before destructive overwrite (OPEN-3)
  IF parish.foundation_polygon IS NOT NULL
     OR parish.foundation_geom IS NOT NULL THEN
    SELECT COALESCE(MAX(version), 0) + 1 INTO next_ver
    FROM delivery.parish_outline_versions
    WHERE parish_id = p_parish_id;

    INSERT INTO delivery.parish_outline_versions (
      parish_id, version, label, notes,
      foundation_polygon, foundation_geom,
      foundation_boundary_pcode, boundary_source
    ) VALUES (
      p_parish_id,
      next_ver,
      'Pre-promote snapshot',
      'Auto snapshot inside promote_boundary_to_parish',
      parish.foundation_polygon,
      parish.foundation_geom,
      parish.foundation_boundary_pcode,
      parish.boundary_source
    );
  END IF;

  ring := (
    SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY i)
    FROM (
      SELECT
        ST_Y(ST_PointN(r.ring, gs)) AS lat,
        ST_X(ST_PointN(r.ring, gs)) AS lng,
        gs AS i
      FROM (
        SELECT ST_ExteriorRing(ST_GeometryN(b.geom, 1)) AS ring
      ) r
      CROSS JOIN generate_series(1, GREATEST(ST_NPoints(r.ring) - 1, 0)) AS gs
    ) s
  );

  UPDATE delivery.service_parishes
  SET
    foundation_geom = b.geom,
    foundation_polygon = COALESCE(ring, foundation_polygon),
    foundation_boundary_pcode = b.pcode,
    pcode = b.pcode,
    parent_pcode = b.parent_pcode,
    admin_level = 1,
    boundary_source = b.source,
    boundary_source_version = b.source_version,
    boundary_valid_on = b.valid_on,
    center_lat = b.center_lat,
    center_lng = b.center_lng,
    foundation_updated_at = now()
  WHERE id = p_parish_id;
END;
$$;


ALTER FUNCTION "delivery"."promote_boundary_to_parish"("p_parish_id" "uuid", "p_pcode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."receive_purchase_order_tx"("p_po_id" "uuid", "p_received_by" "uuid", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
DECLARE
  po_rec RECORD;
  line jsonb;
  po_line RECORD;
  qty_received numeric;
  uom_id uuid;
  qty_base numeric;
  recv_id uuid;
  short_qty numeric;
  damage_qty numeric;
  variance_uom uuid;
BEGIN
  SELECT po.*, n.id AS node_id
  INTO po_rec
  FROM delivery.purchase_orders po
  JOIN delivery.inventory_nodes n ON n.id = po.node_id
  WHERE po.id = p_po_id
  FOR UPDATE;

  IF NOT FOUND OR po_rec.status IN ('cancelled', 'closed') THEN
    RAISE EXCEPTION 'Invalid or closed purchase order';
  END IF;

  INSERT INTO delivery.receiving_events (po_id, received_by)
  VALUES (p_po_id, p_received_by)
  RETURNING id INTO recv_id;

  FOR line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    SELECT pol.*, im.base_uom_id
    INTO po_line
    FROM delivery.purchase_order_lines pol
    JOIN delivery.item_master im ON im.id = pol.item_id
    WHERE pol.id = (line->>'poLineId')::uuid
      AND pol.po_id = p_po_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PO line not found';
    END IF;

    qty_received := (line->>'qtyReceived')::numeric;
    uom_id := COALESCE((line->>'uomId')::uuid, po_line.uom_id);

    SELECT CASE
      WHEN uc.from_uom_id = uom_id AND uc.to_uom_id = po_line.base_uom_id THEN qty_received * uc.factor
      WHEN uc.from_uom_id = po_line.base_uom_id AND uc.to_uom_id = uom_id THEN qty_received / uc.factor
      WHEN uom_id = po_line.base_uom_id THEN qty_received
      ELSE qty_received
    END INTO qty_base
    FROM delivery.uom_conversions uc
    WHERE uc.item_id = po_line.item_id
      AND (
        (uc.from_uom_id = uom_id AND uc.to_uom_id = po_line.base_uom_id)
        OR (uc.from_uom_id = po_line.base_uom_id AND uc.to_uom_id = uom_id)
      )
    LIMIT 1;

    IF qty_base IS NULL THEN
      IF uom_id = po_line.uom_id AND po_line.uom_id = po_line.base_uom_id THEN
        qty_base := qty_received;
      ELSIF uom_id = po_line.uom_id THEN
        qty_base := qty_received;
      ELSE
        qty_base := qty_received;
      END IF;
    END IF;

    IF qty_received > 0 THEN
      PERFORM delivery.inventory_append_entry_tx(
        po_rec.node_id,
        po_line.item_id,
        qty_received,
        uom_id,
        qty_base,
        'receiving',
        'receiving',
        recv_id,
        po_line.unit_price / NULLIF(qty_base / NULLIF(qty_received, 0), 0),
        'recv:' || recv_id::text || ':' || po_line.id::text,
        p_received_by
      );

      INSERT INTO delivery.inventory_cost_layers (
        node_id, item_id, ledger_id, qty_remaining_base, unit_cost_base
      )
      SELECT po_rec.node_id, po_line.item_id, le.id, qty_base,
        po_line.unit_price / NULLIF(qty_received, 0)
      FROM delivery.inventory_ledger le
      WHERE le.idempotency_key = 'recv:' || recv_id::text || ':' || po_line.id::text
      LIMIT 1;

      INSERT INTO delivery.vendor_price_history (catalog_id, unit_price, source)
      SELECT po_line.catalog_id, po_line.unit_price, 'receiving'
      WHERE po_line.catalog_id IS NOT NULL;
    END IF;

    short_qty := COALESCE((line->>'shortQty')::numeric, 0);
    damage_qty := COALESCE((line->>'damagedQty')::numeric, 0);
    variance_uom := uom_id;

    IF short_qty > 0 THEN
      INSERT INTO delivery.receiving_variances (receiving_id, po_line_id, variance_type, qty, uom_id)
      VALUES (recv_id, po_line.id, 'short', short_qty, variance_uom);
    END IF;

    IF damage_qty > 0 THEN
      INSERT INTO delivery.receiving_variances (receiving_id, po_line_id, variance_type, qty, uom_id)
      VALUES (recv_id, po_line.id, 'damage', damage_qty, variance_uom);
    END IF;
  END LOOP;

  UPDATE delivery.purchase_orders SET status = 'closed' WHERE id = p_po_id;

  RETURN recv_id;
END;
$$;


ALTER FUNCTION "delivery"."receive_purchase_order_tx"("p_po_id" "uuid", "p_received_by" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."reconcile_market_pcodes"("p_promote_inactive" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  m record;
  parish_pcode text;
  matches text[];
  chosen text;
  matched int := 0;
  ambiguous int := 0;
  unmatched int := 0;
  skipped_active int := 0;
  report jsonb := '[]'::jsonb;
  promote_result jsonb;
BEGIN
  FOR m IN
    SELECT mk.id, mk.name, mk.is_active, mk.pcode AS existing_pcode, mk.parish_id, p.pcode AS parish_pcode
    FROM delivery.service_markets mk
    JOIN delivery.service_parishes p ON p.id = mk.parish_id
    WHERE p.pcode IS NOT NULL
  LOOP
    parish_pcode := m.parish_pcode;

    SELECT array_agg(b.pcode ORDER BY b.name)
    INTO matches
    FROM geo.boundaries b
    WHERE b.admin_level = 2
      AND b.parent_pcode = parish_pcode
      AND delivery.normalize_place_name(b.name) = delivery.normalize_place_name(m.name);

    IF matches IS NULL OR array_length(matches, 1) IS NULL THEN
      unmatched := unmatched + 1;
      report := report || jsonb_build_array(jsonb_build_object(
        'market_id', m.id, 'name', m.name, 'status', 'unmatched'
      ));
      CONTINUE;
    END IF;

    IF array_length(matches, 1) > 1 THEN
      ambiguous := ambiguous + 1;
      report := report || jsonb_build_array(jsonb_build_object(
        'market_id', m.id, 'name', m.name, 'status', 'ambiguous', 'candidates', to_jsonb(matches)
      ));
      CONTINUE;
    END IF;

    chosen := matches[1];
    matched := matched + 1;

    UPDATE delivery.service_markets
    SET
      pcode = chosen,
      parent_pcode = parish_pcode,
      boundary_source = 'cod-ab'
    WHERE id = m.id;

    IF m.is_active IS TRUE THEN
      skipped_active := skipped_active + 1;
      report := report || jsonb_build_array(jsonb_build_object(
        'market_id', m.id, 'name', m.name, 'status', 'matched_metadata_only', 'pcode', chosen
      ));
    ELSIF p_promote_inactive THEN
      SELECT delivery.promote_boundary_to_market_zone(m.id, chosen, m.name) INTO promote_result;
      report := report || jsonb_build_array(jsonb_build_object(
        'market_id', m.id, 'name', m.name, 'status', 'matched_promoted', 'pcode', chosen, 'promote', promote_result
      ));
    ELSE
      report := report || jsonb_build_array(jsonb_build_object(
        'market_id', m.id, 'name', m.name, 'status', 'matched_metadata_only', 'pcode', chosen
      ));
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'matched', matched,
    'ambiguous', ambiguous,
    'unmatched', unmatched,
    'skipped_active_promote', skipped_active,
    'details', report
  );
END;
$$;


ALTER FUNCTION "delivery"."reconcile_market_pcodes"("p_promote_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."refresh_inventory_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'delivery', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO delivery.inventory_balances (node_id, item_id, quantity_base, updated_at)
  VALUES (NEW.node_id, NEW.item_id, NEW.quantity_base, now())
  ON CONFLICT (node_id, item_id) DO UPDATE
    SET quantity_base = delivery.inventory_balances.quantity_base + EXCLUDED.quantity_base,
        updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "delivery"."refresh_inventory_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."refresh_market_net_coverage"("p_market_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
DECLARE
  v_parish_id uuid;
  v_include_geom geometry;
  v_exclude_geom geometry;
  v_net geometry;
  v_sqkm numeric;
  v_stats jsonb;
  v_has_service boolean;
BEGIN
  SELECT parish_id INTO v_parish_id
  FROM delivery.service_markets WHERE id = p_market_id;

  SELECT EXISTS (
    SELECT 1 FROM delivery.service_zone_polygons
    WHERE market_id = p_market_id
      AND kind = 'include'
      AND is_active
      AND COALESCE(source, 'manual') IN ('manual', 'radius', 'auto_outline')
      AND geom IS NOT NULL
  ) INTO v_has_service;

  IF v_has_service THEN
    SELECT ST_Union(geom) INTO v_include_geom
    FROM delivery.service_zone_polygons
    WHERE market_id = p_market_id
      AND kind = 'include'
      AND is_active
      AND COALESCE(source, 'manual') IN ('manual', 'radius', 'auto_outline')
      AND geom IS NOT NULL;
  ELSE
    SELECT ST_Union(geom) INTO v_include_geom
    FROM delivery.service_zone_polygons
    WHERE market_id = p_market_id
      AND kind = 'include'
      AND is_active
      AND geom IS NOT NULL;
  END IF;

  SELECT ST_Union(u.geom) INTO v_exclude_geom
  FROM (
    SELECT geom FROM delivery.service_zone_polygons
    WHERE market_id = p_market_id AND kind = 'exclude' AND is_active AND geom IS NOT NULL
    UNION ALL
    SELECT geom FROM delivery.scoped_exclusion_zones
    WHERE is_active AND geom IS NOT NULL
      AND (
        scope = 'global'
        OR (scope = 'parish' AND parish_id = v_parish_id)
        OR (scope = 'market' AND market_id = p_market_id)
      )
  ) u;

  IF v_include_geom IS NULL THEN
    UPDATE delivery.service_markets
    SET net_coverage_geom = NULL, net_coverage_stats = NULL
    WHERE id = p_market_id;
    RETURN NULL;
  END IF;

  v_net := ST_Multi(
    ST_CollectionExtract(
      ST_MakeValid(
        ST_Difference(
          v_include_geom,
          COALESCE(v_exclude_geom, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326))
        )
      ),
      3
    )
  );

  IF v_net IS NULL OR ST_IsEmpty(v_net) THEN
    UPDATE delivery.service_markets
    SET net_coverage_geom = NULL,
        net_coverage_stats = jsonb_build_object(
          'net_sqkm', 0,
          'service_areas_mode', v_has_service,
          'refreshed_at', now()
        )
    WHERE id = p_market_id;
    RETURN jsonb_build_object(
      'net_sqkm', 0,
      'service_areas_mode', v_has_service,
      'refreshed_at', now()
    );
  END IF;

  v_sqkm := round((ST_Area(v_net::geography) / 1000000)::numeric, 4);

  v_stats := jsonb_build_object(
    'net_sqkm', v_sqkm,
    'service_areas_mode', v_has_service,
    'refreshed_at', now()
  );

  UPDATE delivery.service_markets
  SET net_coverage_geom = v_net, net_coverage_stats = v_stats
  WHERE id = p_market_id;

  RETURN v_stats;
END;
$$;


ALTER FUNCTION "delivery"."refresh_market_net_coverage"("p_market_id" "uuid") OWNER TO "postgres";


