CREATE OR REPLACE FUNCTION "delivery"."remittance_stamp_paused_since"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.balance_minor >= NEW.pause_threshold_minor THEN
    NEW.paused_since := coalesce(NEW.paused_since, now());
  ELSE
    NEW.paused_since := NULL;
  END IF;
  RETURN NEW;
END;
$$;


