CREATE OR REPLACE FUNCTION "delivery"."resolve_containing_zones"("p_lat" double precision, "p_lng" double precision, "p_market_id" "uuid" DEFAULT NULL::"uuid", "p_parish_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("zone_id" "uuid", "zone_name" "text", "zone_kind" "text", "zone_priority" integer, "zone_source" "text", "market_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
  WITH pt AS (
    SELECT ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326) AS g
  ),
  market_zones AS (
    SELECT
      z.id AS zone_id,
      z.name AS zone_name,
      z.kind AS zone_kind,
      z.priority AS zone_priority,
      'market'::text AS zone_source,
      z.market_id
    FROM delivery.service_zone_polygons z, pt
    WHERE z.is_active
      AND z.geom IS NOT NULL
      AND ST_Covers(z.geom, pt.g)
      AND (p_market_id IS NULL OR z.market_id = p_market_id)
  ),
  scoped AS (
    SELECT
      s.id AS zone_id,
      s.name AS zone_name,
      'exclude'::text AS zone_kind,
      s.priority AS zone_priority,
      'scoped'::text AS zone_source,
      s.market_id
    FROM delivery.scoped_exclusion_zones s, pt
    WHERE s.is_active
      AND s.geom IS NOT NULL
      AND ST_Covers(s.geom, pt.g)
      AND (
        s.scope = 'global'
        OR (s.scope = 'parish' AND p_parish_id IS NOT NULL AND s.parish_id = p_parish_id)
        OR (s.scope = 'market' AND p_market_id IS NOT NULL AND s.market_id = p_market_id)
      )
  ),
  combined AS (
    SELECT * FROM market_zones
    UNION ALL
    SELECT * FROM scoped
  )
  SELECT
    zone_id,
    zone_name,
    zone_kind,
    zone_priority,
    zone_source,
    market_id
  FROM combined
  ORDER BY
    zone_priority DESC,
    CASE WHEN zone_kind = 'exclude' THEN 0 ELSE 1 END,
    zone_id ASC;
$$;


ALTER FUNCTION "delivery"."resolve_containing_zones"("p_lat" double precision, "p_lng" double precision, "p_market_id" "uuid", "p_parish_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."ring_jsonb_to_geom"("ring" "jsonb") RETURNS "public"."geometry"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  pts text := '';
  el jsonb;
  lat double precision;
  lng double precision;
  n int := 0;
  first_lng double precision;
  first_lat double precision;
  last_lng double precision;
  last_lat double precision;
BEGIN
  IF ring IS NULL OR jsonb_typeof(ring) <> 'array' OR jsonb_array_length(ring) < 3 THEN
    RETURN NULL;
  END IF;
  FOR el IN SELECT * FROM jsonb_array_elements(ring)
  LOOP
    lat := (el->>'lat')::double precision;
    lng := (el->>'lng')::double precision;
    IF lat IS NULL OR lng IS NULL THEN
      CONTINUE;
    END IF;
    IF n = 0 THEN
      first_lng := lng;
      first_lat := lat;
      pts := format('%s %s', lng, lat);
    ELSE
      pts := pts || ', ' || format('%s %s', lng, lat);
    END IF;
    last_lng := lng;
    last_lat := lat;
    n := n + 1;
  END LOOP;
  IF n < 3 THEN
    RETURN NULL;
  END IF;
  IF first_lng IS DISTINCT FROM last_lng OR first_lat IS DISTINCT FROM last_lat THEN
    pts := pts || ', ' || format('%s %s', first_lng, first_lat);
  END IF;
  RETURN ST_SetSRID(ST_GeomFromText('POLYGON((' || pts || '))'), 4326);
END;
$$;


ALTER FUNCTION "delivery"."ring_jsonb_to_geom"("ring" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."ring_to_latlng_jsonb"("r" "public"."geometry") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    (
      SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY i)
      FROM (
        SELECT
          ST_Y(ST_PointN(r, gs)) AS lat,
          ST_X(ST_PointN(r, gs)) AS lng,
          gs AS i
        FROM generate_series(1, GREATEST(ST_NPoints(r) - 1, 0)) AS gs
      ) s
    ),
    '[]'::jsonb
  );
$$;


ALTER FUNCTION "delivery"."ring_to_latlng_jsonb"("r" "public"."geometry") OWNER TO "postgres";


