CREATE OR REPLACE FUNCTION "delivery"."union_admin3_to_market_zone"("p_market_id" "uuid", "p_pcodes" "text"[], "p_zone_name" "text" DEFAULT 'Community union'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  g geometry;
  ring jsonb;
  zone_id uuid;
BEGIN
  SELECT ST_Multi(ST_UnaryUnion(ST_Collect(v.geom))) INTO g
  FROM geo.boundaries b
  JOIN geo.boundary_versions v ON v.id = b.current_version_id
  WHERE b.admin_level = 3 AND b.pcode = ANY (p_pcodes);

  IF g IS NULL OR ST_IsEmpty(g) THEN
    RAISE EXCEPTION 'No admin3 geometries for provided pcodes';
  END IF;
  g := ST_MakeValid(g);

  ring := (
    SELECT jsonb_agg(jsonb_build_object('lat', lat, 'lng', lng) ORDER BY idx)
    FROM (
      SELECT
        ST_Y(ST_PointN(r.ring, gs)) AS lat,
        ST_X(ST_PointN(r.ring, gs)) AS lng,
        gs AS idx
      FROM (
        SELECT ST_ExteriorRing(ST_GeometryN(g, 1)) AS ring
      ) r
      CROSS JOIN generate_series(1, GREATEST(ST_NPoints(r.ring) - 1, 0)) AS gs
    ) s
  );

  INSERT INTO delivery.service_zone_polygons (
    market_id, name, polygon, geom, kind, source, priority, updated_at
  ) VALUES (
    p_market_id, p_zone_name, COALESCE(ring, '[]'::jsonb), g, 'include', 'import', 0, now()
  )
  RETURNING id INTO zone_id;

  UPDATE delivery.service_markets SET draft_dirty = true WHERE id = p_market_id;
  RETURN zone_id;
END;
$$;


ALTER FUNCTION "delivery"."union_admin3_to_market_zone"("p_market_id" "uuid", "p_pcodes" "text"[], "p_zone_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "delivery"."void_abandoned_unpaid_orders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'payments', 'public'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  WITH doomed AS (
    SELECT o.id
    FROM delivery.orders o
    WHERE o.status = 'placed'
      AND COALESCE(o.payment_status, 'pending') = 'pending'
      AND NOT EXISTS (
        SELECT 1 FROM payments.payment_intents i
        WHERE i.order_id = o.id
          AND i.expires_at > now() - interval '15 minutes'
          AND i.status IS DISTINCT FROM 'failed'
      )
      AND EXISTS (
        SELECT 1 FROM payments.payment_intents i WHERE i.order_id = o.id
      )
  ),
  updated AS (
    UPDATE delivery.orders o
    SET status = 'cancelled',
        payment_status = 'voided',
        money_state = 'voided',
        cancelled_at = now(),
        cancelled_by = 'system',
        cancellation_reason = 'Payment window expired',
        updated_at = now()
    FROM doomed d
    WHERE o.id = d.id
    RETURNING o.id
  )
  SELECT count(*) INTO v_count FROM updated;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "delivery"."void_abandoned_unpaid_orders"() OWNER TO "postgres";


