CREATE OR REPLACE FUNCTION "fleet"."assign_toll_tag"("p_org" "text", "p_tag_id" "text", "p_vehicle_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
DECLARE
  v_tag fleet.toll_tags%ROWTYPE;
  v_vehicle fleet.vehicles%ROWTYPE;
  v_now timestamptz := now();
  v_plate text;
  v_prev text;
  v_occ text;
  v_payload jsonb;
  v_hist jsonb;
  v_vehicles jsonb := '[]'::jsonb;
  v_occ_payload jsonb;
  v_prev_payload jsonb;
  v_veh_payload jsonb;
BEGIN
  SELECT * INTO v_tag FROM fleet.toll_tags WHERE id = p_tag_id FOR UPDATE;
  IF NOT FOUND OR v_tag.organization_id IS DISTINCT FROM p_org THEN
    RAISE EXCEPTION 'tag_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF coalesce(v_tag.payload_json->>'status', '') = 'Retired' THEN
    RAISE EXCEPTION 'tag_retired' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_vehicle FROM fleet.vehicles WHERE id = p_vehicle_id FOR UPDATE;
  IF NOT FOUND OR v_vehicle.organization_id IS DISTINCT FROM p_org THEN
    RAISE EXCEPTION 'vehicle_not_found' USING ERRCODE = 'P0002';
  END IF;
  v_plate := coalesce(nullif(v_vehicle.license_plate, ''), nullif(v_vehicle.payload_json->>'licensePlate', ''), p_vehicle_id);
  v_payload := v_tag.payload_json;
  v_prev := nullif(v_payload->>'assignedVehicleId', '');
  v_occ := nullif(v_vehicle.payload_json->>'tollTagUuid', '');
  IF v_prev IS NOT NULL AND v_prev = p_vehicle_id AND v_occ IS NOT DISTINCT FROM p_tag_id THEN
    RETURN jsonb_build_object('tag', v_payload, 'vehicles', '[]'::jsonb);
  END IF;
  IF v_occ IS NOT NULL AND v_occ <> p_tag_id THEN
    UPDATE fleet.toll_tag_assignments SET unassigned_at = v_now WHERE tag_id = v_occ AND vehicle_id = p_vehicle_id AND unassigned_at IS NULL;
    UPDATE fleet.toll_tags t
    SET payload_json = ((t.payload_json - 'assignedVehicleId' - 'assignedVehicleName') || jsonb_build_object('updatedAt', v_now)),
        vehicle_id = NULL, updated_at = v_now
    WHERE t.id = v_occ AND t.organization_id = p_org
    RETURNING payload_json INTO v_occ_payload;
    IF v_occ_payload IS NOT NULL THEN
      v_vehicles := v_vehicles || jsonb_build_array(jsonb_build_object('id', v_occ, 'kind', 'tag', 'payload', v_occ_payload));
    END IF;
  END IF;
  IF v_prev IS NOT NULL AND v_prev <> p_vehicle_id THEN
    UPDATE fleet.toll_tag_assignments SET unassigned_at = v_now WHERE tag_id = p_tag_id AND vehicle_id = v_prev AND unassigned_at IS NULL;
    UPDATE fleet.vehicles v
    SET payload_json = (v.payload_json - 'tollTagId' - 'tollTagUuid' - 'tollTagProvider') || jsonb_build_object('updatedAt', v_now),
        toll_tag_id = NULL, updated_at = v_now
    WHERE v.id = v_prev AND v.organization_id = p_org
    RETURNING payload_json INTO v_prev_payload;
    IF v_prev_payload IS NOT NULL THEN
      v_vehicles := v_vehicles || jsonb_build_array(jsonb_build_object('id', v_prev, 'kind', 'vehicle', 'payload', v_prev_payload));
    END IF;
  END IF;
  UPDATE fleet.toll_tag_assignments SET unassigned_at = v_now WHERE tag_id = p_tag_id AND unassigned_at IS NULL AND vehicle_id IS DISTINCT FROM p_vehicle_id;
  IF NOT EXISTS (SELECT 1 FROM fleet.toll_tag_assignments WHERE tag_id = p_tag_id AND vehicle_id = p_vehicle_id AND unassigned_at IS NULL) THEN
    INSERT INTO fleet.toll_tag_assignments (organization_id, tag_id, vehicle_id, assigned_at) VALUES (p_org, p_tag_id, p_vehicle_id, v_now);
  END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN coalesce(elem->>'unassignedAt', '') = '' THEN elem || jsonb_build_object('unassignedAt', v_now) ELSE elem END), '[]'::jsonb)
  INTO v_hist FROM jsonb_array_elements(coalesce(v_payload->'assignmentHistory', '[]'::jsonb)) elem;
  v_hist := v_hist || jsonb_build_array(jsonb_build_object('vehicleId', p_vehicle_id, 'vehicleName', v_plate, 'assignedAt', v_now));
  v_payload := v_payload || jsonb_build_object('assignedVehicleId', p_vehicle_id, 'assignedVehicleName', v_plate, 'assignmentHistory', v_hist, 'updatedAt', v_now);
  UPDATE fleet.toll_tags SET payload_json = v_payload, vehicle_id = p_vehicle_id, tag_number = coalesce(nullif(v_payload->>'tagNumber', ''), tag_number), updated_at = v_now WHERE id = p_tag_id;
  v_veh_payload := v_vehicle.payload_json || jsonb_build_object('tollTagId', v_payload->>'tagNumber', 'tollTagUuid', p_tag_id, 'tollTagProvider', v_payload->>'provider', 'updatedAt', v_now);
  UPDATE fleet.vehicles SET payload_json = v_veh_payload, toll_tag_id = v_payload->>'tagNumber', updated_at = v_now WHERE id = p_vehicle_id;
  v_vehicles := v_vehicles || jsonb_build_array(jsonb_build_object('id', p_vehicle_id, 'kind', 'vehicle', 'payload', v_veh_payload));
  RETURN jsonb_build_object('tag', v_payload, 'vehicles', v_vehicles);
END;
$$;


ALTER FUNCTION "fleet"."assign_toll_tag"("p_org" "text", "p_tag_id" "text", "p_vehicle_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."backfill_trip_facts"("p_batch" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  inserted_n int := 0;
  remaining_n bigint;
  trip_count bigint;
  fact_count bigint;
  trip_amount numeric;
  fact_amount numeric;
begin
  insert into fleet.trip_facts
  select (fleet.project_trip_fact(t)).*
  from fleet.trips t
  where not exists (
    select 1 from fleet.trip_facts f where f.trip_id = t.id
  )
  order by t.id
  limit greatest(coalesce(p_batch, 300), 1)
  on conflict (trip_id) do nothing;
  get diagnostics inserted_n = row_count;

  select count(*) into remaining_n
  from fleet.trips t
  where not exists (
    select 1 from fleet.trip_facts f where f.trip_id = t.id
  );

  if remaining_n = 0 then
    update fleet.trip_facts f
    set anomaly_flags = f.anomaly_flags || array['duplicate']
    where f.status_bucket = 'completed'
      and f.request_at is not null
      and f.driver_id is not null
      and exists (
        select 1 from fleet.trip_facts o
        where o.organization_id = f.organization_id
          and o.driver_id = f.driver_id
          and o.request_at = f.request_at
          and o.trip_id <> f.trip_id
          and o.status_bucket = 'completed'
      )
      and not ('duplicate' = any (f.anomaly_flags));

    select count(*), coalesce(sum(amount), 0) into trip_count, trip_amount from fleet.trips;
    select count(*), coalesce(sum(amount), 0) into fact_count, fact_amount from fleet.trip_facts;
    return jsonb_build_object(
      'inserted', inserted_n,
      'remaining', 0,
      'parityOk', trip_count = fact_count and trip_amount is not distinct from fact_amount,
      'trips', trip_count,
      'facts', fact_count
    );
  end if;

  return jsonb_build_object('inserted', inserted_n, 'remaining', remaining_n);
end;
$$;


ALTER FUNCTION "fleet"."backfill_trip_facts"("p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."bulk_insert_toll_ledger"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
DECLARE
  inserted int := 0;
  skipped int := 0;
  r jsonb;
  row_id text;
  inserted_ids text[] := ARRAY[]::text[];
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RETURN jsonb_build_object(
      'inserted', 0,
      'skipped', 0,
      'inserted_ids', '[]'::jsonb
    );
  END IF;

  FOR r IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    BEGIN
      row_id := coalesce(nullif(r->>'id', ''), gen_random_uuid()::text);
      INSERT INTO fleet.toll_ledger (
        id,
        organization_id,
        date,
        amount,
        type,
        status,
        payment_method,
        vehicle_id,
        driver_id,
        toll_tag_id,
        provider_ref,
        plaza,
        plaza_id,
        batch_id,
        service_line,
        service_line_source,
        metadata,
        payload_json,
        audit_trail,
        created_at,
        updated_at,
        legacy_kv_id,
        is_reconciled
      )
      VALUES (
        row_id,
        r->>'organization_id',
        (r->>'date')::date,
        coalesce((r->>'amount')::numeric, 0),
        nullif(r->>'type', ''),
        coalesce(nullif(r->>'status', ''), 'Completed'),
        nullif(r->>'payment_method', ''),
        nullif(r->>'vehicle_id', ''),
        nullif(r->>'driver_id', ''),
        nullif(r->>'toll_tag_id', ''),
        nullif(r->>'provider_ref', ''),
        nullif(r->>'plaza', ''),
        nullif(r->>'plaza_id', ''),
        nullif(r->>'batch_id', ''),
        nullif(r->>'service_line', ''),
        nullif(r->>'service_line_source', ''),
        coalesce(r->'metadata', '{}'::jsonb),
        coalesce(r->'payload_json', r),
        coalesce(r->'audit_trail', '[]'::jsonb),
        coalesce((r->>'created_at')::timestamptz, now()),
        coalesce((r->>'updated_at')::timestamptz, now()),
        coalesce(nullif(r->>'legacy_kv_id', ''), row_id),
        coalesce((r->>'is_reconciled')::boolean, false)
      )
      ON CONFLICT DO NOTHING;
      IF FOUND THEN
        inserted := inserted + 1;
        inserted_ids := array_append(inserted_ids, row_id);
      ELSE
        skipped := skipped + 1;
      END IF;
    EXCEPTION
      WHEN unique_violation THEN
        skipped := skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'inserted', inserted,
    'skipped', skipped,
    'inserted_ids', to_jsonb(inserted_ids)
  );
END;
$$;


ALTER FUNCTION "fleet"."bulk_insert_toll_ledger"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."can_read_org"("p_org_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'fleet'
    AS $$
  SELECT
    public.rbac_is_platform_user(auth.uid())
    OR (
      p_org_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.organizations o
        WHERE o.id::text = p_org_id AND o.owner_id = auth.uid()
      )
    );
$$;


ALTER FUNCTION "fleet"."can_read_org"("p_org_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."compute_vehicle_tag_balance"("p_vehicle_id" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
  SELECT coalesce(sum(l.amount), 0)
  FROM fleet.toll_ledger l
  WHERE l.vehicle_id = p_vehicle_id
    AND lower(coalesce(l.status, '')) NOT IN ('voided', 'void')
    AND coalesce(l.metadata->>'voided', l.payload_json->'metadata'->>'voided', '') NOT IN ('true', 't')
    AND coalesce(nullif(l.payment_method, ''), l.payload_json->>'paymentMethod', '') NOT ILIKE '%cash%'
    AND coalesce(nullif(l.payment_method, ''), l.payload_json->>'paymentMethod', '') NOT ILIKE '%card%'
    AND coalesce(nullif(l.payment_method, ''), l.payload_json->>'paymentMethod', '') NOT ILIKE '%fleet%'
    AND coalesce(nullif(l.payment_method, ''), l.payload_json->>'paymentMethod', '') NOT ILIKE '%account%';
$$;


ALTER FUNCTION "fleet"."compute_vehicle_tag_balance"("p_vehicle_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."coverage_day_amount"("p_premium" numeric, "p_start" "date", "p_end" "date", "p_day" "date") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_day = p_end THEN p_premium - round(p_premium / ((p_end - p_start) + 1), 2) * ((p_end - p_start))
    ELSE round(p_premium / ((p_end - p_start) + 1), 2)
  END;
$$;


ALTER FUNCTION "fleet"."coverage_day_amount"("p_premium" numeric, "p_start" "date", "p_end" "date", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."coverage_overlaps"("p_contract" "text", "p_start" "date", "p_end" "date", "p_except" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM fleet.expense_coverage_periods c
    WHERE c.contract_id = p_contract
      AND (p_except IS NULL OR c.id <> p_except)
      AND daterange(c.start_date, c.end_date, '[]') && daterange(p_start, p_end, '[]')
  );
$$;


ALTER FUNCTION "fleet"."coverage_overlaps"("p_contract" "text", "p_start" "date", "p_end" "date", "p_except" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."finance_statement_drift"("p_today" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  n integer := 0;
BEGIN
  INSERT INTO fleet.finance_statement_alerts (organization_id, line_date, line_code, stored_amount, recomputed_amount)
  SELECT l.organization_id, l.line_date, l.line_code, l.amount,
         fleet.coverage_day_amount(c.premium, c.start_date, c.end_date, l.line_date)
  FROM fleet.finance_period_lines l
  JOIN fleet.expense_coverage_periods c ON l.line_code = 'prepaid:' || c.id
  WHERE l.line_date <= p_today
    AND abs(l.amount - fleet.coverage_day_amount(c.premium, c.start_date, c.end_date, l.line_date)) > 0.01;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO fleet.finance_statement_alerts (organization_id, line_date, line_code, stored_amount, recomputed_amount)
  SELECT c.organization_id, c.end_date, 'prepaid:' || c.id, COALESCE(SUM(l.amount), 0), c.premium
  FROM fleet.expense_coverage_periods c
  LEFT JOIN fleet.finance_period_lines l ON l.line_code = 'prepaid:' || c.id
  WHERE c.end_date <= p_today
  GROUP BY c.organization_id, c.end_date, c.id, c.premium
  HAVING abs(COALESCE(SUM(l.amount), 0) - c.premium) > 0.01;
  RETURN n;
END;
$$;


ALTER FUNCTION "fleet"."finance_statement_drift"("p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."fuel_entries_amount_sum"("p_org" "text", "p_from" "date", "p_to" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
  select coalesce(sum(abs(amount)), 0)
  from fleet.fuel_entries
  where organization_id = p_org
    and date >= p_from
    and date < p_to + 1;
$$;


ALTER FUNCTION "fleet"."fuel_entries_amount_sum"("p_org" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."fuel_expense_ledger_totals"("p_org" "text", "p_from" "date", "p_to" "date", "p_search" "text") RETURNS TABLE("approved" numeric, "rejected" numeric, "pending" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
  select
    coalesce(sum(abs(t.amount)) filter (where t.status = 'Approved'), 0),
    coalesce(sum(abs(t.amount)) filter (where t.status = 'Rejected'), 0),
    0::numeric
  from fleet.transactions t
  where t.organization_id = p_org
    and (p_from is null or t.date >= p_from)
    and (p_to is null or t.date < p_to + 1)
    and t.status in ('Approved', 'Rejected')
    and (
      (
        lower(t.type) = 'expense'
        and (
          t.category ilike '%fuel%'
          or coalesce(t.payload_json->>'description', '') ilike '%fuel expense%'
          or coalesce(t.payload_json->>'description', '') ilike 'fuel:%'
          or coalesce(t.payload_json->>'description', '') ilike '%fuel —%'
        )
      )
      or (
        t.category in ('Fuel', 'Fuel Reimbursement')
        and t.type in ('Reimbursement', 'Fuel_Manual_Entry', 'Manual_Entry', 'Expense')
      )
    )
    and (
      p_search is null
      or p_search = ''
      or coalesce(t.payload_json->>'description', '') ilike '%' || p_search || '%'
      or coalesce(t.category, '') ilike '%' || p_search || '%'
    );
$$;


ALTER FUNCTION "fleet"."fuel_expense_ledger_totals"("p_org" "text", "p_from" "date", "p_to" "date", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."haversine_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lat1 is null or lng1 is null or lat2 is null or lng2 is null then null
    else 2 * 6371 * asin(sqrt(
      power(sin(radians(lat2 - lat1) / 2), 2)
      + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
    ))
  end;
$$;


ALTER FUNCTION "fleet"."haversine_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."log_master_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  who text := nullif(current_setting('app.actor', true), '');
  why text := nullif(current_setting('app.reason', true), '');
begin
  if why is null then
    if tg_op = 'UPDATE'
      and tg_table_name = 'stations'
      and new.status = 'verified'
      and old.status is distinct from 'verified' then
      why := 'verified';
    elsif tg_op = 'INSERT' then
      why := 'created';
    elsif tg_op = 'UPDATE' then
      why := 'updated';
    else
      why := 'deleted';
    end if;
  end if;

  insert into fleet.master_change_log (dataset, record_id, action, before_json, after_json, actor, reason)
  values (
    tg_table_name,
    coalesce(new.id, old.id)::text,
    lower(tg_op),
    case when tg_op = 'INSERT' then null else to_jsonb(old) - 'payload_json' end,
    case when tg_op = 'DELETE' then null else to_jsonb(new) - 'payload_json' end,
    who,
    why
  );
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "fleet"."log_master_change"() OWNER TO "postgres";


