CREATE OR REPLACE FUNCTION "fleet"."project_trip_fact"("t" "fleet"."trips") RETURNS "fleet"."trip_facts"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  f fleet.trip_facts;
  p jsonb := coalesce(t.payload_json, '{}'::jsonb);
  v_req timestamptz;
  v_local timestamp;
  v_reason text;
  v_by text;
  v_uber text;
  v_token text;
  v_platform text;
  v_line text;
  v_category text;
  v_floor numeric := 5000;
  v_fpk numeric := 500;
  v_long_km numeric := 100;
  v_long_min numeric := 180;
  v_speed_high numeric := 120;
  v_speed_low numeric := 3;
  v_speed_km numeric := 2;
begin
  f.trip_id := t.id;
  f.organization_id := t.organization_id;
  f.driver_id := t.driver_id;
  f.driver_name := nullif(btrim(coalesce(p->>'driverName', '')), '');
  f.vehicle_id := nullif(btrim(coalesce(t.vehicle_id, '')), '');
  v_platform := lower(regexp_replace(coalesce(t.platform, p->>'platform', ''), '\s+', '', 'g'));
  f.platform := case v_platform
    when 'uber' then 'Uber'
    when 'indrive' then 'InDrive'
    when 'roam' then 'Roam'
    when 'goride' then 'Roam'
    when 'roamrush' then 'Roam Rush'
    else coalesce(nullif(btrim(coalesce(t.platform, '')), ''), 'Unknown')
  end;
  v_line := coalesce(t.service_line, p->>'serviceLine', p->>'service_line', 'rideshare');
  f.service_line := v_line;
  v_category := lower(coalesce(p->>'serviceCategory', p->>'service_category', ''));
  f.service_category := nullif(v_category, '');
  f.is_manual := coalesce(fleet.trip_bool(p->>'isManual'), false);
  f.is_live := coalesce(fleet.trip_bool(p->>'isLiveRecorded'), false);
  f.status_bucket := case
    when lower(coalesce(t.status, '')) in ('completed') then 'completed'
    when lower(coalesce(t.status, '')) in ('cancelled', 'canceled') then 'cancelled'
    else 'in_progress'
  end;
  f.amount := t.amount;
  f.payment_method := coalesce(t.payment_method, p->>'paymentMethod');
  f.distance_km := coalesce(t.distance, fleet.trip_num(p->>'distance'));
  f.duration_min := coalesce(t.duration, fleet.trip_num(p->>'duration'));
  f.anchor_period_id := nullif(p->>'anchorPeriodId', '');
  f.cash_collected_abs := abs(fleet.trip_num(p->>'cashCollected'));
  if f.platform = 'Uber' then
    f.net_to_driver := coalesce(t.net_to_driver, fleet.trip_num(p->>'netToDriver'));
  elsif f.platform = 'InDrive' then
    f.net_to_driver := fleet.trip_num(p->>'indriveNetIncome');
  else
    f.net_to_driver := coalesce(t.net_to_driver, fleet.trip_num(p->>'netToDriver'));
  end if;
  if f.platform = 'Uber' and f.amount is not null and f.net_to_driver is not null then
    f.platform_fee := f.amount - f.net_to_driver;
  elsif f.platform = 'InDrive' then
    f.platform_fee := fleet.trip_num(p->>'indriveServiceFee');
  else
    f.platform_fee := null;
  end if;
  f.fare_base := fleet.trip_num(p#>>'{fareBreakdown,baseFare}');
  f.fare_surge := fleet.trip_num(p#>>'{fareBreakdown,surge}');
  f.fare_tips := fleet.trip_num(p#>>'{fareBreakdown,tips}');
  f.fare_wait := fleet.trip_num(p#>>'{fareBreakdown,waitTime}');
  f.fare_airport := fleet.trip_num(p#>>'{fareBreakdown,airportFees}');
  f.fare_taxes := fleet.trip_num(p#>>'{fareBreakdown,taxes}');
  f.tolls := fleet.trip_num(p->>'tollCharges');
  f.has_surge := coalesce(f.fare_surge, 0) > 0;
  f.has_tip := coalesce(f.fare_tips, 0) > 0;
  f.deadhead_km_allocated := fleet.trip_num(p->>'normalizedEnrouteDistance');
  f.pickup_lat := coalesce(fleet.trip_num(p->>'startLat'), fleet.trip_num(p->>'pickupLat'), fleet.trip_num(p#>>'{pickupCoords,lat}'))::double precision;
  f.pickup_lng := coalesce(fleet.trip_num(p->>'startLng'), fleet.trip_num(p->>'pickupLng'), fleet.trip_num(p#>>'{pickupCoords,lon}'), fleet.trip_num(p#>>'{pickupCoords,lng}'))::double precision;
  f.dropoff_lat := coalesce(fleet.trip_num(p->>'endLat'), fleet.trip_num(p->>'dropoffLat'), fleet.trip_num(p#>>'{dropoffCoords,lat}'))::double precision;
  f.dropoff_lng := coalesce(fleet.trip_num(p->>'endLng'), fleet.trip_num(p->>'dropoffLng'), fleet.trip_num(p#>>'{dropoffCoords,lon}'), fleet.trip_num(p#>>'{dropoffCoords,lng}'))::double precision;

  begin
    v_req := nullif(p->>'requestTime', '')::timestamptz;
  exception when others then
    v_req := null;
  end;
  f.request_at := v_req;
  if v_req is not null then
    v_local := v_req at time zone 'America/Jamaica';
    f.local_date := v_local::date;
    f.local_hour := extract(hour from v_local)::smallint;
    f.local_dow := extract(isodow from v_local)::smallint;
    f.time_unknown := false;
  else
    f.local_date := t.date;
    f.local_hour := null;
    f.local_dow := null;
    f.time_unknown := true;
  end if;

  if f.status_bucket = 'cancelled' then
    v_reason := lower(btrim(coalesce(p->>'cancellationReason', '')));
    v_by := lower(btrim(coalesce(p->>'cancelledBy', '')));
    v_uber := lower(btrim(coalesce(p->>'uberTripStatus', '')));
    v_token := case when v_reason <> '' then v_reason else v_uber end;
    if v_token = 'rider_cancelled' then
      f.cancel_actor := 'rider'; f.cancel_reason_code := 'rider_cancelled';
    elsif v_token = 'driver_cancelled' then
      f.cancel_actor := 'driver'; f.cancel_reason_code := 'driver_cancelled';
    elsif v_token = 'delivery_failed' then
      f.cancel_actor := 'delivery'; f.cancel_reason_code := 'delivery_failed';
    elsif v_token = 'other (driver)' or v_by = 'driver' then
      f.cancel_actor := 'driver'; f.cancel_reason_code := 'other';
    elsif v_token = 'other (rider)' or v_by = 'rider' then
      f.cancel_actor := 'rider'; f.cancel_reason_code := 'other';
    elsif v_token = 'wait time too long' then
      f.cancel_reason_code := 'wait_too_long';
      f.cancel_actor := case v_by when 'driver' then 'driver' when 'rider' then 'rider' else 'unknown' end;
    elsif v_by = 'system' then
      f.cancel_actor := 'system';
      f.cancel_reason_code := case when v_token = 'timeout' then 'timeout' else 'unmatched' end;
    elsif v_token = '' then
      f.cancel_actor := 'unknown'; f.cancel_reason_code := 'unknown';
    else
      f.cancel_actor := 'unknown'; f.cancel_reason_code := 'other';
    end if;
    f.cancellation_fee := coalesce(fleet.trip_num(p->>'cancellationFee'), f.amount);
  end if;

  if v_line = 'rush_delivery' or v_category = 'courier' or f.cancel_reason_code = 'delivery_failed' then
    f.analytics_population := 'delivery';
  else
    f.analytics_population := 'rideshare';
  end if;

  f.pickup_zone := coalesce(
    fleet.zone_for_trip(fleet.normalize_trip_area(p->>'pickupArea'), f.pickup_lat, f.pickup_lng),
    initcap(fleet.normalize_trip_area(p->>'pickupArea'))
  );
  f.dropoff_zone := coalesce(
    fleet.zone_for_trip(fleet.normalize_trip_area(p->>'dropoffArea'), f.dropoff_lat, f.dropoff_lng),
    initcap(fleet.normalize_trip_area(p->>'dropoffArea'))
  );

  select
    coalesce(s.fare_floor, 5000), coalesce(s.fare_per_km_max, 500), coalesce(s.long_distance_km, 100),
    coalesce(s.long_duration_min, 180), coalesce(s.speed_high_kmh, 120), coalesce(s.speed_low_kmh, 3),
    coalesce(s.speed_low_min_km, 2)
  into v_floor, v_fpk, v_long_km, v_long_min, v_speed_high, v_speed_low, v_speed_km
  from fleet.trip_analytics_settings s
  where s.organization_id = f.organization_id;
  if v_floor is null then
    v_floor := 5000; v_fpk := 500; v_long_km := 100; v_long_min := 180;
    v_speed_high := 120; v_speed_low := 3; v_speed_km := 2;
  end if;

  f.anomaly_flags := '{}';
  if f.status_bucket = 'completed' and coalesce(f.amount, 0) = 0 then
    f.anomaly_flags := f.anomaly_flags || array['zero_fare'];
  end if;
  if f.status_bucket = 'completed' and (f.distance_km is null or f.distance_km = 0) then
    f.anomaly_flags := f.anomaly_flags || array['zero_distance'];
  end if;
  if f.status_bucket = 'completed' and f.distance_km > v_long_km then
    f.anomaly_flags := f.anomaly_flags || array['long_distance'];
  end if;
  if f.status_bucket = 'completed' and f.duration_min > v_long_min then
    f.anomaly_flags := f.anomaly_flags || array['long_duration'];
  end if;
  if f.status_bucket = 'completed' and f.amount > v_floor then
    f.anomaly_flags := f.anomaly_flags || array['fare_outlier'];
  end if;
  if f.status_bucket = 'completed' and coalesce(f.distance_km, 0) >= 2 and (f.amount / f.distance_km) > v_fpk then
    f.anomaly_flags := f.anomaly_flags || array['fare_per_km'];
  end if;
  if f.status_bucket = 'completed' and f.distance_km > 0 and f.duration_min > 0 then
    if (f.distance_km / (f.duration_min / 60.0)) > v_speed_high then
      f.anomaly_flags := f.anomaly_flags || array['speed_high'];
    elsif (f.distance_km / (f.duration_min / 60.0)) < v_speed_low and f.distance_km > v_speed_km then
      f.anomaly_flags := f.anomaly_flags || array['speed_low'];
    end if;
  end if;
  if f.time_unknown and f.status_bucket = 'completed' then
    f.anomaly_flags := f.anomaly_flags || array['missing_time'];
  end if;
  if f.status_bucket = 'completed' and f.vehicle_id is null then
    f.anomaly_flags := f.anomaly_flags || array['missing_vehicle'];
  end if;
  f.updated_at := now();
  return f;
end;
$$;


ALTER FUNCTION "fleet"."project_trip_fact"("t" "fleet"."trips") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."purge_old_activity_data"("p_keep_days" integer DEFAULT 400) RETURNS TABLE("deleted_events" bigint, "deleted_presence" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'pg_temp'
    AS $$
DECLARE
  v_events bigint;
  v_presence bigint;
BEGIN
  IF p_keep_days IS NULL OR p_keep_days < 30 THEN
    RAISE EXCEPTION 'p_keep_days must be >= 30';
  END IF;

  DELETE FROM fleet.driver_activity_events
  WHERE occurred_at < (now() - make_interval(days => p_keep_days));
  GET DIAGNOSTICS v_events = ROW_COUNT;

  DELETE FROM fleet.driver_presence_log
  WHERE occurred_at < (now() - make_interval(days => p_keep_days));
  GET DIAGNOSTICS v_presence = ROW_COUNT;

  deleted_events := v_events;
  deleted_presence := v_presence;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "fleet"."purge_old_activity_data"("p_keep_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "fleet"."purge_old_activity_data"("p_keep_days" integer) IS 'Deletes activity projection + presence log rows older than p_keep_days (default 400). Cron / service_role only.';



CREATE OR REPLACE FUNCTION "fleet"."recognise_coverage_through_today"("p_today" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  inserted integer := 0;
  cov record;
  day date;
  day_amount numeric;
BEGIN
  FOR cov IN SELECT * FROM fleet.expense_coverage_periods LOOP
    IF (cov.end_date - cov.start_date) + 1 <= 0 THEN CONTINUE; END IF;
    day := cov.start_date;
    WHILE day <= LEAST(cov.end_date, p_today) LOOP
      day_amount := fleet.coverage_day_amount(cov.premium, cov.start_date, cov.end_date, day);
      INSERT INTO fleet.finance_period_lines (
        organization_id, service_line, line_date, line_code, amount, source
      ) VALUES (
        cov.organization_id, cov.service_line, day, 'prepaid:' || cov.id, day_amount, 'coverage'
      )
      ON CONFLICT (organization_id, service_line, line_date, line_code)
      DO UPDATE SET amount = EXCLUDED.amount, updated_at = now();
      inserted := inserted + 1;
      day := day + 1;
    END LOOP;
  END LOOP;
  RETURN inserted;
END;
$$;


ALTER FUNCTION "fleet"."recognise_coverage_through_today"("p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."record_expense_payment"("p_org" "text", "p_payment_id" "text", "p_bill_id" "text", "p_amount" numeric, "p_payment_date" "date", "p_idempotency_key" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  owed numeric;
  paid numeric;
  v_week date;
BEGIN
  IF EXISTS (
    SELECT 1 FROM fleet.expense_bill_payments WHERE idempotency_key = p_idempotency_key
  ) THEN
    RETURN;
  END IF;
  v_week := p_payment_date - ((EXTRACT(ISODOW FROM p_payment_date)::int - 1));
  IF EXISTS (
    SELECT 1 FROM fleet.finance_period_locks AS locks
    WHERE locks.organization_id = p_org AND locks.week_start = v_week
  ) THEN
    RAISE EXCEPTION 'week locked';
  END IF;
  SELECT amount INTO owed FROM fleet.expense_bills WHERE id = p_bill_id AND organization_id = p_org FOR UPDATE;
  IF owed IS NULL THEN
    RAISE EXCEPTION 'bill not found';
  END IF;
  SELECT COALESCE(SUM(amount), 0) INTO paid FROM fleet.expense_bill_payments WHERE bill_id = p_bill_id;
  IF p_amount > owed - paid + 0.001 THEN
    RAISE EXCEPTION 'overpay';
  END IF;
  INSERT INTO fleet.expense_bill_payments (id, organization_id, bill_id, amount, payment_date, idempotency_key)
  VALUES (p_payment_id, p_org, p_bill_id, p_amount, p_payment_date, p_idempotency_key);
END;
$$;


ALTER FUNCTION "fleet"."record_expense_payment"("p_org" "text", "p_payment_id" "text", "p_bill_id" "text", "p_amount" numeric, "p_payment_date" "date", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."reject_overlapping_coverage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF fleet.coverage_overlaps(NEW.contract_id, NEW.start_date, NEW.end_date, NEW.id) THEN
    RAISE EXCEPTION 'coverage overlaps';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "fleet"."reject_overlapping_coverage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."reject_roam_plug_money_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  blob text := COALESCE(NEW.payload_json::text, '');
BEGIN
  IF blob LIKE '%"origin_app":"roam_plug"%'
     OR blob LIKE '%"originApp":"roam_plug"%'
     OR blob LIKE '%"source":"roam_plug"%' THEN
    RAISE EXCEPTION 'Roam Plug cannot write fleet money (%)', TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "fleet"."reject_roam_plug_money_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."retire_toll_tag"("p_org" "text", "p_tag_id" "text", "p_reason" "text", "p_expected" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
DECLARE
  v_tag fleet.toll_tags%ROWTYPE;
  v_now timestamptz := now();
  v_payload jsonb;
  v_vehicle_id text;
  v_cleared jsonb;
BEGIN
  SELECT * INTO v_tag FROM fleet.toll_tags WHERE id = p_tag_id FOR UPDATE;
  IF NOT FOUND OR v_tag.organization_id IS DISTINCT FROM p_org THEN
    RAISE EXCEPTION 'tag_not_found' USING ERRCODE = 'P0002';
  END IF;
  v_payload := v_tag.payload_json;
  IF coalesce(v_payload->>'updatedAt', '') <> '' AND v_payload->>'updatedAt' IS DISTINCT FROM p_expected THEN
    RAISE EXCEPTION 'stale_write' USING ERRCODE = 'P0001';
  END IF;
  v_vehicle_id := nullif(v_payload->>'assignedVehicleId', '');
  IF v_vehicle_id IS NOT NULL THEN
    RAISE EXCEPTION 'tag_assigned' USING ERRCODE = 'P0001';
  END IF;
  UPDATE fleet.vehicles v
  SET payload_json = (v.payload_json - 'tollTagId' - 'tollTagUuid' - 'tollTagProvider') || jsonb_build_object('updatedAt', v_now),
      toll_tag_id = NULL, updated_at = v_now
  WHERE v.organization_id = p_org AND (v.payload_json->>'tollTagUuid') = p_tag_id;
  v_payload := v_payload || jsonb_build_object('status', 'Retired', 'retiredAt', v_now, 'retiredReason', coalesce(nullif(p_reason, ''), 'Retired'), 'updatedAt', v_now);
  UPDATE fleet.toll_tags SET payload_json = v_payload, updated_at = v_now WHERE id = p_tag_id;
  SELECT coalesce(jsonb_agg(v.id), '[]'::jsonb) INTO v_cleared FROM fleet.vehicles v WHERE v.organization_id = p_org AND (v.payload_json->>'tollTagUuid') IS NULL AND v.updated_at = v_now;
  RETURN jsonb_build_object('tag', v_payload, 'clearedVehicleIds', coalesce(v_cleared, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "fleet"."retire_toll_tag"("p_org" "text", "p_tag_id" "text", "p_reason" "text", "p_expected" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."roam_ride_funnel"("p_org" "text", "f" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  requested bigint := 0;
  offered bigint := 0;
  accepted bigint := 0;
  arrived bigint := 0;
  started bigint := 0;
  completed bigint := 0;
  reasons jsonb := '[]'::jsonb;
  offered_med numeric;
  accepted_med numeric;
  arrived_med numeric;
  started_med numeric;
  completed_med numeric;
begin
  -- A request belongs to this fleet when it was stamped, assigned to a fleet driver,
  -- or offered to one. Offered-but-not-accepted demand stays visible. A request
  -- nobody from this fleet was offered is not this fleet's demand.
  with rides as (
    select r.*
    from rides.ride_requests r
    where (
      r.organization_id::text = p_org
      or exists (
        select 1 from public.driver_profiles dp
        where dp.user_id = r.assigned_driver_user_id
          and dp.mode = 'fleet'
          and dp.fleet_id::text = p_org
      )
      or exists (
        select 1
        from rides.driver_offers o
        join public.driver_profiles dp on dp.user_id = o.driver_user_id
        where o.ride_request_id = r.id
          and dp.mode = 'fleet'
          and dp.fleet_id::text = p_org
      )
    )
    and (nullif(f->>'startDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date >= (f->>'startDate')::date)
    and (nullif(f->>'endDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date <= (f->>'endDate')::date)
  ),
  marked as (
    select
      r.status,
      (
        r.organization_id::text = p_org
        or exists (
          select 1 from public.driver_profiles dp
          where dp.user_id = r.assigned_driver_user_id
            and dp.mode = 'fleet'
            and dp.fleet_id::text = p_org
        )
      ) as belongs,
      exists (
        select 1
        from rides.driver_offers o
        join public.driver_profiles dp on dp.user_id = o.driver_user_id
        where o.ride_request_id = r.id
          and dp.mode = 'fleet'
          and dp.fleet_id::text = p_org
      ) as offered_here,
      exists (select 1 from rides.driver_offers o where o.ride_request_id = r.id) as had_any_offer,
      r.cancelled_by,
      r.cancel_reason
    from rides r
  )
  select
    count(*),
    count(*) filter (where offered_here or (belongs and had_any_offer)),
    count(*) filter (where belongs and status in ('driver_assigned', 'driver_en_route_pickup', 'driver_arrived_pickup', 'on_trip', 'completed')),
    count(*) filter (where belongs and status in ('driver_arrived_pickup', 'on_trip', 'completed')),
    count(*) filter (where belongs and status in ('on_trip', 'completed')),
    count(*) filter (where belongs and status = 'completed')
  into requested, offered, accepted, arrived, started, completed
  from marked;

  select coalesce(jsonb_agg(jsonb_build_object('reason', reason, 'count', n) order by n desc), '[]'::jsonb)
  into reasons
  from (
    select coalesce(nullif(r.cancel_reason, ''), 'unmatched') as reason, count(*) as n
    from rides.ride_requests r
    where r.status = 'cancelled'
      and r.cancelled_by = 'system'
      and (
        r.organization_id::text = p_org
        or exists (
          select 1 from public.driver_profiles dp
          where dp.user_id = r.assigned_driver_user_id
            and dp.mode = 'fleet'
            and dp.fleet_id::text = p_org
        )
        or exists (
          select 1
          from rides.driver_offers o
          join public.driver_profiles dp on dp.user_id = o.driver_user_id
          where o.ride_request_id = r.id
            and dp.mode = 'fleet'
            and dp.fleet_id::text = p_org
        )
      )
      and (nullif(f->>'startDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date >= (f->>'startDate')::date)
      and (nullif(f->>'endDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date <= (f->>'endDate')::date)
    group by 1
  ) u;

  -- Same request set as the counts above. A missing timestamp stays null.
  with rides as (
    select r.*
    from rides.ride_requests r
    where (
      r.organization_id::text = p_org
      or exists (
        select 1 from public.driver_profiles dp
        where dp.user_id = r.assigned_driver_user_id
          and dp.mode = 'fleet'
          and dp.fleet_id::text = p_org
      )
      or exists (
        select 1
        from rides.driver_offers o
        join public.driver_profiles dp on dp.user_id = o.driver_user_id
        where o.ride_request_id = r.id
          and dp.mode = 'fleet'
          and dp.fleet_id::text = p_org
      )
    )
    and (nullif(f->>'startDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date >= (f->>'startDate')::date)
    and (nullif(f->>'endDate', '') is null or (r.created_at at time zone 'America/Jamaica')::date <= (f->>'endDate')::date)
  )
  select
    round((percentile_cont(0.5) within group (order by offered_min))::numeric, 1),
    round((percentile_cont(0.5) within group (order by accepted_min))::numeric, 1),
    round((percentile_cont(0.5) within group (order by arrived_min))::numeric, 1),
    round((percentile_cont(0.5) within group (order by started_min))::numeric, 1),
    round((percentile_cont(0.5) within group (order by completed_min))::numeric, 1)
  into offered_med, accepted_med, arrived_med, started_med, completed_med
  from (
    select
      case
        when off.first_offer is not null and r.created_at is not null and off.first_offer >= r.created_at
        then extract(epoch from (off.first_offer - r.created_at)) / 60.0
      end as offered_min,
      case
        when r.en_route_at is not null and r.created_at is not null and r.en_route_at >= r.created_at
        then extract(epoch from (r.en_route_at - r.created_at)) / 60.0
      end as accepted_min,
      case
        when r.arrived_pickup_at is not null and r.en_route_at is not null and r.arrived_pickup_at >= r.en_route_at
        then extract(epoch from (r.arrived_pickup_at - r.en_route_at)) / 60.0
      end as arrived_min,
      case
        when r.trip_started_at is not null and r.arrived_pickup_at is not null and r.trip_started_at >= r.arrived_pickup_at
        then extract(epoch from (r.trip_started_at - r.arrived_pickup_at)) / 60.0
      end as started_min,
      case
        when r.completed_at is not null and r.trip_started_at is not null and r.completed_at >= r.trip_started_at
        then extract(epoch from (r.completed_at - r.trip_started_at)) / 60.0
      end as completed_min
    from rides r
    left join lateral (
      select min(o.created_at) as first_offer
      from rides.driver_offers o
      join public.driver_profiles dp on dp.user_id = o.driver_user_id
      where o.ride_request_id = r.id
        and dp.mode = 'fleet'
        and dp.fleet_id::text = p_org
    ) off on true
  ) gaps;

  return jsonb_build_object(
    'requested', requested,
    'offered', offered,
    'accepted', accepted,
    'arrived', arrived,
    'started', started,
    'completed', completed,
    'stageMinutes', jsonb_build_object(
      'offered', offered_med,
      'accepted', accepted_med,
      'arrived', arrived_med,
      'started', started_med,
      'completed', completed_med
    ),
    'unmatched', reasons,
    'empty', completed = 0
  );
end;
$$;


ALTER FUNCTION "fleet"."roam_ride_funnel"("p_org" "text", "f" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."scan_toll_low_balances"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $_$
DECLARE
  v_org text;
  v_default numeric;
  r record;
  v_threshold numeric;
  v_balance numeric;
  v_known boolean;
  v_requested text;
  v_alert_key text;
  n integer := 0;
BEGIN
  FOR v_org IN
    SELECT DISTINCT organization_id FROM fleet.toll_tags WHERE organization_id IS NOT NULL
  LOOP
    SELECT NULLIF(s.payload_json->>'tollLowBalanceDefaultJmd', '')::numeric INTO v_default
    FROM fleet.organization_settings s WHERE s.organization_id = v_org ORDER BY s.updated_at DESC LIMIT 1;
    FOR r IN
      SELECT t.id, t.payload_json, b.ledger_count, b.balance
      FROM fleet.toll_tags t
      LEFT JOIN fleet.toll_tag_balance_rows(v_org) b ON b.tag_id = t.id
      WHERE t.organization_id = v_org
        AND coalesce(t.payload_json->>'status', '') NOT IN ('Retired', 'Inactive')
    LOOP
      v_threshold := COALESCE(NULLIF(r.payload_json->>'lowBalanceThreshold', '')::numeric, v_default, 500);
      IF COALESCE(r.ledger_count, 0) > 0 THEN
        v_balance := r.balance;
        v_known := true;
        UPDATE fleet.toll_tags
        SET payload_json = payload_json || jsonb_build_object('lastCalculatedBalance', v_balance, 'lastBalanceSyncedAt', now())
        WHERE id = r.id;
      ELSIF (r.payload_json->>'lastCalculatedBalance') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        v_balance := (r.payload_json->>'lastCalculatedBalance')::numeric;
        v_known := true;
      ELSE
        v_balance := NULL;
        v_known := false;
      END IF;
      v_requested := coalesce(r.payload_json->>'topupRequestedAt', '');
      v_alert_key := 'alert:toll-low:' || v_org || ':' || r.id;
      IF v_known AND v_balance IS NOT NULL AND v_balance < v_threshold AND v_requested = '' THEN
        BEGIN
          INSERT INTO public.kv_store_37f42386 (key, value)
          VALUES (v_alert_key, jsonb_build_object(
            'id', 'toll-low:' || r.id, 'orgId', v_org, 'organizationId', v_org,
            'type', 'toll_low_balance',
            'severity', CASE WHEN v_balance <= 0 THEN 'warning' ELSE 'info' END,
            'title', 'Toll tag needs a top-up',
            'body', 'Tag ' || coalesce(r.payload_json->>'tagNumber', r.id) || ' is at J$' || trim(to_char(v_balance, 'FM999999990.00')) || ', under the J$' || trim(to_char(v_threshold, 'FM999999990')) || ' alert.',
            'createdAt', now(), 'read', false
          ))
          ON CONFLICT (key) DO NOTHING;
        EXCEPTION WHEN undefined_table THEN NULL;
        END;
        n := n + 1;
      ELSE
        BEGIN
          DELETE FROM public.kv_store_37f42386 WHERE key = v_alert_key;
        EXCEPTION WHEN undefined_table THEN NULL;
        END;
        IF v_known AND v_balance IS NOT NULL AND v_balance >= v_threshold AND v_requested <> '' THEN
          UPDATE fleet.toll_tags SET payload_json = payload_json - 'topupRequestedAt' WHERE id = r.id;
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN n;
END;
$_$;


ALTER FUNCTION "fleet"."scan_toll_low_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."score_master_data"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public', 'places', 'geo'
    AS $$
declare
  total int;
  failing int;
  score int;
  note text;
  boundary_total int;
  boundary_fail int;
  place_total int;
  place_fail int;
begin
  select count(*) into total from fleet.stations;
  select count(*) into failing from fleet.station_quality where not coalesce(complete, false);
  if total = 0 then
    score := null; note := 'Not scored yet'; failing := 0;
  else
    score := ((total - failing) * 100) / total; note := null;
  end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('stations', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;

  select count(*) into total from fleet.toll_plazas;
  select count(*) into failing from fleet.toll_plazas
    where name is null or lat is null or lng is null;
  if total = 0 then score := null; note := 'Not scored yet'; failing := 0;
  else score := ((total - failing) * 100) / total; note := null; end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('tolls', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;

  select count(*) into total from fleet.platform_vendors;
  select count(*) into failing from fleet.platform_vendors
    where name is null or publish_state is null;
  if total = 0 then score := null; note := 'Not scored yet'; failing := 0;
  else score := ((total - failing) * 100) / total; note := null; end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('vendors', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;

  if to_regclass('public.vehicle_catalog') is null then
    total := 0;
  else
    execute 'select count(*) from public.vehicle_catalog' into total;
    execute 'select count(*) from public.vehicle_catalog where make is null or model is null' into failing;
  end if;
  if total = 0 then score := null; note := 'Not scored yet'; failing := 0;
  else score := ((total - failing) * 100) / total; note := null; end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('vehicles', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;

  boundary_total := 0;
  boundary_fail := 0;
  place_total := 0;
  place_fail := 0;
  if to_regclass('geo.boundaries') is not null then
    select count(*) into boundary_total from geo.boundaries;
    select count(*) into boundary_fail
    from geo.boundaries b
    where not exists (
      select 1
      from geo.boundary_versions v
      where v.id = b.current_version_id
        and v.status = 'published'
        and v.geom is not null
    );
  end if;
  if to_regclass('geo.places') is not null then
    select count(*) into place_total from geo.places;
    select count(*) into place_fail from geo.places
      where name is null or lat is null or lng is null;
  end if;
  total := boundary_total + place_total;
  failing := boundary_fail + place_fail;
  if total = 0 then score := null; note := 'Not scored yet'; failing := 0;
  else score := ((total - failing) * 100) / total; note := null; end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('maps', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;

  if to_regclass('public.gct_rates') is null then
    total := 0; failing := 0;
  else
    execute 'select count(*) from public.gct_rates' into total;
    execute 'select count(*) from public.gct_rates where supply_class is null or rate_percent is null or effective_from is null' into failing;
  end if;
  if total = 0 then score := null; note := 'Not scored yet'; failing := 0;
  else score := ((total - failing) * 100) / total; note := null; end if;
  insert into fleet.dataset_quality (dataset, score, failing, checked_at, note)
  values ('gct_rates', score, failing, now(), note)
  on conflict (dataset) do update
    set score = excluded.score, failing = excluded.failing, checked_at = excluded.checked_at, note = excluded.note;
end;
$$;


