CREATE OR REPLACE FUNCTION "fleet"."trip_bool"("v" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case lower(btrim(coalesce(v, '')))
    when 'true' then true
    when '1' then true
    when 'false' then false
    when '0' then false
    else null
  end;
$$;


