CREATE OR REPLACE FUNCTION "fleet"."trip_fact_page"("p_org" "text", "f" "jsonb", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'local_date'::"text", "p_asc" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_limit int := least(greatest(coalesce(p_limit, 50), 1), 10000);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_sort text := case p_sort
    when 'amount' then 'amount'
    when 'distance_km' then 'distance_km'
    when 'duration_min' then 'duration_min'
    when 'platform' then 'platform'
    when 'status_bucket' then 'status_bucket'
    when 'trip_id' then 'trip_id'
    else 'local_date'
  end;
  v_floor numeric := 5000;
  v_fpk numeric := 500;
  v_long_km numeric := 100;
  v_long_min numeric := 180;
  v_speed_high numeric := 120;
  v_speed_low numeric := 3;
  v_speed_km numeric := 2;
  v_gps_m numeric := 50;
  p99map jsonb := '{}'::jsonb;
  total_n bigint;
  rows jsonb;
begin
  select
    coalesce(s.fare_floor, 5000), coalesce(s.fare_per_km_max, 500), coalesce(s.long_distance_km, 100),
    coalesce(s.long_duration_min, 180), coalesce(s.speed_high_kmh, 120), coalesce(s.speed_low_kmh, 3),
    coalesce(s.speed_low_min_km, 2), coalesce(s.gps_equal_meters, 50)
  into v_floor, v_fpk, v_long_km, v_long_min, v_speed_high, v_speed_low, v_speed_km, v_gps_m
  from fleet.trip_analytics_settings s
  where s.organization_id = p_org;
  if v_floor is null then
    v_floor := 5000; v_fpk := 500; v_long_km := 100; v_long_min := 180;
    v_speed_high := 120; v_speed_low := 3; v_speed_km := 2; v_gps_m := 50;
  end if;

  select coalesce(jsonb_object_agg(platform, jsonb_build_object('p99', p99, 'med', med)), '{}'::jsonb)
  into p99map
  from (
    select platform,
      percentile_cont(0.99) within group (order by amount) as p99,
      percentile_cont(0.5) within group (order by amount) as med
    from fleet.trip_facts_matching(p_org, f)
    where status_bucket = 'completed' and amount is not null and platform is not null
    group by platform
  ) s;

  select count(*) into total_n from fleet.trip_facts_matching(p_org, f);
  execute format(
    'select coalesce(jsonb_agg(row_to_json(page)::jsonb), ''[]''::jsonb) from (
       select trip_id,
         coalesce((
           select array_agg(flag)
           from unnest(fleet.trip_live_anomaly_flags(
             t::fleet.trip_facts, $6, $7, $8, $9, $10, $11, $12, $13,
             nullif($14 -> coalesce(t.platform, '''') ->> ''p99'', '''')::numeric,
             nullif($14 -> coalesce(t.platform, '''') ->> ''med'', '''')::numeric
           )) as flag
           where not exists (
             select 1 from fleet.trip_anomaly_reviews r
             where r.organization_id = $1 and r.trip_id = t.trip_id and r.rule = flag and r.action = ''dismiss''
           )
         ), ''{}''::text[]) as anomaly_flags,
         cancel_actor, local_date, platform, amount
       from fleet.trip_facts_matching($1, $2) t
       where (
         nullif($2->>''cursorDate'', '''') is null
         or ($3 = false and (t.local_date, t.trip_id) < (($2->>''cursorDate'')::date, $2->>''cursorId''))
         or ($3 = true and (t.local_date, t.trip_id) > (($2->>''cursorDate'')::date, $2->>''cursorId''))
       )
       order by %I %s nulls last, trip_id %s
       limit $4 offset $5
     ) page',
    v_sort,
    case when p_asc then 'asc' else 'desc' end,
    case when p_asc then 'asc' else 'desc' end
  )
  into rows
  using p_org, f, p_asc, v_limit, v_offset,
    v_floor, v_fpk, v_long_km, v_long_min, v_speed_high, v_speed_low, v_speed_km, v_gps_m, p99map;

  return jsonb_build_object('total', total_n, 'rows', rows);
end;
$_$;


ALTER FUNCTION "fleet"."trip_fact_page"("p_org" "text", "f" "jsonb", "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_asc" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_facts_fill_statement_components"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
declare
  p jsonb;
  amt numeric;
  base numeric;
  surge numeric;
  wait_n numeric;
  stop_n numeric;
  tips numeric;
  cancel_n numeric;
  other_n numeric;
  priority_n numeric;
begin
  select payload_json, amount into p, amt
  from fleet.trips
  where id = new.trip_id;
  if p is null then
    return new;
  end if;

  base := fleet.trip_num(p#>>'{fareBreakdown,baseFare}');
  surge := fleet.trip_num(p#>>'{fareBreakdown,surge}');
  wait_n := fleet.trip_num(p#>>'{fareBreakdown,waitTime}');
  stop_n := fleet.trip_num(p#>>'{fareBreakdown,timeAtStop}');
  tips := coalesce(fleet.trip_num(p->>'uberTips'), fleet.trip_num(p#>>'{fareBreakdown,tips}'));
  cancel_n := coalesce(fleet.trip_num(p->>'cancellationFare'), fleet.trip_num(p#>>'{fareBreakdown,cancellation}'));
  other_n := fleet.trip_num(p#>>'{fareBreakdown,other}');
  priority_n := fleet.trip_num(p#>>'{fareBreakdown,priority}');

  if priority_n is null
     and new.platform = 'Uber'
     and (base is not null or surge is not null or wait_n is not null or stop_n is not null or cancel_n is not null) then
    priority_n := coalesce(amt, 0)
      - coalesce(base, 0) - coalesce(surge, 0) - coalesce(wait_n, 0)
      - coalesce(stop_n, 0) - coalesce(tips, 0) - coalesce(cancel_n, 0) - coalesce(other_n, 0);
  end if;

  new.fare_time_at_stop := stop_n;
  new.fare_cancellation := cancel_n;
  new.fare_priority := priority_n;
  new.fare_other := other_n;
  new.toll_refund := coalesce(fleet.trip_num(p->>'uberRefundExpenseAmount'), fleet.trip_num(p->>'tollCharges'));
  new.cash_collected := fleet.trip_num(p->>'cashCollected');
  if tips is not null then
    new.fare_tips := tips;
  end if;

  if new.platform in ('Roam', 'GoRide') and new.net_to_driver is null then
    new.net_to_driver := coalesce(amt, 0)
      - coalesce(fleet.trip_num(p->>'roamCommission'), fleet.trip_num(p->>'platformFee'), 0);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "fleet"."trip_facts_fill_statement_components"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_facts_matching"("p_org" "text", "f" "jsonb") RETURNS SETOF "fleet"."trip_facts"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select t.*
  from fleet.trip_facts t
  where t.organization_id = p_org
    and (
      coalesce(f->>'population', 'rideshare') = 'all'
      or t.analytics_population = coalesce(nullif(f->>'population', ''), 'rideshare')
    )
    and (nullif(f->>'startDate', '') is null or t.local_date >= (f->>'startDate')::date)
    and (nullif(f->>'endDate', '') is null or t.local_date <= (f->>'endDate')::date)
    and (
      f->'platforms' is null
      or jsonb_typeof(f->'platforms') <> 'array'
      or jsonb_array_length(f->'platforms') = 0
      or t.platform in (select jsonb_array_elements_text(f->'platforms'))
    )
    and (nullif(f->>'platform', '') is null or t.platform = f->>'platform')
    and (nullif(f->>'serviceLine', '') is null or t.service_line = f->>'serviceLine')
    and (
      f->'driverIds' is null
      or jsonb_typeof(f->'driverIds') <> 'array'
      or jsonb_array_length(f->'driverIds') = 0
      or t.driver_id in (select jsonb_array_elements_text(f->'driverIds'))
    )
    and (nullif(f->>'driverId', '') is null or t.driver_id = f->>'driverId')
    and (
      f->'vehicleIds' is null
      or jsonb_typeof(f->'vehicleIds') <> 'array'
      or jsonb_array_length(f->'vehicleIds') = 0
      or t.vehicle_id in (select jsonb_array_elements_text(f->'vehicleIds'))
    )
    and (nullif(f->>'vehicleId', '') is null or t.vehicle_id = f->>'vehicleId')
    and (nullif(f->>'status', '') is null or t.status_bucket = f->>'status')
    and (
      nullif(f->>'paymentMethod', '') is null
      or (f->>'paymentMethod' = 'cash' and lower(coalesce(t.payment_method, '')) = 'cash')
      or (f->>'paymentMethod' = 'digital' and lower(coalesce(t.payment_method, '')) is distinct from 'cash')
    )
    and (
      nullif(f->>'zone', '') is null
      or t.pickup_zone = f->>'zone'
      or t.dropoff_zone = f->>'zone'
    )
    and (f->>'isManual' is null or t.is_manual = (f->>'isManual')::boolean)
    and (nullif(f->>'hour', '') is null or t.local_hour = (f->>'hour')::int)
    and (nullif(f->>'dow', '') is null or t.local_dow = (f->>'dow')::int)
    and (nullif(f->>'minEarnings', '') is null or t.amount >= (f->>'minEarnings')::numeric)
    and (nullif(f->>'maxEarnings', '') is null or t.amount <= (f->>'maxEarnings')::numeric)
    and (nullif(f->>'minDistance', '') is null or t.distance_km >= (f->>'minDistance')::numeric)
    and (f->>'hasTip' is null or t.has_tip = (f->>'hasTip')::boolean)
    and (f->>'hasSurge' is null or t.has_surge = (f->>'hasSurge')::boolean)
    and (nullif(f->>'anchorPeriodId', '') is null or t.anchor_period_id = f->>'anchorPeriodId');
$$;


ALTER FUNCTION "fleet"."trip_facts_matching"("p_org" "text", "f" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_facts_parity"("p_org" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'trips', (select count(*) from fleet.trips where organization_id = p_org),
    'facts', (select count(*) from fleet.trip_facts where organization_id = p_org),
    'tripAmount', (select coalesce(sum(amount), 0) from fleet.trips where organization_id = p_org),
    'factAmount', (select coalesce(sum(amount), 0) from fleet.trip_facts where organization_id = p_org),
    'ok', (
      (select count(*) from fleet.trips where organization_id = p_org)
      = (select count(*) from fleet.trip_facts where organization_id = p_org)
      and (select coalesce(sum(amount), 0) from fleet.trips where organization_id = p_org)
        is not distinct from (select coalesce(sum(amount), 0) from fleet.trip_facts where organization_id = p_org)
    )
  );
$$;


ALTER FUNCTION "fleet"."trip_facts_parity"("p_org" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_kpi_block"("p_org" "text", "f" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_completed bigint;
  v_cancelled bigint;
  v_progress bigint;
  v_total bigint;
  v_gross numeric;
  v_cancel_fees numeric;
  v_sum_amount numeric;
  v_sum_net numeric;
  v_net_known bigint;
  v_net_unknown bigint;
  v_cash numeric;
  v_cash_trips bigint;
  v_median numeric;
  v_fare_num numeric;
  v_dist_sum numeric;
  v_dist_n bigint;
  v_avg_dist numeric;
  v_avg_dur numeric;
  v_dur_n bigint;
  v_fee numeric;
  v_time_unknown bigint;
  s date;
  e date;
  len int;
  i int;
  b0 date;
  b1 date;
  spark numeric[] := array[]::numeric[];
  bucket_count numeric;
begin
  select
    count(*) filter (where status_bucket = 'completed'),
    count(*) filter (where status_bucket = 'cancelled'),
    count(*) filter (where status_bucket = 'in_progress'),
    count(*),
    coalesce(sum(amount) filter (where status_bucket = 'completed'), 0),
    coalesce(sum(amount) filter (where status_bucket = 'cancelled'), 0),
    coalesce(sum(amount), 0),
    coalesce(sum(net_to_driver) filter (where net_to_driver is not null), 0),
    count(*) filter (where net_to_driver is not null),
    count(*) filter (where net_to_driver is null),
    coalesce(sum(cash_collected_abs) filter (where status_bucket = 'completed'), 0),
    count(*) filter (where status_bucket = 'completed' and lower(coalesce(payment_method, '')) = 'cash'),
    percentile_cont(0.5) within group (order by amount) filter (where status_bucket = 'completed' and amount is not null),
    coalesce(sum(amount) filter (where status_bucket = 'completed' and coalesce(distance_km, 0) > 0), 0),
    coalesce(sum(distance_km) filter (where status_bucket = 'completed' and coalesce(distance_km, 0) > 0), 0),
    count(*) filter (where status_bucket = 'completed' and coalesce(distance_km, 0) > 0),
    avg(distance_km) filter (where status_bucket = 'completed' and coalesce(distance_km, 0) > 0),
    avg(duration_min) filter (where status_bucket = 'completed' and coalesce(duration_min, 0) > 0),
    count(*) filter (where status_bucket = 'completed' and coalesce(duration_min, 0) > 0),
    coalesce(sum(platform_fee) filter (where status_bucket = 'completed' and platform_fee is not null), 0),
    count(*) filter (where time_unknown)
  into
    v_completed, v_cancelled, v_progress, v_total, v_gross, v_cancel_fees, v_sum_amount,
    v_sum_net, v_net_known, v_net_unknown, v_cash, v_cash_trips, v_median,
    v_fare_num, v_dist_sum, v_dist_n, v_avg_dist, v_avg_dur, v_dur_n, v_fee, v_time_unknown
  from fleet.trip_facts_matching(p_org, f);

  s := nullif(f->>'startDate', '')::date;
  e := nullif(f->>'endDate', '')::date;
  if s is null or e is null then
    select min(local_date), max(local_date) into s, e from fleet.trip_facts_matching(p_org, f);
  end if;
  if s is not null and e is not null and e >= s then
    len := greatest(1, (e - s) + 1);
    for i in 0..6 loop
      b0 := s + floor(i * len / 7.0)::int;
      b1 := s + floor((i + 1) * len / 7.0)::int - 1;
      if b1 < b0 then b1 := b0; end if;
      select count(*) into bucket_count
      from fleet.trip_facts_matching(p_org, f) t
      where t.status_bucket = 'completed'
        and t.local_date between b0 and b1;
      spark := spark || bucket_count;
    end loop;
  end if;

  return jsonb_build_object(
    'completed', v_completed,
    'cancelled', v_cancelled,
    'inProgress', v_progress,
    'total', v_total,
    'grossFares', v_gross,
    'cancelFees', v_cancel_fees,
    'sumAmount', v_sum_amount,
    'sumNet', v_sum_net,
    'netKnownCount', v_net_known,
    'netUnknownCount', v_net_unknown,
    'cashCollected', v_cash,
    'cashTrips', v_cash_trips,
    'cashShare', case when v_completed > 0 then v_cash_trips::numeric / v_completed else null end,
    'avgFare', case when v_completed > 0 then v_gross / v_completed else null end,
    'medianFare', v_median,
    'farePerKm', case when v_dist_sum > 0 then v_fare_num / v_dist_sum else null end,
    'distanceTrips', v_dist_n,
    'distanceKm', v_dist_sum,
    'avgDistance', v_avg_dist,
    'avgDuration', v_avg_dur,
    'durationTrips', v_dur_n,
    'platformFee', v_fee,
    'timeUnknown', v_time_unknown,
    'cancellationRate', case when (v_completed + v_cancelled) > 0 then v_cancelled::numeric / (v_completed + v_cancelled) else null end,
    'sparkline', to_jsonb(spark)
  );
end;
$$;


ALTER FUNCTION "fleet"."trip_kpi_block"("p_org" "text", "f" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_live_anomaly_flags"("b" "fleet"."trip_facts", "p_floor" numeric, "p_fpk" numeric, "p_long_km" numeric, "p_long_min" numeric, "p_speed_high" numeric, "p_speed_low" numeric, "p_speed_km" numeric, "p_gps_m" numeric, "p_p99" numeric, "p_med" numeric) RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when b.status_bucket is distinct from 'completed' then '{}'::text[]
    else coalesce(array_remove(array[
      case when coalesce(b.amount, 0) = 0 then 'zero_fare' end,
      case when b.distance_km is null or b.distance_km = 0 then 'zero_distance' end,
      case when b.distance_km > p_long_km then 'long_distance' end,
      case when b.duration_min > p_long_min then 'long_duration' end,
      case when b.amount > greatest(p_floor, coalesce(p_p99, 0) * 1.5) then 'fare_outlier' end,
      case when coalesce(b.distance_km, 0) >= 2 and b.amount / nullif(b.distance_km, 0) > p_fpk then 'fare_per_km' end,
      case when coalesce(b.duration_min, 0) > 0 and coalesce(b.distance_km, 0) > 0
        and (b.distance_km / (b.duration_min / 60.0)) > p_speed_high then 'speed_high' end,
      case when coalesce(b.duration_min, 0) > 0 and coalesce(b.distance_km, 0) > p_speed_km
        and (b.distance_km / (b.duration_min / 60.0)) < p_speed_low then 'speed_low' end,
      case when b.request_at is not null and exists (
        select 1 from fleet.trip_facts o
        where o.organization_id = b.organization_id
          and o.driver_id = b.driver_id
          and o.request_at = b.request_at
          and o.trip_id <> b.trip_id
          and o.status_bucket = 'completed'
      ) then 'duplicate' end,
      case when b.time_unknown then 'missing_time' end,
      case when b.vehicle_id is null then 'missing_vehicle' end,
      case when b.pickup_lat is not null and b.dropoff_lat is not null
        and fleet.haversine_km(b.pickup_lat, b.pickup_lng, b.dropoff_lat, b.dropoff_lng) * 1000 < p_gps_m
        and b.amount > 2 * coalesce(p_med, b.amount) then 'gps_equal' end
    ], null), '{}'::text[])
  end;
$$;


ALTER FUNCTION "fleet"."trip_live_anomaly_flags"("b" "fleet"."trip_facts", "p_floor" numeric, "p_fpk" numeric, "p_long_km" numeric, "p_long_min" numeric, "p_speed_high" numeric, "p_speed_low" numeric, "p_speed_km" numeric, "p_gps_m" numeric, "p_p99" numeric, "p_med" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_num"("v" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when v is null or btrim(v) = '' then null
    when btrim(v) ~ '^-?[0-9]+(\.[0-9]+)?$' then btrim(v)::numeric
    else null
  end;
$_$;


ALTER FUNCTION "fleet"."trip_num"("v" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."trip_prior_window"("p_start" "date", "p_end" "date") RETURNS TABLE("prior_start" "date", "prior_end" "date")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  len int;
  prev_month date;
  day_n int;
  last_prev int;
begin
  if p_start is null or p_end is null or p_end < p_start then
    return;
  end if;
  -- same days of the previous month when the range starts on the 1st and stays in that month
  if extract(day from p_start) = 1
     and date_trunc('month', p_start) = date_trunc('month', p_end) then
    prev_month := (p_start - interval '1 month')::date;
    day_n := extract(day from p_end)::int;
    last_prev := extract(day from (date_trunc('month', prev_month) + interval '1 month - 1 day'))::int;
    prior_start := date_trunc('month', prev_month)::date;
    prior_end := (date_trunc('month', prev_month)::date + (least(day_n, last_prev) - 1));
    return next;
    return;
  end if;
  len := (p_end - p_start) + 1;
  prior_end := p_start - 1;
  prior_start := prior_end - (len - 1);
  return next;
end;
$$;


ALTER FUNCTION "fleet"."trip_prior_window"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."try_timestamptz"("p_text" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  IF p_text IS NULL OR btrim(p_text) = '' THEN
    RETURN NULL;
  END IF;
  RETURN p_text::timestamptz;
EXCEPTION
  WHEN others THEN
    RETURN NULL;
END;
$$;


ALTER FUNCTION "fleet"."try_timestamptz"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."unassign_toll_tag"("p_org" "text", "p_tag_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $$
DECLARE
  v_tag fleet.toll_tags%ROWTYPE;
  v_now timestamptz := now();
  v_vehicle_id text;
  v_payload jsonb;
  v_hist jsonb;
  v_veh_payload jsonb;
  v_vehicles jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_tag FROM fleet.toll_tags WHERE id = p_tag_id FOR UPDATE;
  IF NOT FOUND OR v_tag.organization_id IS DISTINCT FROM p_org THEN
    RAISE EXCEPTION 'tag_not_found' USING ERRCODE = 'P0002';
  END IF;
  v_payload := v_tag.payload_json;
  v_vehicle_id := nullif(v_payload->>'assignedVehicleId', '');
  IF v_vehicle_id IS NOT NULL THEN
    UPDATE fleet.toll_tag_assignments SET unassigned_at = v_now WHERE tag_id = p_tag_id AND vehicle_id = v_vehicle_id AND unassigned_at IS NULL;
    UPDATE fleet.vehicles v
    SET payload_json = (v.payload_json - 'tollTagId' - 'tollTagUuid' - 'tollTagProvider') || jsonb_build_object('updatedAt', v_now),
        toll_tag_id = NULL, updated_at = v_now
    WHERE v.id = v_vehicle_id AND v.organization_id = p_org
    RETURNING payload_json INTO v_veh_payload;
    IF v_veh_payload IS NOT NULL THEN
      v_vehicles := jsonb_build_array(jsonb_build_object('id', v_vehicle_id, 'kind', 'vehicle', 'payload', v_veh_payload));
    END IF;
  END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN elem->>'vehicleId' = v_vehicle_id AND coalesce(elem->>'unassignedAt', '') = '' THEN elem || jsonb_build_object('unassignedAt', v_now) ELSE elem END), '[]'::jsonb)
  INTO v_hist FROM jsonb_array_elements(coalesce(v_payload->'assignmentHistory', '[]'::jsonb)) elem;
  v_payload := (v_payload - 'assignedVehicleId' - 'assignedVehicleName') || jsonb_build_object('assignmentHistory', v_hist, 'updatedAt', v_now);
  UPDATE fleet.toll_tags SET payload_json = v_payload, vehicle_id = NULL, updated_at = v_now WHERE id = p_tag_id;
  RETURN jsonb_build_object('tag', v_payload, 'vehicles', v_vehicles);
END;
$$;


ALTER FUNCTION "fleet"."unassign_toll_tag"("p_org" "text", "p_tag_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."upsert_master"("p_table" "text", "p_row" "jsonb", "p_actor" "text", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
    AS $_$
declare
  col text;
  cols text := 'id';
  selects text := 'r.id';
  sets text := '';
begin
  if p_table not in ('stations', 'toll_plazas', 'platform_vendors') then
    raise exception 'unsupported master table %', p_table;
  end if;
  if p_row is null or not (p_row ? 'id') then
    raise exception 'master row needs id';
  end if;

  perform set_config('app.actor', coalesce(p_actor, ''), true);
  perform set_config('app.reason', coalesce(p_action, ''), true);

  for col in
    select c.column_name
    from information_schema.columns c
    where c.table_schema = 'fleet'
      and c.table_name = p_table
      and c.column_name <> 'id'
      and p_row ? c.column_name
  loop
    cols := cols || ', ' || quote_ident(col);
    selects := selects || ', r.' || quote_ident(col);
    if sets <> '' then
      sets := sets || ', ';
    end if;
    sets := sets || format('%I = excluded.%I', col, col);
  end loop;

  if sets = '' then
    execute format(
      'insert into fleet.%I (id) select r.id from jsonb_populate_record(null::fleet.%I, $1) as r on conflict (id) do nothing',
      p_table, p_table
    ) using p_row;
  else
    execute format(
      'insert into fleet.%I (%s) select %s from jsonb_populate_record(null::fleet.%I, $1) as r on conflict (id) do update set %s',
      p_table, cols, selects, p_table, sets
    ) using p_row;
  end if;
end;
$_$;


ALTER FUNCTION "fleet"."upsert_master"("p_table" "text", "p_row" "jsonb", "p_actor" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."void_expense_bill"("p_org" "text", "p_bill_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_bill_date date;
  v_week date;
BEGIN
  SELECT b.bill_date INTO v_bill_date FROM fleet.expense_bills b
  WHERE b.id = p_bill_id AND b.organization_id = p_org FOR UPDATE;
  IF v_bill_date IS NULL THEN
    RAISE EXCEPTION 'bill not found';
  END IF;
  v_week := v_bill_date - ((EXTRACT(ISODOW FROM v_bill_date)::int - 1));
  IF EXISTS (
    SELECT 1 FROM fleet.finance_period_locks AS locks
    WHERE locks.organization_id = p_org AND locks.week_start = v_week
  ) THEN
    RAISE EXCEPTION 'week locked';
  END IF;
  UPDATE fleet.expense_bills SET status = 'voided' WHERE id = p_bill_id;
END;
$$;


ALTER FUNCTION "fleet"."void_expense_bill"("p_org" "text", "p_bill_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fleet"."zone_for_trip"("p_area" "text", "p_lat" double precision, "p_lng" double precision) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select z.name
      from fleet.trip_zones z
      where p_area is not null
        and (lower(z.name) = p_area or p_area = any (z.aliases))
      limit 1
    ),
    (
      select z.name
      from fleet.trip_zones z
      where p_lat is not null
        and z.centroid_lat is not null
        and fleet.haversine_km(p_lat, p_lng, z.centroid_lat, z.centroid_lng) <= 3
      order by fleet.haversine_km(p_lat, p_lng, z.centroid_lat, z.centroid_lng)
      limit 1
    )
  );
$$;


ALTER FUNCTION "fleet"."zone_for_trip"("p_area" "text", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "freight"."accrue_storage_days"("p_on" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'freight'
    AS $$
DECLARE
  inserted INT := 0;
BEGIN
  INSERT INTO freight.warehouse_storage_ledger (
    warehouse_org_id,
    courier_org_id,
    package_id,
    event_type,
    quantity,
    unit_amount_minor,
    currency,
    occurred_on
  )
  SELECT
    p.operating_warehouse_org_id,
    p.owner_org_id,
    p.id,
    'storage_day',
    1,
    COALESCE((l.terms->>'per_day_minor')::bigint, 0),
    COALESCE(NULLIF(l.terms->>'currency', ''), 'USD'),
    p_on
  FROM freight.packages p
  JOIN freight.warehouse_courier_links l
    ON l.warehouse_org_id = p.operating_warehouse_org_id
   AND l.courier_org_id = p.owner_org_id
   AND l.status = 'active'
  WHERE p.operating_warehouse_org_id IS NOT NULL
    AND p.status = 'received_at_warehouse'
    AND COALESCE((l.terms->>'per_day_minor')::bigint, 0) > 0
    AND p_on > (
      COALESCE(
        (
          SELECT MIN(s.occurred_on)
          FROM freight.warehouse_storage_ledger s
          WHERE s.package_id = p.id AND s.event_type = 'receive'
        ),
        p.created_at::date
      ) + COALESCE((l.terms->>'free_days')::int, 0)
    )
    AND NOT EXISTS (
      SELECT 1
      FROM freight.warehouse_storage_ledger d
      WHERE d.package_id = p.id
        AND d.event_type = 'storage_day'
        AND d.occurred_on = p_on
    );

  GET DIAGNOSTICS inserted = ROW_COUNT;
  RETURN inserted;
END;
$$;


ALTER FUNCTION "freight"."accrue_storage_days"("p_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "freight"."org_has_active_link"("p_warehouse_org" "uuid", "p_courier_org" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'freight'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM freight.warehouse_courier_links l
    WHERE l.warehouse_org_id = p_warehouse_org
      AND l.courier_org_id = p_courier_org
      AND l.status = 'active'
  )
  OR p_warehouse_org = p_courier_org;
