CREATE OR REPLACE FUNCTION "geo"."border_area_change_pct"("p_pcode" "text", "p_version_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'public'
    AS $$
  SELECT CASE
    WHEN old.geom IS NULL OR ST_Area(old.geom::geography) = 0 THEN 0
    ELSE round((ST_Area(ST_SymDifference(old.geom, neu.geom)::geography) / ST_Area(old.geom::geography) * 100)::numeric, 1)
  END
  FROM geo.boundary_versions neu
  JOIN geo.boundaries b ON b.pcode = neu.pcode
  JOIN geo.boundary_versions old ON old.id = b.current_version_id
  WHERE neu.id = p_version_id AND neu.pcode = p_pcode;
$$;


ALTER FUNCTION "geo"."border_area_change_pct"("p_pcode" "text", "p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."commit_boundary_publish"("p_pcode" "text", "p_version_id" "uuid", "p_pending_generation" integer, "p_recompiled_markets" "uuid"[], "p_merchant_moves" "jsonb", "p_actor" "uuid", "p_impact" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  old_generation integer;
  place_name text;
  version_geom geometry;
  move jsonb;
  market_id uuid;
BEGIN
  SELECT active_generation INTO old_generation
  FROM delivery.coverage_state
  WHERE id = 1
  FOR UPDATE;

  SELECT v.geom, b.name INTO version_geom, place_name
  FROM geo.boundary_versions v
  JOIN geo.boundaries b ON b.pcode = v.pcode
  WHERE v.id = p_version_id
    AND v.pcode = p_pcode;
  IF version_geom IS NULL THEN
    RAISE EXCEPTION 'version_not_found';
  END IF;

  UPDATE geo.boundaries
  SET current_version_id = p_version_id, updated_at = now()
  WHERE pcode = p_pcode;

  UPDATE geo.boundary_versions
  SET status = 'retired'
  WHERE pcode = p_pcode
    AND id <> p_version_id
    AND status = 'published';

  UPDATE geo.boundary_versions
  SET status = 'published'
  WHERE id = p_version_id;

  UPDATE delivery.service_parishes sp
  SET
    adopted_geom = version_geom,
    adopted_version_id = p_version_id,
    adopted_at = now(),
    border_notice = 'Border updated by Roam Dominion · ' || place_name || ' v' ||
      (SELECT version FROM geo.boundary_versions WHERE id = p_version_id) || ' · ' ||
      to_char(now() AT TIME ZONE 'America/Jamaica', 'DD Mon')
  WHERE sp.pcode = p_pcode;

  UPDATE delivery.service_zone_polygons z
  SET
    geom = version_geom,
    polygon = CASE
      WHEN z.geom IS NOT NULL AND ST_Equals(z.geom, version_geom) THEN z.polygon
      ELSE delivery.geom_to_coverage_parts(version_geom)
    END,
    boundary_version_id = p_version_id,
    updated_at = now()
  WHERE z.boundary_pcode = p_pcode
    AND COALESCE(z.kind, 'include') = 'include';

  IF p_recompiled_markets IS NOT NULL THEN
    FOREACH market_id IN ARRAY p_recompiled_markets LOOP
      PERFORM delivery.refresh_market_net_coverage(market_id);
    END LOOP;
  END IF;

  IF p_recompiled_markets IS NOT NULL AND array_length(p_recompiled_markets, 1) IS NOT NULL THEN
    INSERT INTO delivery.coverage_cells (market_id, h3_cell, h3_res, kind, generation)
    SELECT c.market_id, c.h3_cell, c.h3_res, c.kind, p_pending_generation
    FROM delivery.coverage_cells c
    WHERE c.generation = old_generation
      AND NOT (c.market_id = ANY (p_recompiled_markets))
    ON CONFLICT DO NOTHING;

    UPDATE delivery.coverage_state
    SET active_generation = p_pending_generation
    WHERE id = 1;

    DELETE FROM delivery.coverage_cells
    WHERE generation = old_generation;
  END IF;

  IF p_merchant_moves IS NOT NULL AND jsonb_typeof(p_merchant_moves) = 'array' THEN
    FOR move IN SELECT * FROM jsonb_array_elements(p_merchant_moves)
    LOOP
      UPDATE delivery.merchants
      SET market_id = (move->>'market_id')::uuid
      WHERE id = (move->>'merchant_id')::uuid
        AND (move->>'market_id') IS NOT NULL;
    END LOOP;
  END IF;

  INSERT INTO geo.publish_log (pcode, version_id, actor_id, impact, status)
  VALUES (p_pcode, p_version_id, p_actor, COALESCE(p_impact, '{}'::jsonb), 'published');

  RETURN jsonb_build_object('ok', true, 'pcode', p_pcode, 'name', place_name);
END;
$$;


ALTER FUNCTION "geo"."commit_boundary_publish"("p_pcode" "text", "p_version_id" "uuid", "p_pending_generation" integer, "p_recompiled_markets" "uuid"[], "p_merchant_moves" "jsonb", "p_actor" "uuid", "p_impact" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."current_boundary"("p_pcode" "text", "p_level" smallint) RETURNS TABLE("pcode" "text", "admin_level" smallint, "parent_pcode" "text", "name" "text", "slug" "text", "center_lat" double precision, "center_lng" double precision, "geom" "public"."geometry", "source" "text", "source_version" "text", "valid_on" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'public'
    AS $$
  SELECT b.pcode, b.admin_level, b.parent_pcode, b.name, b.slug,
    b.center_lat, b.center_lng, v.geom, v.source, v.source_version, v.valid_on
  FROM geo.boundaries b
  JOIN geo.boundary_versions v ON v.id = b.current_version_id
  WHERE b.pcode = p_pcode
    AND (p_level IS NULL OR b.admin_level = p_level)
  LIMIT 1;
$$;


ALTER FUNCTION "geo"."current_boundary"("p_pcode" "text", "p_level" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."fare_tree"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(county_row ORDER BY county_row->>'slug'), '[]'::jsonb)
  FROM (
    SELECT jsonb_build_object(
      'slug', c.alias_value,
      'label', initcap(c.alias_value),
      'parishes', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'slug', fp.alias_value,
          'label', b.name,
          'pcode', b.pcode,
          'localities', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('slug', t.slug, 'label', t.name) ORDER BY t.name)
            FROM geo.boundaries t
            WHERE t.parent_pcode = b.pcode AND t.admin_level = 2 AND t.status = 'active'
          ), '[]'::jsonb)
        ) ORDER BY b.name)
        FROM geo.boundaries b
        JOIN geo.place_aliases fp ON fp.pcode = b.pcode AND fp.alias_kind = 'fare_parish'
        JOIN geo.place_aliases c2 ON c2.pcode = b.pcode AND c2.alias_kind = 'county' AND c2.alias_value = c.alias_value
        WHERE b.admin_level = 1
      ), '[]'::jsonb)
    ) AS county_row
    FROM (SELECT DISTINCT alias_value FROM geo.place_aliases WHERE alias_kind = 'county') c
  ) counties;
$$;


ALTER FUNCTION "geo"."fare_tree"() OWNER TO "postgres";


