CREATE OR REPLACE FUNCTION "geo"."list_shapes"("p_levels" integer[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.admin_level, s.name), '[]'::jsonb)
  FROM (
    SELECT b.pcode, b.admin_level, b.parent_pcode, b.name, b.slug, b.status, v.version, v.source, v.source_version, v.valid_on,
      b.center_lat, b.center_lng,
      delivery.display_rings_json(COALESCE(v.geom_display, delivery.simplify_boundary_display(v.geom))) AS rings
    FROM geo.boundaries b
    JOIN geo.boundary_versions v ON v.id = b.current_version_id
    WHERE b.status = 'active' AND (p_levels IS NULL OR b.admin_level = ANY (p_levels))
  ) s;
$$;


ALTER FUNCTION "geo"."list_shapes"("p_levels" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."preview_merchant_moves"("p_pcode" "text", "p_version_id" "uuid") RETURNS TABLE("merchant_id" "uuid", "lat" double precision, "lng" double precision, "market_id" "uuid", "market_is_active" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
  SELECT m.id, m.lat, m.lng, m.market_id, COALESCE(sm.is_active, false)
  FROM delivery.merchants m
  LEFT JOIN delivery.service_markets sm ON sm.id = m.market_id
  JOIN geo.boundaries b ON b.pcode = p_pcode
  JOIN geo.boundary_versions neu ON neu.id = p_version_id AND neu.pcode = p_pcode
  LEFT JOIN geo.boundary_versions old ON old.id = b.current_version_id
  WHERE b.current_version_id IS DISTINCT FROM p_version_id
    AND m.lat IS NOT NULL
    AND m.lng IS NOT NULL
    AND (
      ST_Covers(neu.geom, ST_SetSRID(ST_MakePoint(m.lng, m.lat), 4326))
      OR (
        old.geom IS NOT NULL
        AND ST_Covers(old.geom, ST_SetSRID(ST_MakePoint(m.lng, m.lat), 4326))
      )
    );
$$;


ALTER FUNCTION "geo"."preview_merchant_moves"("p_pcode" "text", "p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."resolve_fare_location"("p_lat" double precision, "p_lng" double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'geo', 'public'
    AS $$
DECLARE
  parish record;
  county_slug text;
  fare_parish text;
  locality text;
BEGIN
  SELECT b.pcode, b.name, b.slug INTO parish
  FROM geo.boundaries b
  JOIN geo.boundary_versions v ON v.id = b.current_version_id
  WHERE b.admin_level = 1 AND b.status = 'active'
    AND ST_Covers(v.geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
  ORDER BY ST_Area(v.geom::geography) ASC
  LIMIT 1;

  IF parish.pcode IS NULL THEN
    RETURN jsonb_build_object('location_key', 'jamaica', 'fallback_keys', jsonb_build_array('jamaica'));
  END IF;

  SELECT alias_value INTO county_slug FROM geo.place_aliases WHERE pcode = parish.pcode AND alias_kind = 'county' LIMIT 1;
  SELECT alias_value INTO fare_parish FROM geo.place_aliases WHERE pcode = parish.pcode AND alias_kind = 'fare_parish' LIMIT 1;
  fare_parish := COALESCE(fare_parish, parish.slug);

  SELECT b.slug INTO locality
  FROM geo.boundaries b
  JOIN geo.boundary_versions v ON v.id = b.current_version_id
  WHERE b.admin_level = 2 AND b.parent_pcode = parish.pcode AND b.status = 'active'
    AND ST_Covers(v.geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
  ORDER BY ST_Area(v.geom::geography) ASC
  LIMIT 1;

  RETURN jsonb_build_object(
    'county', county_slug,
    'parish', fare_parish,
    'locality', locality,
    'location_key', 'jamaica/' || COALESCE(county_slug, 'surrey') || '/' || fare_parish || CASE WHEN locality IS NULL THEN '' ELSE '/' || locality END
  );
END;
$$;


ALTER FUNCTION "geo"."resolve_fare_location"("p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."save_draft_border"("p_pcode" "text", "p_geojson" "jsonb", "p_notes" "text", "p_actor" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'delivery', 'public'
    AS $$
DECLARE
  next_version integer;
  new_id uuid;
  g geometry;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM geo.boundaries WHERE pcode = p_pcode) THEN
    RAISE EXCEPTION 'place_not_found';
  END IF;
  g := delivery.geojson_to_multipolygon(p_geojson);
  IF g IS NULL OR ST_IsEmpty(g) THEN
    RAISE EXCEPTION 'invalid_shape';
  END IF;
  SELECT COALESCE(MAX(version), 0) + 1 INTO next_version
  FROM geo.boundary_versions
  WHERE pcode = p_pcode;
  INSERT INTO geo.boundary_versions (pcode, version, geom, geom_display, source, notes, status, created_by)
  VALUES (
    p_pcode,
    next_version,
    g,
    delivery.simplify_boundary_display(g),
    'manual',
    COALESCE(p_notes, 'Drawn in World Maps'),
    'draft',
    p_actor
  )
  RETURNING id INTO new_id;
  RETURN new_id;
END;
$$;


ALTER FUNCTION "geo"."save_draft_border"("p_pcode" "text", "p_geojson" "jsonb", "p_notes" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "geo"."try_begin_publish"("p_holder" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'geo', 'public'
    AS $$
DECLARE
  got integer;
BEGIN
  IF p_holder IS NULL OR btrim(p_holder) = '' THEN
    RETURN false;
  END IF;

  UPDATE geo.publish_guard
  SET started_at = now(), holder = p_holder
  WHERE id = 1
    AND (
      started_at IS NULL
      OR started_at < now() - interval '10 minutes'
      OR holder = p_holder
    );

  GET DIAGNOSTICS got = ROW_COUNT;
  RETURN got = 1;
END;
$$;


ALTER FUNCTION "geo"."try_begin_publish"("p_holder" "text") OWNER TO "postgres";


