CREATE OR REPLACE FUNCTION "ledger"."_batch_totals_apply"("p_org" "uuid", "p_batch" "text", "p_driver" "uuid", "p_entry_type" "text", "p_count" bigint, "p_sum" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
declare
  v_driver uuid := ledger.driver_grain_id(p_driver);
begin
  if p_org is null or nullif(p_batch, '') is null or p_entry_type is null then
    return;
  end if;

  insert into ledger.batch_totals as t (
    organization_id, batch_id, driver_id, entry_type, entry_count, sum_minor
  ) values (
    p_org, p_batch, v_driver, p_entry_type, p_count, p_sum
  )
  on conflict (organization_id, batch_id, driver_id, entry_type)
  do update set
    entry_count = t.entry_count + excluded.entry_count,
    sum_minor = t.sum_minor + excluded.sum_minor;

  delete from ledger.batch_totals
  where organization_id = p_org
    and batch_id = p_batch
    and driver_id = v_driver
    and entry_type = p_entry_type
    and entry_count = 0;
end;
$$;


ALTER FUNCTION "ledger"."_batch_totals_apply"("p_org" "uuid", "p_batch" "text", "p_driver" "uuid", "p_entry_type" "text", "p_count" bigint, "p_sum" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_bump_org_version"("p_org" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
begin
  if p_org is null then
    return;
  end if;
  insert into ledger.org_version as o (organization_id, entry_seq, changed_at)
  values (p_org, 1, now())
  on conflict (organization_id) do update
    set entry_seq = o.entry_seq + 1, changed_at = now();
end;
$$;


ALTER FUNCTION "ledger"."_bump_org_version"("p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_ensure_account"("p_account_key" "text", "p_currency" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_role" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'auth'
    AS $$
DECLARE
  v_id UUID;
  v_class TEXT;
  v_owner_role TEXT;
  v_owner UUID := p_user_id;
BEGIN
  -- Orphaned historic driverIds must not block dual-write / backfill
  IF v_owner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = v_owner) THEN
    v_owner := NULL;
  END IF;

  SELECT id INTO v_id
  FROM ledger.accounts
  WHERE account_key = p_account_key AND currency = p_currency;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT account_class, owner_role INTO v_class, v_owner_role
  FROM ledger._infer_account_meta(p_account_key, v_owner, p_role);

  INSERT INTO ledger.accounts (
    organization_id, account_key, account_class, owner_user_id, owner_role, currency, balance_minor
  )
  VALUES (
    p_organization_id, p_account_key, v_class, v_owner, v_owner_role, p_currency, 0
  )
  ON CONFLICT (account_key, currency) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM ledger.accounts
    WHERE account_key = p_account_key AND currency = p_currency;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "ledger"."_ensure_account"("p_account_key" "text", "p_currency" "text", "p_organization_id" "uuid", "p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_gross_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case
    when nullif(p_metadata->>'grossAmount', '') ~ '^-?[0-9]+(\\.[0-9]+)?$'
      then round((p_metadata->>'grossAmount')::numeric * 100)::bigint
    else abs(p_amount_minor)
  end;
$_$;


ALTER FUNCTION "ledger"."_entry_gross_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_is_reversal"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select lower(coalesce(p_metadata->>'reversal', '')) in ('true', 't', '1');
$$;


ALTER FUNCTION "ledger"."_entry_is_reversal"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_page_meta"("p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select jsonb_build_object(
    'reversal', case when ledger._entry_is_reversal(p_metadata) then true else null end,
    'grossAmount', nullif(p_metadata->>'grossAmount', ''),
    'periodStart', nullif(p_metadata->>'periodStart', ''),
    'periodEnd', nullif(p_metadata->>'periodEnd', ''),
    'paymentMethod', nullif(p_metadata->>'paymentMethod', ''),
    'category', nullif(p_metadata->>'category', ''),
    'bankRole', nullif(p_metadata->>'bankRole', ''),
    'recipient', nullif(p_metadata->>'recipient', ''),
    'source', nullif(p_metadata->>'source', ''),
    'organizationUuid', nullif(p_metadata->>'organizationUuid', ''),
    'weekKey', nullif(p_metadata->>'weekKey', '')
  );
$$;


ALTER FUNCTION "ledger"."_entry_page_meta"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_reconciled"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select lower(coalesce(p_metadata->>'isReconciled', '')) in ('true', 't', '1');
$$;


ALTER FUNCTION "ledger"."_entry_reconciled"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_signed_gross_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when ledger._entry_is_reversal(p_metadata)
      then -abs(ledger._entry_gross_minor(p_metadata, p_amount_minor))
    else ledger._entry_gross_minor(p_metadata, p_amount_minor)
  end;
$$;


ALTER FUNCTION "ledger"."_entry_signed_gross_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_entry_signed_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when ledger._entry_is_reversal(p_metadata) then -abs(p_amount_minor)
    else p_amount_minor
  end;
$$;


ALTER FUNCTION "ledger"."_entry_signed_minor"("p_metadata" "jsonb", "p_amount_minor" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_infer_account_meta"("p_account_key" "text", "p_user_id" "uuid", "p_role" "text") RETURNS TABLE("account_class" "text", "owner_role" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
BEGIN
  IF p_account_key LIKE 'platform:fleet_%_expense' OR p_account_key = 'platform:write_off' THEN
    RETURN QUERY SELECT 'expense'::TEXT, 'system'::TEXT;
  ELSIF p_account_key IN (
    'platform:driver_reimbursement_payable',
    'platform:driver_payable',
    'platform:driver_cash_outlay',
    'platform:toll_tag_clearing',
    'platform:fuel_card_clearing'
  ) THEN
    RETURN QUERY SELECT 'liability'::TEXT, 'system'::TEXT;
  ELSIF p_account_key IN (
    'platform:receivable',
    'platform:clearing',
    'platform:driver_receivable',
    'platform:reimbursement_receivable',
    'platform:bank_clearing'
  ) THEN
    RETURN QUERY SELECT 'asset'::TEXT, 'system'::TEXT;
  ELSIF p_account_key LIKE 'platform:%' THEN
    RETURN QUERY SELECT 'asset'::TEXT, 'system'::TEXT;
  ELSIF p_account_key ~ '^user:[^:]+:rider$' THEN
    RETURN QUERY SELECT 'asset'::TEXT, 'rider'::TEXT;
  ELSIF p_account_key ~ '^user:[^:]+:driver' THEN
    RETURN QUERY SELECT 'asset'::TEXT, 'driver'::TEXT;
  ELSIF p_account_key LIKE 'org:%' THEN
    RETURN QUERY SELECT 'asset'::TEXT, NULL::TEXT;
  ELSIF p_account_key LIKE 'merchant:%' THEN
    RETURN QUERY SELECT 'asset'::TEXT, 'merchant'::TEXT;
  ELSIF p_account_key LIKE 'courier:%' THEN
    RETURN QUERY SELECT 'liability'::TEXT, 'courier'::TEXT;
  ELSE
    RETURN QUERY SELECT 'asset'::TEXT, COALESCE(p_role, NULL::TEXT);
  END IF;
END;
$_$;


ALTER FUNCTION "ledger"."_infer_account_meta"("p_account_key" "text", "p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_resolve_account_id"("p_account_key" "text", "p_currency" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'rides', 'public'
    AS $_$ DECLARE v_id UUID; v_user_id UUID; BEGIN IF p_account_key IN ('platform:receivable', 'platform:clearing') THEN RETURN ledger._ensure_account(p_account_key, p_currency, NULL, NULL, 'system'); END IF; IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:driver:(digital|cash|debt)$' THEN v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):driver:'))[1]::UUID; RETURN ledger._ensure_account(p_account_key, p_currency, NULL, v_user_id, 'driver'); END IF; IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:rider$' THEN v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):rider$'))[1]::UUID; RETURN ledger._ensure_account(p_account_key, p_currency, NULL, v_user_id, 'rider'); END IF; IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:driver$' THEN v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):driver$'))[1]::UUID; RETURN ledger._ensure_account(p_account_key, p_currency, NULL, v_user_id, 'driver'); END IF; IF p_account_key ~ '^org:([0-9a-fA-F-]{36}):' THEN RETURN ledger._ensure_account(p_account_key, p_currency, (regexp_match(p_account_key, '^org:([0-9a-fA-F-]{36}):'))[1]::UUID, NULL, NULL); END IF; IF p_account_key ~ '^merchant:([0-9a-fA-F-]{36}):' THEN v_user_id := (regexp_match(p_account_key, '^merchant:([0-9a-fA-F-]{36}):'))[1]::UUID; RETURN ledger._ensure_account(p_account_key, p_currency, NULL, v_user_id, 'merchant'); END IF; IF p_account_key ~ '^courier:([0-9a-fA-F-]{36}):' THEN v_user_id := (regexp_match(p_account_key, '^courier:([0-9a-fA-F-]{36}):'))[1]::UUID; RETURN ledger._ensure_account(p_account_key, p_currency, NULL, v_user_id, 'courier'); END IF; SELECT id INTO v_id FROM ledger.accounts WHERE account_key = p_account_key AND currency = p_currency; IF v_id IS NULL THEN RAISE EXCEPTION 'account_not_found:%', p_account_key; END IF; RETURN v_id; END; $_$;


ALTER FUNCTION "ledger"."_resolve_account_id"("p_account_key" "text", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."_week_totals_apply"("p_org" "uuid", "p_week" "date", "p_driver" "uuid", "p_product" "text", "p_entry_type" "text", "p_platform" "text", "p_direction" "text", "p_sum" bigint, "p_abs" bigint, "p_gross" bigint, "p_count" bigint, "p_recon" bigint, "p_last" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
declare
  v_driver uuid := ledger.driver_grain_id(p_driver);
begin
  if p_org is null or p_week is null or p_product is null or p_entry_type is null then
    return;
  end if;

  insert into ledger.week_totals as t (
    organization_id, week_start, driver_id, product, entry_type, platform, direction,
    sum_minor, abs_sum_minor, gross_minor, entry_count, reconciled_count, last_entry_at
  ) values (
    p_org, p_week, v_driver, p_product, p_entry_type,
    coalesce(p_platform, ''), coalesce(p_direction, 'inflow'),
    p_sum, p_abs, p_gross, p_count, p_recon, p_last
  )
  on conflict (organization_id, week_start, driver_id, product, entry_type, platform, direction)
  do update set
    sum_minor = t.sum_minor + excluded.sum_minor,
    abs_sum_minor = t.abs_sum_minor + excluded.abs_sum_minor,
    gross_minor = t.gross_minor + excluded.gross_minor,
    entry_count = t.entry_count + excluded.entry_count,
    reconciled_count = t.reconciled_count + excluded.reconciled_count,
    last_entry_at = greatest(t.last_entry_at, excluded.last_entry_at);

  delete from ledger.week_totals
  where organization_id = p_org
    and week_start = p_week
    and driver_id = v_driver
    and product = p_product
    and entry_type = p_entry_type
    and platform = coalesce(p_platform, '')
    and direction = coalesce(p_direction, 'inflow')
    and entry_count = 0;
end;
$$;


ALTER FUNCTION "ledger"."_week_totals_apply"("p_org" "uuid", "p_week" "date", "p_driver" "uuid", "p_product" "text", "p_entry_type" "text", "p_platform" "text", "p_direction" "text", "p_sum" bigint, "p_abs" bigint, "p_gross" bigint, "p_count" bigint, "p_recon" bigint, "p_last" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."driver_grain_id"("p_driver" "uuid") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(p_driver, '00000000-0000-0000-0000-000000000000'::uuid);
$$;


ALTER FUNCTION "ledger"."driver_grain_id"("p_driver" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."driver_page"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_driver_ids" "uuid"[], "p_entry_types" "text"[] DEFAULT NULL::"text"[], "p_products" "text"[] DEFAULT NULL::"text"[], "p_platform" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT NULL::"text", "p_after_effective_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "entry_type" "text", "product" "text", "amount_minor" bigint, "currency" "text", "effective_at" timestamp with time zone, "created_at" timestamp with time zone, "reference_type" "text", "reference_id" "text", "driver_id" "uuid", "platform" "text", "batch_id" "text", "direction" "text", "is_reconciled" boolean, "vehicle_id" "text", "description" "text", "meta" "jsonb", "has_more" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
begin
  if p_org is null then
    raise exception 'ledger.driver_page requires organization_id';
  end if;
  if p_from is null or p_to is null then
    raise exception 'ledger.driver_page requires date range';
  end if;
  if p_driver_ids is null or cardinality(p_driver_ids) = 0 then
    raise exception 'ledger.driver_page requires driver_ids';
  end if;

  return query
  select * from ledger.page(
    p_org, p_from, p_to, p_entry_types, p_products, p_platform, p_direction,
    p_driver_ids, null, null, null, null, null, null,
    p_after_effective_at, p_after_id, p_limit
  );
end;
$$;


ALTER FUNCTION "ledger"."driver_page"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_driver_ids" "uuid"[], "p_entry_types" "text"[], "p_products" "text"[], "p_platform" "text", "p_direction" "text", "p_after_effective_at" timestamp with time zone, "p_after_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."entries_maintain_read_models"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
declare
  r record;
  v_signed bigint;
  v_gross bigint;
  v_recon int;
begin
  if tg_op in ('DELETE', 'UPDATE') then
    for r in
      select
        d.organization_id,
        ledger.jamaica_week_start(d.effective_at) as week_start,
        d.driver_id,
        d.product,
        d.entry_type,
        coalesce(d.platform, '') as platform,
        ledger.entry_direction(d.metadata, da.account_key, ca.account_key) as direction,
        d.amount_minor,
        d.metadata,
        d.batch_id,
        d.effective_at
      from old_table d
      join ledger.accounts da on da.id = d.debit_account_id
      join ledger.accounts ca on ca.id = d.credit_account_id
    loop
      v_signed := ledger._entry_signed_minor(r.metadata, r.amount_minor);
      v_gross := ledger._entry_signed_gross_minor(r.metadata, r.amount_minor);
      v_recon := case when ledger._entry_reconciled(r.metadata) then 1 else 0 end;
      perform ledger._week_totals_apply(
        r.organization_id, r.week_start, r.driver_id, r.product, r.entry_type,
        r.platform, r.direction,
        -v_signed, -abs(r.amount_minor), -v_gross, -1, -v_recon, null
      );
      perform ledger._batch_totals_apply(
        r.organization_id, r.batch_id, r.driver_id, r.entry_type, -1, -v_signed
      );
      perform ledger._bump_org_version(r.organization_id);
    end loop;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    for r in
      select
        n.organization_id,
        ledger.jamaica_week_start(n.effective_at) as week_start,
        n.driver_id,
        n.product,
        n.entry_type,
        coalesce(n.platform, '') as platform,
        ledger.entry_direction(n.metadata, da.account_key, ca.account_key) as direction,
        n.amount_minor,
        n.metadata,
        n.batch_id,
        n.effective_at
      from new_table n
      join ledger.accounts da on da.id = n.debit_account_id
      join ledger.accounts ca on ca.id = n.credit_account_id
    loop
      v_signed := ledger._entry_signed_minor(r.metadata, r.amount_minor);
      v_gross := ledger._entry_signed_gross_minor(r.metadata, r.amount_minor);
      v_recon := case when ledger._entry_reconciled(r.metadata) then 1 else 0 end;
      perform ledger._week_totals_apply(
        r.organization_id, r.week_start, r.driver_id, r.product, r.entry_type,
        r.platform, r.direction,
        v_signed, abs(r.amount_minor), v_gross, 1, v_recon, r.effective_at
      );
      perform ledger._batch_totals_apply(
        r.organization_id, r.batch_id, r.driver_id, r.entry_type, 1, v_signed
      );
      perform ledger._bump_org_version(r.organization_id);
    end loop;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "ledger"."entries_maintain_read_models"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."entry_detail"("p_org" "uuid", "p_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "idempotency_key" "text", "entry_type" "text", "product" "text", "debit_account_id" "uuid", "credit_account_id" "uuid", "amount_minor" bigint, "currency" "text", "effective_at" timestamp with time zone, "created_at" timestamp with time zone, "reference_type" "text", "reference_id" "text", "metadata" "jsonb", "driver_id" "uuid", "platform" "text", "batch_id" "text", "created_by_user_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
begin
  if p_org is null then
    raise exception 'ledger.entry_detail requires organization_id';
  end if;
  if p_id is null then
    raise exception 'ledger.entry_detail requires id';
  end if;

  return query
  select
    e.id, e.organization_id, e.idempotency_key, e.entry_type, e.product,
    e.debit_account_id, e.credit_account_id, e.amount_minor, e.currency,
    e.effective_at, e.created_at, e.reference_type, e.reference_id, e.metadata,
    e.driver_id, e.platform, e.batch_id, e.created_by_user_id
  from ledger.entries e
  where e.organization_id = p_org
    and e.id = p_id;
end;
$$;


ALTER FUNCTION "ledger"."entry_detail"("p_org" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."entry_direction"("p_metadata" "jsonb", "p_debit_account_key" "text", "p_credit_account_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_raw text := lower(nullif(btrim(coalesce(p_metadata->>'direction', '')), ''));
  v_credit_driver text;
  v_debit_driver text;
begin
  if v_raw in ('inflow', 'outflow', 'neutral') then
    return v_raw;
  end if;
  v_credit_driver := ledger.extract_driver_token_from_account_key(p_credit_account_key);
  v_debit_driver := ledger.extract_driver_token_from_account_key(p_debit_account_key);
  if v_credit_driver is not null and v_debit_driver is null then
    return 'inflow';
  end if;
  if v_debit_driver is not null and v_credit_driver is null then
    return 'outflow';
  end if;
  return 'inflow';
end;
$$;


ALTER FUNCTION "ledger"."entry_direction"("p_metadata" "jsonb", "p_debit_account_key" "text", "p_credit_account_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."extract_driver_token_from_account_key"("p_account_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select (regexp_match(coalesce(p_account_key, ''), '^user:([^:]+):driver(?::|$)', 'i'))[1];
$_$;


ALTER FUNCTION "ledger"."extract_driver_token_from_account_key"("p_account_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."jamaica_week_start"("p_at" timestamp with time zone) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select date_trunc('week', (p_at at time zone 'America/Jamaica'))::date;
$$;


ALTER FUNCTION "ledger"."jamaica_week_start"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."mark_reversed_on_reverse"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public'
    AS $$
BEGIN
  IF NEW.reverses_event_id IS NOT NULL THEN
    UPDATE ledger.financial_events
    SET reversed_at = COALESCE(reversed_at, now())
    WHERE id = NEW.reverses_event_id
      AND reversed_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "ledger"."mark_reversed_on_reverse"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."page"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_entry_types" "text"[] DEFAULT NULL::"text"[], "p_products" "text"[] DEFAULT NULL::"text"[], "p_platform" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT NULL::"text", "p_driver_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_batch_id" "text" DEFAULT NULL::"text", "p_vehicle_id" "text" DEFAULT NULL::"text", "p_reconciled" boolean DEFAULT NULL::boolean, "p_search" "text" DEFAULT NULL::"text", "p_amount_min_minor" bigint DEFAULT NULL::bigint, "p_amount_max_minor" bigint DEFAULT NULL::bigint, "p_after_effective_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "entry_type" "text", "product" "text", "amount_minor" bigint, "currency" "text", "effective_at" timestamp with time zone, "created_at" timestamp with time zone, "reference_type" "text", "reference_id" "text", "driver_id" "uuid", "platform" "text", "batch_id" "text", "direction" "text", "is_reconciled" boolean, "vehicle_id" "text", "description" "text", "meta" "jsonb", "has_more" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
declare
  v_limit int := greatest(1, least(coalesce(p_limit, 50), 200));
begin
  if p_org is null then
    raise exception 'ledger.page requires organization_id';
  end if;
  if p_from is null or p_to is null then
    raise exception 'ledger.page requires date range';
  end if;

  return query
  with filtered as (
    select
      e.id,
      e.organization_id,
      e.entry_type,
      e.product,
      e.amount_minor,
      e.currency,
      e.effective_at,
      e.created_at,
      e.reference_type,
      e.reference_id,
      e.driver_id,
      e.platform,
      e.batch_id,
      ledger.entry_direction(e.metadata, da.account_key, ca.account_key) as direction,
      ledger._entry_reconciled(e.metadata) as is_reconciled,
      nullif(e.metadata->>'vehicleId', '') as vehicle_id,
      nullif(e.metadata->>'description', '') as description,
      ledger._entry_page_meta(e.metadata) as meta
    from ledger.entries e
    join ledger.accounts da on da.id = e.debit_account_id
    join ledger.accounts ca on ca.id = e.credit_account_id
    where e.organization_id = p_org
      and e.effective_at >= p_from
      and e.effective_at <= p_to
      and (
        p_entry_types is null or cardinality(p_entry_types) = 0
        or e.entry_type = any (p_entry_types)
      )
      and (
        p_products is null or cardinality(p_products) = 0
        or e.product = any (p_products)
      )
      and (p_platform is null or e.platform = p_platform)
      and (
        p_driver_ids is null or cardinality(p_driver_ids) = 0
        or e.driver_id = any (p_driver_ids)
      )
      and (p_batch_id is null or e.batch_id = p_batch_id)
      and (
        p_vehicle_id is null
        or e.metadata->>'vehicleId' = p_vehicle_id
      )
      and (
        p_reconciled is null
        or ledger._entry_reconciled(e.metadata) = p_reconciled
      )
      and (
        p_search is null
        or e.metadata->>'description' ilike '%' || p_search || '%'
        or e.reference_id ilike '%' || p_search || '%'
        or e.batch_id ilike '%' || p_search || '%'
      )
      and (p_amount_min_minor is null or e.amount_minor >= p_amount_min_minor)
      and (p_amount_max_minor is null or e.amount_minor <= p_amount_max_minor)
      and (
        p_after_effective_at is null
        or (e.effective_at, e.id) < (p_after_effective_at, p_after_id)
      )
      and (
        p_direction is null
        or ledger.entry_direction(e.metadata, da.account_key, ca.account_key) = p_direction
      )
    order by e.effective_at desc, e.id desc
    limit v_limit + 1
  )
  select
    f.id,
    f.organization_id,
    f.entry_type,
    f.product,
    f.amount_minor,
    f.currency,
    f.effective_at,
    f.created_at,
    f.reference_type,
    f.reference_id,
    f.driver_id,
    f.platform,
    f.batch_id,
    f.direction,
    f.is_reconciled,
    f.vehicle_id,
    f.description,
    f.meta,
    (count(*) over () > v_limit) as has_more
  from filtered f
  order by f.effective_at desc, f.id desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "ledger"."page"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_entry_types" "text"[], "p_products" "text"[], "p_platform" "text", "p_direction" "text", "p_driver_ids" "uuid"[], "p_batch_id" "text", "p_vehicle_id" "text", "p_reconciled" boolean, "p_search" "text", "p_amount_min_minor" bigint, "p_amount_max_minor" bigint, "p_after_effective_at" timestamp with time zone, "p_after_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."post_entry"("p_idempotency_key" "text", "p_entry_type" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_amount_minor" bigint, "p_currency" "text", "p_request_hash" "text" DEFAULT NULL::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_product" "text" DEFAULT 'platform'::"text", "p_effective_at" timestamp with time zone DEFAULT "now"(), "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid", "p_source_system" "text" DEFAULT NULL::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_source_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'fleet', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_debit_id UUID;
  v_credit_id UUID;
  v_first_id UUID;
  v_second_id UUID;
  v_inserted INTEGER;
  v_existing_hash TEXT;
  v_entry_id UUID;
  v_org_id UUID;
  v_meta JSONB := COALESCE(p_metadata, '{}'::jsonb);
  v_driver_id UUID;
  v_platform TEXT;
  v_batch_id TEXT;
BEGIN
  IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'invalid_amount_minor';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id required for ledger.post_entry';
  END IF;
  v_org_id := p_organization_id;

  v_debit_id := ledger._resolve_account_id(p_debit_account_key, p_currency);
  v_credit_id := ledger._resolve_account_id(p_credit_account_key, p_currency);

  IF v_debit_id < v_credit_id THEN
    v_first_id := v_debit_id;
    v_second_id := v_credit_id;
  ELSE
    v_first_id := v_credit_id;
    v_second_id := v_debit_id;
  END IF;

  PERFORM id FROM ledger.accounts WHERE id = v_first_id FOR UPDATE;
  PERFORM id FROM ledger.accounts WHERE id = v_second_id FOR UPDATE;

  v_driver_id := COALESCE(
    ledger.resolve_canonical_driver_id(NULLIF(v_meta->>'driverId', '')),
    ledger.resolve_canonical_driver_id(ledger.extract_driver_token_from_account_key(p_credit_account_key)),
    ledger.resolve_canonical_driver_id(ledger.extract_driver_token_from_account_key(p_debit_account_key))
  );
  v_platform := NULLIF(btrim(COALESCE(v_meta->>'platform', '')), '');
  v_batch_id := NULLIF(btrim(COALESCE(v_meta->>'batchId', '')), '');

  INSERT INTO ledger.entries (
    organization_id, idempotency_key, entry_type, product,
    debit_account_id, credit_account_id, amount_minor, currency, request_hash,
    effective_at, reference_type, reference_id, metadata, created_by_user_id,
    driver_id, platform, batch_id
  )
  VALUES (
    v_org_id, p_idempotency_key, p_entry_type, p_product,
    v_debit_id, v_credit_id, p_amount_minor, p_currency, p_request_hash,
    COALESCE(p_effective_at, now()), p_reference_type, p_reference_id,
    v_meta, p_created_by_user_id,
    v_driver_id, v_platform, v_batch_id
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_entry_id;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT id, request_hash INTO v_entry_id, v_existing_hash
    FROM ledger.entries WHERE idempotency_key = p_idempotency_key;

    IF v_existing_hash IS NOT NULL AND p_request_hash IS NOT NULL
       AND v_existing_hash IS DISTINCT FROM p_request_hash THEN
      RETURN jsonb_build_object('inserted', false, 'skipped', false, 'conflict', true, 'entry_id', NULL);
    END IF;

    IF p_source_system IS NOT NULL AND p_source_id IS NOT NULL AND v_entry_id IS NOT NULL THEN
      BEGIN
        INSERT INTO ledger.source_receipts (
          ledger_entry_id, source_system, source_id, source_idempotency_key
        )
        VALUES (v_entry_id, p_source_system, p_source_id, p_source_idempotency_key)
        ON CONFLICT (source_system, source_id) DO NOTHING;
      EXCEPTION WHEN unique_violation THEN
        NULL;
      END;
    END IF;

    RETURN jsonb_build_object(
      'inserted', false, 'skipped', true, 'conflict', false, 'entry_id', v_entry_id
    );
  END IF;

  UPDATE ledger.accounts SET balance_minor = balance_minor - p_amount_minor WHERE id = v_debit_id;
  UPDATE ledger.accounts SET balance_minor = balance_minor + p_amount_minor WHERE id = v_credit_id;

  IF p_source_system IS NOT NULL AND p_source_id IS NOT NULL THEN
    INSERT INTO ledger.source_receipts (
      ledger_entry_id, source_system, source_id, source_idempotency_key
    )
    VALUES (v_entry_id, p_source_system, p_source_id, p_source_idempotency_key)
    ON CONFLICT (source_system, source_id) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'inserted', true, 'skipped', false, 'conflict', false, 'entry_id', v_entry_id
  );
END;
$$;


ALTER FUNCTION "ledger"."post_entry"("p_idempotency_key" "text", "p_entry_type" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_amount_minor" bigint, "p_currency" "text", "p_request_hash" "text", "p_organization_id" "uuid", "p_product" "text", "p_effective_at" timestamp with time zone, "p_reference_type" "text", "p_reference_id" "text", "p_metadata" "jsonb", "p_created_by_user_id" "uuid", "p_source_system" "text", "p_source_id" "text", "p_source_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."post_financial_event"("p_idempotency_key" "text", "p_request_hash" "text", "p_domain" "text", "p_event_type" "text", "p_source_system" "text", "p_source_id" "text", "p_driver_id" "text", "p_vehicle_id" "text", "p_occurred_at" timestamp with time zone, "p_period_anchor" "date", "p_amount_minor" bigint, "p_currency" "text" DEFAULT 'JMD'::"text", "p_direction" "text" DEFAULT 'outflow'::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_product" "text" DEFAULT 'roam_fleet'::"text", "p_debit_account_key" "text" DEFAULT NULL::"text", "p_credit_account_key" "text" DEFAULT NULL::"text", "p_reverses_event_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "text" DEFAULT NULL::"text", "p_causation_id" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public'
    AS $_$
DECLARE
  v_existing ledger.financial_events%ROWTYPE; v_event_id UUID; v_entry_result JSONB;
  v_entry_id UUID; v_abs BIGINT; v_debit TEXT; v_credit TEXT; v_alloc JSONB; v_alloc_id UUID;
BEGIN
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency_key_required';
  END IF;
  SELECT * INTO v_existing FROM ledger.financial_events WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing.request_hash IS NOT NULL AND p_request_hash IS NOT NULL
       AND v_existing.request_hash IS DISTINCT FROM p_request_hash THEN
      RETURN jsonb_build_object('inserted', false, 'skipped', false, 'conflict', true, 'event_id', NULL, 'ledger_entry_id', NULL);
    END IF;
    RETURN jsonb_build_object('inserted', false, 'skipped', true, 'conflict', false, 'event_id', v_existing.id, 'ledger_entry_id', v_existing.ledger_entry_id);
  END IF;
  v_abs := abs(COALESCE(p_amount_minor, 0));
  v_debit := p_debit_account_key; v_credit := p_credit_account_key;
  IF v_abs > 0 AND (v_debit IS NULL OR v_credit IS NULL) THEN
    IF p_direction = 'outflow' THEN
      v_debit := COALESCE(v_debit, 'platform:fleet_toll_expense');
      v_credit := COALESCE(v_credit, 'platform:clearing');
      IF p_domain = 'fuel' THEN v_debit := COALESCE(p_debit_account_key, 'platform:fleet_fuel_expense'); END IF;
      IF p_event_type IN ('toll_charged_to_driver', 'driver_charge') THEN
        v_debit := COALESCE(p_debit_account_key, CASE WHEN p_driver_id ~ '^[0-9a-fA-F-]{36}$' THEN 'user:' || p_driver_id || ':driver:digital' ELSE 'platform:driver_receivable' END);
        v_credit := COALESCE(p_credit_account_key, 'platform:clearing');
      END IF;
    ELSIF p_direction = 'inflow' THEN
      v_debit := COALESCE(v_debit, 'platform:clearing');
      v_credit := COALESCE(v_credit, CASE WHEN p_driver_id ~ '^[0-9a-fA-F-]{36}$' THEN 'user:' || p_driver_id || ':driver:digital' ELSE 'platform:clearing' END);
    END IF;
  END IF;
  IF v_abs > 0 AND v_debit IS NOT NULL AND v_credit IS NOT NULL THEN
    v_entry_result := ledger.post_entry(
      'fin_event:' || p_idempotency_key, p_event_type, v_debit, v_credit, v_abs,
      COALESCE(p_currency, 'JMD'), p_request_hash, p_organization_id, COALESCE(p_product, 'roam_fleet'),
      p_occurred_at, p_source_system, p_source_id, COALESCE(p_payload, '{}'::jsonb), p_created_by_user_id,
      'financial_event', p_idempotency_key, p_idempotency_key
    );
    IF (v_entry_result->>'conflict')::boolean THEN
      RETURN jsonb_build_object('inserted', false, 'skipped', false, 'conflict', true, 'event_id', NULL, 'ledger_entry_id', NULL);
    END IF;
    v_entry_id := (v_entry_result->>'entry_id')::UUID;
  END IF;
  INSERT INTO ledger.financial_events (
    organization_id, idempotency_key, request_hash, domain, event_type, source_system, source_id,
    driver_id, vehicle_id, occurred_at, period_anchor, amount_minor, currency, direction,
    reverses_event_id, correlation_id, causation_id, payload, ledger_entry_id, created_by_user_id
  ) VALUES (
    p_organization_id, p_idempotency_key, p_request_hash, p_domain, p_event_type, p_source_system, p_source_id,
    p_driver_id, p_vehicle_id, p_occurred_at, p_period_anchor, COALESCE(p_amount_minor, 0), COALESCE(p_currency, 'JMD'), p_direction,
    p_reverses_event_id, p_correlation_id, p_causation_id, COALESCE(p_payload, '{}'::jsonb), v_entry_id, p_created_by_user_id
  ) RETURNING id INTO v_event_id;
  IF p_allocations IS NOT NULL AND jsonb_typeof(p_allocations) = 'array' THEN
    FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
      INSERT INTO ledger.financial_allocations (
        organization_id, financial_event_id, allocation_type, amount_minor, currency, driver_id, toll_id,
        claim_id, fuel_entry_id, period_anchor, idempotency_key, reverses_id, notes, metadata
      ) VALUES (
        p_organization_id, v_event_id, v_alloc->>'allocation_type', (v_alloc->>'amount_minor')::BIGINT,
        COALESCE(v_alloc->>'currency', p_currency, 'JMD'), COALESCE(v_alloc->>'driver_id', p_driver_id),
        v_alloc->>'toll_id', v_alloc->>'claim_id', v_alloc->>'fuel_entry_id',
        COALESCE((v_alloc->>'period_anchor')::DATE, p_period_anchor),
        COALESCE(v_alloc->>'idempotency_key', p_idempotency_key || ':' || (v_alloc->>'allocation_type')),
        (v_alloc->>'reverses_id')::UUID, v_alloc->>'notes', COALESCE(v_alloc->'metadata', '{}'::jsonb)
      ) ON CONFLICT (idempotency_key) DO NOTHING RETURNING id INTO v_alloc_id;
    END LOOP;
  END IF;
  INSERT INTO ledger.financial_outbox (topic, payload) VALUES (
    'period_projection_refresh',
    jsonb_build_object('driver_id', p_driver_id, 'period_anchor', p_period_anchor, 'event_id', v_event_id, 'domain', p_domain, 'event_type', p_event_type)
  );
  RETURN jsonb_build_object('inserted', true, 'skipped', false, 'conflict', false, 'event_id', v_event_id, 'ledger_entry_id', v_entry_id);
END; $_$;


ALTER FUNCTION "ledger"."post_financial_event"("p_idempotency_key" "text", "p_request_hash" "text", "p_domain" "text", "p_event_type" "text", "p_source_system" "text", "p_source_id" "text", "p_driver_id" "text", "p_vehicle_id" "text", "p_occurred_at" timestamp with time zone, "p_period_anchor" "date", "p_amount_minor" bigint, "p_currency" "text", "p_direction" "text", "p_organization_id" "uuid", "p_product" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_reverses_event_id" "uuid", "p_correlation_id" "text", "p_causation_id" "text", "p_payload" "jsonb", "p_created_by_user_id" "uuid", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."range_summary"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_entry_types" "text"[] DEFAULT NULL::"text"[], "p_products" "text"[] DEFAULT NULL::"text"[], "p_driver_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_platform" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT NULL::"text") RETURNS TABLE("organization_id" "uuid", "day" "date", "driver_id" "uuid", "product" "text", "entry_type" "text", "platform" "text", "direction" "text", "sum_minor" bigint, "abs_sum_minor" bigint, "gross_minor" bigint, "entry_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
begin
  if p_org is null then
    raise exception 'ledger.range_summary requires organization_id';
  end if;
  if p_from is null or p_to is null then
    raise exception 'ledger.range_summary requires date range';
  end if;

  return query
  select
    e.organization_id,
    (e.effective_at at time zone 'America/Jamaica')::date as day,
    e.driver_id,
    e.product,
    e.entry_type,
    e.platform,
    ledger.entry_direction(e.metadata, da.account_key, ca.account_key) as direction,
    sum(ledger._entry_signed_minor(e.metadata, e.amount_minor))::bigint as sum_minor,
    sum(abs(e.amount_minor))::bigint as abs_sum_minor,
    sum(ledger._entry_signed_gross_minor(e.metadata, e.amount_minor))::bigint as gross_minor,
    count(*)::bigint as entry_count
  from ledger.entries e
  join ledger.accounts da on da.id = e.debit_account_id
  join ledger.accounts ca on ca.id = e.credit_account_id
  where e.organization_id = p_org
    and e.effective_at >= p_from
    and e.effective_at <= p_to
    and (
      p_entry_types is null or cardinality(p_entry_types) = 0
      or e.entry_type = any (p_entry_types)
    )
    and (
      p_products is null or cardinality(p_products) = 0
      or e.product = any (p_products)
    )
    and (
      p_driver_ids is null or cardinality(p_driver_ids) = 0
      or e.driver_id = any (p_driver_ids)
    )
    and (p_platform is null or e.platform = p_platform)
    and (
      p_direction is null
      or ledger.entry_direction(e.metadata, da.account_key, ca.account_key) = p_direction
    )
  group by 1, 2, 3, 4, 5, 6, 7
  order by 2 desc, 5, 3;
end;
$$;


ALTER FUNCTION "ledger"."range_summary"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_entry_types" "text"[], "p_products" "text"[], "p_driver_ids" "uuid"[], "p_platform" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."recon_check"("p_org" "uuid") RETURNS TABLE("week_start" "date", "driver_id" "uuid", "product" "text", "entry_type" "text", "platform" "text", "direction" "text", "totals_sum_minor" bigint, "live_sum_minor" bigint, "totals_count" bigint, "live_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
  WITH live AS (
    SELECT
      e.organization_id,
      ledger.jamaica_week_start(e.effective_at) AS week_start,
      ledger.driver_grain_id(e.driver_id) AS driver_id,
      e.product,
      e.entry_type,
      coalesce(e.platform, '') AS platform,
      ledger.entry_direction(e.metadata, da.account_key, ca.account_key) AS direction,
      sum(ledger._entry_signed_minor(e.metadata, e.amount_minor))::bigint AS live_sum_minor,
      count(*)::bigint AS live_count
    FROM ledger.entries e
    JOIN ledger.accounts da ON da.id = e.debit_account_id
    JOIN ledger.accounts ca ON ca.id = e.credit_account_id
    WHERE e.organization_id = p_org
    GROUP BY 1, 2, 3, 4, 5, 6, 7
  ),
  totals AS (
    SELECT *
    FROM ledger.week_totals t
    WHERE t.organization_id = p_org
  ),
  grain_drift AS (
    SELECT
      coalesce(t.week_start, l.week_start) AS week_start,
      nullif(coalesce(t.driver_id, l.driver_id), '00000000-0000-0000-0000-000000000000'::uuid) AS driver_id,
      coalesce(t.product, l.product) AS product,
      coalesce(t.entry_type, l.entry_type) AS entry_type,
      coalesce(t.platform, l.platform) AS platform,
      coalesce(t.direction, l.direction) AS direction,
      coalesce(t.sum_minor, 0)::bigint AS totals_sum_minor,
      coalesce(l.live_sum_minor, 0)::bigint AS live_sum_minor,
      coalesce(t.entry_count, 0)::bigint AS totals_count,
      coalesce(l.live_count, 0)::bigint AS live_count
    FROM totals t
    FULL OUTER JOIN live l
      ON t.organization_id = l.organization_id
     AND t.week_start = l.week_start
     AND t.driver_id = l.driver_id
     AND t.product = l.product
     AND t.entry_type = l.entry_type
     AND t.platform = l.platform
     AND t.direction = l.direction
    WHERE coalesce(t.sum_minor, 0) IS DISTINCT FROM coalesce(l.live_sum_minor, 0)
       OR coalesce(t.entry_count, 0) IS DISTINCT FROM coalesce(l.live_count, 0)
  ),
  global_live AS (
    SELECT
      count(*)::bigint AS live_count,
      coalesce(sum(ledger._entry_signed_minor(e.metadata, e.amount_minor)), 0)::bigint AS live_sum
    FROM ledger.entries e
  ),
  global_totals AS (
    SELECT
      coalesce(sum(entry_count), 0)::bigint AS totals_count,
      coalesce(sum(sum_minor), 0)::bigint AS totals_sum
    FROM ledger.week_totals
  ),
  global_drift AS (
    SELECT
      DATE '1970-01-01' AS week_start,
      NULL::uuid AS driver_id,
      'integrity'::text AS product,
      'global'::text AS entry_type,
      ''::text AS platform,
      ''::text AS direction,
      g.totals_sum AS totals_sum_minor,
      l.live_sum AS live_sum_minor,
      g.totals_count,
      l.live_count
    FROM global_live l
    CROSS JOIN global_totals g
    WHERE g.totals_count IS DISTINCT FROM l.live_count
       OR g.totals_sum IS DISTINCT FROM l.live_sum
  )
  SELECT * FROM grain_drift
  UNION ALL
  SELECT * FROM global_drift;
$$;


ALTER FUNCTION "ledger"."recon_check"("p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."resolve_canonical_driver_id"("p_candidate" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'fleet', 'public', 'pg_catalog'
    AS $_$
declare
  v_raw text := nullif(btrim(coalesce(p_candidate, '')), '');
  v_id text;
begin
  if v_raw is null then
    return null;
  end if;

  -- Prefer exact fleet.drivers.id / uber / indrive match.
  select d.id into v_id
  from fleet.drivers d
  where d.id = v_raw
     or d.uber_driver_id = v_raw
     or d.indrive_driver_id = v_raw
  limit 1;

  if v_id is not null and v_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return v_id::uuid;
  end if;

  -- Fallback: candidate itself is a UUID (orphan / not yet in fleet.drivers).
  if v_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return v_raw::uuid;
  end if;

  return null;
exception when others then
  return null;
end;
$_$;


ALTER FUNCTION "ledger"."resolve_canonical_driver_id"("p_candidate" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."reverse_entry"("p_entry_id" "uuid", "p_idempotency_key" "text", "p_reason" "text" DEFAULT NULL::"text", "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public'
    AS $$
DECLARE v_src ledger.entries%ROWTYPE; v_result JSONB;
BEGIN
  SELECT * INTO v_src FROM ledger.entries WHERE id = p_entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'entry_not_found:%', p_entry_id; END IF;
  v_result := ledger.post_entry(
    p_idempotency_key, v_src.entry_type || '_reversal',
    (SELECT account_key FROM ledger.accounts WHERE id = v_src.credit_account_id),
    (SELECT account_key FROM ledger.accounts WHERE id = v_src.debit_account_id),
    v_src.amount_minor, v_src.currency, NULL, v_src.organization_id, v_src.product, now(),
    'reversal', v_src.id::TEXT, jsonb_build_object('reverses_entry_id', v_src.id, 'reason', p_reason),
    p_created_by_user_id, 'financial_event', 'reversal:' || v_src.id::TEXT, p_idempotency_key
  );
  RETURN v_result;
END; $$;


ALTER FUNCTION "ledger"."reverse_entry"("p_entry_id" "uuid", "p_idempotency_key" "text", "p_reason" "text", "p_created_by_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ledger"."week_summary"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_driver_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_entry_types" "text"[] DEFAULT NULL::"text"[], "p_platform" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT NULL::"text", "p_products" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("organization_id" "uuid", "week_start" "date", "driver_id" "uuid", "product" "text", "entry_type" "text", "platform" "text", "direction" "text", "sum_minor" bigint, "abs_sum_minor" bigint, "gross_minor" bigint, "entry_count" bigint, "reconciled_count" bigint, "last_entry_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
declare
  v_from_ymd date;
  v_to_ymd date;
  v_from_week date;
  v_to_week date;
begin
  if p_org is null then
    raise exception 'ledger.week_summary requires organization_id';
  end if;
  if p_from is null or p_to is null then
    raise exception 'ledger.week_summary requires date range';
  end if;

  -- Callers pass Mon/Sun as UTC calendar dates (…T00:00:00Z / …T23:59:59Z).
  v_from_ymd := p_from::date;
  v_to_ymd := p_to::date;
  if extract(dow from v_from_ymd)::int is distinct from 1 then
    raise exception 'ledger.week_summary requires from to be a Jamaica Monday';
  end if;
  if extract(dow from v_to_ymd)::int is distinct from 0 then
    raise exception 'ledger.week_summary requires to to be a Jamaica Sunday';
  end if;

  v_from_week := ledger.jamaica_week_start(p_from);
  v_to_week := ledger.jamaica_week_start(p_to);

  return query
  select
    t.organization_id,
    t.week_start,
    nullif(t.driver_id, '00000000-0000-0000-0000-000000000000'::uuid) as driver_id,
    t.product,
    t.entry_type,
    nullif(t.platform, '') as platform,
    t.direction,
    t.sum_minor,
    t.abs_sum_minor,
    t.gross_minor,
    t.entry_count,
    t.reconciled_count,
    t.last_entry_at
  from ledger.week_totals t
  where t.organization_id = p_org
    and t.week_start >= v_from_week
    and t.week_start <= v_to_week
    and (
      p_driver_ids is null
      or cardinality(p_driver_ids) = 0
      or t.driver_id = any (select ledger.driver_grain_id(x) from unnest(p_driver_ids) as x)
    )
    and (
      p_entry_types is null
      or cardinality(p_entry_types) = 0
      or t.entry_type = any (p_entry_types)
    )
    and (p_platform is null or t.platform = p_platform)
    and (p_direction is null or t.direction = p_direction)
    and (
      p_products is null
      or cardinality(p_products) = 0
      or t.product = any (p_products)
    )
  order by t.week_start desc, t.entry_type, t.driver_id;
end;
$$;


ALTER FUNCTION "ledger"."week_summary"("p_org" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_driver_ids" "uuid"[], "p_entry_types" "text"[], "p_platform" "text", "p_direction" "text", "p_products" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."accept_job_offer"("p_offer_id" "uuid", "p_driver_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'logistics', 'public'
    AS $$
DECLARE
  v_offer logistics.job_offers%ROWTYPE;
  v_job logistics.jobs%ROWTYPE;
  v_now TIMESTAMPTZ := now();
BEGIN
  SELECT * INTO v_offer
  FROM logistics.job_offers
  WHERE id = p_offer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_found');
  END IF;

  IF v_offer.driver_user_id IS DISTINCT FROM p_driver_user_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_wrong_driver');
  END IF;

  IF v_offer.status IS DISTINCT FROM 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_pending', 'status', v_offer.status);
  END IF;

  IF v_offer.expires_at <= v_now THEN
    UPDATE logistics.job_offers SET status = 'expired' WHERE id = v_offer.id;
    RETURN jsonb_build_object('ok', false, 'error', 'offer_expired');
  END IF;

  SELECT * INTO v_job
  FROM logistics.jobs
  WHERE id = v_offer.job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'job_not_found');
  END IF;

  IF v_job.status NOT IN ('matching', 'unassigned') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'job_not_open', 'status', v_job.status);
  END IF;

  UPDATE logistics.job_offers
  SET status = 'accepted'
  WHERE id = v_offer.id;

  UPDATE logistics.job_offers
  SET status = 'superseded'
  WHERE job_id = v_job.id
    AND status = 'pending'
    AND id IS DISTINCT FROM v_offer.id;

  UPDATE logistics.jobs
  SET
    status = 'assigned',
    assignee_type = 'roam_marketplace',
    assignee_driver_id = p_driver_user_id,
    assigned_at = v_now,
    updated_at = v_now
  WHERE id = v_job.id;

  INSERT INTO logistics.job_events (
    organization_id, job_id, event_type, from_status, to_status,
    actor_user_id, note, payload, idempotency_key, occurred_at
  ) VALUES (
    v_job.organization_id,
    v_job.id,
    'marketplace_offer_accepted',
    v_job.status,
    'assigned',
    p_driver_user_id,
    'Driver accepted marketplace offer',
    jsonb_build_object('offer_id', v_offer.id, 'wave', v_offer.wave),
    'accept:' || v_offer.id::text,
    v_now
  )
  ON CONFLICT (organization_id, idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job.id,
    'offer_id', v_offer.id,
    'status', 'assigned'
  );
END;
$$;


ALTER FUNCTION "logistics"."accept_job_offer"("p_offer_id" "uuid", "p_driver_user_id" "uuid") OWNER TO "postgres";


