CREATE OR REPLACE FUNCTION "payments"."bank_account_number"("p_party" "text", "p_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'payments', 'vault', 'public'
    AS $$
DECLARE
  v_secret uuid;
  v_plain text;
  v_number text;
BEGIN
  IF p_party = 'courier' THEN
    SELECT account_secret_id, account_number INTO v_secret, v_plain
    FROM payments.courier_bank_accounts WHERE id = p_id;
  ELSIF p_party = 'merchant' THEN
    SELECT account_secret_id, account_number INTO v_secret, v_plain
    FROM payments.merchant_bank_accounts WHERE id = p_id;
  ELSE
    RETURN NULL;
  END IF;

  IF v_secret IS NOT NULL THEN
    BEGIN
      SELECT decrypted_secret INTO v_number
      FROM vault.decrypted_secrets
      WHERE id = v_secret;
    EXCEPTION
      WHEN undefined_table THEN
        v_number := NULL;
    END;
    IF v_number IS NOT NULL AND btrim(v_number) <> '' THEN
      RETURN v_number;
    END IF;
  END IF;

  RETURN NULLIF(btrim(COALESCE(v_plain, '')), '');
END;
$$;


ALTER FUNCTION "payments"."bank_account_number"("p_party" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "payments"."complete_payment_intent"("p_intent_id" "uuid", "p_provider" "text", "p_provider_transaction_id" "text", "p_amount" numeric, "p_currency" "text", "p_net_amount" numeric, "p_provider_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'payments', 'delivery', 'public'
    AS $$
DECLARE
  v_intent payments.payment_intents%ROWTYPE;
  v_order delivery.orders%ROWTYPE;
  v_existing uuid;
  v_txn uuid;
  v_refund uuid;
  v_provider_txn text;
  v_posted text;
BEGIN
  SELECT * INTO v_intent FROM payments.payment_intents WHERE id = p_intent_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'intent_not_found');
  END IF;

  IF p_amount IS NOT NULL AND abs(p_amount - v_intent.amount) > 0.01 THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'amount_mismatch');
  END IF;
  IF p_currency IS NOT NULL AND upper(btrim(p_currency)) <> 'JMD' THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'currency_mismatch');
  END IF;

  v_provider_txn := NULLIF(btrim(COALESCE(p_provider_transaction_id, '')), '');

  IF v_provider_txn IS NOT NULL THEN
    SELECT id INTO v_existing
    FROM payments.transactions
    WHERE provider = p_provider
      AND provider_transaction_id = v_provider_txn
      AND status = 'completed'
    LIMIT 1;
    IF v_existing IS NOT NULL THEN
      IF v_intent.status IN ('pending', 'created') THEN
        UPDATE payments.payment_intents
        SET status = 'superseded', completed_at = now()
        WHERE id = p_intent_id;
      END IF;
      RETURN jsonb_build_object('action', 'replay', 'transaction_id', v_existing, 'order_id', v_intent.order_id);
    END IF;
  END IF;

  SELECT id INTO v_existing
  FROM payments.transactions
  WHERE intent_id = p_intent_id AND status = 'completed'
  LIMIT 1;

  IF v_intent.order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM delivery.orders WHERE id = v_intent.order_id FOR UPDATE;
  END IF;

  IF v_existing IS NOT NULL THEN
    IF v_intent.status IN ('pending', 'created') THEN
      UPDATE payments.payment_intents
      SET status = 'superseded', completed_at = now()
      WHERE id = p_intent_id;
    END IF;
    INSERT INTO payments.transactions (
      intent_id, order_id, customer_id, amount, net_amount, currency, status, provider,
      provider_transaction_id, provider_data, payment_method, failure_reason
    ) VALUES (
      p_intent_id, v_intent.order_id, v_intent.customer_id, v_intent.amount, COALESCE(p_net_amount, v_intent.amount),
      'JMD', 'duplicate_superseded', p_provider, v_provider_txn, COALESCE(p_provider_data, '{}'::jsonb),
      'credit_card', 'second_capture'
    )
    RETURNING id INTO v_txn;

    INSERT INTO payments.refunds (transaction_id, order_id, amount, currency, reason, status, idempotency_key)
    SELECT v_txn, v_intent.order_id, v_intent.amount, 'JMD', 'Duplicate capture refund', 'pending', 'dup-capture:' || v_txn::text
    WHERE NOT EXISTS (
      SELECT 1 FROM payments.refunds r WHERE r.idempotency_key = 'dup-capture:' || v_txn::text
    )
    RETURNING id INTO v_refund;

    RETURN jsonb_build_object(
      'action', 'duplicate_refund_required',
      'transaction_id', v_txn,
      'refund_id', v_refund,
      'order_id', v_intent.order_id
    );
  END IF;

  INSERT INTO payments.transactions (
    intent_id, order_id, customer_id, amount, net_amount, currency, status, provider,
    provider_transaction_id, provider_data, payment_method
  ) VALUES (
    p_intent_id, v_intent.order_id, v_intent.customer_id, v_intent.amount, COALESCE(p_net_amount, v_intent.amount),
    'JMD', 'completed', p_provider, COALESCE(v_provider_txn, p_intent_id::text),
    COALESCE(p_provider_data, '{}'::jsonb), 'credit_card'
  )
  RETURNING id INTO v_txn;

  SELECT status INTO v_posted FROM payments.transactions WHERE id = v_txn;
  IF v_posted = 'duplicate_superseded' THEN
    IF v_intent.status IN ('pending', 'created') THEN
      UPDATE payments.payment_intents
      SET status = 'superseded', completed_at = now()
      WHERE id = p_intent_id;
    END IF;
    RETURN jsonb_build_object(
      'action', 'duplicate_refund_required',
      'transaction_id', v_txn,
      'order_id', v_intent.order_id
    );
  END IF;

  UPDATE payments.payment_intents
  SET status = 'completed',
      completed_at = now(),
      provider_data = COALESCE(provider_data, '{}'::jsonb) || jsonb_build_object('callback', COALESCE(p_provider_data, '{}'::jsonb))
  WHERE id = p_intent_id;

  IF v_intent.order_id IS NULL THEN
    RETURN jsonb_build_object('action', 'captured', 'transaction_id', v_txn);
  END IF;

  IF v_order.status = 'cancelled'
     OR v_order.payment_status IN ('refunded', 'refund_pending', 'partially_refunded')
     OR (v_intent.expires_at IS NOT NULL AND v_intent.expires_at < now()) THEN
    INSERT INTO payments.refunds (transaction_id, order_id, amount, currency, reason, status, idempotency_key)
    VALUES (
      v_txn, v_intent.order_id, v_intent.amount, 'JMD',
      'Late or cancelled capture refund', 'pending', 'late-capture:' || v_txn::text
    )
    RETURNING id INTO v_refund;
    RETURN jsonb_build_object(
      'action', 'late_capture_refund_required',
      'transaction_id', v_txn,
      'refund_id', v_refund,
      'order_id', v_intent.order_id
    );
  END IF;

  IF v_order.payment_status IS NULL
     OR v_order.payment_status IN ('pending', 'pending_collection') THEN
    UPDATE delivery.orders
    SET payment_status = 'paid', updated_at = now()
    WHERE id = v_intent.order_id;
  END IF;

  RETURN jsonb_build_object('action', 'captured', 'transaction_id', v_txn, 'order_id', v_intent.order_id);
END;
$$;


ALTER FUNCTION "payments"."complete_payment_intent"("p_intent_id" "uuid", "p_provider" "text", "p_provider_transaction_id" "text", "p_amount" numeric, "p_currency" "text", "p_net_amount" numeric, "p_provider_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "payments"."refund_superseded_capture"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'duplicate_superseded' AND NEW.failure_reason = 'second_capture' THEN
    INSERT INTO payments.refunds (transaction_id, order_id, amount, currency, reason, status, idempotency_key)
    SELECT NEW.id, NEW.order_id, NEW.amount, 'JMD', 'Duplicate capture refund', 'pending', 'dup-capture:' || NEW.id::text
    WHERE NOT EXISTS (
      SELECT 1 FROM payments.refunds r WHERE r.idempotency_key = 'dup-capture:' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "payments"."refund_superseded_capture"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "payments"."refuse_second_capture"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_prior uuid;
BEGIN
  IF NEW.status IS DISTINCT FROM 'completed' OR NEW.order_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_prior
  FROM payments.transactions
  WHERE order_id = NEW.order_id
    AND status = 'completed'
    AND intent_id IS DISTINCT FROM NEW.intent_id
  LIMIT 1;
  IF v_prior IS NULL THEN
    RETURN NEW;
  END IF;
  NEW.status := 'duplicate_superseded';
  NEW.failure_reason := 'second_capture';
  RETURN NEW;
END;
$$;


ALTER FUNCTION "payments"."refuse_second_capture"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "payments"."seal_bank_account_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'payments', 'vault', 'public'
    AS $$
BEGIN
  IF NEW.account_number IS NULL OR btrim(NEW.account_number) = '' THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'vault' AND p.proname = 'create_secret'
  ) THEN
    RETURN NEW;
  END IF;
  IF NEW.id IS NULL THEN
    NEW.id := gen_random_uuid();
  END IF;
  IF NEW.account_secret_id IS NULL THEN
    NEW.account_secret_id := vault.create_secret(
      btrim(NEW.account_number),
      'rush-bank-' || TG_TABLE_NAME || '-' || NEW.id::text,
      'Rush payout account'
    );
  ELSE
    PERFORM vault.update_secret(NEW.account_secret_id, btrim(NEW.account_number));
  END IF;
  NEW.account_number := NULL;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "payments"."seal_bank_account_number"() OWNER TO "postgres";


