CREATE OR REPLACE FUNCTION "places"."latest_retail_estimate"("p_grade" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'fuel', 'public'
    AS $$
DECLARE
  wholesale numeric;
  mark numeric;
BEGIN
  SELECT CASE p_grade
    WHEN 'e10_90' THEN gasolene_90
    WHEN 'diesel' THEN auto_diesel
    ELSE gasolene_87
  END
  INTO wholesale
  FROM fuel.petrojam_prices
  ORDER BY price_date DESC
  LIMIT 1;

  IF wholesale IS NULL OR wholesale <= 0 THEN
    RETURN NULL;
  END IF;

  SELECT CASE p_grade
    WHEN 'e10_90' THEN gasolene_90_markup
    WHEN 'diesel' THEN auto_diesel_markup
    ELSE gasolene_87_markup
  END
  INTO mark
  FROM fuel.retail_price_markup
  WHERE is_published IS TRUE
  ORDER BY effective_from DESC
  LIMIT 1;

  IF mark IS NULL OR mark < 0 THEN
    RETURN NULL;
  END IF;
  RETURN wholesale + mark;
END;
$$;


ALTER FUNCTION "places"."latest_retail_estimate"("p_grade" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "places"."parish_pcode"("lat" double precision, "lng" double precision) RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT b.pcode
  FROM geo.boundaries b
  JOIN geo.boundary_versions v ON v.id = b.current_version_id
  WHERE b.admin_level = 1
    AND b.status = 'active'
    AND v.geom IS NOT NULL
    AND ST_Contains(v.geom, ST_SetSRID(ST_Point(lng, lat), 4326))
  LIMIT 1
$$;


ALTER FUNCTION "places"."parish_pcode"("lat" double precision, "lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "places"."refresh_coverage"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'places', 'public'
    AS $$
begin
  delete from places.coverage_count where true;
  insert into places.coverage_count (pcode, kind, verified_count, pending_count)
  select pcode, kind, sum(verified_count)::integer, sum(pending_count)::integer
  from (
    select pcode, 'station'::text as kind, count(*)::integer as verified_count, 0 as pending_count
    from places.public_station
    where pcode is not null and btrim(pcode) <> ''
    group by pcode
    union all
    select pcode, kind, count(*)::integer, 0
    from places.public_place
    where pcode is not null and btrim(pcode) <> ''
    group by pcode, kind
    union all
    select p.pcode, coalesce(c.kind, 'mechanic'), 0, count(*)::integer
    from places.place p
    left join lateral (
      select cap.kind
      from places.place_capability cap
      where cap.place_id = p.id
      limit 1
    ) c on true
    where p.status = 'pending'
      and p.pcode is not null
      and btrim(p.pcode) <> ''
    group by p.pcode, coalesce(c.kind, 'mechanic')
  ) rows
  group by pcode, kind;
end;
$$;


ALTER FUNCTION "places"."refresh_coverage"() OWNER TO "postgres";


