BEGIN
  SELECT string_agg(COALESCE(email, '(owner count)') || ': ' || problem, '; ')
  INTO problems
  FROM platform.role_consistency_problems();
  IF problems IS NOT NULL THEN
    RAISE EXCEPTION 'Platform role consistency failed: %', problems;
  END IF;
END;
$$;


