CREATE OR REPLACE FUNCTION "platform"."jwt_role_texts"("meta" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE((
    SELECT array_agg(DISTINCT role_name)
    FROM (
      SELECT btrim(meta->>'role') AS role_name
      WHERE COALESCE(btrim(meta->>'role'), '') <> ''
      UNION ALL
      SELECT btrim(elem) AS role_name
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(meta->'roles') = 'array' THEN meta->'roles'
          ELSE '[]'::jsonb
        END
      ) AS elem
      WHERE COALESCE(btrim(elem), '') <> ''
    ) s
    WHERE role_name IS NOT NULL AND role_name <> ''
  ), '{}'::text[]);
$$;


ALTER FUNCTION "platform"."jwt_role_texts"("meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform"."merge_app_metadata_roles"("meta" "jsonb", "add_roles" "text"[], "remove_roles" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  roles text[];
  primary_role text;
BEGIN
  roles := ARRAY(
    SELECT DISTINCT role_name
    FROM (
      SELECT unnest(platform.jwt_role_texts(meta)) AS role_name
      UNION ALL
      SELECT unnest(COALESCE(add_roles, '{}'::text[]))
    ) s
    WHERE role_name IS NOT NULL
      AND role_name <> ''
      AND NOT (role_name = ANY (COALESCE(remove_roles, '{}'::text[])))
  );

  primary_role := COALESCE(btrim(meta->>'role'), '');
  IF primary_role = ''
     OR primary_role = ANY (COALESCE(remove_roles, '{}'::text[]))
     OR NOT (primary_role = ANY (roles)) THEN
    primary_role := COALESCE(NULLIF(add_roles[1], ''), roles[1], '');
  END IF;

  RETURN jsonb_set(
    jsonb_set(COALESCE(meta, '{}'::jsonb), '{roles}', to_jsonb(roles), true),
    '{role}',
    to_jsonb(primary_role),
    true
  );
END;
$$;


ALTER FUNCTION "platform"."merge_app_metadata_roles"("meta" "jsonb", "add_roles" "text"[], "remove_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform"."reconcile_identities"() RETURNS TABLE("synced_count" integer, "drift_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'platform', 'delivery', 'auth', 'public'
    AS $$
DECLARE
  v_synced INT := 0;
  v_drift INT := 0;
  r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT user_id FROM (
      SELECT user_id FROM delivery.customers
      UNION SELECT user_id FROM delivery.courier_profiles
      UNION SELECT owner_id AS user_id FROM delivery.merchants WHERE owner_id IS NOT NULL
      UNION SELECT user_id FROM delivery.merchant_team_members WHERE user_id IS NOT NULL
    ) personas
  LOOP
    PERFORM platform.upsert_identity_for_user(r.user_id);
    v_synced := v_synced + 1;
  END LOOP;

  SELECT COUNT(*)::INT INTO v_drift
  FROM (
    SELECT DISTINCT user_id FROM (
      SELECT user_id FROM delivery.customers
      UNION SELECT user_id FROM delivery.courier_profiles
      UNION SELECT owner_id AS user_id FROM delivery.merchants WHERE owner_id IS NOT NULL
      UNION SELECT user_id FROM delivery.merchant_team_members WHERE user_id IS NOT NULL
    ) p
  ) expected
  WHERE NOT EXISTS (SELECT 1 FROM platform.identities i WHERE i.user_id = expected.user_id);

  RETURN QUERY SELECT v_synced, v_drift;
END;
$$;


ALTER FUNCTION "platform"."reconcile_identities"() OWNER TO "postgres";


