CREATE OR REPLACE FUNCTION "private"."invoke_finance_doctor"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'net'
    AS $$
DECLARE
  secret text;
  req_id bigint;
BEGIN
