CREATE OR REPLACE FUNCTION "public"."adjust_org_part_stock"("p_org" "text", "p_part" "uuid", "p_delta" numeric) RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_stock_id uuid;
  v_qty numeric;
  v_applied numeric;
BEGIN
  IF p_org IS NULL OR p_part IS NULL OR p_delta IS NULL OR p_delta = 0 THEN
    RETURN 0;
  END IF;
  SELECT s.id, s.qty INTO v_stock_id, v_qty
  FROM public.org_part_stock s
  WHERE s.organization_id = p_org AND s.part_id = p_part
  ORDER BY s.qty DESC
  LIMIT 1;
  IF v_stock_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF p_delta < 0 THEN
    v_applied := -LEAST(v_qty, -p_delta);
  ELSE
    v_applied := p_delta;
  END IF;
  UPDATE public.org_part_stock
  SET qty = qty + v_applied, updated_at = now()
  WHERE id = v_stock_id;
  RETURN v_applied;
END;
$$;


ALTER FUNCTION "public"."adjust_org_part_stock"("p_org" "text", "p_part" "uuid", "p_delta" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_usage_events_between"("p_provider" "text", "p_status" "text", "p_q" "text", "p_from" "date", "p_to" "date", "p_limit" integer) RETURNS TABLE("occurred_at" timestamp with time zone, "provider" "text", "service" "text", "route" "text", "model" "text", "status" "text", "http_status" integer, "latency_ms" integer, "input_tokens" integer, "output_tokens" integer, "images" integer, "requests" integer, "cost_usd" numeric, "error_code" "text", "error_message" "text", "user_id" "text", "org_id" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select e.occurred_at, e.provider, e.service, e.route, e.model, e.status, e.http_status, e.latency_ms, e.input_tokens, e.output_tokens, e.images, e.requests, e.cost_usd, e.error_code, e.error_message, e.user_id, e.org_id
  from private.api_usage_events e
  where e.occurred_at >= p_from and e.occurred_at < p_to + 1
    and (p_provider is null or p_provider = '' or e.provider = p_provider)
    and (p_status is null or p_status = '' or e.status = p_status)
    and (p_q is null or p_q = '' or e.route ilike '%' || p_q || '%' or e.model ilike '%' || p_q || '%' or e.error_message ilike '%' || p_q || '%')
  order by e.occurred_at desc
  limit least(greatest(coalesce(p_limit, 100), 1), 200);
$$;


ALTER FUNCTION "public"."api_usage_events_between"("p_provider" "text", "p_status" "text", "p_q" "text", "p_from" "date", "p_to" "date", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_usage_top_routes"("p_provider" "text", "p_day" "date") RETURNS TABLE("route" "text", "calls" bigint, "cost_usd" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(nullif(e.route, ''), '(unknown)'), count(*)::bigint, coalesce(sum(e.cost_usd), 0)
  from private.api_usage_events e
  where e.provider = p_provider and e.occurred_at >= p_day and e.occurred_at < p_day + 1
  group by 1 order by 3 desc limit 10;
$$;


