CREATE OR REPLACE FUNCTION "public"."decide_part_rule_proposal"("p_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_prop public.part_rule_proposal%ROWTYPE;
  v_group uuid;
BEGIN
  IF p_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Choose approve or reject.';
  END IF;
  SELECT * INTO v_prop
  FROM public.part_rule_proposal
  WHERE id = p_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Suggestion not found';
  END IF;
  IF v_prop.status <> 'proposed' THEN
    RAISE EXCEPTION 'This suggestion is already closed.';
  END IF;
  IF p_status = 'approved' THEN
    SELECT pm.interchange_group_id INTO v_group
    FROM public.part_master pm
    WHERE pm.id = v_prop.part_id;
    IF v_group IS NULL THEN
      RAISE EXCEPTION 'This part has no interchange group yet.';
    END IF;
    INSERT INTO public.interchange_fitment_rule (
      interchange_group_id, target_kind, platform_id, engine_family_id, source
    ) VALUES (
      v_group, v_prop.target_kind, v_prop.platform_id, v_prop.engine_family_id, 'install_confirmed'
    );
  END IF;
  UPDATE public.part_rule_proposal
  SET status = p_status
  WHERE id = p_id
  RETURNING * INTO v_prop;
  RETURN to_jsonb(v_prop);
END;
$$;


ALTER FUNCTION "public"."decide_part_rule_proposal"("p_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delivery_courier_upsert_presence"("p_driver_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_h3_cell" "text", "p_h3_res" integer, "p_is_online" boolean DEFAULT true, "p_active_order_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'fleet', 'public'
    AS $$
DECLARE
  v_cell TEXT := NULLIF(trim(p_h3_cell), '');
  v_res SMALLINT := CASE WHEN p_h3_res IS NULL THEN NULL ELSE p_h3_res::SMALLINT END;
  v_prev boolean;
BEGIN
  IF p_driver_id IS NULL THEN
    RAISE EXCEPTION 'driver_id_required' USING ERRCODE = '22023';
  END IF;

  IF p_is_online IS TRUE THEN
    IF p_lat IS NULL OR p_lng IS NULL THEN
      RAISE EXCEPTION 'location_required' USING ERRCODE = '22023';
    END IF;
    IF v_cell IS NULL OR v_res IS NULL THEN
      RAISE EXCEPTION 'presence_h3_required' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT is_online INTO v_prev
  FROM delivery.courier_availability
  WHERE driver_id = p_driver_id;

  INSERT INTO delivery.courier_availability (
    driver_id, current_lat, current_lng, h3_cell, h3_res,
    is_online, active_order_id, last_location_update, updated_at
  ) VALUES (
    p_driver_id, p_lat, p_lng, v_cell, v_res,
    COALESCE(p_is_online, FALSE), p_active_order_id, NOW(), NOW()
  )
  ON CONFLICT (driver_id) DO UPDATE SET
    current_lat = COALESCE(EXCLUDED.current_lat, delivery.courier_availability.current_lat),
    current_lng = COALESCE(EXCLUDED.current_lng, delivery.courier_availability.current_lng),
    h3_cell = CASE
      WHEN EXCLUDED.current_lat IS NOT NULL AND EXCLUDED.current_lng IS NOT NULL
        THEN EXCLUDED.h3_cell
      ELSE delivery.courier_availability.h3_cell
    END,
    h3_res = CASE
      WHEN EXCLUDED.current_lat IS NOT NULL AND EXCLUDED.current_lng IS NOT NULL
        THEN EXCLUDED.h3_res
      ELSE delivery.courier_availability.h3_res
    END,
    is_online = EXCLUDED.is_online,
    active_order_id = COALESCE(EXCLUDED.active_order_id, delivery.courier_availability.active_order_id),
    last_location_update = NOW(),
    updated_at = NOW();

  IF (v_prev IS NOT NULL OR COALESCE(p_is_online, FALSE))
     AND v_prev IS DISTINCT FROM COALESCE(p_is_online, FALSE) THEN
    PERFORM fleet.append_presence_transition(
      p_driver_id,
      'roam_rush',
      COALESCE(p_is_online, FALSE),
      'app_toggle',
      NULL,
      '{}'::jsonb
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."delivery_courier_upsert_presence"("p_driver_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_h3_cell" "text", "p_h3_res" integer, "p_is_online" boolean, "p_active_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delivery_couriers_in_h3_cells"("p_cells" "text"[], "p_res" smallint, "p_fresh_since" timestamp with time zone, "p_limit" integer DEFAULT 200) RETURNS TABLE("driver_id" "uuid", "current_lat" double precision, "current_lng" double precision, "h3_cell" "text", "h3_res" smallint, "last_location_update" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
BEGIN
  IF p_cells IS NULL OR cardinality(p_cells) = 0 THEN
    RETURN;
  END IF;
  IF cardinality(p_cells) > 2000 THEN
    RAISE EXCEPTION 'h3_cell_array_too_large' USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 THEN
    p_limit := 200;
  END IF;
  p_limit := LEAST(p_limit, 500);

  RETURN QUERY
  SELECT
    ca.driver_id,
    ca.current_lat,
    ca.current_lng,
    ca.h3_cell,
    ca.h3_res,
    ca.last_location_update
  FROM delivery.courier_availability ca
  WHERE ca.h3_res = p_res
    AND ca.h3_cell = ANY (p_cells)
    AND ca.is_online = TRUE
    AND ca.h3_cell IS NOT NULL
    AND ca.last_location_update >= p_fresh_since
  ORDER BY ca.last_location_update DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."delivery_couriers_in_h3_cells"("p_cells" "text"[], "p_res" smallint, "p_fresh_since" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delivery_refresh_surge_now"("p_window_minutes" integer DEFAULT 15) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
DECLARE
  v_since TIMESTAMPTZ := NOW() - make_interval(mins => GREATEST(1, p_window_minutes));
  v_count INTEGER := 0;
BEGIN
  DELETE FROM delivery.surge_now;

  INSERT INTO delivery.surge_now (h3_cell, h3_res, open_demand, surge_multiplier, updated_at)
  SELECT
    de.h3_cell,
    de.h3_res,
    COUNT(*)::INTEGER AS open_demand,
    CASE
      WHEN COUNT(*) >= 12 THEN 2.0
      WHEN COUNT(*) >= 8 THEN 1.5
      WHEN COUNT(*) >= 4 THEN 1.2
      ELSE 1.0
    END,
    NOW()
  FROM delivery.demand_events de
  WHERE de.occurred_at >= v_since
  GROUP BY de.h3_cell, de.h3_res;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."delivery_refresh_surge_now"("p_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dfp_service_line_matches"("p_metadata" "jsonb", "p_service_line" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_service_line IS NULL OR btrim(p_service_line) = '' THEN true
    WHEN COALESCE((p_metadata->>'rushTripCount')::numeric, 0) = 0
      AND COALESCE((p_metadata->>'rideshareTripCount')::numeric, 0) = 0 THEN true
    WHEN p_service_line = 'rush_delivery'
      THEN COALESCE((p_metadata->>'rushTripCount')::numeric, 0) > 0
    WHEN p_service_line = 'rideshare'
      THEN COALESCE((p_metadata->>'rideshareTripCount')::numeric, 0) > 0
    ELSE true
  END;
$$;


