CREATE OR REPLACE FUNCTION "public"."driver_audit_events_since"("p_after" timestamp with time zone, "p_after_key" "text", "p_limit" integer) RETURNS TABLE("kv_key" "text", "value" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select s.key, s.value
  from public.kv_store_37f42386 s
  where starts_with(s.key, 'driver_audit:')
    and (s.value->>'at') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
    and (
      p_after is null
      or (s.value->>'at')::timestamptz > p_after
      or ((s.value->>'at')::timestamptz = p_after and s.key > coalesce(p_after_key, ''))
    )
  order by (s.value->>'at')::timestamptz, s.key
  limit least(greatest(coalesce(p_limit, 500), 1), 500);
$$;


