CREATE OR REPLACE FUNCTION "public"."enforce_interchange_fitment_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  scope text;
BEGIN
  SELECT fit_scope INTO scope
  FROM public.part_interchange_group
  WHERE id = NEW.interchange_group_id;
  IF NEW.target_kind = 'engine_family' AND scope NOT IN ('powertrain', 'universal') THEN
    RAISE EXCEPTION 'engine-family fitment is only allowed for powertrain or universal groups';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_interchange_fitment_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_verified_part_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.catalog_decision = 'confirmed' AND coalesce(btrim(NEW.evidence_url), '') = '' THEN
    IF TG_OP = 'INSERT'
      OR OLD.catalog_decision IS DISTINCT FROM 'confirmed'
      OR coalesce(btrim(OLD.evidence_url), '') <> '' THEN
      RAISE EXCEPTION 'A verified part needs a source link';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_verified_part_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_doctor_anon_execute_audit"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  names text[] := ARRAY[
    'bulk_insert_toll_ledger',
    'try_claim_week_close',
    'release_week_close_lock',
    'compute_source_coverage',
    'list_week_source_summaries',
    'fleet_compute_vehicle_tag_balance',
    'fleet_toll_tag_balance_rows',
    'rush_post_journal',
    'rush_transition_money_state',
    'rush_lock_week',
    'rush_lock_lines',
    'rush_week_payable',
    'freeze_settlement_periods_batch',
    'fleet_rebuild_operational_periods',
    'fleet_assign_toll_tag',
    'fleet_unassign_toll_tag',
    'fleet_retire_toll_tag',
    'fleet_scan_toll_low_balances',
    'delivery_refresh_surge_now',
    'fleet_driver_lifetime_totals',
    'fleet_fare_earnings_by_driver',
    'fleet_period_earnings_by_driver',
    'fleet_operational_rollup_by_driver',
    'fleet_trip_status_buckets_by_driver',
    'sum_settlement_queue_totals',
    'delivery_couriers_in_h3_cells',
    'rides_drivers_in_h3_cells'
  ];
  leaks jsonb := '[]'::jsonb;
  r record;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname = ANY (names)
  LOOP
    IF has_function_privilege('anon', r.oid, 'EXECUTE')
       OR has_function_privilege('authenticated', r.oid, 'EXECUTE') THEN
      leaks := leaks || jsonb_build_array(jsonb_build_object(
        'proname', r.proname,
        'args', r.args,
        'anon', has_function_privilege('anon', r.oid, 'EXECUTE'),
        'authenticated', has_function_privilege('authenticated', r.oid, 'EXECUTE')
      ));
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', jsonb_array_length(leaks) = 0,
    'leaks', leaks,
    'checked', names
  );
END;
$$;


ALTER FUNCTION "public"."finance_doctor_anon_execute_audit"() OWNER TO "postgres";


