CREATE OR REPLACE FUNCTION "public"."freeze_settlement_periods_batch"("p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ledger'
    AS $$
DECLARE
  r jsonb;
  n int := 0;
  v_close text;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'FREEZE_BATCH_INVALID';
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows)
  LOOP
    v_close := NULLIF(r->>'close_hash', '');
    UPDATE ledger.driver_financial_periods p
    SET
      status = 'closed',
      closed_at = COALESCE((r->>'closed_at')::timestamptz, now()),
      reopened_at = NULL,
      -- Dual-write: legacy column + dedicated close_hash (Phase 1).
      source_event_hash = COALESCE(v_close, ''),
      close_hash = v_close,
      metadata = COALESCE(r->'metadata', p.metadata)
    WHERE p.id = (r->>'id')::uuid;
    IF FOUND THEN
      n := n + 1;
    END IF;
  END LOOP;

  RETURN n;
END;
$$;


ALTER FUNCTION "public"."freeze_settlement_periods_batch"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."freeze_settlement_periods_batch"("p_rows" "jsonb") IS 'H-2/Phase1: atomic calendar freeze; dual-writes source_event_hash + close_hash + metadata.';



