CREATE OR REPLACE FUNCTION "public"."ledger_delete_entries"("p_reference_type" "text" DEFAULT NULL::"text", "p_reference_ids" "text"[] DEFAULT NULL::"text"[], "p_batch_id" "text" DEFAULT NULL::"text", "p_from_ymd" "date" DEFAULT NULL::"date", "p_source_system" "text" DEFAULT 'kv_ledger_event'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public'
    AS $$
DECLARE
  v_entry_ids uuid[];
  v_deleted int := 0;
  v_receipts int := 0;
BEGIN
  IF p_batch_id IS NOT NULL AND length(trim(p_batch_id)) > 0 THEN
    SELECT coalesce(array_agg(e.id), ARRAY[]::uuid[])
    INTO v_entry_ids
    FROM ledger.entries e
    WHERE e.metadata->>'batchId' = p_batch_id
      AND (p_from_ymd IS NULL OR (e.effective_at AT TIME ZONE 'UTC')::date >= p_from_ymd);
  ELSIF p_reference_type IS NOT NULL AND p_reference_ids IS NOT NULL AND cardinality(p_reference_ids) > 0 THEN
    SELECT coalesce(array_agg(e.id), ARRAY[]::uuid[])
    INTO v_entry_ids
    FROM ledger.entries e
    WHERE e.reference_type = p_reference_type
      AND e.reference_id = ANY (p_reference_ids)
      AND (p_from_ymd IS NULL OR (e.effective_at AT TIME ZONE 'UTC')::date >= p_from_ymd);
  ELSE
    RETURN jsonb_build_object('deleted', 0, 'receipts_deleted', 0);
  END IF;

  IF v_entry_ids IS NULL OR cardinality(v_entry_ids) = 0 THEN
    RETURN jsonb_build_object('deleted', 0, 'receipts_deleted', 0);
  END IF;

  DELETE FROM ledger.source_receipts sr
  WHERE sr.ledger_entry_id = ANY (v_entry_ids)
     OR (
       p_source_system IS NOT NULL
       AND sr.source_system = p_source_system
       AND sr.source_id IN (
         SELECT e.id::text FROM ledger.entries e WHERE e.id = ANY (v_entry_ids)
       )
     );
  GET DIAGNOSTICS v_receipts = ROW_COUNT;

  DELETE FROM ledger.entries e WHERE e.id = ANY (v_entry_ids);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object('deleted', v_deleted, 'receipts_deleted', v_receipts);
END;
$$;


ALTER FUNCTION "public"."ledger_delete_entries"("p_reference_type" "text", "p_reference_ids" "text"[], "p_batch_id" "text", "p_from_ymd" "date", "p_source_system" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ledger_delete_source_receipts"("p_source_system" "text", "p_source_ids" "text"[] DEFAULT NULL::"text"[], "p_source_idempotency_keys" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ledger'
    AS $$
DECLARE
  v_deleted int := 0;
  v_n int := 0;
BEGIN
  IF p_source_system IS NULL OR length(trim(p_source_system)) = 0 THEN
    RETURN jsonb_build_object('deleted', 0, 'error', 'source_system_required');
  END IF;

  IF p_source_ids IS NOT NULL AND array_length(p_source_ids, 1) IS NOT NULL THEN
    DELETE FROM ledger.source_receipts sr
    WHERE sr.source_system = p_source_system
      AND sr.source_id = ANY (p_source_ids);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_deleted := v_deleted + v_n;
  END IF;

  IF p_source_idempotency_keys IS NOT NULL AND array_length(p_source_idempotency_keys, 1) IS NOT NULL THEN
    DELETE FROM ledger.source_receipts sr
    WHERE sr.source_system = p_source_system
      AND sr.source_idempotency_key = ANY (p_source_idempotency_keys);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_deleted := v_deleted + v_n;
  END IF;

  RETURN jsonb_build_object('deleted', v_deleted);
END;
$$;


ALTER FUNCTION "public"."ledger_delete_source_receipts"("p_source_system" "text", "p_source_ids" "text"[], "p_source_idempotency_keys" "text"[]) OWNER TO "postgres";


