CREATE OR REPLACE FUNCTION "public"."ledger_post_entry"("p_idempotency_key" "text", "p_entry_type" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_amount_minor" bigint, "p_currency" "text", "p_request_hash" "text" DEFAULT NULL::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_product" "text" DEFAULT 'platform'::"text", "p_effective_at" timestamp with time zone DEFAULT "now"(), "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid", "p_source_system" "text" DEFAULT NULL::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_source_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public'
    AS $$ SELECT ledger.post_entry(p_idempotency_key, p_entry_type, p_debit_account_key, p_credit_account_key, p_amount_minor, p_currency, p_request_hash, p_organization_id, p_product, p_effective_at, p_reference_type, p_reference_id, p_metadata, p_created_by_user_id, p_source_system, p_source_id, p_source_idempotency_key); $$;


