CREATE OR REPLACE FUNCTION "public"."ledger_product_balances"("p_products" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("product" "text", "total_debits_minor" bigint, "total_credits_minor" bigint, "net_balance_minor" bigint, "balanced" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'ledger', 'public', 'pg_catalog'
    AS $$
  with scoped as (
    select
      e.product,
      e.amount_minor,
      e.debit_account_id,
      e.credit_account_id
    from ledger.entries e
    where p_products is null
       or cardinality(p_products) = 0
       or e.product = any (p_products)
  ),
  agg as (
    select
      s.product,
      coalesce(sum(abs(s.amount_minor)) filter (
        where s.debit_account_id is distinct from s.credit_account_id
      ), 0)::bigint as side_minor,
      count(*) filter (where s.debit_account_id = s.credit_account_id)::bigint as self_ref
    from scoped s
    group by s.product
  )
  select
    a.product,
    a.side_minor as total_debits_minor,
    a.side_minor as total_credits_minor,
    0::bigint as net_balance_minor,
    (a.self_ref = 0) as balanced
  from agg a
  order by a.product;
$$;


ALTER FUNCTION "public"."ledger_product_balances"("p_products" "text"[]) OWNER TO "postgres";


