CREATE OR REPLACE FUNCTION "public"."log_api_usage"("p_provider" "text", "p_service" "text", "p_route" "text", "p_model" "text", "p_status" "text", "p_http_status" integer, "p_latency_ms" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_images" integer, "p_requests" integer, "p_cost_usd" numeric, "p_error_code" "text", "p_error_message" "text", "p_user_id" "text", "p_org_id" "text", "p_occurred_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_at timestamptz := coalesce(p_occurred_at, now());
  v_day text := to_char(v_at at time zone 'UTC', 'YYYY-MM-DD');
  v_month text := to_char(v_at at time zone 'UTC', 'YYYY-MM');
  v_err int := case when p_status = 'error' then 1 else 0 end;
  v_cost numeric := coalesce(p_cost_usd, 0);
begin
  insert into private.api_usage_events (
    occurred_at, provider, service, route, model, status, http_status, latency_ms,
    input_tokens, output_tokens, images, requests, cost_usd, error_code, error_message, user_id, org_id
  ) values (
    v_at, p_provider, p_service, p_route, p_model, coalesce(p_status, 'success'), p_http_status, p_latency_ms,
    p_input_tokens, p_output_tokens, p_images, p_requests, v_cost, p_error_code, left(p_error_message, 500),
    p_user_id, p_org_id
  );
  insert into private.api_usage_totals as t (provider, period, calls, errors, cost_usd, input_tokens, output_tokens, images, requests, updated_at)
  values (p_provider, v_day, 1, v_err, v_cost, coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0), coalesce(p_images, 0), coalesce(p_requests, 0), now())
  on conflict (provider, period) do update set
    calls = t.calls + 1, errors = t.errors + excluded.errors, cost_usd = t.cost_usd + excluded.cost_usd,
    input_tokens = t.input_tokens + excluded.input_tokens, output_tokens = t.output_tokens + excluded.output_tokens,
    images = t.images + excluded.images, requests = t.requests + excluded.requests, updated_at = now();
  insert into private.api_usage_totals as t (provider, period, calls, errors, cost_usd, input_tokens, output_tokens, images, requests, updated_at)
  values (p_provider, v_month, 1, v_err, v_cost, coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0), coalesce(p_images, 0), coalesce(p_requests, 0), now())
  on conflict (provider, period) do update set
    calls = t.calls + 1, errors = t.errors + excluded.errors, cost_usd = t.cost_usd + excluded.cost_usd,
    input_tokens = t.input_tokens + excluded.input_tokens, output_tokens = t.output_tokens + excluded.output_tokens,
    images = t.images + excluded.images, requests = t.requests + excluded.requests, updated_at = now();
end;
$$;


