CREATE OR REPLACE FUNCTION "public"."mark_vehicle_week_distance_stale"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  org text;
  vehicle text;
  day date;
  week date;
begin
  org := coalesce(new.organization_id, old.organization_id);
  vehicle := coalesce(new.vehicle_id, old.vehicle_id);
  day := coalesce(new.date, old.date);
  if org is null or vehicle is null or day is null then
    return coalesce(new, old);
  end if;
  week := date_trunc('week', day::timestamp)::date;
  update public.vehicle_week_distance
     set stale = true
   where organization_id = org
     and vehicle_id = vehicle
     and week_start = week;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."mark_vehicle_week_distance_stale"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."matching_accept_driver_offer"("p_offer_id" "uuid", "p_driver_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_offer rides.driver_offers%ROWTYPE;
  v_ride rides.ride_requests%ROWTYPE;
  v_now TIMESTAMPTZ := NOW();
  v_result JSONB;
BEGIN
  -- 1. Lock and fetch offer
  SELECT * INTO v_offer
  FROM rides.driver_offers
  WHERE id = p_offer_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_found');
  END IF;
  
  -- 2. Verify driver owns the offer
  IF v_offer.driver_user_id != p_driver_user_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_found');
  END IF;
  
  -- 3. Check offer is pending
  IF v_offer.status != 'pending' THEN
    RETURN jsonb_build_object(
      'ok', false, 
      'error', 'offer_not_pending',
      'current_status', v_offer.status
    );
  END IF;
  
  -- 4. Check offer hasn't expired
  IF v_offer.expires_at <= v_now THEN
    -- Mark as expired
    UPDATE rides.driver_offers
    SET status = 'expired'
    WHERE id = p_offer_id;
    
    RETURN jsonb_build_object('ok', false, 'error', 'offer_expired');
  END IF;
  
  -- 5. Lock and fetch ride
  SELECT * INTO v_ride
  FROM rides.ride_requests
  WHERE id = v_offer.ride_request_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ride_not_found');
  END IF;
  
  -- 6. Verify ride is still matching
  IF v_ride.status != 'matching' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'ride_not_matching',
      'current_status', v_ride.status
    );
  END IF;
  
  -- 7. Accept the offer
  UPDATE rides.driver_offers
  SET status = 'accepted'
  WHERE id = p_offer_id;
  
  -- 8. Assign driver to ride
  UPDATE rides.ride_requests
  SET 
    status = 'driver_assigned',
    assigned_driver_user_id = p_driver_user_id,
    updated_at = v_now
  WHERE id = v_offer.ride_request_id
    AND status = 'matching';
  
  IF NOT FOUND THEN
    -- Race condition: another driver won
    -- Rollback the offer accept
    UPDATE rides.driver_offers
    SET status = 'superseded'
    WHERE id = p_offer_id;
    
    RETURN jsonb_build_object('ok', false, 'error', 'assign_failed');
  END IF;
  
  -- 9. Supersede other pending offers for this ride
  UPDATE rides.driver_offers
  SET status = 'superseded'
  WHERE ride_request_id = v_offer.ride_request_id
    AND status = 'pending'
    AND id != p_offer_id;
  
  -- 10. Supersede all pending offers for this driver (other rides)
  UPDATE rides.driver_offers
  SET status = 'superseded'
  WHERE driver_user_id = p_driver_user_id
    AND status = 'pending'
    AND id != p_offer_id;
  
  -- 11. Fetch the updated ride
  SELECT * INTO v_ride
  FROM rides.ride_requests
  WHERE id = v_offer.ride_request_id;
  
  -- 12. Return success with ride data
  v_result := jsonb_build_object(
    'ok', true,
    'offer_id', p_offer_id,
    'ride_request_id', v_offer.ride_request_id,
    'ride', to_jsonb(v_ride)
  );
  
  RETURN v_result;
  
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'internal_error',
      'message', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."matching_accept_driver_offer"("p_offer_id" "uuid", "p_driver_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."matching_accept_driver_offer"("p_offer_id" "uuid", "p_driver_user_id" "uuid") IS 'Atomically accept a driver offer. Prevents race conditions by using row-level locks.';



