    'coveragePct', 0,
    'vehicleCount', (SELECT count(*) FROM public.vehicle_catalog WHERE nullif(trim(chassis_code), '') IS NOT NULL),
    'note', 'Active fleet coverage is calculated when Dominion opens Vehicles'
  );
$$;


