END;
$$;


ALTER FUNCTION "public"."recon_enqueue_unit"("p_org" "text", "p_kind" "text", "p_week" "date", "p_driver" "text", "p_vehicle" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recon_enqueue_week_desk"("p_org" "text", "p_line" "text", "p_week" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pgmq', 'public'
    AS $$
BEGIN
  IF p_org IS NULL OR p_line IS NULL OR p_week IS NULL THEN
    RETURN;
  END IF;
  IF p_line NOT IN ('rideshare', 'rush_delivery') THEN
    RETURN;
  END IF;
  PERFORM pgmq.send(
    'recon_recompute',
    jsonb_build_object(
      'organizationId', p_org,
      'unitKind', 'week_desk',
      'weekKey', to_char(p_week, 'YYYY-MM-DD'),
      'serviceLine', p_line
    )
  );
END;
$$;


ALTER FUNCTION "public"."recon_enqueue_week_desk"("p_org" "text", "p_line" "text", "p_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recon_mark_week_pending"("p_org" "text", "p_week" "date", "p_line" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'recon', 'pgmq', 'public', 'ledger', 'fleet'
    AS $$
DECLARE
  r record;
  n int := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT driver_id::text AS driver_id
    FROM ledger.driver_financial_periods
    WHERE organization_id::text = p_org
      AND period_anchor = p_week
      AND driver_id IS NOT NULL
  LOOP
    PERFORM recon.enqueue_unit(p_org, 'driver_week', p_week, r.driver_id, NULL);
    IF p_line = 'rush_delivery' THEN
      PERFORM recon.enqueue_unit(p_org, 'courier_week', p_week, r.driver_id, NULL);
    END IF;
    n := n + 1;
  END LOOP;
  FOR r IN
    SELECT DISTINCT vehicle_id
    FROM fleet.fuel_entries
    WHERE organization_id = p_org
      AND date >= p_week
      AND date < p_week + 7
      AND vehicle_id IS NOT NULL
  LOOP
    PERFORM recon.enqueue_unit(p_org, 'vehicle_week', p_week, NULL, r.vehicle_id);
  END LOOP;
  RETURN n;
END;
$$;


ALTER FUNCTION "public"."recon_mark_week_pending"("p_org" "text", "p_week" "date", "p_line" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recon_queue_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pgmq', 'recon', 'public'
    AS $$
DECLARE
  v_oldest double precision;
  v_failed int;
BEGIN
  BEGIN
    EXECUTE 'SELECT EXTRACT(EPOCH FROM (now() - min(enqueued_at))) FROM pgmq.q_recon_recompute'
      INTO v_oldest;
  EXCEPTION WHEN undefined_table THEN
    v_oldest := NULL;
  END;
  SELECT count(*) INTO v_failed FROM recon.projection_state WHERE status = 'failed';
  RETURN jsonb_build_object('oldestSeconds', v_oldest, 'failedUnits', COALESCE(v_failed, 0));
END;
$$;


ALTER FUNCTION "public"."recon_queue_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recon_read_recompute_batch"("p_qty" integer, "p_vt" integer) RETURNS TABLE("msg_id" bigint, "read_ct" integer, "enqueued_at" timestamp with time zone, "vt" timestamp with time zone, "message" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pgmq', 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT r.msg_id, r.read_ct, r.enqueued_at, r.vt, r.message
  FROM pgmq.read('recon_recompute', GREATEST(p_vt, 1), GREATEST(p_qty, 1)) AS r;
END;
$$;


ALTER FUNCTION "public"."recon_read_recompute_batch"("p_qty" integer, "p_vt" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recon_worker_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pgmq', 'recon', 'public'
    AS $$
DECLARE
  v_off boolean := false;
  v_queue int := 0;
  v_close int := 0;
  v_started timestamptz;
  v_finished timestamptz;
BEGIN
  SELECT emergency_off INTO v_off FROM recon.worker_control WHERE id = 1;
  BEGIN
    EXECUTE 'SELECT count(*)::int FROM pgmq.q_recon_recompute' INTO v_queue;
  EXCEPTION WHEN undefined_table THEN
    v_queue := 0;
  END;
  SELECT count(*)::int INTO v_close
  FROM recon.close_workflows
  WHERE state = 'running';
  SELECT max(created_at) INTO v_started
  FROM recon.worker_alerts
  WHERE kind = 'nightly_started';
  SELECT max(created_at) INTO v_finished
  FROM recon.worker_alerts
  WHERE kind IN ('shadow_ok', 'shadow_mismatch');
  RETURN jsonb_build_object(
    'emergencyOff', COALESCE(v_off, false),
    'queueWaiting', COALESCE(v_queue, 0),
    'closeRunning', COALESCE(v_close, 0) > 0,
    'nightlyInProgress', v_started IS NOT NULL AND (v_finished IS NULL OR v_finished < v_started),
    'nightlyDue', v_started IS NULL OR v_started < now() - interval '24 hours'
  );
END;
$$;


ALTER FUNCTION "public"."recon_worker_status"() OWNER TO "postgres";


