CREATE OR REPLACE FUNCTION "public"."remove_guided_variant"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group uuid := NULLIF(p_input->>'groupId', '')::uuid;
  v_variant uuid := NULLIF(p_input->>'variantId', '')::uuid;
  v_delete boolean := COALESCE((p_input->>'deletePart')::boolean, false);
  v_rule record;
  v_other record;
  v_left integer;
BEGIN
  IF v_group IS NULL OR v_variant IS NULL THEN
    RAISE EXCEPTION 'Choose the part and the vehicle';
  END IF;
  DELETE FROM public.interchange_fitment_rule
  WHERE interchange_group_id = v_group
    AND target_kind = 'catalog_variant'
    AND vehicle_catalog_id = v_variant;

  FOR v_rule IN
    SELECT r.*
    FROM public.interchange_fitment_rule r
    JOIN public.vehicle_catalog vc ON vc.id = v_variant
    LEFT JOIN public.vehicle_platform mine ON mine.id = vc.platform_id
    WHERE r.interchange_group_id = v_group
      AND (
        (r.target_kind = 'platform' AND (r.platform_id = vc.platform_id OR r.platform_id = mine.parent_id))
        OR (r.target_kind = 'engine_family' AND r.engine_family_id = vc.engine_family_id)
      )
      AND (r.year_from IS NULL OR vc.production_start_year IS NULL OR vc.production_start_year >= r.year_from)
      AND (r.year_to IS NULL OR vc.production_start_year IS NULL OR vc.production_start_year <= r.year_to)
  LOOP
    FOR v_other IN
      SELECT id FROM public.vehicle_catalog other
      LEFT JOIN public.vehicle_platform om ON om.id = other.platform_id
      WHERE other.id <> v_variant
        AND (
          (v_rule.target_kind = 'platform' AND (other.platform_id = v_rule.platform_id OR om.parent_id = v_rule.platform_id))
          OR (v_rule.target_kind = 'engine_family' AND other.engine_family_id = v_rule.engine_family_id)
        )
        AND (v_rule.year_from IS NULL OR other.production_start_year IS NULL OR other.production_start_year >= v_rule.year_from)
        AND (v_rule.year_to IS NULL OR other.production_start_year IS NULL OR other.production_start_year <= v_rule.year_to)
    LOOP
      INSERT INTO public.interchange_fitment_rule (
        interchange_group_id, target_kind, vehicle_catalog_id, year_from, year_to, "position", source, notes
      ) VALUES (
        v_group, 'catalog_variant', v_other.id, NULL, NULL, v_rule."position", 'manual', v_rule.notes
      );
    END LOOP;
    DELETE FROM public.interchange_fitment_rule WHERE id = v_rule.id;
  END LOOP;

  SELECT count(*) INTO v_left FROM public.interchange_fitment_rule WHERE interchange_group_id = v_group;
  IF v_left = 0 AND v_delete THEN
    DELETE FROM public.part_master WHERE interchange_group_id = v_group;
    DELETE FROM public.part_interchange_group WHERE id = v_group;
  END IF;
  PERFORM public.refresh_variant_parts_readiness();
  RETURN jsonb_build_object('ok', true, 'rulesLeft', v_left, 'deletedPart', v_left = 0 AND v_delete);
END;
$$;


ALTER FUNCTION "public"."remove_guided_variant"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_guided_fit"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group uuid := NULLIF(p_input->>'groupId', '')::uuid;
  v_before jsonb;
  v_after jsonb;
  v_op text;
  v_ticked uuid[];
  v_actor uuid := NULLIF(p_input->>'verifiedBy', '')::uuid;
BEGIN
  IF v_group IS NULL THEN
    RAISE EXCEPTION 'Choose the part to change';
  END IF;
  SELECT upper(c.op_code) INTO v_op
  FROM public.part_master pm
  JOIN public.maintenance_service_categories c ON c.id = pm.maintenance_component_id
  WHERE pm.interchange_group_id = v_group
  LIMIT 1;
  IF v_op IS NULL THEN
    RAISE EXCEPTION 'That part has no job';
  END IF;
  IF p_input ? 'tickedVariantIds' AND jsonb_typeof(p_input->'tickedVariantIds') = 'array' THEN
    SELECT COALESCE(array_agg(value::uuid), ARRAY[]::uuid[])
    INTO v_ticked
    FROM jsonb_array_elements_text(p_input->'tickedVariantIds') AS value;
  END IF;
  v_before := public.rules_reach(v_group);
  PERFORM public.write_guided_rules(
    v_group,
    NULLIF(p_input->>'variantId', '')::uuid,
    COALESCE(NULLIF(p_input->>'fit', ''), 'catalog_variant'),
    NULLIF(p_input->>'yearFrom', '')::integer,
    NULLIF(p_input->>'yearTo', '')::integer,
    v_ticked,
    NULLIF(p_input->>'position', ''),
    v_op,
    NULLIF(p_input->>'note', ''),
    v_actor,
    true
  );
  v_after := public.rules_reach(v_group);
  PERFORM public.refresh_variant_parts_readiness();
  RETURN jsonb_build_object('ok', true, 'before', v_before, 'after', v_after);
END;
$$;


ALTER FUNCTION "public"."replace_guided_fit"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_parts_usage_for_work_order"("p_work_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_usage public.maintenance_parts_usage%ROWTYPE;
BEGIN
  FOR v_usage IN
    SELECT * FROM public.maintenance_parts_usage WHERE work_order_id = p_work_order_id
  LOOP
    IF COALESCE(v_usage.stock_decremented, 0) > 0 THEN
      PERFORM public.adjust_org_part_stock(v_usage.organization_id, v_usage.part_id, v_usage.stock_decremented);
    END IF;
    IF v_usage.line_id IS NOT NULL THEN
      DELETE FROM public.part_core_return WHERE work_order_line_id = v_usage.line_id;
    END IF;
    DELETE FROM public.maintenance_parts_usage WHERE id = v_usage.id;
  END LOOP;
  DELETE FROM public.part_core_return c
  USING public.maintenance_work_order_lines l
  WHERE l.id = c.work_order_line_id AND l.work_order_id = p_work_order_id;
END;
$$;


ALTER FUNCTION "public"."reverse_parts_usage_for_work_order"("p_work_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_apply_pending_driver_debt"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_driver RECORD;
  v_processed INT := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'rides' AND table_name = 'payment_obligations'
  ) THEN
    RETURN jsonb_build_object('processed', 0, 'skipped', true);
  END IF;

  FOR v_driver IN
    SELECT DISTINCT driver_user_id, currency
    FROM rides.payment_obligations
    WHERE status IN ('open', 'partial')
      AND remaining_minor > 0
  LOOP
    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed,
    'note', 'Debt auto-repay runs in Edge on digital credits; cron marks stale obligations for ops review.',
    'ran_at', p_now
  );
END;
$$;


ALTER FUNCTION "public"."rides_apply_pending_driver_debt"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_cancel_ride_request"("p_id" "uuid", "p_cancelled_by" "text" DEFAULT 'rider'::"text", "p_cancel_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  rec rides.ride_requests;
BEGIN
  UPDATE rides.ride_requests SET
    status = 'cancelled',
    cancelled_by = COALESCE(p_cancelled_by, 'rider'),
    cancel_reason = p_cancel_reason,
    updated_at = NOW()
  WHERE id = p_id
    AND status NOT IN ('completed', 'cancelled')
  RETURNING * INTO rec;
  IF NOT FOUND THEN
    SELECT * INTO rec FROM rides.ride_requests WHERE id = p_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  RETURN to_jsonb(rec);
END;
$$;


ALTER FUNCTION "public"."rides_cancel_ride_request"("p_id" "uuid", "p_cancelled_by" "text", "p_cancel_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_cancel_stale_matching_rides"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  max_min INTEGER;
  cancelled_count INTEGER;
BEGIN
  SELECT COALESCE(max_matching_duration_minutes, 15)
  INTO max_min
  FROM rides.dispatch_settings
  WHERE id = 1;

  max_min := GREATEST(2, LEAST(120, COALESCE(max_min, 15)));

  PERFORM public.rides_expire_all_pending_offers(p_now);

  WITH cancelled AS (
    UPDATE rides.ride_requests
    SET
      status = 'cancelled',
      cancelled_by = 'system',
      cancel_reason = 'matching_timeout',
      updated_at = p_now
    WHERE status = 'matching'
      AND created_at < p_now - (max_min || ' minutes')::INTERVAL
    RETURNING id
  )
  SELECT COUNT(*)::INTEGER INTO cancelled_count FROM cancelled;

  RETURN COALESCE(cancelled_count, 0);
END;
$$;


ALTER FUNCTION "public"."rides_cancel_stale_matching_rides"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_create_ride_request"("p_row" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $_$
DECLARE
  rec rides.ride_requests;
  pin TEXT;
BEGIN
  INSERT INTO rides.ride_requests (
    rider_user_id,
    status,
    pickup_lat,
    pickup_lng,
    pickup_address,
    dropoff_lat,
    dropoff_lng,
    dropoff_address,
    vehicle_option,
    fare_estimate_minor,
    surge_multiplier,
    currency,
    distance_estimate_km,
    duration_estimate_minutes,
    eta_pickup_seconds_estimate,
    quote_token_hash,
    fare_breakdown,
    idempotency_key,
    driver_offer_timeout_seconds,
    matching_wave,
    route_polyline_encoded,
    payment_method,
    guest_passenger_name,
    guest_passenger_phone,
    booking_purpose,
    passenger_user_id,
    rider_contact_id,
    booking_request_id,
    roam_mode,
    booking_kind,
    scheduled_pickup_at,
    pickup_window_minutes,
    scheduled_dispatched_at,
    scheduled_cancel_reason
  )
  VALUES (
    (p_row->>'rider_user_id')::UUID,
    COALESCE(p_row->>'status', 'matching'),
    (p_row->>'pickup_lat')::DOUBLE PRECISION,
    (p_row->>'pickup_lng')::DOUBLE PRECISION,
    NULLIF(p_row->>'pickup_address', ''),
    (p_row->>'dropoff_lat')::DOUBLE PRECISION,
    (p_row->>'dropoff_lng')::DOUBLE PRECISION,
    NULLIF(p_row->>'dropoff_address', ''),
    COALESCE(p_row->>'vehicle_option', 'standard'),
    (p_row->>'fare_estimate_minor')::BIGINT,
    COALESCE((p_row->>'surge_multiplier')::NUMERIC, 1),
    COALESCE(p_row->>'currency', 'USD'),
    NULLIF(p_row->>'distance_estimate_km', '')::NUMERIC,
    NULLIF(p_row->>'duration_estimate_minutes', '')::NUMERIC,
    NULLIF(p_row->>'eta_pickup_seconds_estimate', '')::INTEGER,
    NULLIF(p_row->>'quote_token_hash', ''),
    p_row->'fare_breakdown',
    NULLIF(p_row->>'idempotency_key', ''),
    COALESCE((p_row->>'driver_offer_timeout_seconds')::INTEGER, 15),
    COALESCE((p_row->>'matching_wave')::INTEGER, 0),
    NULLIF(p_row->>'route_polyline_encoded', ''),
    NULLIF(p_row->>'payment_method', ''),
    NULLIF(p_row->>'guest_passenger_name', ''),
    NULLIF(p_row->>'guest_passenger_phone', ''),
    NULLIF(p_row->>'booking_purpose', ''),
    NULLIF(p_row->>'passenger_user_id', '')::UUID,
    NULLIF(p_row->>'rider_contact_id', '')::UUID,
    NULLIF(p_row->>'booking_request_id', '')::UUID,
    NULLIF(p_row->>'roam_mode', ''),
    COALESCE(p_row->>'booking_kind', 'immediate'),
    NULLIF(p_row->>'scheduled_pickup_at', '')::TIMESTAMPTZ,
    COALESCE((p_row->>'pickup_window_minutes')::INTEGER, 10),
    NULLIF(p_row->>'scheduled_dispatched_at', '')::TIMESTAMPTZ,
    NULLIF(p_row->>'scheduled_cancel_reason', '')
  )
  RETURNING * INTO rec;

  pin := NULLIF(p_row->>'verification_pin', '');
  IF pin IS NOT NULL AND pin ~ '^[0-9]{4}$' THEN
    INSERT INTO rides.ride_pins (ride_request_id, verification_pin)
    VALUES (rec.id, pin)
    ON CONFLICT (ride_request_id) DO UPDATE SET verification_pin = EXCLUDED.verification_pin;
  END IF;

  RETURN to_jsonb(rec) || jsonb_build_object('verification_pin', pin);
END;
$_$;


ALTER FUNCTION "public"."rides_create_ride_request"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_dispatch_due_scheduled_rides"("p_now" timestamp with time zone DEFAULT "now"(), "p_buffer_minutes" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  rec rides.ride_requests;
  activated UUID[] := ARRAY[]::UUID[];
  skipped_busy UUID[] := ARRAY[]::UUID[];
  cancelled_missed INT := 0;
BEGIN
  -- Missed window: scheduled pickup passed without dispatch.
  UPDATE rides.ride_requests
  SET
    status = 'cancelled',
    cancelled_by = 'system',
    cancel_reason = 'scheduled_missed_window',
    scheduled_cancel_reason = 'system_missed_window',
    updated_at = p_now
  WHERE status = 'scheduled'
    AND scheduled_pickup_at < p_now - INTERVAL '15 minutes';
  GET DIAGNOSTICS cancelled_missed = ROW_COUNT;

  FOR rec IN
    SELECT *
    FROM rides.ride_requests
    WHERE status = 'scheduled'
      AND scheduled_pickup_at <= p_now + (p_buffer_minutes || ' minutes')::INTERVAL
      AND scheduled_pickup_at > p_now - INTERVAL '5 minutes'
    ORDER BY scheduled_pickup_at ASC
    FOR UPDATE SKIP LOCKED
  LOOP
    IF public.rides_rider_has_active_ride(rec.rider_user_id) THEN
      UPDATE rides.ride_requests
      SET
        status = 'cancelled',
        cancelled_by = 'system',
        cancel_reason = 'rider_busy_at_dispatch',
        scheduled_cancel_reason = 'system_rider_busy',
        updated_at = p_now
      WHERE id = rec.id;
      skipped_busy := array_append(skipped_busy, rec.id);
      CONTINUE;
    END IF;

    UPDATE rides.ride_requests
    SET
      status = 'matching',
      scheduled_dispatched_at = p_now,
      matching_wave = 0,
      updated_at = p_now
    WHERE id = rec.id;

    activated := array_append(activated, rec.id);
  END LOOP;

  RETURN jsonb_build_object(
    'activated_ids', to_jsonb(activated),
    'skipped_busy_ids', to_jsonb(skipped_busy),
    'cancelled_missed', cancelled_missed,
    'ran_at', p_now
  );
END;
$$;


ALTER FUNCTION "public"."rides_dispatch_due_scheduled_rides"("p_now" timestamp with time zone, "p_buffer_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_drivers_in_h3_cells"("p_h3_cells" "text"[], "p_fresh_since" timestamp with time zone, "p_h3_res" smallint DEFAULT 7, "p_limit" integer DEFAULT 500) RETURNS TABLE("user_id" "uuid", "lat" double precision, "lng" double precision, "updated_at" timestamp with time zone, "body_type_slug" "text", "h3_cell" "text", "h3_res" smallint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
BEGIN
  IF p_h3_cells IS NULL OR cardinality(p_h3_cells) = 0 THEN
    RETURN;
  END IF;
  IF cardinality(p_h3_cells) > 2000 THEN
    RAISE EXCEPTION 'h3_cell_array_too_large' USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 THEN
    p_limit := 500;
  END IF;
  p_limit := LEAST(p_limit, 500);
  IF p_h3_res IS NULL THEN
    p_h3_res := 7;
  END IF;

  RETURN QUERY
  SELECT
    dl.user_id,
    dl.lat,
    dl.lng,
    dl.updated_at,
    dl.body_type_slug,
    dl.h3_cell,
    dl.h3_res
  FROM rides.driver_locations dl
  WHERE dl.h3_cell = ANY (p_h3_cells)
    AND dl.h3_res = p_h3_res
    AND dl.available_for_rides = TRUE
    AND dl.updated_at >= p_fresh_since
  ORDER BY dl.updated_at DESC
  LIMIT p_limit;
END;
$$;


