CREATE OR REPLACE FUNCTION "public"."rides_insert_location_update"("p_ride_id" "uuid", "p_driver_user_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_heading" double precision, "p_speed_mps" double precision, "p_accuracy_m" double precision, "p_recorded_at" timestamp with time zone, "p_client_seq" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  ride_rec rides.ride_requests;
BEGIN
  SELECT * INTO ride_rec FROM rides.ride_requests WHERE id = p_ride_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF ride_rec.assigned_driver_user_id IS DISTINCT FROM p_driver_user_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF ride_rec.status NOT IN (
    'driver_assigned', 'driver_en_route_pickup', 'driver_arrived_pickup', 'on_trip'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ride_not_active');
  END IF;

  INSERT INTO rides.ride_location_updates (
    ride_request_id, driver_user_id, lat, lng, heading_degrees,
    speed_mps, accuracy_m, recorded_at, client_seq
  ) VALUES (
    p_ride_id, p_driver_user_id, p_lat, p_lng, p_heading,
    p_speed_mps, p_accuracy_m, p_recorded_at, p_client_seq
  )
  ON CONFLICT (ride_request_id, client_seq) DO NOTHING;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'duplicate', true, 'ride_id', p_ride_id);
  END IF;

  UPDATE rides.ride_requests SET
    last_driver_lat = p_lat,
    last_driver_lng = p_lng,
    last_driver_heading = p_heading,
    last_driver_location_at = COALESCE(p_recorded_at, NOW()),
    updated_at = NOW()
  WHERE id = p_ride_id;

  RETURN jsonb_build_object('ok', true, 'duplicate', false, 'ride_id', p_ride_id);
END;
$$;


ALTER FUNCTION "public"."rides_insert_location_update"("p_ride_id" "uuid", "p_driver_user_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_heading" double precision, "p_speed_mps" double precision, "p_accuracy_m" double precision, "p_recorded_at" timestamp with time zone, "p_client_seq" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_patch_driver_offer"("p_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  rec rides.driver_offers;
BEGIN
  UPDATE rides.driver_offers SET
    status = CASE WHEN p_patch ? 'status' THEN p_patch->>'status' ELSE status END
  WHERE id = p_id
  RETURNING * INTO rec;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN to_jsonb(rec);
END;
$$;


