CREATE OR REPLACE FUNCTION "public"."rides_read_surge_multiplier"("p_cell_key" "text", "p_h3_cell_key" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE v_mult NUMERIC;
BEGIN
  IF p_h3_cell_key IS NOT NULL THEN
    SELECT surge_multiplier INTO v_mult FROM rides.surge_cells WHERE h3_cell_key = p_h3_cell_key LIMIT 1;
    IF FOUND THEN RETURN v_mult; END IF;
  END IF;
  SELECT surge_multiplier INTO v_mult FROM rides.surge_cells WHERE cell_key = p_cell_key LIMIT 1;
  RETURN COALESCE(v_mult, 1.0);
END;
$$;


