CREATE OR REPLACE FUNCTION "public"."rides_rider_has_active_ride"("p_rider_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM rides.ride_requests r
    WHERE r.rider_user_id = p_rider_user_id
      AND r.status IN (
        'matching',
        'driver_assigned',
        'driver_en_route_pickup',
        'driver_arrived_pickup',
        'on_trip',
        'awaiting_cash_settlement'
      )
  );
$$;


