CREATE OR REPLACE FUNCTION "public"."rides_run_cash_settlement_timeout"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_ride RECORD;
  v_settled INTEGER := 0;
  v_rider_acct UUID;
  v_receivable_acct UUID;
  v_owed BIGINT;
  v_currency TEXT;
  v_idempotency TEXT;
  v_inserted INTEGER;
BEGIN
  FOR v_ride IN
    SELECT *
    FROM rides.ride_requests
    WHERE status = 'awaiting_cash_settlement'
      AND fare_locked_at IS NOT NULL
      AND fare_locked_at < p_now - INTERVAL '7 days'
      AND fare_final_minor IS NOT NULL
    FOR UPDATE SKIP LOCKED
  LOOP
    v_currency := COALESCE(v_ride.currency, 'JMD');
    v_owed := GREATEST(0, COALESCE(v_ride.fare_final_minor, 0));
    v_idempotency := 'timeout:' || v_ride.id::TEXT;

    IF v_owed > 0 AND v_ride.rider_user_id IS NOT NULL THEN
      v_rider_acct := rides._ensure_payment_account(
        v_ride.rider_user_id,
        'rider',
        'user:' || v_ride.rider_user_id::TEXT || ':rider',
        v_currency
      );
      v_receivable_acct := rides._ensure_payment_account(
        NULL,
        'system',
        'platform:receivable',
        v_currency
      );

      INSERT INTO rides.payment_journal_entries (
        ride_request_id,
        idempotency_key,
        entry_type,
        debit_account_id,
        credit_account_id,
        amount_minor,
        currency,
        request_hash,
        metadata,
        created_by_user_id
      )
      VALUES (
        v_ride.id,
        v_idempotency,
        'cash_trip_arrears',
        v_rider_acct,
        v_receivable_acct,
        v_owed,
        v_currency,
        'timeout_unpaid',
        jsonb_build_object(
          'outcome', 'unpaid',
          'owed_minor', v_owed,
          'cash_received_minor', 0,
          'auto_timeout', true
        ),
        NULL
      )
      ON CONFLICT (ride_request_id, idempotency_key) DO NOTHING;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      IF v_inserted > 0 THEN
        UPDATE rides.payment_accounts
        SET balance_minor = balance_minor - v_owed
        WHERE id = v_rider_acct;

        UPDATE rides.payment_accounts
        SET balance_minor = balance_minor + v_owed
        WHERE id = v_receivable_acct;
      END IF;
    END IF;

    UPDATE rides.ride_requests
    SET
      status = 'completed',
      cash_received_minor = 0,
      cash_settlement_status = 'settled',
      cash_settlement_outcome = 'unpaid',
      settled_at = p_now,
      completed_at = p_now,
      updated_at = p_now
    WHERE id = v_ride.id;

    INSERT INTO rides.audit_events (ride_request_id, actor_user_id, event_type, payload)
    VALUES (
      v_ride.id,
      NULL,
      'cash_settlement_auto_unpaid',
      jsonb_build_object(
        'owed_minor', v_owed,
        'cash_received_minor', 0,
        'outcome', 'unpaid',
        'fare_locked_at', v_ride.fare_locked_at
      )
    );

    v_settled := v_settled + 1;
  END LOOP;

  RETURN jsonb_build_object('settled', v_settled, 'ran_at', p_now);
END;
$$;


ALTER FUNCTION "public"."rides_run_cash_settlement_timeout"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_run_matching_hygiene"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  p_now TIMESTAMPTZ := NOW();
  expired_offers INTEGER;
  cancelled_rides INTEGER;
BEGIN
  expired_offers := public.rides_expire_all_pending_offers(p_now);
  cancelled_rides := public.rides_cancel_stale_matching_rides(p_now);
  RETURN jsonb_build_object(
    'expired_offers', expired_offers,
    'cancelled_rides', cancelled_rides,
    'ran_at', p_now
  );
END;
$$;


