CREATE OR REPLACE FUNCTION "public"."rides_supersede_pending_offers"("p_ride_id" "uuid", "p_except_offer_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
  WITH updated AS (
    UPDATE rides.driver_offers
    SET status = 'superseded'
    WHERE ride_request_id = p_ride_id
      AND status = 'pending'
      AND (p_except_offer_id IS NULL OR id <> p_except_offer_id)
    RETURNING 1
  )
  SELECT COUNT(*)::INTEGER FROM updated;
$$;


