CREATE OR REPLACE FUNCTION "public"."rides_upsert_driver_presence"("p_user_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_heading_degrees" double precision DEFAULT NULL::double precision, "p_available_for_rides" boolean DEFAULT true, "p_body_type_slug" "text" DEFAULT NULL::"text", "p_h3_cell" "text" DEFAULT NULL::"text", "p_dispatch_mode" "text" DEFAULT NULL::"text", "p_h3_res" smallint DEFAULT NULL::smallint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'fleet', 'public'
    AS $$
DECLARE
  v_prev boolean;
BEGIN
  IF p_dispatch_mode IS NOT NULL AND p_dispatch_mode NOT IN ('haulage', 'rideshare') THEN
    RAISE EXCEPTION 'invalid_dispatch_mode';
  END IF;

  SELECT available_for_rides INTO v_prev
  FROM rides.driver_locations
  WHERE user_id = p_user_id;

  INSERT INTO rides.driver_locations (
    user_id, lat, lng, heading_degrees, available_for_rides,
    body_type_slug, h3_cell, h3_res, dispatch_mode, updated_at
  ) VALUES (
    p_user_id, p_lat, p_lng, p_heading_degrees, p_available_for_rides,
    p_body_type_slug, NULLIF(trim(p_h3_cell), ''), p_h3_res, p_dispatch_mode, NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    lat = EXCLUDED.lat,
    lng = EXCLUDED.lng,
    heading_degrees = COALESCE(EXCLUDED.heading_degrees, rides.driver_locations.heading_degrees),
    available_for_rides = EXCLUDED.available_for_rides,
    body_type_slug = COALESCE(EXCLUDED.body_type_slug, rides.driver_locations.body_type_slug),
    h3_cell = EXCLUDED.h3_cell,
    h3_res = EXCLUDED.h3_res,
    dispatch_mode = COALESCE(EXCLUDED.dispatch_mode, rides.driver_locations.dispatch_mode),
    updated_at = NOW();

  IF (v_prev IS NOT NULL OR COALESCE(p_available_for_rides, FALSE))
     AND v_prev IS DISTINCT FROM p_available_for_rides THEN
    PERFORM fleet.append_presence_transition(
      p_user_id,
      'roam_rides',
      COALESCE(p_available_for_rides, FALSE),
      'app_toggle',
      NULL,
      '{}'::jsonb
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."rides_upsert_driver_presence"("p_user_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_heading_degrees" double precision, "p_available_for_rides" boolean, "p_body_type_slug" "text", "p_h3_cell" "text", "p_dispatch_mode" "text", "p_h3_res" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_upsert_surge_cell"("p_cell_key" "text", "p_h3_cell_key" "text" DEFAULT NULL::"text", "p_delta" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_row rides.surge_cells%ROWTYPE;
BEGIN
  IF p_delta <= 0 THEN
    UPDATE rides.surge_cells
    SET
      open_requests = GREATEST(0, COALESCE(open_requests, 0) + p_delta),
      surge_multiplier = CASE
        WHEN GREATEST(0, COALESCE(open_requests, 0) + p_delta) <= 2
          THEN GREATEST(1.0, COALESCE(surge_multiplier, 1.0) - 0.02)
        ELSE COALESCE(surge_multiplier, 1.0)
      END,
      h3_cell_key = COALESCE(p_h3_cell_key, h3_cell_key),
      updated_at = NOW()
    WHERE cell_key = p_cell_key
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', true, 'action', 'skip', 'reason', 'negative_delta_no_row');
    END IF;

    RETURN jsonb_build_object(
      'ok', true, 'action', 'update',
      'cell_key', v_row.cell_key, 'h3_cell_key', v_row.h3_cell_key,
      'open_requests', v_row.open_requests, 'surge_multiplier', v_row.surge_multiplier
    );
  END IF;

  INSERT INTO rides.surge_cells (cell_key, h3_cell_key, open_requests, surge_multiplier, updated_at)
  VALUES (p_cell_key, p_h3_cell_key, GREATEST(0, p_delta), 1.0, NOW())
  ON CONFLICT (cell_key) DO UPDATE SET
    open_requests = GREATEST(0, COALESCE(rides.surge_cells.open_requests, 0) + p_delta),
    surge_multiplier = CASE
      WHEN GREATEST(0, COALESCE(rides.surge_cells.open_requests, 0) + p_delta) >= 8
        THEN LEAST(2.5, COALESCE(rides.surge_cells.surge_multiplier, 1.0) + 0.05)
      WHEN GREATEST(0, COALESCE(rides.surge_cells.open_requests, 0) + p_delta) <= 2
        THEN GREATEST(1.0, COALESCE(rides.surge_cells.surge_multiplier, 1.0) - 0.02)
      ELSE COALESCE(rides.surge_cells.surge_multiplier, 1.0)
    END,
    h3_cell_key = COALESCE(EXCLUDED.h3_cell_key, rides.surge_cells.h3_cell_key),
    updated_at = NOW()
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'ok', true, 'action', 'upsert',
    'cell_key', v_row.cell_key, 'h3_cell_key', v_row.h3_cell_key,
    'open_requests', v_row.open_requests, 'surge_multiplier', v_row.surge_multiplier
  );
END;
$$;


ALTER FUNCTION "public"."rides_upsert_surge_cell"("p_cell_key" "text", "p_h3_cell_key" "text", "p_delta" integer) OWNER TO "postgres";


