CREATE OR REPLACE FUNCTION "public"."svc_module_purchase_fail"("p_id" "uuid", "p_provider_data" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'fleet', 'public'
