CREATE OR REPLACE FUNCTION "public"."toll_settlement_active_credits"("p_toll_id" "text") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(
    CASE
      WHEN a.source_type = 'reversal' THEN -a.amount
      WHEN a.source_type IN ('driver_charge', 'write_off') THEN 0
      WHEN EXISTS (
        SELECT 1 FROM public.toll_settlement_allocations r
        WHERE r.reverses_id = a.id
      ) THEN 0
      ELSE a.amount
    END
  ), 0)
  FROM public.toll_settlement_allocations a
  WHERE a.toll_id = p_toll_id
    AND a.source_type <> 'reversal';
$$;


ALTER FUNCTION "public"."toll_settlement_active_credits"("p_toll_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toll_settlement_apply"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'toll', 'pg_temp'
    AS $$
DECLARE
  v_existing public.toll_settlement_allocations%ROWTYPE;
  v_inserted public.toll_settlement_allocations%ROWTYPE;
  v_toll_cost NUMERIC := COALESCE((p->>'toll_cost')::NUMERIC, 0);
  v_amount NUMERIC := COALESCE((p->>'amount')::NUMERIC, 0);
  v_active NUMERIC;
  v_remaining NUMERIC;
BEGIN
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be > 0';
  END IF;

  SELECT * INTO v_existing
  FROM public.toll_settlement_allocations
  WHERE idempotency_key = p->>'idempotency_key';

  IF FOUND THEN
    PERFORM toll.mirror_settlement_from_public(v_existing);
    RETURN jsonb_build_object('ok', true, 'duplicate', true, 'allocation', to_jsonb(v_existing));
  END IF;

  v_active := public.toll_settlement_active_credits(p->>'toll_id');
  v_remaining := GREATEST(0, v_toll_cost - v_active);

  IF (p->>'source_type') IN ('trip_refund', 'unlinked_trip', 'dispute_refund')
     AND v_amount > v_remaining + 0.05 THEN
    RAISE EXCEPTION 'over_allocation: amount % exceeds remaining %', v_amount, v_remaining;
  END IF;

  INSERT INTO public.toll_settlement_allocations (
    source_type, source_id, toll_id, claim_id, amount,
    toll_period_anchor, idempotency_key, actor, notes, metadata
  ) VALUES (
    p->>'source_type', p->>'source_id', p->>'toll_id', NULLIF(p->>'claim_id', ''),
    v_amount, NULLIF(p->>'toll_period_anchor', '')::DATE, p->>'idempotency_key',
    NULLIF(p->>'actor', ''), NULLIF(p->>'notes', ''), COALESCE(p->'metadata', '{}'::jsonb)
  )
  RETURNING * INTO v_inserted;

  PERFORM toll.mirror_settlement_from_public(v_inserted);

  RETURN jsonb_build_object(
    'ok', true, 'duplicate', false, 'allocation', to_jsonb(v_inserted),
    'remaining_after', GREATEST(0, v_toll_cost - public.toll_settlement_active_credits(p->>'toll_id'))
  );
END;
$$;


ALTER FUNCTION "public"."toll_settlement_apply"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toll_settlement_reverse"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'toll', 'pg_temp'
    AS $$
DECLARE
  v_target public.toll_settlement_allocations%ROWTYPE;
  v_existing_rev public.toll_settlement_allocations%ROWTYPE;
  v_inserted public.toll_settlement_allocations%ROWTYPE;
  v_rev_key TEXT;
BEGIN
  IF COALESCE(p->>'idempotency_key', '') <> '' THEN
    SELECT * INTO v_target FROM public.toll_settlement_allocations WHERE idempotency_key = p->>'idempotency_key';
  ELSIF COALESCE(p->>'allocation_id', '') <> '' THEN
    SELECT * INTO v_target FROM public.toll_settlement_allocations WHERE id = (p->>'allocation_id')::UUID;
  ELSE
    RAISE EXCEPTION 'idempotency_key or allocation_id required';
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'noop', true, 'reason', 'not_found');
  END IF;

  IF v_target.source_type = 'reversal' THEN
    RETURN jsonb_build_object('ok', true, 'noop', true, 'reason', 'already_reversal');
  END IF;

  v_rev_key := COALESCE(NULLIF(p->>'reversal_idempotency_key', ''), 'rev:' || v_target.idempotency_key);

  SELECT * INTO v_existing_rev
  FROM public.toll_settlement_allocations
  WHERE idempotency_key = v_rev_key OR reverses_id = v_target.id
  LIMIT 1;

  IF FOUND THEN
    PERFORM toll.mirror_settlement_from_public(v_existing_rev);
    RETURN jsonb_build_object('ok', true, 'duplicate', true, 'allocation', to_jsonb(v_existing_rev));
  END IF;

  INSERT INTO public.toll_settlement_allocations (
    source_type, source_id, toll_id, claim_id, amount,
    toll_period_anchor, idempotency_key, reverses_id, actor, notes, metadata
  ) VALUES (
    'reversal', v_target.source_id, v_target.toll_id, v_target.claim_id, v_target.amount,
    v_target.toll_period_anchor, v_rev_key, v_target.id,
    NULLIF(p->>'actor', ''), NULLIF(p->>'notes', ''),
    jsonb_build_object('reversed_source_type', v_target.source_type)
  )
  RETURNING * INTO v_inserted;

  PERFORM toll.mirror_settlement_from_public(v_inserted);

  RETURN jsonb_build_object('ok', true, 'duplicate', false, 'allocation', to_jsonb(v_inserted));
END;
$$;


ALTER FUNCTION "public"."toll_settlement_reverse"("p" "jsonb") OWNER TO "postgres";


