CREATE OR REPLACE FUNCTION "public"."trip_anomaly_review_save"("p_org" "text", "p_trip_id" "text", "p_rule" "text", "p_action" "text", "p_reason" "text", "p_reviewed_by" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
