CREATE OR REPLACE FUNCTION "public"."try_claim_week_close"("p_org_id" "uuid", "p_week_key" "text", "p_actor" "text", "p_ttl_seconds" integer DEFAULT 120, "p_service_line" "text" DEFAULT 'rideshare'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ledger'
    AS $$
DECLARE
  claimed boolean := false;
  ttl int := GREATEST(COALESCE(p_ttl_seconds, 120), 1);
  line text := COALESCE(NULLIF(trim(p_service_line), ''), 'rideshare');
BEGIN
  IF p_org_id IS NULL OR NULLIF(trim(p_week_key), '') IS NULL OR NULLIF(trim(p_actor), '') IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO ledger.week_close_locks (organization_id, service_line, week_key, locked_at, locked_by)
  VALUES (p_org_id, line, trim(p_week_key), now(), trim(p_actor))
  ON CONFLICT (organization_id, service_line, week_key) DO UPDATE
  SET
    locked_at = now(),
    locked_by = EXCLUDED.locked_by
  WHERE ledger.week_close_locks.locked_at < now() - make_interval(secs => ttl)
     OR ledger.week_close_locks.locked_by = EXCLUDED.locked_by
  RETURNING true INTO claimed;

  RETURN COALESCE(claimed, false);
END;
$$;


ALTER FUNCTION "public"."try_claim_week_close"("p_org_id" "uuid", "p_week_key" "text", "p_actor" "text", "p_ttl_seconds" integer, "p_service_line" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."undo_parts_catalog_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rules int;
  parts int;
  restored int;
BEGIN
  DELETE FROM public.interchange_fitment_rule WHERE import_batch_id = p_batch_id;
  GET DIAGNOSTICS rules = ROW_COUNT;
  UPDATE public.part_master pm
  SET category_id = COALESCE((r.previous->>'category_id')::uuid, pm.category_id),
      interchange_group_id = NULLIF(r.previous->>'interchange_group_id', '')::uuid,
      maintenance_component_id = NULLIF(r.previous->>'maintenance_component_id', '')::uuid,
      part_kind = COALESCE(NULLIF(r.previous->>'part_kind', ''), pm.part_kind)
  FROM public.part_import_restore r
  WHERE r.batch_id = p_batch_id AND r.part_id = pm.id;
  GET DIAGNOSTICS restored = ROW_COUNT;
  DELETE FROM public.part_import_restore WHERE batch_id = p_batch_id;
  DELETE FROM public.part_master pm
  WHERE pm.import_batch_id = p_batch_id
    AND NOT EXISTS (SELECT 1 FROM public.maintenance_parts_usage u WHERE u.part_id = pm.id);
  GET DIAGNOSTICS parts = ROW_COUNT;
  DELETE FROM public.part_interchange_group g
  WHERE g.import_batch_id = p_batch_id
    AND NOT EXISTS (SELECT 1 FROM public.part_master pm WHERE pm.interchange_group_id = g.id);
  RETURN jsonb_build_object('rulesRemoved', rules, 'partsRemoved', parts, 'partsRestored', restored);
END;
$$;


ALTER FUNCTION "public"."undo_parts_catalog_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."universal_parts_for_variant"("p_catalog_id" "uuid", "p_vehicle_year" integer DEFAULT NULL::integer) RETURNS TABLE("spec_key" "text", "label" "text", "spec_value" "text", "unit" "text", "universal_part_id" "uuid", "manufacturer" "text", "part_number" "text", "name" "text", "extra" "jsonb")
    LANGUAGE "sql" STABLE
    AS $$
  WITH specs AS (
    SELECT * FROM public.specs_for_variant(p_catalog_id, p_vehicle_year)
    WHERE sourced
  ),
  conn AS (
    SELECT value FROM specs WHERE spec_key = 'wiper_connector' LIMIT 1
  )
  SELECT
    s.spec_key,
    s.label,
    s.value,
    s.unit,
    up.id,
    up.manufacturer,
    up.part_number,
    up.name,
    up.extra
  FROM specs s
  LEFT JOIN public.universal_part up
    ON up.spec_key = s.spec_key
   AND lower(btrim(up.spec_value)) = lower(btrim(s.value))
   AND (
     s.spec_key NOT LIKE 'wiper_%_mm'
     OR NOT EXISTS (SELECT 1 FROM conn)
     OR lower(coalesce(up.extra->>'connector', '')) = lower((SELECT value FROM conn))
   );
$$;


ALTER FUNCTION "public"."universal_parts_for_variant"("p_catalog_id" "uuid", "p_vehicle_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."universal_section_for_variant"("p_catalog_id" "uuid", "p_vehicle_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'specKey', spec_key,
    'label', label,
    'value', spec_value,
    'unit', unit,
    'items', items
  ) ORDER BY label), '[]'::jsonb)
  FROM (
    SELECT
      spec_key,
      label,
      spec_value,
      unit,
      COALESCE(jsonb_agg(jsonb_build_object(
        'id', universal_part_id,
        'manufacturer', manufacturer,
        'partNumber', part_number,
        'name', name,
        'extra', extra
      ) ORDER BY manufacturer) FILTER (WHERE universal_part_id IS NOT NULL), '[]'::jsonb) AS items
    FROM public.universal_parts_for_variant(p_catalog_id, p_vehicle_year)
    GROUP BY spec_key, label, spec_value, unit
  ) s;
$$;


ALTER FUNCTION "public"."universal_section_for_variant"("p_catalog_id" "uuid", "p_vehicle_year" integer) OWNER TO "postgres";


