    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."variant_parts_checklist"("p_catalog_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_jobs jsonb;
  v_specs jsonb;
  v_supplies jsonb;
BEGIN
  WITH hits AS (
    SELECT * FROM public.parts_for_vehicle(p_catalog_id, NULL, NULL)
  ),
  na AS (
    SELECT DISTINCT ON (c.op_code)
      c.op_code,
      a.applicable,
      a.reason
    FROM public.catalog_component_applicability a
    JOIN public.maintenance_service_categories c ON c.id = a.component_id
    JOIN public.vehicle_catalog vc ON vc.id = p_catalog_id
    WHERE (
      (a.scope = 'variant' AND a.vehicle_catalog_id = vc.id)
      OR (a.scope = 'platform' AND a.platform_id = vc.platform_id)
      OR (
        a.scope = 'platform'
        AND a.platform_id = (SELECT parent_id FROM public.vehicle_platform WHERE id = vc.platform_id)
      )
      OR (a.scope = 'engine_family' AND a.engine_family_id = vc.engine_family_id)
    )
    ORDER BY c.op_code, CASE a.scope WHEN 'variant' THEN 1 WHEN 'platform' THEN 2 ELSE 3 END
  ),
  job_hits AS (
    SELECT
      j.section,
      j.op_code,
      j.label,
      j."position",
      j.sort_order,
      h.tier,
      h.part_id,
      h.part_name,
      h.oem_part_number,
      h.manufacturer,
      h.part_kind,
      h.interchange_group_id,
      pm.catalog_decision,
      pm.evidence_url
    FROM public.guided_part_jobs() j
    LEFT JOIN public.maintenance_service_categories c ON c.op_code = j.op_code
    LEFT JOIN hits h ON h.maintenance_component_id = c.id
      AND (
        j."position" IS NULL
        OR h."position" IS NULL
        OR lower(h."position") = lower(j."position")
      )
    LEFT JOIN public.part_master pm ON pm.id = h.part_id
  ),
  rolled AS (
    SELECT
      section,
      op_code,
      label,
      "position",
      sort_order,
      CASE
        WHEN bool_or(catalog_decision = 'confirmed' AND tier BETWEEN 1 AND 3) THEN 'verified'
        WHEN (SELECT na.applicable FROM na WHERE na.op_code = job_hits.op_code) = false
          AND EXISTS (SELECT 1 FROM na WHERE na.op_code = job_hits.op_code) THEN 'not_applicable'
        WHEN bool_or(part_id IS NOT NULL AND catalog_decision IS DISTINCT FROM 'rejected') THEN 'unverified'
        ELSE 'missing'
      END AS status,
      (SELECT na.reason FROM na WHERE na.op_code = job_hits.op_code) AS na_reason,
      (ARRAY_AGG(interchange_group_id ORDER BY tier NULLS LAST))[1] AS group_id,
      (ARRAY_AGG(evidence_url ORDER BY tier NULLS LAST) FILTER (WHERE evidence_url IS NOT NULL))[1] AS evidence_url,
      COALESCE(jsonb_agg(DISTINCT jsonb_build_object(
        'id', part_id,
        'manufacturer', manufacturer,
        'partNumber', oem_part_number,
        'name', part_name,
        'kind', part_kind
      )) FILTER (WHERE part_id IS NOT NULL), '[]'::jsonb) AS parts
    FROM job_hits
    GROUP BY section, op_code, label, "position", sort_order
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'section', section,
    'opCode', op_code,
    'label', label,
    'position', "position",
    'status', status,
    'reason', na_reason,
    'groupId', group_id,
    'evidenceUrl', evidence_url,
    'parts', parts
  ) ORDER BY sort_order), '[]'::jsonb)
  INTO v_jobs
  FROM rolled;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'specKey', s.spec_key,
    'label', s.label,
    'value', s.value,
    'unit', s.unit,
    'scope', s.scope,
    'sourced', s.sourced
  ) ORDER BY s.label), '[]'::jsonb)
  INTO v_specs
  FROM public.specs_for_variant(p_catalog_id, NULL) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'opCode', c.op_code,
    'name', s.supply_name,
    'note', s.note
  ) ORDER BY c.op_code, s.supply_name), '[]'::jsonb)
  INTO v_supplies
  FROM public.component_related_supply s
  JOIN public.maintenance_service_categories c ON c.id = s.component_id;

  RETURN jsonb_build_object('jobs', v_jobs, 'specs', COALESCE(v_specs, '[]'::jsonb), 'supplies', COALESCE(v_supplies, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."variant_parts_checklist"("p_catalog_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_guided_rules"("p_group" "uuid", "p_variant" "uuid", "p_fit" "text", "p_year_from" integer, "p_year_to" integer, "p_ticked" "uuid"[], "p_position" "text", "p_op" "text", "p_note" "text", "p_verified_by" "uuid", "p_replace" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_fit text := lower(trim(coalesce(p_fit, 'catalog_variant')));
  v_src public.vehicle_catalog%ROWTYPE;
  v_root uuid;
  v_included integer;
  v_total integer;
  v_engines integer;
  v_year_blocked boolean;
  v_from integer;
  v_to integer;
  v_row record;
BEGIN
  SELECT * INTO v_src FROM public.vehicle_catalog WHERE id = p_variant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That vehicle is not in the catalog';
  END IF;
  IF v_fit = 'engine_family' AND NOT public.is_engine_level_op(p_op) THEN
    RAISE EXCEPTION 'All cars with this engine is only for the oil filter, spark plugs, coils, and thermostat';
  END IF;
  SELECT
    count(*) FILTER (WHERE included),
    count(*),
    count(DISTINCT upper(trim(coalesce(engine, '')))),
    bool_or(included AND outside_years)
  INTO v_included, v_total, v_engines, v_year_blocked
  FROM public.guided_fit_rows(p_variant, v_fit, p_year_from, p_year_to, p_ticked);
  IF COALESCE(v_included, 0) = 0 THEN
    RAISE EXCEPTION 'Pick at least one vehicle';
  END IF;
  IF p_replace THEN
    DELETE FROM public.interchange_fitment_rule WHERE interchange_group_id = p_group;
  END IF;

  v_from := p_year_from;
  v_to := p_year_to;
  IF COALESCE(v_year_blocked, false) THEN
    v_from := NULL;
    v_to := NULL;
  END IF;

  IF v_fit = 'catalog_variant' OR v_included < v_total
    OR (v_fit = 'platform' AND public.is_engine_level_op(p_op) AND v_engines > 1) THEN
    FOR v_row IN
      SELECT variant_id FROM public.guided_fit_rows(p_variant, v_fit, p_year_from, p_year_to, p_ticked)
      WHERE included
    LOOP
      IF p_replace OR NOT EXISTS (
        SELECT 1 FROM public.interchange_fitment_rule r
        WHERE r.interchange_group_id = p_group
          AND r.target_kind = 'catalog_variant'
          AND r.vehicle_catalog_id = v_row.variant_id
          AND coalesce(r."position", '') = coalesce(NULLIF(p_position, ''), '')
      ) THEN
        INSERT INTO public.interchange_fitment_rule (
          interchange_group_id, target_kind, vehicle_catalog_id, "position", source, notes, verified_by, verified_at
        ) VALUES (
          p_group, 'catalog_variant', v_row.variant_id, NULLIF(p_position, ''), 'manual',
          NULLIF(p_note, ''), p_verified_by, now()
        );
      END IF;
    END LOOP;
    RETURN;
  END IF;

  IF v_fit = 'engine_family' THEN
    IF p_replace OR NOT EXISTS (
      SELECT 1 FROM public.interchange_fitment_rule r
      WHERE r.interchange_group_id = p_group
        AND r.target_kind = 'engine_family'
        AND r.engine_family_id = v_src.engine_family_id
    ) THEN
      INSERT INTO public.interchange_fitment_rule (
        interchange_group_id, target_kind, engine_family_id, year_from, year_to, "position", source, notes, verified_by, verified_at
      ) VALUES (
        p_group, 'engine_family', v_src.engine_family_id, v_from, v_to, NULLIF(p_position, ''), 'manual',
        NULLIF(p_note, ''), p_verified_by, now()
      );
    END IF;
    RETURN;
  END IF;

  SELECT COALESCE(p.parent_id, p.id) INTO v_root
  FROM public.vehicle_platform p
  WHERE p.id = v_src.platform_id;
  IF v_root IS NULL THEN
    RAISE EXCEPTION 'This vehicle has no body on file';
  END IF;
  IF p_replace OR NOT EXISTS (
    SELECT 1 FROM public.interchange_fitment_rule r
    WHERE r.interchange_group_id = p_group
      AND r.target_kind = 'platform'
      AND r.platform_id = v_root
  ) THEN
    INSERT INTO public.interchange_fitment_rule (
      interchange_group_id, target_kind, platform_id, year_from, year_to, "position", source, notes, verified_by, verified_at
    ) VALUES (
      p_group, 'platform', v_root, v_from, v_to, NULLIF(p_position, ''), 'manual',
      NULLIF(p_note, ''), p_verified_by, now()
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."write_guided_rules"("p_group" "uuid", "p_variant" "uuid", "p_fit" "text", "p_year_from" integer, "p_year_to" integer, "p_ticked" "uuid"[], "p_position" "text", "p_op" "text", "p_note" "text", "p_verified_by" "uuid", "p_replace" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_day_covered_by_batch"("p_org" "text", "p_source_id" "text", "p_day" "date") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM fleet.import_batches b
    WHERE b.organization_id = p_org
      AND b.source_id = p_source_id
      AND b.status IN ('completed', 'committed')
      AND b.coverage_start IS NOT NULL
      AND b.coverage_end IS NOT NULL
      AND p_day BETWEEN b.coverage_start AND b.coverage_end
  );
$$;


ALTER FUNCTION "recon"."_day_covered_by_batch"("p_org" "text", "p_source_id" "text", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_day_has_daily_rows"("p_org" "text", "p_line" "text", "p_source_id" "text", "p_day" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  CASE p_source_id
    WHEN 'indrive_trips' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.trips t
        WHERE t.organization_id = p_org
          AND t.date::date = p_day
          AND lower(coalesce(t.platform, '')) LIKE '%indrive%'
          AND (p_line <> 'rideshare' OR coalesce(t.service_line, 'rideshare') = 'rideshare')
      );
    WHEN 'roam_trips' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.trips t
        WHERE t.organization_id = p_org
          AND t.date::date = p_day
          AND coalesce(t.platform, '') = 'Roam'
          AND coalesce(t.service_line, 'rideshare') = 'rideshare'
      );
    WHEN 'cash_tolls' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.toll_ledger l
        WHERE l.organization_id = p_org
          AND l.date::date = p_day
          AND (
            lower(coalesce(l.payment_method, '')) = 'cash'
            OR lower(coalesce(l.type, '')) = 'cash'
          )
      );
    WHEN 'cash_fuel' THEN
      -- fuel_entries has no import_batch_id column; batch lives in payload_json.batchId
      RETURN EXISTS (
        SELECT 1 FROM fleet.fuel_entries f
        WHERE f.organization_id = p_org
          AND f.date::date = p_day
          AND (
            nullif(trim(coalesce(f.payload_json->>'batchId', '')), '') IS NULL
            OR coalesce(f.payload_json->>'source', '') IN ('driver', 'receipt', 'ocr')
          )
      );
    WHEN 'rush_deliveries' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.trips t
        WHERE t.organization_id = p_org
          AND t.date::date = p_day
          AND coalesce(t.service_line, '') = 'rush_delivery'
      );
    ELSE
      RETURN false;
  END CASE;
END;
$$;


ALTER FUNCTION "recon"."_day_has_daily_rows"("p_org" "text", "p_line" "text", "p_source_id" "text", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_day_has_statement_live"("p_org" "text", "p_source_id" "text", "p_day" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  CASE p_source_id
    WHEN 'uber_bundle' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.trips t
        WHERE t.organization_id = p_org
          AND t.date::date = p_day
          AND lower(coalesce(t.platform, '')) LIKE '%uber%'
          AND coalesce(t.service_line, 'rideshare') <> 'rush_delivery'
      );
    WHEN 'indrive_trips' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.trips t
        WHERE t.organization_id = p_org
          AND t.date::date = p_day
          AND lower(coalesce(t.platform, '')) LIKE '%indrive%'
          AND coalesce(t.service_line, 'rideshare') <> 'rush_delivery'
      );
    WHEN 'toll_usage' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.toll_ledger l
        WHERE l.organization_id = p_org
          AND l.date::date = p_day
          AND lower(coalesce(l.type, '')) IN ('usage', 'toll_usage')
          AND lower(coalesce(l.payment_method, '')) NOT LIKE '%cash%'
      );
    WHEN 'toll_topup' THEN
      RETURN EXISTS (
        SELECT 1 FROM fleet.toll_ledger l
        WHERE l.organization_id = p_org
          AND l.date::date = p_day
          AND lower(coalesce(l.type, '')) IN ('top_up', 'topup')
      );
    WHEN 'fuel_card_roam' THEN
      RETURN EXISTS (
        SELECT 1
        FROM fleet.fuel_entries f
        WHERE f.organization_id = p_org
          AND f.date::date = p_day
          AND (
            coalesce(f.type, '') = 'Card_Transaction'
            OR lower(coalesce(f.payload_json->>'entrySource', '')) = 'fuel-card'
            OR lower(coalesce(f.payload_json->>'paymentMethod', '')) IN ('gas card', 'company_card', 'gas_card')
            OR lower(coalesce(f.payload_json->>'paidBy', '')) IN ('gas card', 'company_card')
            OR (
              nullif(trim(coalesce(f.payload_json->>'cardId', '')), '') IS NOT NULL
              AND EXISTS (
                SELECT 1 FROM fleet.fuel_cards c
                WHERE c.organization_id = f.organization_id
                  AND (
                    c.id = nullif(trim(coalesce(f.payload_json->>'cardId', '')), '')
                    OR c.legacy_kv_id = nullif(trim(coalesce(f.payload_json->>'cardId', '')), '')
                  )
              )
            )
          )
      );
    WHEN 'fuel_card_self' THEN
      RETURN EXISTS (
        SELECT 1
        FROM fleet.fuel_entries f
        LEFT JOIN fleet.fuel_cards c
          ON c.organization_id = f.organization_id
         AND (
           c.id = nullif(trim(coalesce(f.payload_json->>'cardId', '')), '')
           OR c.legacy_kv_id = nullif(trim(coalesce(f.payload_json->>'cardId', '')), '')
         )
        WHERE f.organization_id = p_org
          AND f.date::date = p_day
          AND (
            lower(coalesce(f.payload_json->>'importSource', '')) LIKE '%jaa%'
            OR lower(coalesce(f.payload_json->>'importSource', '')) LIKE '%self_serve%'
            OR (
              lower(coalesce(c.payload_json->>'jaaCardType', '')) = 'driver_tied'
              AND lower(coalesce(f.payload_json->>'entrySource', '')) <> 'fuel-card'
            )
          )
      );
    ELSE
      RETURN false;
  END CASE;
END;
$$;


ALTER FUNCTION "recon"."_day_has_statement_live"("p_org" "text", "p_source_id" "text", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_week_batch_overlaps"("p_org" "text", "p_source_id" "text", "p_week_key" "date") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM fleet.import_batches b
    WHERE b.organization_id = p_org
      AND b.source_id = p_source_id
      AND b.status IN ('completed', 'committed')
      AND b.coverage_start IS NOT NULL
      AND b.coverage_end IS NOT NULL
      AND b.coverage_start <= (p_week_key + 6)
      AND b.coverage_end >= p_week_key
  );
$$;


ALTER FUNCTION "recon"."_week_batch_overlaps"("p_org" "text", "p_source_id" "text", "p_week_key" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_week_day_keys"("p_week_key" "date") RETURNS "date"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT array_agg(d::date ORDER BY d)
  FROM generate_series(p_week_key, p_week_key + 6, interval '1 day') AS d;
$$;


ALTER FUNCTION "recon"."_week_day_keys"("p_week_key" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."_week_has_statement_live"("p_org" "text", "p_source_id" "text", "p_week_key" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  d date;
BEGIN
  FOREACH d IN ARRAY recon._week_day_keys(p_week_key)
  LOOP
    IF recon._day_has_statement_live(p_org, p_source_id, d) THEN
      RETURN true;
    END IF;
  END LOOP;
  RETURN false;
END;
$$;


ALTER FUNCTION "recon"."_week_has_statement_live"("p_org" "text", "p_source_id" "text", "p_week_key" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."compute_source_coverage"("p_org" "text", "p_line" "text", "p_source_id" "text", "p_week_key" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'recon', 'fleet', 'public'
    AS $$
DECLARE
  d date;
  days date[];
  day_status text;
  out jsonb := '{}'::jsonb;
  stmt_sources text[] := ARRAY[
    'uber_bundle', 'indrive_trips', 'toll_usage', 'toll_topup', 'fuel_card_roam', 'fuel_card_self'
  ];
  daily_sources text[] := ARRAY[
    'roam_trips', 'cash_tolls', 'cash_fuel', 'rush_deliveries'
  ];
  c_bridge_go_live_week constant date := date '2026-10-19';
  allow_live_fallback boolean;
BEGIN
  IF extract(isodow FROM p_week_key) <> 1 THEN
    RAISE EXCEPTION 'week_key must be a Monday (ADR 0007)';
  END IF;

  IF p_source_id = 'cod_remittance' THEN
    RETURN '{}'::jsonb;
  END IF;

  allow_live_fallback := p_week_key < c_bridge_go_live_week;

  days := recon._week_day_keys(p_week_key);
  FOREACH d IN ARRAY days
  LOOP
    IF EXISTS (
      SELECT 1 FROM recon.source_attestations a
      WHERE a.organization_id = p_org
        AND a.service_line = p_line
        AND a.week_key = p_week_key
        AND a.source_id = p_source_id
        AND a.day = d
        AND a.kind = 'attest_none'
    ) THEN
      day_status := 'zero_attested';
    ELSIF p_source_id = ANY (stmt_sources)
      AND recon._day_covered_by_batch(p_org, p_source_id, d) THEN
      day_status := 'covered';
    ELSIF p_source_id = ANY (stmt_sources)
      AND allow_live_fallback
      AND recon._day_has_statement_live(p_org, p_source_id, d) THEN
      day_status := 'covered';
    ELSIF p_source_id = ANY (daily_sources)
      AND recon._day_has_daily_rows(p_org, p_line, p_source_id, d) THEN
      day_status := 'covered';
    ELSE
      day_status := 'missing';
    END IF;
    out := out || jsonb_build_object(to_char(d, 'YYYY-MM-DD'), day_status);
  END LOOP;

  RETURN out;
END;
$$;


ALTER FUNCTION "recon"."compute_source_coverage"("p_org" "text", "p_line" "text", "p_source_id" "text", "p_week_key" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."enqueue_unit"("p_org" "text", "p_kind" "text", "p_week" "date", "p_driver" "text", "p_vehicle" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'recon', 'pgmq', 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF p_org IS NULL OR p_week IS NULL OR p_kind IS NULL THEN
    RETURN;
  END IF;

  SELECT status INTO v_status
  FROM recon.projection_state
  WHERE organization_id = p_org
    AND unit_kind = p_kind
    AND week_key = p_week
    AND driver_id IS NOT DISTINCT FROM p_driver
    AND vehicle_id IS NOT DISTINCT FROM p_vehicle
  FOR UPDATE;

  IF v_status = 'pending' THEN
    RETURN;
  END IF;

  INSERT INTO recon.projection_state (
    organization_id, unit_kind, week_key, driver_id, vehicle_id, status, updated_at
  ) VALUES (
    p_org, p_kind, p_week, p_driver, p_vehicle, 'pending', now()
  )
  ON CONFLICT (organization_id, unit_kind, week_key, driver_id, vehicle_id)
  DO UPDATE SET status = 'pending', last_error = NULL, updated_at = now();

  PERFORM pgmq.send(
    'recon_recompute',
    jsonb_build_object(
      'organizationId', p_org,
      'unitKind', p_kind,
      'weekKey', to_char(p_week, 'YYYY-MM-DD'),
      'driverId', p_driver,
      'vehicleId', p_vehicle,
      'reason', NULLIF(p_reason, '')
    )
  );
END;
$$;


ALTER FUNCTION "recon"."enqueue_unit"("p_org" "text", "p_kind" "text", "p_week" "date", "p_driver" "text", "p_vehicle" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "recon"."list_week_source_summaries"("p_org" "text", "p_line" "text", "p_year" integer DEFAULT NULL::integer) RETURNS TABLE("week_key" "date", "sources" "jsonb", "missing_count" integer, "needs_data" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'recon', 'fleet', 'public'
    AS $$
DECLARE
  w date;
  src text;
  cov jsonb;
  src_rows jsonb := '[]'::jsonb;
  miss int;
  source_ids text[] := ARRAY[
    'uber_bundle', 'indrive_trips', 'roam_trips',
    'toll_usage', 'toll_topup', 'cash_tolls',
    'fuel_card_roam', 'fuel_card_self', 'cash_fuel',
    'rush_deliveries', 'cod_remittance'
  ];
  yr int := coalesce(p_year, extract(year FROM current_date)::int);
  anchor date := date_trunc('week', current_date)::date;
BEGIN
  FOR i IN 0..11 LOOP
    w := anchor - (i * 7);
    IF extract(year FROM w) <> yr AND p_year IS NOT NULL THEN
      CONTINUE;
    END IF;

    src_rows := '[]'::jsonb;
    miss := 0;

    FOREACH src IN ARRAY source_ids
    LOOP
      cov := recon.compute_source_coverage(p_org, p_line, src, w);
      IF cov <> '{}'::jsonb AND cov ?| ARRAY(SELECT jsonb_object_keys(cov)) THEN
        IF EXISTS (
          SELECT 1 FROM jsonb_each_text(cov) e WHERE e.value = 'missing'
        ) THEN
          miss := miss + 1;
        END IF;
      END IF;
      src_rows := src_rows || jsonb_build_array(
        jsonb_build_object('id', src, 'coverage', cov)
      );
    END LOOP;

    week_key := w;
    sources := src_rows;
    missing_count := miss;
    needs_data := miss > 0;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "recon"."list_week_source_summaries"("p_org" "text", "p_line" "text", "p_year" integer) OWNER TO "postgres";


