CREATE OR REPLACE FUNCTION "recon"."tg_import_pending"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'recon', 'pgmq', 'public'
    AS $$
DECLARE
  r record;
  v_week date;
BEGIN
  v_week := recon.week_monday(COALESCE(NEW.period_start, NEW.upload_date::date));
  IF v_week IS NULL THEN
    RETURN NEW;
  END IF;
  FOR r IN
    SELECT DISTINCT driver_id
    FROM fleet.trips
    WHERE organization_id = NEW.organization_id
      AND batch_id = NEW.id
      AND driver_id IS NOT NULL
  LOOP
    PERFORM recon.enqueue_unit(NEW.organization_id, 'driver_week', v_week, r.driver_id, NULL);
  END LOOP;
  RETURN NEW;
END;
$$;


