CREATE OR REPLACE FUNCTION "rides"."_ensure_payment_account"("p_user_id" "uuid", "p_role" "text", "p_account_key" "text", "p_currency" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  SELECT id INTO v_id
  FROM rides.payment_accounts
  WHERE account_key = p_account_key AND currency = p_currency;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO rides.payment_accounts (user_id, role, account_key, currency, balance_minor)
  VALUES (p_user_id, p_role, p_account_key, p_currency, 0)
  ON CONFLICT (account_key, currency) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM rides.payment_accounts
    WHERE account_key = p_account_key AND currency = p_currency;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "rides"."_ensure_payment_account"("p_user_id" "uuid", "p_role" "text", "p_account_key" "text", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rides"."_resolve_payment_account_id"("p_account_key" "text", "p_currency" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $_$
DECLARE
  v_id UUID;
  v_user_id UUID;
  v_org_id UUID;
BEGIN
  IF p_account_key IN ('platform:receivable', 'platform:clearing') THEN
    RETURN rides._ensure_payment_account(NULL, 'system', p_account_key, p_currency);
  END IF;

  IF p_account_key ~ '^org:[0-9a-fA-F-]{36}:(digital|cash)$' THEN
    v_org_id := (regexp_match(p_account_key, '^org:([0-9a-fA-F-]{36}):'))[1]::UUID;
    v_id := rides._ensure_payment_account(NULL, 'org', p_account_key, p_currency);
    UPDATE rides.payment_accounts
      SET organization_id = v_org_id
      WHERE id = v_id AND organization_id IS NULL;
    RETURN v_id;
  END IF;

  IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:driver:(digital|cash|debt)$' THEN
    v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):driver:'))[1]::UUID;
    RETURN rides._ensure_payment_account(v_user_id, 'driver', p_account_key, p_currency);
  END IF;

  IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:rider$' THEN
    v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):rider$'))[1]::UUID;
    RETURN rides._ensure_payment_account(v_user_id, 'rider', p_account_key, p_currency);
  END IF;

  IF p_account_key ~ '^user:[0-9a-fA-F-]{36}:driver$' THEN
    v_user_id := (regexp_match(p_account_key, '^user:([0-9a-fA-F-]{36}):driver$'))[1]::UUID;
    RETURN rides._ensure_payment_account(v_user_id, 'driver', p_account_key, p_currency);
  END IF;

  SELECT id INTO v_id
  FROM rides.payment_accounts
  WHERE account_key = p_account_key
    AND currency = p_currency;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'account_not_found:%', p_account_key;
  END IF;

  RETURN v_id;
END;
$_$;


ALTER FUNCTION "rides"."_resolve_payment_account_id"("p_account_key" "text", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rides"."audit_offer_accepted"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'rides', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'accepted' AND OLD.status = 'pending' THEN
    BEGIN
      INSERT INTO rides.audit_events (
        ride_request_id,
        actor_user_id,
        event_type,
        payload
      ) VALUES (
        NEW.ride_request_id,
        NEW.driver_user_id,
        'offer_accepted_atomic',
        jsonb_build_object(
          'offer_id', NEW.id,
          'wave', NEW.wave,
          'distance_km', NEW.distance_km
        )
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'audit_offer_accepted: failed to log offer % (%)', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "rides"."audit_offer_accepted"() OWNER TO "postgres";


COMMENT ON FUNCTION "rides"."audit_offer_accepted"() IS 'Best-effort audit on offer accept; never rolls back the acceptance transaction.';



CREATE OR REPLACE FUNCTION "rides"."post_payment_journal_line"("p_ride_request_id" "uuid", "p_idempotency_key" "text", "p_entry_type" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_amount_minor" bigint, "p_currency" "text", "p_request_hash" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'public'
    AS $$
DECLARE
  v_debit_id UUID;
  v_credit_id UUID;
  v_first_id UUID;
  v_second_id UUID;
  v_inserted INTEGER;
  v_existing_hash TEXT;
BEGIN
  IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'invalid_amount_minor';
  END IF;

  v_debit_id := rides._resolve_payment_account_id(p_debit_account_key, p_currency);
  v_credit_id := rides._resolve_payment_account_id(p_credit_account_key, p_currency);

  IF v_debit_id < v_credit_id THEN
    v_first_id := v_debit_id;
    v_second_id := v_credit_id;
  ELSE
    v_first_id := v_credit_id;
    v_second_id := v_debit_id;
  END IF;

  PERFORM id
  FROM rides.payment_accounts
  WHERE id = v_first_id
  FOR UPDATE;

  PERFORM id
  FROM rides.payment_accounts
  WHERE id = v_second_id
  FOR UPDATE;

  INSERT INTO rides.payment_journal_entries (
    ride_request_id,
    idempotency_key,
    entry_type,
    debit_account_id,
    credit_account_id,
    amount_minor,
    currency,
    request_hash,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_ride_request_id,
    p_idempotency_key,
    p_entry_type,
    v_debit_id,
    v_credit_id,
    p_amount_minor,
    p_currency,
    p_request_hash,
    COALESCE(p_metadata, '{}'::jsonb),
    p_created_by_user_id
  )
  ON CONFLICT (ride_request_id, idempotency_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT request_hash INTO v_existing_hash
    FROM rides.payment_journal_entries
    WHERE ride_request_id IS NOT DISTINCT FROM p_ride_request_id
      AND idempotency_key = p_idempotency_key;

    IF v_existing_hash IS NOT NULL AND v_existing_hash IS DISTINCT FROM p_request_hash THEN
      RETURN jsonb_build_object('inserted', false, 'skipped', false, 'conflict', true);
    END IF;

    RETURN jsonb_build_object('inserted', false, 'skipped', true, 'conflict', false);
  END IF;

  UPDATE rides.payment_accounts
  SET balance_minor = balance_minor - p_amount_minor
  WHERE id = v_debit_id;

  UPDATE rides.payment_accounts
  SET balance_minor = balance_minor + p_amount_minor
  WHERE id = v_credit_id;

  RETURN jsonb_build_object('inserted', true, 'skipped', false, 'conflict', false);
END;
$$;


ALTER FUNCTION "rides"."post_payment_journal_line"("p_ride_request_id" "uuid", "p_idempotency_key" "text", "p_entry_type" "text", "p_debit_account_key" "text", "p_credit_account_key" "text", "p_amount_minor" bigint, "p_currency" "text", "p_request_hash" "text", "p_metadata" "jsonb", "p_created_by_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rides"."purge_old_location_updates"("p_keep_days" integer DEFAULT 30) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rides', 'pg_temp'
    AS $$
DECLARE
  deleted_count bigint;
BEGIN
  IF p_keep_days IS NULL OR p_keep_days < 1 THEN
    RAISE EXCEPTION 'p_keep_days must be >= 1';
  END IF;

  DELETE FROM rides.ride_location_updates
  WHERE recorded_at < (now() - make_interval(days => p_keep_days));

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "rides"."purge_old_location_updates"("p_keep_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "rides"."purge_old_location_updates"("p_keep_days" integer) IS 'Deletes ride GPS pings older than p_keep_days (default 30). Service-role / cron only.';



