CREATE OR REPLACE FUNCTION "rush_config"."apply_change"("p_key" "text", "p_scope" "text", "p_scope_id" "uuid", "p_new_value" "jsonb", "p_reason" "text", "p_changed_by" "uuid", "p_expected_version" integer, "p_approved_by" "uuid" DEFAULT NULL::"uuid", "p_risk_high" boolean DEFAULT false, "p_effective_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rush_config', 'public'
    AS $$
DECLARE
  v_scope_id uuid;
  v_row rush_config.setting_values%ROWTYPE;
  v_old jsonb;
  v_new_version int;
  v_effective timestamptz;
  v_change_id bigint;
BEGIN
  IF p_key IS NULL OR btrim(p_key) = '' THEN
    RAISE EXCEPTION 'invalid_key' USING ERRCODE = 'P0001';
  END IF;
  IF p_scope NOT IN ('platform', 'market') THEN
    RAISE EXCEPTION 'invalid_scope' USING ERRCODE = 'P0001';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = 'P0001';
  END IF;
  IF p_changed_by IS NULL THEN
    RAISE EXCEPTION 'changed_by_required' USING ERRCODE = 'P0001';
  END IF;
  IF p_new_value IS NULL THEN
    RAISE EXCEPTION 'value_required' USING ERRCODE = 'P0001';
  END IF;

  IF p_risk_high THEN
    IF p_approved_by IS NULL THEN
      RAISE EXCEPTION 'approver_required' USING ERRCODE = 'P0001';
    END IF;
    IF p_approved_by = p_changed_by THEN
      RAISE EXCEPTION 'self_approval_forbidden' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_scope_id := CASE
    WHEN p_scope = 'platform' THEN '00000000-0000-0000-0000-000000000000'::uuid
    ELSE COALESCE(p_scope_id, '00000000-0000-0000-0000-000000000000'::uuid)
  END;
  IF p_scope = 'market' AND (p_scope_id IS NULL OR p_scope_id = '00000000-0000-0000-0000-000000000000'::uuid) THEN
    RAISE EXCEPTION 'market_scope_id_required' USING ERRCODE = 'P0001';
  END IF;

  v_effective := COALESCE(p_effective_at, now());

  SELECT * INTO v_row
  FROM rush_config.setting_values
  WHERE key = p_key AND scope = p_scope AND scope_id = v_scope_id
  FOR UPDATE;

  IF FOUND THEN
    IF p_expected_version IS NOT NULL AND v_row.version <> p_expected_version THEN
      RAISE EXCEPTION 'stale_version' USING ERRCODE = 'P0001';
    END IF;
    v_old := v_row.value;
    v_new_version := v_row.version + 1;
    UPDATE rush_config.setting_values
    SET value = p_new_value,
        version = v_new_version,
        updated_by = p_changed_by,
        updated_at = now()
    WHERE key = p_key AND scope = p_scope AND scope_id = v_scope_id;
  ELSE
    IF p_expected_version IS NOT NULL AND p_expected_version <> 0 THEN
      RAISE EXCEPTION 'stale_version' USING ERRCODE = 'P0001';
    END IF;
    v_old := NULL;
    v_new_version := 1;
    INSERT INTO rush_config.setting_values (key, scope, scope_id, value, version, updated_by, updated_at)
    VALUES (p_key, p_scope, v_scope_id, p_new_value, v_new_version, p_changed_by, now());
  END IF;

  INSERT INTO rush_config.setting_changes (
    key, scope, scope_id, old_value, new_value, reason, changed_by, approved_by, effective_at
  ) VALUES (
    p_key, p_scope,
    CASE WHEN p_scope = 'platform' THEN NULL ELSE v_scope_id END,
    v_old, p_new_value, p_reason, p_changed_by, p_approved_by, v_effective
  )
  RETURNING id INTO v_change_id;

  RETURN jsonb_build_object(
    'ok', true,
    'key', p_key,
    'scope', p_scope,
    'scope_id', CASE WHEN p_scope = 'platform' THEN NULL ELSE to_jsonb(v_scope_id) END,
    'version', v_new_version,
    'change_id', v_change_id,
    'old_value', v_old,
    'new_value', p_new_value
  );
END;
$$;


ALTER FUNCTION "rush_config"."apply_change"("p_key" "text", "p_scope" "text", "p_scope_id" "uuid", "p_new_value" "jsonb", "p_reason" "text", "p_changed_by" "uuid", "p_expected_version" integer, "p_approved_by" "uuid", "p_risk_high" boolean, "p_effective_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_config"."apply_due_pending_changes"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rush_config', 'public'
    AS $$
DECLARE
  r RECORD;
  v_count int := 0;
  v_approver uuid;
BEGIN
  FOR r IN
    SELECT *
    FROM rush_config.pending_changes
    WHERE status IN ('pending', 'approved')
      AND (effective_at IS NULL OR effective_at <= now())
      AND (
        risk_high = false
        OR (status = 'approved' AND decided_by IS NOT NULL AND decided_by <> requested_by)
      )
    ORDER BY created_at ASC
    FOR UPDATE SKIP LOCKED
  LOOP
    IF r.risk_high AND r.status <> 'approved' THEN
      CONTINUE;
    END IF;

    v_approver := CASE WHEN r.risk_high THEN r.decided_by ELSE NULL END;

    BEGIN
      PERFORM rush_config.apply_change(
        r.key,
        r.scope,
        r.scope_id,
        r.new_value,
        r.reason,
        r.requested_by,
        r.expected_version,
        v_approver,
        r.risk_high,
        COALESCE(r.effective_at, now())
      );
      UPDATE rush_config.pending_changes
      SET status = 'applied', decided_at = COALESCE(decided_at, now())
      WHERE id = r.id;
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'apply_due_pending_changes skip %: %', r.id, SQLERRM;
    END;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "rush_config"."apply_due_pending_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."enforce_two_person_payout"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_approvers int;
BEGIN
  IF NEW.status IN ('approved', 'exported', 'sent', 'paid') THEN
    SELECT count(DISTINCT actor_id) INTO v_approvers
    FROM rush_money.payout_approvals
    WHERE batch_id = NEW.id
      AND actor_id IS DISTINCT FROM NEW.created_by;
    IF v_approvers < 2 THEN
      RAISE EXCEPTION 'payout_two_person_required';
    END IF;
    IF NEW.created_by IS NOT NULL AND EXISTS (
      SELECT 1 FROM rush_money.payout_approvals
      WHERE batch_id = NEW.id AND actor_id = NEW.created_by
    ) THEN
      RAISE EXCEPTION 'payout_preparer_cannot_approve';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "rush_money"."enforce_two_person_payout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."lock_lines"("p_batch_id" "uuid", "p_line_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rush_money', 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE rush_money.lines
  SET payout_batch_id = p_batch_id
  WHERE id = ANY(p_line_ids)
    AND payout_batch_id IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "rush_money"."lock_lines"("p_batch_id" "uuid", "p_line_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."lock_week"("p_batch_id" "uuid", "p_kind" "text", "p_start" "date", "p_end" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rush_money', 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE rush_money.lines l
  SET payout_batch_id = p_batch_id
  FROM rush_money.journals j, rush_money.accounts a
  WHERE l.journal_id = j.id
    AND l.account_id = a.id
    AND l.payout_batch_id IS NULL
    AND a.party_id IS NOT NULL
    AND j.event_type IS DISTINCT FROM 'payout_in_flight'
    AND j.created_at < (p_end + 1)::timestamptz
    AND (
      a.kind = p_kind
      OR (p_kind = 'merchant_payable' AND a.kind = 'merchant_receivable')
    )
    AND a.party_id IN (
      SELECT party_id FROM rush_money.week_payable(p_kind, p_start, p_end)
    );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "rush_money"."lock_week"("p_batch_id" "uuid", "p_kind" "text", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."post_journal"("p_idempotency_key" "text", "p_event_type" "text", "p_order_id" "uuid", "p_correlation_id" "uuid", "p_lines" "jsonb", "p_actor_id" "uuid", "p_actor_type" "text", "p_reason" "text", "p_evidence" "jsonb", "p_policy_version" "text") RETURNS "rush_money"."journals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'rush_money', 'public'
    AS $$
DECLARE
  v_existing rush_money.journals%ROWTYPE;
  v_journal rush_money.journals%ROWTYPE;
  v_line jsonb;
  v_sum bigint := 0;
  v_count int := 0;
  v_account_id uuid;
  v_ids uuid[] := ARRAY[]::uuid[];
  v_id uuid;
  v_amount bigint;
  v_party uuid;
  v_kind text;
  v_party_type text;
  v_component text;
  v_balance bigint;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'idempotency_key_required';
  END IF;

  SELECT * INTO v_existing FROM rush_money.journals WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN v_existing;
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_amount := (v_line->>'amount_minor')::bigint;
    IF v_amount IS NULL OR v_amount = 0 THEN
      RAISE EXCEPTION 'line_amount_required';
    END IF;
    v_sum := v_sum + v_amount;
    v_count := v_count + 1;
  END LOOP;
  IF v_count < 2 OR v_sum <> 0 THEN
    RAISE EXCEPTION 'journal_imbalance: %', v_sum;
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_kind := v_line->>'kind';
    v_party_type := v_line->>'party_type';
    v_component := COALESCE(v_line->>'component', '');
    v_party := NULLIF(v_line->>'party_id', '')::uuid;
    SELECT id INTO v_account_id
    FROM rush_money.accounts
    WHERE kind = v_kind
      AND party_type = v_party_type
      AND component = v_component
      AND party_id IS NOT DISTINCT FROM v_party;
    IF v_account_id IS NULL THEN
      BEGIN
        INSERT INTO rush_money.accounts (kind, party_type, party_id, component)
        VALUES (v_kind, v_party_type, v_party, v_component)
        RETURNING id INTO v_account_id;
      EXCEPTION WHEN unique_violation THEN
        SELECT id INTO v_account_id
        FROM rush_money.accounts
        WHERE kind = v_kind
          AND party_type = v_party_type
          AND component = v_component
          AND party_id IS NOT DISTINCT FROM v_party;
      END;
    END IF;
    v_ids := array_append(v_ids, v_account_id);
  END LOOP;

  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_ids FROM unnest(v_ids) AS x;
  FOREACH v_id IN ARRAY v_ids LOOP
    PERFORM 1 FROM rush_money.accounts WHERE id = v_id FOR UPDATE;
  END LOOP;

  INSERT INTO rush_money.journals (
    idempotency_key, event_type, order_id, correlation_id, policy_version,
    reason, evidence, actor_id, actor_type
  ) VALUES (
    p_idempotency_key, p_event_type, p_order_id, p_correlation_id, p_policy_version,
    p_reason, COALESCE(p_evidence, '{}'::jsonb), p_actor_id, COALESCE(p_actor_type, 'system')
  )
  RETURNING * INTO v_journal;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_kind := v_line->>'kind';
    v_party_type := v_line->>'party_type';
    v_component := COALESCE(v_line->>'component', '');
    v_party := NULLIF(v_line->>'party_id', '')::uuid;
    v_amount := (v_line->>'amount_minor')::bigint;
    SELECT id, balance_minor INTO v_account_id, v_balance
    FROM rush_money.accounts
    WHERE kind = v_kind
      AND party_type = v_party_type
      AND component = v_component
      AND party_id IS NOT DISTINCT FROM v_party
    FOR UPDATE;

    IF v_kind = 'customer_wallet' AND v_balance + v_amount > 500000
       AND COALESCE(p_evidence->>'allow_debt_over_cap', '') <> 'true' THEN
      RAISE EXCEPTION 'wallet_debt_cap';
    END IF;

    INSERT INTO rush_money.lines (journal_id, account_id, component, amount_minor)
    VALUES (v_journal.id, v_account_id, v_component, v_amount);

    UPDATE rush_money.accounts
    SET balance_minor = balance_minor + v_amount
    WHERE id = v_account_id;
  END LOOP;

  RETURN v_journal;
END;
$$;


ALTER FUNCTION "rush_money"."post_journal"("p_idempotency_key" "text", "p_event_type" "text", "p_order_id" "uuid", "p_correlation_id" "uuid", "p_lines" "jsonb", "p_actor_id" "uuid", "p_actor_type" "text", "p_reason" "text", "p_evidence" "jsonb", "p_policy_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."reject_in_house_merchant_payable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_kind text;
  v_party uuid;
  v_party_type text;
BEGIN
  SELECT kind, party_id, party_type INTO v_kind, v_party, v_party_type
  FROM rush_money.accounts
  WHERE id = NEW.account_id;
  IF v_kind = 'merchant_payable' AND v_party_type = 'merchant' AND v_party IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM delivery.merchants
      WHERE id = v_party AND procurement_mode = 'in_house'
    ) THEN
      RAISE EXCEPTION 'in_house_merchant_payable_forbidden';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "rush_money"."reject_in_house_merchant_payable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."reject_journal_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'rush_money_append_only';
  END IF;
  IF OLD.period_id IS NOT NULL THEN
    RAISE EXCEPTION 'period_locked';
  END IF;
  IF (to_jsonb(NEW) - 'period_id') IS DISTINCT FROM (to_jsonb(OLD) - 'period_id') THEN
    RAISE EXCEPTION 'rush_money_append_only';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "rush_money"."reject_journal_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."reject_line_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.journal_id = OLD.journal_id
     AND NEW.account_id = OLD.account_id
     AND NEW.amount_minor = OLD.amount_minor
     AND NEW.payout_batch_id IS DISTINCT FROM OLD.payout_batch_id
     AND OLD.payout_batch_id IS NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'rush_money_append_only';
END;
$$;


ALTER FUNCTION "rush_money"."reject_line_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."transition_money_state"("p_order_id" "uuid", "p_to" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'delivery', 'public'
    AS $$
DECLARE
  v_from text;
BEGIN
  SELECT money_state INTO v_from FROM delivery.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found';
  END IF;
  IF v_from = p_to THEN
    RETURN v_from;
  END IF;
  IF NOT (
    (v_from = 'awaiting_payment' AND p_to IN ('captured','voided','awaiting_collection')) OR
    (v_from = 'captured' AND p_to IN ('settled','partially_refunded','refunded','cancel_settled','disputed')) OR
    (v_from = 'settled' AND p_to IN ('partially_refunded','refunded','disputed')) OR
    (v_from = 'partially_refunded' AND p_to IN ('refunded','disputed','settled')) OR
    (v_from = 'disputed' AND p_to IN ('settled','charged_back')) OR
    (v_from = 'awaiting_collection' AND p_to IN ('collected','short_collected','failed_delivery','voided')) OR
    (v_from IN ('collected','short_collected') AND p_to = 'settled') OR
    (v_from = 'failed_delivery' AND p_to = 'cancel_settled')
  ) THEN
    RAISE EXCEPTION 'money_state_refused: % -> %', v_from, p_to;
  END IF;
  UPDATE delivery.orders SET money_state = p_to, updated_at = now() WHERE id = p_order_id;
  RETURN p_to;
END;
$$;


ALTER FUNCTION "rush_money"."transition_money_state"("p_order_id" "uuid", "p_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rush_money"."week_payable"("p_kind" "text", "p_start" "date", "p_end" "date") RETURNS TABLE("party_id" "uuid", "amount_minor" bigint, "line_ids" "uuid"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'rush_money', 'public'
    AS $$
  WITH unlocked AS (
    SELECT a.party_id, a.kind, l.id AS line_id, l.amount_minor
    FROM rush_money.lines l
    JOIN rush_money.journals j ON j.id = l.journal_id
    JOIN rush_money.accounts a ON a.id = l.account_id
    WHERE a.party_id IS NOT NULL
      AND l.payout_batch_id IS NULL
      AND j.event_type IS DISTINCT FROM 'payout_in_flight'
      AND j.created_at < (p_end + 1)::timestamptz
      AND (
        a.kind = p_kind
        OR (p_kind = 'merchant_payable' AND a.kind = 'merchant_receivable')
      )
  )
  SELECT party_id,
    (-SUM(amount_minor))::bigint AS amount_minor,
    array_agg(line_id) AS line_ids
  FROM unlocked
  GROUP BY party_id
  HAVING SUM(amount_minor) < 0;
$$;


ALTER FUNCTION "rush_money"."week_payable"("p_kind" "text", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."toll_settlement_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "text" NOT NULL,
    "toll_id" "text" NOT NULL,
    "claim_id" "text",
    "amount" numeric(12,2) NOT NULL,
    "toll_period_anchor" "date",
    "idempotency_key" "text" NOT NULL,
    "reverses_id" "uuid",
    "actor" "text",
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "toll_settlement_allocations_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "toll_settlement_allocations_source_type_check" CHECK (("source_type" = ANY (ARRAY['trip_refund'::"text", 'unlinked_trip'::"text", 'dispute_refund'::"text", 'driver_charge'::"text", 'write_off'::"text", 'reversal'::"text"])))
);


ALTER TABLE "public"."toll_settlement_allocations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "toll"."mirror_settlement_from_public"("p_row" "public"."toll_settlement_allocations") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'toll', 'public', 'pg_temp'
    AS $_$
BEGIN
  INSERT INTO toll.settlement_allocations (
    id, legacy_public_id, source_type, source_id, toll_id, trip_id, claim_id,
    amount_minor, toll_period_anchor, idempotency_key, reverses_id, actor, notes,
    metadata, parse_status, created_at
  ) VALUES (
    p_row.id, p_row.id, p_row.source_type, p_row.source_id, p_row.toll_id,
    CASE
      WHEN (p_row.metadata->>'trip_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (p_row.metadata->>'trip_id')::uuid
      ELSE NULL
    END,
    p_row.claim_id,
    GREATEST(1, ROUND(p_row.amount * 100)::bigint),
    p_row.toll_period_anchor,
    p_row.idempotency_key,
    p_row.reverses_id,
    p_row.actor,
    p_row.notes,
    COALESCE(p_row.metadata, '{}'::jsonb),
    'ok',
    COALESCE(p_row.created_at, now())
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    reverses_id = EXCLUDED.reverses_id,
    notes = EXCLUDED.notes,
    metadata = EXCLUDED.metadata;
END;
$_$;


ALTER FUNCTION "toll"."mirror_settlement_from_public"("p_row" "public"."toll_settlement_allocations") OWNER TO "postgres";


