CREATE OR REPLACE VIEW "delivery"."coverage_health_summary" AS
 SELECT "id" AS "parish_id",
    "slug",
    "name",
    "coverage_mode",
    "pcode",
    "boundary_source",
    "boundary_valid_on",
    ("foundation_geom" IS NOT NULL) AS "has_foundation_geom",
    (("foundation_polygon" IS NOT NULL) AND ("jsonb_typeof"("foundation_polygon") = 'array'::"text")) AS "has_foundation_jsonb",
        CASE
            WHEN (("foundation_polygon" IS NOT NULL) AND ("jsonb_typeof"("foundation_polygon") = 'array'::"text")) THEN "jsonb_array_length"("foundation_polygon")
            ELSE 0
        END AS "foundation_vertex_count",
    ( SELECT "count"(*) AS "count"
           FROM "delivery"."service_markets" "m"
          WHERE ("m"."parish_id" = "p"."id")) AS "town_count",
    ( SELECT "count"(*) AS "count"
           FROM "delivery"."service_markets" "m"
          WHERE (("m"."parish_id" = "p"."id") AND ("m"."pcode" IS NOT NULL))) AS "towns_with_pcode",
    ( SELECT "count"(*) AS "count"
           FROM "geo"."boundaries" "b"
          WHERE (("b"."admin_level" = 2) AND ("b"."parent_pcode" = "p"."pcode"))) AS "catalog_admin2_count",
    ( SELECT "count"(*) AS "count"
           FROM "delivery"."service_markets" "m"
          WHERE (("m"."parish_id" = "p"."id") AND "m"."is_active")) AS "active_town_count",
    ( SELECT "count"(*) AS "count"
           FROM "delivery"."service_markets" "m"
          WHERE (("m"."parish_id" = "p"."id") AND (NOT (EXISTS ( SELECT 1
                   FROM "delivery"."service_zone_polygons" "z"
                  WHERE (("z"."market_id" = "m"."id") AND ("z"."kind" = 'include'::"text"))))))) AS "towns_missing_border",
    ( SELECT COALESCE("string_agg"("m"."name", ', '::"text" ORDER BY "m"."name"), ''::"text") AS "coalesce"
           FROM "delivery"."service_markets" "m"
          WHERE (("m"."parish_id" = "p"."id") AND (NOT (EXISTS ( SELECT 1
                   FROM "delivery"."service_zone_polygons" "z"
                  WHERE (("z"."market_id" = "m"."id") AND ("z"."kind" = 'include'::"text"))))))) AS "towns_missing_border_names"
   FROM "delivery"."service_parishes" "p"
  ORDER BY "sort_order";


ALTER VIEW "delivery"."coverage_health_summary" OWNER TO "postgres";


