CREATE TABLE IF NOT EXISTS "delivery"."merchants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid",
    "name" "text",
    "slug" "text",
    "description" "text",
    "logo_url" "text",
    "cover_image_url" "text",
    "address" "text",
    "lat" numeric,
    "lng" numeric,
    "phone" "text",
    "email" "text",
    "cuisine_type" "text",
    "business_hours" "jsonb" DEFAULT '{}'::"jsonb",
    "is_active" boolean DEFAULT false,
    "is_verified" boolean DEFAULT false,
    "is_accepting_orders" boolean DEFAULT true,
    "avg_prep_time_mins" integer DEFAULT 30,
    "min_order_amount" numeric DEFAULT 0,
    "delivery_fee" numeric DEFAULT 0,
    "delivery_radius_km" numeric DEFAULT 10,
    "commission_rate" numeric,
    "rating" numeric DEFAULT 0,
    "total_ratings" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "verification_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "verification_notes" "text",
    "rejection_reason" "text",
    "verified_at" timestamp with time zone,
    "verified_by" "uuid",
    "submitted_at" timestamp with time zone,
    "business_type" "text",
    "business_registration_number" "text",
    "tax_id" "text",
    "owner_full_name" "text",
    "city" "text",
    "postal_code" "text",
    "cuisine_types" "text"[] DEFAULT '{}'::"text"[],
    "website" "text",
    "notification_settings" "jsonb" DEFAULT '{}'::"jsonb",
    "operational_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "suspended_at" timestamp with time zone,
    "suspended_reason" "text",
    "suspended_by" "uuid",
    "deactivated_at" timestamp with time zone,
    "deactivated_reason" "text",
    "deactivated_by" "uuid",
    "admin_assigned_to" "uuid",
    "admin_internal_notes" "text",
    "verification_checklist" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "onboarding_status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "wizard_step" smallint DEFAULT 1 NOT NULL,
    "wizard_step_key" "text",
    "onboarding_draft" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_onboarding_activity_at" timestamp with time zone,
    "vertical_type" "text",
    "fulfillment_type" "text",
    "go_live_rule" "text",
    "kiosk_pairing_code" "text",
    "kiosk_pairing_rotated_at" timestamp with time zone,
    "staff_operations_enabled" boolean DEFAULT false NOT NULL,
    "staff_station_pin_enabled" boolean DEFAULT false NOT NULL,
    "capabilities" "text"[] DEFAULT ARRAY['roam_delivery'::"text"] NOT NULL,
    "pos_printer_id" "text",
    "pos_tax_rate_percent" numeric DEFAULT 0 NOT NULL,
    "pos_receipt_footer" "text",
    "pos_show_in_store_on_counter" boolean DEFAULT false NOT NULL,
    "pos_show_in_store_on_kitchen" boolean DEFAULT false NOT NULL,
    "venue_style" "text",
    "enabled_stations" "text"[] DEFAULT '{counter,kitchen,manager,pos}'::"text"[] NOT NULL,
    "inventory_mode" "text" DEFAULT 'legacy'::"text" NOT NULL,
    "inventory_company_id" "uuid",
    "enterprise_inventory_shadow" boolean DEFAULT false NOT NULL,
    "stripe_connect_account_id" "text",
    "instagram" "text",
    "facebook" "text",
    "payout_ready" boolean DEFAULT false NOT NULL,
    "is_test_merchant" boolean DEFAULT false NOT NULL,
    "payout_ready_at" timestamp with time zone,
    "payout_ready_by" "uuid",
    "gct_registered" boolean DEFAULT false NOT NULL,
    "pricing_tier_id" "uuid",
    "merchant_commission_rate" numeric,
    "service_fee_override" "jsonb",
    "market_id" "uuid",
    "market_id_locked" boolean DEFAULT false NOT NULL,
    "market_id_lock_source" "text",
    "menu_inflation_percent" numeric DEFAULT 0 NOT NULL,
    "dominant_assigned_at" timestamp with time zone,
    "procurement_mode" "text" DEFAULT 'partner'::"text" NOT NULL,
    "in_house_live" boolean DEFAULT false NOT NULL,
    "cuisines" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "menu_brand_id" "uuid",
    "engine_menu_id" "uuid",
    CONSTRAINT "merchants_capabilities_roam_required" CHECK (('roam_delivery'::"text" = ANY ("capabilities"))),
    CONSTRAINT "merchants_commission_rate_check" CHECK ((("commission_rate" IS NULL) OR (("commission_rate" >= (0)::numeric) AND ("commission_rate" <= (1)::numeric)))),
    CONSTRAINT "merchants_fulfillment_type_check" CHECK ((("fulfillment_type" IS NULL) OR ("fulfillment_type" = ANY (ARRAY['cook_to_order'::"text", 'pick_and_pack'::"text"])))),
    CONSTRAINT "merchants_gct_registered_requires_tax_id" CHECK ((("gct_registered" = false) OR (("tax_id" IS NOT NULL) AND ("length"(TRIM(BOTH FROM "tax_id")) > 0)))),
    CONSTRAINT "merchants_go_live_rule_check" CHECK ((("go_live_rule" IS NULL) OR ("go_live_rule" = ANY (ARRAY['menu_min_5'::"text", 'catalog_imported'::"text", 'pos_connected'::"text"])))),
    CONSTRAINT "merchants_inventory_mode_check" CHECK (("inventory_mode" = ANY (ARRAY['legacy'::"text", 'enterprise'::"text"]))),
    CONSTRAINT "merchants_market_id_lock_source_check" CHECK ((("market_id_lock_source" IS NULL) OR ("market_id_lock_source" = ANY (ARRAY['manual'::"text", 'pin'::"text"])))),
    CONSTRAINT "merchants_menu_inflation_percent_check" CHECK ((("menu_inflation_percent" >= (0)::numeric) AND ("menu_inflation_percent" <= (1)::numeric))),
    CONSTRAINT "merchants_merchant_commission_rate_check" CHECK ((("merchant_commission_rate" IS NULL) OR (("merchant_commission_rate" >= (0)::numeric) AND ("merchant_commission_rate" <= (1)::numeric)))),
    CONSTRAINT "merchants_onboarding_status_check" CHECK (("onboarding_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))),
    CONSTRAINT "merchants_onboarding_submitted_fields" CHECK ((("onboarding_status" = 'draft'::"text") OR (("name" IS NOT NULL) AND ("slug" IS NOT NULL) AND ("submitted_at" IS NOT NULL)))),
    CONSTRAINT "merchants_operational_status_check" CHECK (("operational_status" = ANY (ARRAY['active'::"text", 'suspended'::"text", 'deactivated'::"text"]))),
    CONSTRAINT "merchants_owner_matches_procurement" CHECK (((("procurement_mode" = 'partner'::"text") AND ("owner_id" IS NOT NULL)) OR (("procurement_mode" = 'in_house'::"text") AND ("owner_id" IS NULL)))),
    CONSTRAINT "merchants_pos_tax_rate_percent_check" CHECK ((("pos_tax_rate_percent" IS NULL) OR (("pos_tax_rate_percent" >= (0)::numeric) AND ("pos_tax_rate_percent" <= (100)::numeric)))),
    CONSTRAINT "merchants_procurement_mode_check" CHECK (("procurement_mode" = ANY (ARRAY['partner'::"text", 'in_house'::"text"]))),
    CONSTRAINT "merchants_venue_style_check" CHECK ((("venue_style" IS NULL) OR ("venue_style" = ANY (ARRAY['fast_food'::"text", 'sports_bar'::"text", 'fine_dining'::"text", 'cafe'::"text", 'ghost_kitchen'::"text", 'delivery_only'::"text", 'custom'::"text"])))),
    CONSTRAINT "merchants_verification_status_check" CHECK (("verification_status" = ANY (ARRAY['pending'::"text", 'in_review'::"text", 'docs_requested'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "merchants_vertical_type_check" CHECK ((("vertical_type" IS NULL) OR ("vertical_type" = ANY (ARRAY['restaurant'::"text", 'grocery'::"text", 'pharmacy'::"text", 'alcohol'::"text", 'convenience'::"text", 'retail'::"text"])))),
    CONSTRAINT "merchants_wizard_step_check" CHECK ((("wizard_step" >= 1) AND ("wizard_step" <= 7)))
);


ALTER TABLE "delivery"."merchants" OWNER TO "postgres";


COMMENT ON COLUMN "delivery"."merchants"."commission_rate" IS 'Optional Dash platform fee override as 0–1 fraction (e.g. 0.05 = 5%). NULL = use global platformFeeRate from platform:settings:dash.';



COMMENT ON COLUMN "delivery"."merchants"."verification_checklist" IS 'Admin checklist keys: id_verified, business_proof_verified, bank_verified, hours_verified, menu_preview_verified';



COMMENT ON COLUMN "delivery"."merchants"."wizard_step" IS 'Partner onboarding wizard progress (1–7). Final step is verification.';



COMMENT ON COLUMN "delivery"."merchants"."vertical_type" IS 'Snapshot of vertical at submit; null = restaurant default';



COMMENT ON COLUMN "delivery"."merchants"."pos_tax_rate_percent" IS 'Optional POS override %. NULL = use Dominion/accounting standard GCT rate when registered.';



COMMENT ON COLUMN "delivery"."merchants"."stripe_connect_account_id" IS 'Deprecated 2026-09 — Jamaica bank/WiPay payouts; column no longer written.';



COMMENT ON COLUMN "delivery"."merchants"."instagram" IS 'Public Instagram handle or URL';



COMMENT ON COLUMN "delivery"."merchants"."facebook" IS 'Public Facebook page URL or handle';



COMMENT ON COLUMN "delivery"."merchants"."payout_ready" IS 'Admin-verified: merchant may go live and accept paid orders.';



COMMENT ON COLUMN "delivery"."merchants"."is_test_merchant" IS 'Seed/dev store: bypasses payout gate for E2E and internal testing.';



COMMENT ON COLUMN "delivery"."merchants"."gct_registered" IS 'True when merchant is GCT-registered and may charge GCT on taxable food supplies.';



COMMENT ON COLUMN "delivery"."merchants"."market_id" IS 'Assigned delivery town (service_markets). Required for discovery and order eligibility; must match customer dropoff market.';



COMMENT ON COLUMN "delivery"."merchants"."market_id_locked" IS 'When true, coverage publish/restore will not auto-change market_id from the store pin.';



COMMENT ON COLUMN "delivery"."merchants"."market_id_lock_source" IS 'manual = ops locked town; pin = auto from store pin (follows pin, resists publish recompute); null = fully auto';



COMMENT ON COLUMN "delivery"."merchants"."menu_inflation_percent" IS 'Merchant-chosen menu markup 0–1; capped by platform.max_menu_inflation_percent';



COMMENT ON COLUMN "delivery"."merchants"."dominant_assigned_at" IS 'When merchant was assigned Dominant tier (Growth Guarantee window start).';



COMMENT ON CONSTRAINT "merchants_owner_matches_procurement" ON "delivery"."merchants" IS 'Partner restaurants belong to one owner. In-House restaurants belong to Roam and have no owner.';



