    "money_state" "text" DEFAULT 'awaiting_payment'::"text" NOT NULL,
    "cash_collected_minor" bigint,
    "cash_change_kept_minor" bigint,
    "failed_delivery_outcome" "text",
    "cancel_stage" "text",
    "fault" "text",
    "policy_version" "text",
    "delivery_pin" "text",
    "delivery_pin_verified_at" timestamp with time zone,
    "wait_pay_jmd" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "orders_amounts_nonneg_check" CHECK (((COALESCE("subtotal", (0)::numeric) >= (0)::numeric) AND (COALESCE("delivery_fee", (0)::numeric) >= (0)::numeric) AND (COALESCE("platform_fee", (0)::numeric) >= (0)::numeric) AND (COALESCE("tax", (0)::numeric) >= (0)::numeric) AND (COALESCE("tip", (0)::numeric) >= (0)::numeric) AND (COALESCE("discount", (0)::numeric) >= (0)::numeric) AND (COALESCE("total", (0)::numeric) >= (0)::numeric))),
    CONSTRAINT "orders_customer_required_for_roam" CHECK (((("channel" = 'roam_app'::"text") AND ("customer_id" IS NOT NULL)) OR ("channel" = ANY (ARRAY['in_store'::"text", 'phone'::"text"])))),
    CONSTRAINT "orders_fulfillment_type_check" CHECK ((("fulfillment_type" IS NULL) OR ("fulfillment_type" = ANY (ARRAY['delivery'::"text", 'pickup'::"text", 'dine_in'::"text", 'counter'::"text"])))),
    CONSTRAINT "orders_money_state_check" CHECK (("money_state" = ANY (ARRAY['awaiting_payment'::"text", 'captured'::"text", 'settled'::"text", 'partially_refunded'::"text", 'refunded'::"text", 'voided'::"text", 'cancel_settled'::"text", 'disputed'::"text", 'charged_back'::"text", 'awaiting_collection'::"text", 'collected'::"text", 'short_collected'::"text", 'failed_delivery'::"text"]))),
    CONSTRAINT "orders_promo_funded_by_check" CHECK ((("promo_funded_by" IS NULL) OR ("promo_funded_by" = ANY (ARRAY['merchant'::"text", 'platform'::"text", 'shared'::"text"])))),
    CONSTRAINT "orders_status_check" CHECK (("status" = ANY (ARRAY['placed'::"text", 'accepted'::"text", 'preparing'::"text", 'ready'::"text", 'assigned'::"text", 'picked_up'::"text", 'in_transit'::"text", 'delivered'::"text", 'completed'::"text", 'cancelled'::"text", 'paid'::"text"])))
);

ALTER TABLE ONLY "delivery"."orders" REPLICA IDENTITY FULL;


ALTER TABLE "delivery"."orders" OWNER TO "postgres";


COMMENT ON COLUMN "delivery"."orders"."tax_food_jmd" IS 'GCT on merchant food supply (Model B)';



COMMENT ON COLUMN "delivery"."orders"."tax_platform_jmd" IS 'GCT on platform service + delivery platform share';



COMMENT ON COLUMN "delivery"."orders"."courier_tip_net" IS 'Tip after card processing fee deduction';



COMMENT ON COLUMN "delivery"."orders"."platform_delivery_subsidy_jmd" IS 'Platform cost when courier pay exceeds customer delivery fee.';



COMMENT ON COLUMN "delivery"."orders"."small_order_fee" IS 'Customer small-order fee when subtotal below threshold.';



COMMENT ON COLUMN "delivery"."orders"."contribution_jmd" IS 'True platform contribution: commission + service + delivery_platform + small_order - peak (excludes GCT/WiPay)';



COMMENT ON COLUMN "delivery"."orders"."promo_funded_by" IS 'Who funds food discount: merchant | platform | shared';



COMMENT ON COLUMN "delivery"."orders"."free_delivery_applied" IS 'True when customer delivery fee was waived (Pass or promo). Denormalized from pricing_snapshot for subsidy RPCs.';



COMMENT ON COLUMN "delivery"."orders"."delivery_pin" IS '4-digit customer handoff PIN when courier.delivery.pin_required_over_jmd applies';



COMMENT ON COLUMN "delivery"."orders"."delivery_pin_verified_at" IS 'Set when courier successfully verifies delivery_pin at drop-off';



COMMENT ON COLUMN "delivery"."orders"."wait_pay_jmd" IS 'Sum of billable restaurant wait pay (J$) credited to courier earnings';



