CREATE OR REPLACE VIEW "delivery"."v_expired_active_exclusions" AS
 SELECT "service_zone_polygons"."id",
    "service_zone_polygons"."name",
    "service_zone_polygons"."effective_to",
    'market'::"text" AS "scope"
   FROM "delivery"."service_zone_polygons"
  WHERE (("service_zone_polygons"."kind" = 'exclude'::"text") AND "service_zone_polygons"."is_active" AND ("service_zone_polygons"."effective_to" IS NOT NULL) AND ("service_zone_polygons"."effective_to" < "now"()))
UNION ALL
 SELECT "scoped_exclusion_zones"."id",
    "scoped_exclusion_zones"."name",
    "scoped_exclusion_zones"."effective_to",
    "scoped_exclusion_zones"."scope"
   FROM "delivery"."scoped_exclusion_zones"
  WHERE ("scoped_exclusion_zones"."is_active" AND ("scoped_exclusion_zones"."effective_to" IS NOT NULL) AND ("scoped_exclusion_zones"."effective_to" < "now"()));


ALTER VIEW "delivery"."v_expired_active_exclusions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_card_unmatched_7d" AS
 SELECT 'statement'::"text" AS "side",
    ("s"."id")::"text" AS "ref"
   FROM "delivery"."in_house_card_statement_lines" "s"
  WHERE (("s"."task_id" IS NULL) AND ("s"."imported_at" < ("now"() - '7 days'::interval)))
UNION ALL
 SELECT 'task'::"text" AS "side",
    ("t"."id")::"text" AS "ref"
   FROM "delivery"."procurement_tasks" "t"
  WHERE (("t"."state" = ANY (ARRAY['placed_external'::"text", 'ready_for_pickup'::"text", 'picked_up'::"text", 'closed'::"text"])) AND ("t"."placed_at" < ("now"() - '7 days'::interval)) AND (NOT (EXISTS ( SELECT 1
           FROM "delivery"."in_house_card_statement_lines" "s"
          WHERE ("s"."task_id" = "t"."id")))));


ALTER VIEW "delivery"."v_in_house_card_unmatched_7d" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "rush_money"."accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kind" "text" NOT NULL,
    "party_type" "text" NOT NULL,
    "party_id" "uuid",
    "component" "text" DEFAULT ''::"text" NOT NULL,
    "balance_minor" bigint DEFAULT 0 NOT NULL,
    "currency" "text" DEFAULT 'JMD'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounts_kind_check" CHECK (("kind" = ANY (ARRAY['gateway_clearing'::"text", 'order_clearing'::"text", 'merchant_payable'::"text", 'merchant_receivable'::"text", 'courier_earnings'::"text", 'courier_cash_earned'::"text", 'customer_wallet'::"text", 'platform_revenue'::"text", 'platform_cost'::"text", 'marketing_goodwill'::"text", 'gct_output_payable'::"text", 'refunds_in_flight'::"text", 'chargeback_reserve'::"text", 'payouts_in_flight'::"text", 'bank'::"text", 'cod_clearing'::"text", 'vendor_prepaid'::"text", 'procurement_card_payable'::"text"]))),
    CONSTRAINT "accounts_party_type_check" CHECK (("party_type" = ANY (ARRAY['customer'::"text", 'courier'::"text", 'merchant'::"text", 'order'::"text", 'platform'::"text"])))
);


ALTER TABLE "rush_money"."accounts" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "rush_money"."lines" (
    "journal_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
