    "payout_batch_id" "uuid",
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    CONSTRAINT "lines_amount_minor_check" CHECK (("amount_minor" <> 0))
);


ALTER TABLE "rush_money"."lines" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_merchant_payable" AS
 SELECT "l"."journal_id",
    "a"."party_id" AS "merchant_id",
    "l"."amount_minor"
   FROM (("rush_money"."lines" "l"
     JOIN "rush_money"."accounts" "a" ON (("a"."id" = "l"."account_id")))
     JOIN "delivery"."merchants" "m" ON (("m"."id" = "a"."party_id")))
  WHERE (("a"."kind" = 'merchant_payable'::"text") AND ("m"."procurement_mode" = 'in_house'::"text"));


ALTER VIEW "delivery"."v_in_house_merchant_payable" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_paid_without_task" AS
 SELECT "o"."id" AS "order_id",
    "o"."created_at"
   FROM ("delivery"."orders" "o"
     JOIN "delivery"."merchants" "m" ON (("m"."id" = "o"."merchant_id")))
  WHERE (("m"."procurement_mode" = 'in_house'::"text") AND ("o"."money_state" = 'captured'::"text") AND ("o"."created_at" < ("now"() - '00:02:00'::interval)) AND (NOT (EXISTS ( SELECT 1
           FROM "delivery"."procurement_tasks" "t"
          WHERE ("t"."order_id" = "o"."id")))));


ALTER VIEW "delivery"."v_in_house_paid_without_task" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_placed_without_purchase_journal" AS
 SELECT "id" AS "task_id",
    "order_id"
   FROM "delivery"."procurement_tasks" "t"
  WHERE (("state" = ANY (ARRAY['placed_external'::"text", 'ready_for_pickup'::"text", 'picked_up'::"text", 'closed'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "rush_money"."journals" "j"
          WHERE ("j"."idempotency_key" = ('procure:'::"text" || ("t"."id")::"text"))))));


ALTER VIEW "delivery"."v_in_house_placed_without_purchase_journal" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_variance_outliers" AS
 SELECT "t"."id" AS "task_id",
    "t"."order_id",
    "t"."variance_minor"
   FROM ("delivery"."procurement_tasks" "t"
     JOIN "delivery"."in_house_stores" "s" ON (("s"."merchant_id" = "t"."merchant_id")))
  WHERE (("t"."actual_total_minor" IS NOT NULL) AND ("t"."expected_cost_minor" > 0) AND ("t"."variance_minor" > LEAST((("t"."expected_cost_minor" * "s"."price_tolerance_bps") / 10000), "s"."absorb_cap_minor")) AND ("t"."customer_price_approved_at" IS NULL));


ALTER VIEW "delivery"."v_in_house_variance_outliers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_in_house_vendor_prepaid_open" AS
 SELECT "a"."party_id" AS "order_id",
    "a"."balance_minor"
   FROM ("rush_money"."accounts" "a"
     JOIN "delivery"."orders" "o" ON (("o"."id" = "a"."party_id")))
  WHERE (("a"."kind" = 'vendor_prepaid'::"text") AND ("a"."balance_minor" <> 0) AND ("o"."status" = ANY (ARRAY['delivered'::"text", 'completed'::"text", 'cancelled'::"text"])));


ALTER VIEW "delivery"."v_in_house_vendor_prepaid_open" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_remittance_drift" AS
 SELECT "a"."courier_id",
    "a"."balance_minor" AS "account_balance_minor",
    COALESCE("sum"("e"."amount_minor"), (0)::numeric) AS "event_sum_minor",
    (("a"."balance_minor")::numeric - COALESCE("sum"("e"."amount_minor"), (0)::numeric)) AS "drift_minor"
   FROM ("delivery"."courier_remittance_accounts" "a"
     LEFT JOIN "delivery"."courier_remittance_events" "e" USING ("courier_id"))
  GROUP BY "a"."courier_id", "a"."balance_minor"
 HAVING (("a"."balance_minor")::numeric <> COALESCE("sum"("e"."amount_minor"), (0)::numeric));


ALTER VIEW "delivery"."v_remittance_drift" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_remittance_legacy_drift" AS
 SELECT COALESCE("a"."courier_id", "b"."courier_id") AS "courier_id",
    COALESCE("b"."balance_jmd", (0)::numeric) AS "legacy_balance_jmd",
    ((COALESCE("a"."balance_minor", (0)::bigint))::numeric / 100.0) AS "remittance_balance_jmd",
    "round"((COALESCE("b"."balance_jmd", (0)::numeric) - ((COALESCE("a"."balance_minor", (0)::bigint))::numeric / 100.0)), 2) AS "drift_jmd"
   FROM ("delivery"."courier_remittance_accounts" "a"
     FULL JOIN "delivery"."courier_cash_balances" "b" ON (("a"."courier_id" = "b"."courier_id")))
  WHERE ("round"((COALESCE("b"."balance_jmd", (0)::numeric) - ((COALESCE("a"."balance_minor", (0)::bigint))::numeric / 100.0)), 2) <> (0)::numeric);


ALTER VIEW "delivery"."v_remittance_legacy_drift" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_remittance_missing_collections" AS
 SELECT "id" AS "order_id",
    "courier_id",
    "total",
    "delivered_at"
   FROM "delivery"."orders" "o"
  WHERE (("payment_method" = 'cash'::"text") AND ("status" = ANY (ARRAY['delivered'::"text", 'completed'::"text"])) AND ("courier_id" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "delivery"."courier_remittance_events" "e"
          WHERE (("e"."order_id" = "o"."id") AND ("e"."event_type" = 'collected'::"text"))))) AND (NOT (EXISTS ( SELECT 1
           FROM "delivery"."courier_remittance_exceptions" "x"
          WHERE (("x"."order_id" = "o"."id") AND ("x"."resolved_at" IS NULL))))));


ALTER VIEW "delivery"."v_remittance_missing_collections" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_remittance_stale_pending" AS
 SELECT "id",
    "reference",
    "courier_id",
    "amount_minor",
    "method",
    "created_at"
   FROM "delivery"."courier_remittance_settlements"
  WHERE (("status" = 'pending'::"text") AND ("created_at" < ("now"() - '00:15:00'::interval)));


ALTER VIEW "delivery"."v_remittance_stale_pending" OWNER TO "postgres";


COMMENT ON VIEW "delivery"."v_remittance_stale_pending" IS 'N-2: pending settlements older than 15m — operator believed settle posted but event never landed.';



CREATE OR REPLACE VIEW "delivery"."v_remittance_trial_balance_breaks" AS
 SELECT "id",
    "order_id",
    "bag_total_minor",
    (("platform_due_minor" + "merchant_due_minor") + "courier_retained_minor") AS "split_sum_minor"
   FROM "delivery"."courier_remittance_events"
  WHERE (("event_type" = 'collected'::"text") AND ("bag_total_minor" IS NOT NULL) AND ("bag_total_minor" <> (("platform_due_minor" + "merchant_due_minor") + "courier_retained_minor")));


ALTER VIEW "delivery"."v_remittance_trial_balance_breaks" OWNER TO "postgres";


