CREATE TABLE IF NOT EXISTS "payments"."transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "intent_id" "uuid",
    "order_id" "uuid",
    "customer_id" "uuid",
    "amount" numeric NOT NULL,
    "fee" numeric DEFAULT 0,
    "net_amount" numeric NOT NULL,
    "currency" "text" DEFAULT 'JMD'::"text",
    "status" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "provider_transaction_id" "text",
    "provider_data" "jsonb" DEFAULT '{}'::"jsonb",
    "payment_method" "text",
    "failure_reason" "text",
    "refund_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "transactions_amounts_nonneg_check" CHECK (((COALESCE("amount", (0)::numeric) >= (0)::numeric) AND (COALESCE("fee", (0)::numeric) >= (0)::numeric) AND (COALESCE("net_amount", (0)::numeric) >= (0)::numeric)))
);


ALTER TABLE "payments"."transactions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_rush_cancelled_paid_unrefunded" AS
 SELECT "id",
    "order_number",
    "payment_status",
    "status"
   FROM "delivery"."orders" "o"
  WHERE (("status" = 'cancelled'::"text") AND ("payment_status" = 'paid'::"text") AND (COALESCE(( SELECT "sum"("r"."amount") AS "sum"
           FROM "payments"."refunds" "r"
          WHERE (("r"."order_id" = "o"."id") AND ("r"."status" = ANY (ARRAY['completed'::"text", 'succeeded'::"text"])))), (0)::numeric) < COALESCE(( SELECT "sum"("t"."amount") AS "sum"
           FROM "payments"."transactions" "t"
          WHERE (("t"."order_id" = "o"."id") AND ("t"."status" = 'completed'::"text"))), (0)::numeric)));


ALTER VIEW "delivery"."v_rush_cancelled_paid_unrefunded" OWNER TO "postgres";


CREATE OR REPLACE VIEW "delivery"."v_rush_multi_capture_orders" AS
 SELECT "order_id",
    "count"(*) AS "captures"
   FROM "payments"."transactions"
  WHERE (("status" = 'completed'::"text") AND ("order_id" IS NOT NULL))
  GROUP BY "order_id"
 HAVING ("count"(*) > 1);


