);


ALTER TABLE "fleet"."toll_ledger" OWNER TO "postgres";


COMMENT ON COLUMN "fleet"."toll_ledger"."service_line_source" IS 'How service_line was resolved: program|explicit|trip|vehicle|driver|unattributed|org (tag top-ups)|org_default (single-line fleet fallback). explicit is sticky.';



COMMENT ON COLUMN "fleet"."toll_ledger"."service_line_set_at" IS 'Set only when service_line_source = explicit.';



COMMENT ON COLUMN "fleet"."toll_ledger"."service_line_set_by" IS 'Actor uuid when service_line_source = explicit.';



COMMENT ON COLUMN "fleet"."toll_ledger"."provider_ref" IS 'Provider transaction id (Txn ID). Dedupe key is (org, ref, date) excluding voided; do not rely on client fingerprint alone.';



CREATE OR REPLACE VIEW "fleet"."ledger_entries" AS
 SELECT "t"."id" AS "entry_id",
    "t"."organization_id",
    'trip'::"text" AS "entry_type",
    COALESCE("t"."platform", 'unknown'::"text") AS "source_system",
    "t"."id" AS "source_id",
    (("t"."date")::timestamp without time zone AT TIME ZONE 'UTC'::"text") AS "occurred_at",
    "t"."created_at" AS "posted_at",
    "to_char"("date_trunc"('week'::"text", ("t"."date")::timestamp without time zone), 'IYYY-"W"IW'::"text") AS "period_key",
    "t"."driver_id",
    "t"."vehicle_id",
    "t"."batch_id",
    'inflow'::"text" AS "direction",
    "t"."amount" AS "amount_gross",
    COALESCE("t"."net_to_driver", (NULLIF(("t"."payload_json" ->> 'indriveNetIncome'::"text"), ''::"text"))::numeric) AS "amount_net",
    (COALESCE(NULLIF(("t"."payload_json" ->> 'currency'::"text"), ''::"text"), 'USD'::"text"))::character(3) AS "currency",
    "t"."status",
    "jsonb_build_object"('lines_match', ("t"."payload_json" -> 'paymentLineRollupMatch'::"text"), 'cash_collected', ("t"."payload_json" -> 'cashCollected'::"text")) AS "integrity_flags",
    "t"."payload_json"
   FROM "fleet"."trips" "t"
UNION ALL
 SELECT "f"."id" AS "entry_id",
    "f"."organization_id",
    'fuel'::"text" AS "entry_type",
    COALESCE("f"."payment_source", 'fuel'::"text") AS "source_system",
    "f"."id" AS "source_id",
    (("f"."date")::timestamp without time zone AT TIME ZONE 'UTC'::"text") AS "occurred_at",
    "f"."created_at" AS "posted_at",
    "to_char"("date_trunc"('week'::"text", ("f"."date")::timestamp without time zone), 'IYYY-"W"IW'::"text") AS "period_key",
    "f"."driver_id",
    "f"."vehicle_id",
    NULL::"text" AS "batch_id",
    'outflow'::"text" AS "direction",
    "f"."amount" AS "amount_gross",
    "f"."amount" AS "amount_net",
    (COALESCE(NULLIF(("f"."payload_json" ->> 'currency'::"text"), ''::"text"), 'USD'::"text"))::character(3) AS "currency",
    "f"."type" AS "status",
    '{}'::"jsonb" AS "integrity_flags",
    "f"."payload_json"
   FROM "fleet"."fuel_entries" "f"
UNION ALL
 SELECT "l"."id" AS "entry_id",
    "l"."organization_id",
    'toll'::"text" AS "entry_type",
    COALESCE("l"."payment_method", 'toll'::"text") AS "source_system",
    "l"."id" AS "source_id",
    (("l"."date")::timestamp without time zone AT TIME ZONE 'UTC'::"text") AS "occurred_at",
    "l"."created_at" AS "posted_at",
    "to_char"("date_trunc"('week'::"text", ("l"."date")::timestamp without time zone), 'IYYY-"W"IW'::"text") AS "period_key",
    "l"."driver_id",
    "l"."vehicle_id",
    "l"."batch_id",
    'outflow'::"text" AS "direction",
    "abs"(COALESCE("l"."amount", (0)::numeric)) AS "amount_gross",
    "abs"(COALESCE("l"."amount", (0)::numeric)) AS "amount_net",
    (COALESCE(NULLIF(("l"."payload_json" ->> 'currency'::"text"), ''::"text"), 'USD'::"text"))::character(3) AS "currency",
    "l"."status",
    "jsonb_build_object"('is_reconciled', "l"."is_reconciled", 'resolution', "l"."resolution", 'trip_id', "l"."trip_id") AS "integrity_flags",
    "l"."payload_json"
   FROM "fleet"."toll_ledger" "l";


ALTER VIEW "fleet"."ledger_entries" OWNER TO "postgres";


