CREATE OR REPLACE VIEW "fleet"."v_toll_plaza_stats" WITH ("security_invoker"='on') AS
 SELECT "organization_id",
    "plaza_id",
    "count"(*) AS "total_transactions",
    COALESCE("sum"("abs"("amount")), (0)::numeric) AS "total_spend",
    COALESCE("avg"("abs"("amount")), (0)::numeric) AS "avg_amount",
    "max"("date") AS "last_transaction_date",
    "max"("updated_at") AS "last_updated"
   FROM "fleet"."toll_ledger" "l"
  WHERE (("plaza_id" IS NOT NULL) AND (COALESCE("type", 'usage'::"text") = 'usage'::"text") AND (COALESCE("status", ''::"text") <> 'voided'::"text") AND (COALESCE((("metadata" ->> 'voided'::"text"))::boolean, false) = false))
  GROUP BY "organization_id", "plaza_id";


ALTER VIEW "fleet"."v_toll_plaza_stats" OWNER TO "postgres";


COMMENT ON VIEW "fleet"."v_toll_plaza_stats" IS 'Toll passage counts and spend per plaza. Excludes top-ups and voided rows. Source of truth for TollPlaza.stats.';



