    CONSTRAINT "driver_profiles_fleet_role_check" CHECK (("fleet_role" = ANY (ARRAY['driver'::"text", 'lead_driver'::"text", 'trainer'::"text"]))),
    CONSTRAINT "driver_profiles_gender_check" CHECK ((("gender" IS NULL) OR ("gender" = ANY (ARRAY['male'::"text", 'female'::"text", 'other'::"text"])))),
    CONSTRAINT "driver_profiles_mode_check" CHECK (("mode" = ANY (ARRAY['fleet'::"text", 'independent'::"text"]))),
