COMMENT ON COLUMN "public"."driver_profiles"."dispatch_pilot" IS 'Staged rollout: allows this driver into Roam passenger dispatch even while independent_only_matching is on. Set by platform admins only.';



COMMENT ON COLUMN "public"."driver_profiles"."manual_start_trip_enabled" IS 'When FALSE, hide Start Trip. Temporary until passenger app is widely available. Layer B only — never writes rides.ride_requests.';



CREATE OR REPLACE VIEW "fleet"."workforce_membership_drift" AS
 SELECT 'rideshare_profile_without_membership'::"text" AS "kind",
    "dp"."user_id",
    ("dp"."fleet_id")::"text" AS "profile_fleet_id",
    NULL::"text" AS "membership_fleet_id"
   FROM "public"."driver_profiles" "dp"
  WHERE (("dp"."mode" = 'fleet'::"text") AND ("dp"."fleet_id" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "fleet"."workforce_memberships" "m"
          WHERE (("m"."user_id" = "dp"."user_id") AND ("m"."service_line" = 'rideshare'::"text") AND ("m"."status" <> 'ended'::"text") AND (("m"."organization_id")::"text" = ("dp"."fleet_id")::"text"))))))
UNION ALL
 SELECT 'rush_profile_without_membership'::"text" AS "kind",
    "cp"."user_id",
    ("cp"."fleet_id")::"text" AS "profile_fleet_id",
    NULL::"text" AS "membership_fleet_id"
   FROM "delivery"."courier_profiles" "cp"
  WHERE (("cp"."mode" = 'fleet'::"text") AND ("cp"."fleet_id" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "fleet"."workforce_memberships" "m"
          WHERE (("m"."user_id" = "cp"."user_id") AND ("m"."service_line" = 'rush_delivery'::"text") AND ("m"."status" <> 'ended'::"text") AND (("m"."organization_id")::"text" = ("cp"."fleet_id")::"text"))))));


ALTER VIEW "fleet"."workforce_membership_drift" OWNER TO "postgres";


