    "organization_id" "uuid" NOT NULL,
    "suite_id" "uuid",
    "client_id" "uuid",
    "courier_tracking_number" "text",
    "description" "text",
    "status" "text" DEFAULT 'expected'::"text" NOT NULL,
    "weight_lbs" numeric(12,3),
    "length_in" numeric(12,2),
    "width_in" numeric(12,2),
    "height_in" numeric(12,2),
    "declared_value_usd_minor" bigint,
    "invoice_storage_path" "text",
    "invoice_file_name" "text",
    "current_facility_id" "uuid",
    "sort_zone" "text",
    "fulfillment_mode" "text",
    "preferred_assignee_type" "text",
    "pickup_facility_id" "uuid",
    "delivery_address" "text",
    "delivery_lat" double precision,
    "delivery_lng" double precision,
    "manifest_id" "uuid",
    "notes" "text",
    "last_notified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hs_tariff_code_id" "uuid",
    "item_category" "text",
    "freight_fee_usd_minor" bigint,
    "insurance_usd_minor" bigint,
    "bin_location" "text",
    "invoice_verified_at" timestamp with time zone,
    "invoice_verified_by" "uuid",
    "weight_kg" numeric(12,3),
    "warehouse_invoice_storage_path" "text",
    "warehouse_invoice_file_name" "text",
    "invoice_required_from_customer" boolean DEFAULT false NOT NULL,
    "invoice_unobtainable_at" timestamp with time zone,
    "invoice_unobtainable_by" "uuid",
    "invoice_unobtainable_note" "text",
    "intended_facility_id" "uuid",
    "retailer" "text",
    "owner_org_id" "uuid" NOT NULL,
    "operating_warehouse_org_id" "uuid",
    "retail_order_id" "uuid",
    CONSTRAINT "packages_fulfillment_mode_check" CHECK ((("fulfillment_mode" IS NULL) OR ("fulfillment_mode" = ANY (ARRAY['pickup'::"text", 'door_delivery'::"text"])))),
    CONSTRAINT "packages_preferred_assignee_type_check" CHECK ((("preferred_assignee_type" IS NULL) OR ("preferred_assignee_type" = ANY (ARRAY['roam_marketplace'::"text", 'org_fleet'::"text", 'client_fleet'::"text", 'third_party'::"text"])))),
    CONSTRAINT "packages_status_check" CHECK (("status" = ANY (ARRAY['expected'::"text", 'received_at_warehouse'::"text", 'handed_off'::"text", 'manifested'::"text", 'in_transit_intl'::"text", 'customs_hold'::"text", 'customs_cleared'::"text", 'received_hub'::"text", 'ready_for_fulfillment'::"text", 'out_for_delivery'::"text", 'awaiting_pickup'::"text", 'delivered'::"text", 'collected'::"text", 'exception'::"text"])))
);


ALTER TABLE "freight"."packages" OWNER TO "postgres";


COMMENT ON COLUMN "freight"."packages"."invoice_storage_path" IS 'Customer/commercial invoice (seal gate)';



COMMENT ON COLUMN "freight"."packages"."warehouse_invoice_storage_path" IS 'Optional packing slip from US warehouse intake';



COMMENT ON COLUMN "freight"."packages"."invoice_required_from_customer" IS 'Warehouse flagged: courier must request invoice from customer';



COMMENT ON COLUMN "freight"."packages"."invoice_unobtainable_at" IS 'Courier marked could not obtain customer invoice (allows seal override)';



COMMENT ON COLUMN "freight"."packages"."intended_facility_id" IS 'Roam warehouse facility this pre-alert is assigned to; null = external / CSV handoff';



COMMENT ON COLUMN "freight"."packages"."retailer" IS 'Retailer / marketplace label (Amazon, Shein, etc.) for warehouse matching';



CREATE TABLE IF NOT EXISTS "freight"."rate_cards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_id" "uuid",
    "name" "text" NOT NULL,
    "origin_label" "text",
    "destination_label" "text",
    "currency" "text" DEFAULT 'JMD'::"text" NOT NULL,
    "amount_minor" bigint DEFAULT 0 NOT NULL,
    "effective_from" "date",
    "effective_to" "date",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pricing_strategy" "text" DEFAULT 'flat'::"text" NOT NULL,
    "rules" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "rate_cards_amount_minor_check" CHECK (("amount_minor" >= 0)),
    CONSTRAINT "rate_cards_pricing_strategy_check" CHECK (("pricing_strategy" = ANY (ARRAY['flat'::"text", 'distance_tier'::"text", 'zone'::"text", 'per_stop'::"text"]))),
    CONSTRAINT "rate_cards_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"])))
);


ALTER TABLE "freight"."rate_cards" OWNER TO "postgres";


COMMENT ON COLUMN "freight"."rate_cards"."pricing_strategy" IS 'flat | distance_tier | zone | per_stop — amount_minor is flat amount / fallback.';



COMMENT ON COLUMN "freight"."rate_cards"."rules" IS 'Strategy payload: distance tiers, zone amounts, or per-stop base+perStop.';



