CREATE TABLE IF NOT EXISTS "fuel"."brain_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" DEFAULT 'default'::"text" NOT NULL,
    "deadhead_gap_max_minutes" integer DEFAULT 30 NOT NULL,
    "personal_gap_min_minutes" integer DEFAULT 120 NOT NULL,
    "peak_hours_start" integer DEFAULT 6 NOT NULL,
    "peak_hours_end" integer DEFAULT 22 NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "industry_fallback_pct" numeric DEFAULT 35 NOT NULL,
    "cross_validation_pp" numeric DEFAULT 20 NOT NULL,
    "prefer_odo_gaps" boolean DEFAULT true NOT NULL,
    "ambiguous_deadhead_split_pct" numeric DEFAULT 60 NOT NULL,
    CONSTRAINT "brain_policies_ambiguous_deadhead_split_pct_check" CHECK ((("ambiguous_deadhead_split_pct" >= (0)::numeric) AND ("ambiguous_deadhead_split_pct" <= (100)::numeric))),
    CONSTRAINT "brain_policies_cross_validation_pp_check" CHECK ((("cross_validation_pp" >= (0)::numeric) AND ("cross_validation_pp" <= (100)::numeric))),
    CONSTRAINT "brain_policies_deadhead_gap_max_minutes_check" CHECK ((("deadhead_gap_max_minutes" >= 1) AND ("deadhead_gap_max_minutes" <= 240))),
    CONSTRAINT "brain_policies_industry_fallback_pct_check" CHECK ((("industry_fallback_pct" >= (0)::numeric) AND ("industry_fallback_pct" <= (80)::numeric))),
    CONSTRAINT "brain_policies_peak_hours_end_check" CHECK ((("peak_hours_end" >= 0) AND ("peak_hours_end" <= 23))),
    CONSTRAINT "brain_policies_peak_hours_start_check" CHECK ((("peak_hours_start" >= 0) AND ("peak_hours_start" <= 23))),
    CONSTRAINT "brain_policies_personal_gap_min_minutes_check" CHECK ((("personal_gap_min_minutes" >= 30) AND ("personal_gap_min_minutes" <= 1440)))
);


ALTER TABLE "fuel"."brain_policies" OWNER TO "postgres";


