CREATE OR REPLACE VIEW "geo"."quality_issues" AS
 SELECT "b"."pcode",
    "b"."name",
    "b"."admin_level",
    'invalid_shape'::"text" AS "issue"
   FROM ("geo"."boundaries" "b"
     JOIN "geo"."boundary_versions" "v" ON (("v"."id" = "b"."current_version_id")))
  WHERE (NOT "public"."st_isvalid"("v"."geom"))
UNION ALL
 SELECT "b"."pcode",
    "b"."name",
    "b"."admin_level",
    'missing_parent'::"text" AS "issue"
   FROM "geo"."boundaries" "b"
  WHERE (("b"."admin_level" > 0) AND (("b"."parent_pcode" IS NULL) OR (NOT (EXISTS ( SELECT 1
           FROM "geo"."boundaries" "p"
          WHERE ("p"."pcode" = "b"."parent_pcode"))))))
UNION ALL
 SELECT "b"."pcode",
    "b"."name",
    "b"."admin_level",
    'too_many_vertices'::"text" AS "issue"
   FROM ("geo"."boundaries" "b"
     JOIN "geo"."boundary_versions" "v" ON (("v"."id" = "b"."current_version_id")))
  WHERE (("b"."admin_level" > 0) AND ("public"."st_npoints"("v"."geom") > 8000));


