CREATE TABLE IF NOT EXISTS "ledger"."driver_financial_periods" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "driver_id" "text" NOT NULL,
    "period_anchor" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "timezone" "text" DEFAULT 'America/Jamaica'::"text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "toll_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "toll_cash_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "toll_tag_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "toll_reimbursed" numeric(14,2) DEFAULT 0 NOT NULL,
    "toll_charged_to_driver" numeric(14,2) DEFAULT 0 NOT NULL,
    "toll_unmatched_count" integer DEFAULT 0 NOT NULL,
    "toll_reconciled_count" integer DEFAULT 0 NOT NULL,
    "toll_workflow_actionable" integer DEFAULT 0 NOT NULL,
    "dispute_refund_matched" numeric(14,2) DEFAULT 0 NOT NULL,
    "dispute_refund_unmatched" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_driver_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_gas_card_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_deduction" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_fleet_share" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_net_pay" numeric(14,2) DEFAULT 0 NOT NULL,
    "fuel_finalized" boolean DEFAULT false NOT NULL,
    "earnings_gross" numeric(14,2) DEFAULT 0 NOT NULL,
    "cash_collected" numeric(14,2) DEFAULT 0 NOT NULL,
    "cash_returned" numeric(14,2) DEFAULT 0 NOT NULL,
    "cash_still_held" numeric(14,2) DEFAULT 0 NOT NULL,
    "settlement_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "payout_net" numeric(14,2) DEFAULT 0 NOT NULL,
    "settlement_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "payout_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "toll_status" "text" DEFAULT 'n/a'::"text" NOT NULL,
    "source_event_hash" "text" DEFAULT ''::"text",
    "projection_version" integer DEFAULT 1 NOT NULL,
    "projected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "reopened_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "driver_share" numeric(14,2) DEFAULT 0 NOT NULL,
    "fleet_share" numeric(14,2) DEFAULT 0 NOT NULL,
    "driver_share_percent" numeric(8,4) DEFAULT 0 NOT NULL,
    "trip_count" integer DEFAULT 0 NOT NULL,
    "tier_id" "text",
    "tier_name" "text",
    "cash_written_off" numeric(14,2) DEFAULT 0 NOT NULL,
    "settlement_paid" numeric(14,2) DEFAULT 0 NOT NULL,
    "tips_paid_to_driver" numeric(14,2) DEFAULT 0 NOT NULL,
    "tips_withheld" numeric(14,2) DEFAULT 0 NOT NULL,
    "settlement_amount_minor" bigint,
    "payout_net_minor" bigint,
    "cash_still_held_minor" bigint,
    "fuel_status" "text" DEFAULT 'n/a'::"text" NOT NULL,
    "row_version" integer DEFAULT 1 NOT NULL,
    "reconciliation_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "close_hash" "text",
    CONSTRAINT "driver_financial_periods_cash_nonneg_check" CHECK (((COALESCE("cash_collected", (0)::numeric) >= (0)::numeric) AND (COALESCE("cash_returned", (0)::numeric) >= (0)::numeric) AND (COALESCE("cash_still_held", (0)::numeric) >= (0)::numeric) AND (COALESCE("toll_cash_spend", (0)::numeric) >= (0)::numeric) AND (COALESCE("cash_written_off", (0)::numeric) >= (0)::numeric) AND (COALESCE("tips_paid_to_driver", (0)::numeric) >= (0)::numeric) AND (COALESCE("tips_withheld", (0)::numeric) >= (0)::numeric))),
    CONSTRAINT "driver_financial_periods_fuel_status_check" CHECK (("fuel_status" = ANY (ARRAY['n/a'::"text", 'pending'::"text", 'in_progress'::"text", 'finalized'::"text"]))),
    CONSTRAINT "driver_financial_periods_payout_status_check" CHECK (("payout_status" = ANY (ARRAY['pending'::"text", 'awaiting_cash'::"text", 'awaiting_tolls'::"text", 'finalized'::"text"]))),
    CONSTRAINT "driver_financial_periods_reconciliation_status_check" CHECK (("reconciliation_status" = ANY (ARRAY['open'::"text", 'cleared'::"text", 'reopened'::"text"]))),
    CONSTRAINT "driver_financial_periods_settlement_status_check" CHECK (("settlement_status" = ANY (ARRAY['pending'::"text", 'settled'::"text", 'company_owes'::"text", 'driver_owes'::"text", 'overpaid'::"text", 'processing'::"text", 'failed'::"text", 'on_hold'::"text"]))),
    CONSTRAINT "driver_financial_periods_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text", 'reopened'::"text"]))),
    CONSTRAINT "driver_financial_periods_toll_status_check" CHECK (("toll_status" = ANY (ARRAY['n/a'::"text", 'reconciled'::"text", 'unmatched'::"text", 'in_progress'::"text"])))
);


ALTER TABLE "ledger"."driver_financial_periods" OWNER TO "postgres";


COMMENT ON COLUMN "ledger"."driver_financial_periods"."driver_share" IS 'Commission Driver Share for the week (gross × tier %). Settlement/Payout SSOT.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."fleet_share" IS 'Fleet residual of gross after driver share.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."cash_written_off" IS 'Sum of Cash_Write_Off txs tagged to this Settlement Week. Reduces cash_still_held; never cash_returned.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."settlement_paid" IS 'Sum of cleared Driver Payout (Payout / Driver Payouts) txs tagged to this Settlement Week. Reduces settlement_amount when company owes; never cash_returned.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."tips_paid_to_driver" IS 'Tips paid to driver this week (quota met or quota off). Adds to payout_net.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."tips_withheld" IS 'Tips withheld when quota missed — belongs to fleet share.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."settlement_amount_minor" IS 'A-3 dual-write: round(settlement_amount * 100). Display still uses NUMERIC until cutover.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."fuel_status" IS 'n/a | pending | in_progress | finalized — SoT is fuel_reconciliation_period lock, not money-posted events';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."row_version" IS 'Settlement command optimistic lock (independent of projection_version).';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."reconciliation_status" IS 'Toll/fuel reconciliation gate (open|cleared|reopened). Distinct from calendar status/closed_at.';



COMMENT ON COLUMN "ledger"."driver_financial_periods"."close_hash" IS 'Authoritative week-close seal (H-4). Distinct from source_event_hash (projection). Written only by freeze_settlement_periods_batch / reopen.';



