    CONSTRAINT "policies_toll_geofence_radius_m_check" CHECK ((("toll_geofence_radius_m" >= 50) AND ("toll_geofence_radius_m" <= 500))),
    CONSTRAINT "policies_toll_round_trip_cooldown_ms_check" CHECK ((("toll_round_trip_cooldown_ms" >= 0) AND ("toll_round_trip_cooldown_ms" <= 3600000))),
    CONSTRAINT "policies_trip_location_interval_seconds_check" CHECK ((("trip_location_interval_seconds" >= 2) AND ("trip_location_interval_seconds" <= 30))),
    CONSTRAINT "policies_wait_time_grace_minutes_check" CHECK ((("wait_time_grace_minutes" >= 0) AND ("wait_time_grace_minutes" <= 10))),
    CONSTRAINT "policies_wait_time_max_minutes_check" CHECK ((("wait_time_max_minutes" >= 1) AND ("wait_time_max_minutes" <= 60)))
);


ALTER TABLE "matching"."policies" OWNER TO "postgres";


COMMENT ON TABLE "matching"."policies" IS 'Global matching policies. Multiple policies can exist for A/B testing or per-product overrides.';



COMMENT ON COLUMN "matching"."policies"."serial_dispatch_enabled" IS 'When true, offer one driver at a time (serial) instead of parallel broadcast.';



COMMENT ON COLUMN "matching"."policies"."h3_resolution" IS 'H3 hexagon resolution for spatial indexing. 7 = ~1.2km edge, 8 = ~460m edge.';



COMMENT ON COLUMN "matching"."policies"."wave_h3_k_rings" IS 'Array of k-ring values per wave for H3 lookups. Calibrate per market.';



