CREATE OR REPLACE VIEW "platform"."identity_personas" WITH ("security_invoker"='true') AS
 SELECT "c"."user_id",
    'customer'::"text" AS "persona",
    "c"."id" AS "ref_id",
    COALESCE("c"."account_status", 'active'::"text") AS "status",
    NULL::"uuid" AS "market_id"
   FROM "delivery"."customers" "c"
UNION ALL
 SELECT "cp"."user_id",
    'courier'::"text" AS "persona",
    "cp"."user_id" AS "ref_id",
    "cp"."status",
    NULL::"uuid" AS "market_id"
   FROM "delivery"."courier_profiles" "cp"
UNION ALL
 SELECT "m"."owner_id" AS "user_id",
    'merchant_owner'::"text" AS "persona",
    "m"."id" AS "ref_id",
    COALESCE("mop"."account_status", 'active'::"text") AS "status",
    "m"."market_id"
   FROM ("delivery"."merchants" "m"
     LEFT JOIN "delivery"."merchant_owner_profiles" "mop" ON (("mop"."user_id" = "m"."owner_id")))
  WHERE ("m"."owner_id" IS NOT NULL)
UNION ALL
 SELECT "mtm"."user_id",
    'merchant_staff'::"text" AS "persona",
    "mtm"."id" AS "ref_id",
    'active'::"text" AS "status",
    "m"."market_id"
   FROM ("delivery"."merchant_team_members" "mtm"
     JOIN "delivery"."merchants" "m" ON (("m"."id" = "mtm"."merchant_id")))
  WHERE ("mtm"."user_id" IS NOT NULL);


ALTER VIEW "platform"."identity_personas" OWNER TO "postgres";


CREATE OR REPLACE VIEW "platform"."merchant_staff_role_aliases" WITH ("security_invoker"='true') AS
 SELECT "id" AS "member_id",
    "user_id",
    "merchant_id",
    "role" AS "legacy_role",
        CASE "role"
            WHEN 'admin'::"text" THEN 'merchant.staff.admin'::"text"
            WHEN 'manager'::"text" THEN 'merchant.staff.manager'::"text"
            ELSE 'merchant.staff.member'::"text"
        END AS "platform_role"
   FROM "delivery"."merchant_team_members" "mtm";


