COMMENT ON TABLE "public"."vehicle_catalog" IS 'Platform-wide motor vehicle specification catalog (admin-managed).';



COMMENT ON COLUMN "public"."vehicle_catalog"."model_code" IS 'OEM or platform model code (optional).';



COMMENT ON COLUMN "public"."vehicle_catalog"."generation_code" IS 'OEM generation / chassis code (e.g. M900A). Distinct from numeric generation.';



COMMENT ON COLUMN "public"."vehicle_catalog"."engine_type" IS 'Free-text engine / induction label (e.g. Turbo, N/A)';



COMMENT ON COLUMN "public"."vehicle_catalog"."vehicle_class" IS 'car (default) or motorcycle — filters facets, Rides body types, maintenance, and variant identity.';



COMMENT ON COLUMN "public"."vehicle_catalog"."final_drive" IS 'Motorcycle final drive: chain, belt, or shaft.';



COMMENT ON COLUMN "public"."vehicle_catalog"."cooling_type" IS 'Motorcycle cooling: air, oil, or liquid.';



COMMENT ON COLUMN "public"."vehicle_catalog"."starter_type" IS 'Motorcycle starter: electric, kick, or both.';



COMMENT ON COLUMN "public"."vehicle_catalog"."front_tire_size" IS 'Motorcycle front tire size (cars keep tire_size).';



COMMENT ON COLUMN "public"."vehicle_catalog"."rear_tire_size" IS 'Motorcycle rear tire size (cars keep tire_size).';



COMMENT ON COLUMN "public"."vehicle_catalog"."created_by" IS 'Auth user that created the row (edge-stamped).';



COMMENT ON COLUMN "public"."vehicle_catalog"."updated_by" IS 'Auth user that last updated the row (edge-stamped).';



COMMENT ON COLUMN "public"."vehicle_catalog"."import_batch_id" IS 'UUID minted per CSV import run; enables undo-batch.';



COMMENT ON COLUMN "public"."vehicle_catalog"."source" IS 'manual | csv_import | pending_approve';



CREATE OR REPLACE VIEW "public"."catalog_signal_part_demand" AS
 SELECT "vc"."id" AS "variant_id",
    "r"."maintenance_component_id" AS "component_id",
    ("count"(*))::integer AS "open_count",
    ("count"(DISTINCT "r"."organization_id"))::integer AS "fleet_count"
   FROM (("public"."parts_sourcing_requests" "r"
     JOIN "fleet"."vehicles" "v" ON ((("v"."legacy_kv_id" = ('vehicle:'::"text" || "r"."vehicle_id")) OR ("v"."legacy_kv_id" = "r"."vehicle_id") OR ("v"."id" = "r"."vehicle_id"))))
     JOIN "public"."vehicle_catalog" "vc" ON ((("vc"."id")::"text" = "v"."vehicle_catalog_id")))
  WHERE ("r"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"]))
  GROUP BY "vc"."id", "r"."maintenance_component_id"
 HAVING ("count"(DISTINCT "r"."organization_id") >= 2);


