CREATE OR REPLACE VIEW "public"."catalog_signal_unmatched_numbers" AS
 SELECT "upper"("regexp_replace"("r"."part_number", '[^A-Za-z0-9]'::"text", ''::"text", 'g'::"text")) AS "part_number",
    "l"."component_id",
    "vc"."id" AS "variant_id",
    ("count"(*))::integer AS "occurrences"
   FROM (((("public"."part_number_link_review" "r"
     JOIN "public"."maintenance_work_order_lines" "l" ON (("l"."id" = "r"."work_order_line_id")))
     JOIN "public"."maintenance_work_orders" "w" ON (("w"."id" = "l"."work_order_id")))
     JOIN "fleet"."vehicles" "v" ON ((("v"."legacy_kv_id" = ('vehicle:'::"text" || "w"."vehicle_id")) OR ("v"."legacy_kv_id" = "w"."vehicle_id") OR ("v"."id" = "w"."vehicle_id"))))
     JOIN "public"."vehicle_catalog" "vc" ON ((("vc"."id")::"text" = "v"."vehicle_catalog_id")))
  WHERE ("r"."status" = 'open'::"text")
  GROUP BY ("upper"("regexp_replace"("r"."part_number", '[^A-Za-z0-9]'::"text", ''::"text", 'g'::"text"))), "l"."component_id", "vc"."id"
 HAVING ("count"(DISTINCT "r"."organization_id") >= 2);


ALTER VIEW "public"."catalog_signal_unmatched_numbers" OWNER TO "postgres";


