    "tip_received_minor" bigint,
    "cash_settlement_status" "text",
    "cash_settlement_outcome" "text",
    "fare_locked_at" timestamp with time zone,
    "settled_at" timestamp with time zone,
    "booking_kind" "text" DEFAULT 'immediate'::"text" NOT NULL,
    "scheduled_pickup_at" timestamp with time zone,
    "pickup_window_minutes" integer DEFAULT 10 NOT NULL,
    "scheduled_dispatched_at" timestamp with time zone,
    "scheduled_cancel_reason" "text",
    "cash_settlement_snapshot" "jsonb",
    "shortfall_payment_method" "text",
