    "fleet_id" "uuid",
    "organization_id" "uuid",
    "attribution_mode" "text",
    CONSTRAINT "ride_requests_actual_tolls_minor_check" CHECK (("actual_tolls_minor" >= 0)),
    CONSTRAINT "ride_requests_attribution_mode_check" CHECK ((("attribution_mode" IS NULL) OR ("attribution_mode" = ANY (ARRAY['independent'::"text", 'fleet'::"text"])))),
    CONSTRAINT "ride_requests_booking_kind_check" CHECK (("booking_kind" = ANY (ARRAY['immediate'::"text", 'scheduled'::"text"]))),
    CONSTRAINT "ride_requests_booking_kind_scheduled_pickup_check" CHECK (((("booking_kind" = 'immediate'::"text") AND ("scheduled_pickup_at" IS NULL)) OR (("booking_kind" = 'scheduled'::"text") AND ("scheduled_pickup_at" IS NOT NULL)))),
    CONSTRAINT "ride_requests_booking_purpose_check" CHECK ((("booking_purpose" IS NULL) OR ("booking_purpose" = ANY (ARRAY['guest'::"text", 'family'::"text", 'business'::"text"])))),
    CONSTRAINT "ride_requests_cancelled_by_check" CHECK ((("cancelled_by" IS NULL) OR ("cancelled_by" = ANY (ARRAY['rider'::"text", 'driver'::"text", 'system'::"text"])))),
    CONSTRAINT "ride_requests_cash_settlement_outcome_check" CHECK ((("cash_settlement_outcome" IS NULL) OR ("cash_settlement_outcome" = ANY (ARRAY['exact'::"text", 'underpay'::"text", 'overpay'::"text", 'unpaid'::"text", 'split'::"text"])))),
    CONSTRAINT "ride_requests_completed_fields_check" CHECK ((("status" <> 'completed'::"text") OR (("fare_final_minor" IS NOT NULL) AND ("payment_method" IS NOT NULL) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "ride_requests_payment_method_check" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['cash'::"text", 'card'::"text"])))),
    CONSTRAINT "ride_requests_pickup_window_minutes_check" CHECK ((("pickup_window_minutes" >= 5) AND ("pickup_window_minutes" <= 30))),
    CONSTRAINT "ride_requests_roam_mode_check" CHECK ((("roam_mode" IS NULL) OR ("roam_mode" = ANY (ARRAY['open_roam'::"text", 'shadow_roam'::"text"])))),
    CONSTRAINT "ride_requests_scheduled_cancel_reason_check" CHECK ((("scheduled_cancel_reason" IS NULL) OR ("scheduled_cancel_reason" = ANY (ARRAY['rider'::"text", 'system_no_drivers'::"text", 'system_rider_busy'::"text", 'system_missed_window'::"text"])))),
    CONSTRAINT "ride_requests_shortfall_payment_method_check" CHECK (("shortfall_payment_method" = ANY (ARRAY['wallet'::"text", 'card'::"text", 'arrears'::"text"]))),
    CONSTRAINT "ride_requests_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'matching'::"text", 'driver_assigned'::"text", 'driver_en_route_pickup'::"text", 'driver_arrived_pickup'::"text", 'on_trip'::"text", 'awaiting_cash_settlement'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "ride_requests_surge_multiplier_check" CHECK ((("surge_multiplier" IS NULL) OR ("surge_multiplier" > (0)::numeric))),
    CONSTRAINT "ride_requests_wait_time_fee_minor_check" CHECK ((("wait_time_fee_minor" IS NULL) OR ("wait_time_fee_minor" >= 0)))
);

