COMMENT ON COLUMN "rides"."ride_requests"."wait_time_started_at" IS 'Timestamp when wait time billing started (after grace period expired)';



COMMENT ON COLUMN "rides"."ride_requests"."wait_time_fee_minor" IS 'Accumulated wait time fee in minor units (cents)';



COMMENT ON COLUMN "rides"."ride_requests"."pin_verified_at" IS 'Timestamp when driver verified the PIN';



COMMENT ON COLUMN "rides"."ride_requests"."actual_tolls_minor" IS 'Sum of actual tolls detected via geofence crossings during trip';



COMMENT ON COLUMN "rides"."ride_requests"."dropoff_arrived_at" IS 'Timestamp when driver reached dropoff geofence';



COMMENT ON COLUMN "rides"."ride_requests"."guest_passenger_name" IS 'Display name of the person riding when booked by another account holder.';



COMMENT ON COLUMN "rides"."ride_requests"."guest_passenger_phone" IS 'E.164 phone for SMS ride updates to the guest passenger.';



COMMENT ON COLUMN "rides"."ride_requests"."booking_purpose" IS 'Why the account holder booked for someone else: guest, family, or business.';



COMMENT ON COLUMN "rides"."ride_requests"."booking_kind" IS 'immediate = on-demand; scheduled = reserve ride awaiting dispatch cron.';



COMMENT ON COLUMN "rides"."ride_requests"."scheduled_pickup_at" IS 'Target pickup time for scheduled bookings.';



COMMENT ON COLUMN "rides"."ride_requests"."scheduled_dispatched_at" IS 'When cron transitioned scheduled → matching.';



COMMENT ON COLUMN "rides"."ride_requests"."shortfall_payment_method" IS 'How the rider paid any shortfall: wallet (auto-deducted), card (manually paid via card), or arrears (owed to platform)';



COMMENT ON COLUMN "rides"."ride_requests"."fleet_id" IS 'Fleet org from driver_profiles at assign/complete (nullable for independent).';



COMMENT ON COLUMN "rides"."ride_requests"."organization_id" IS 'Org stamped for fleet books / future org payout (usually same as fleet_id).';



COMMENT ON COLUMN "rides"."ride_requests"."attribution_mode" IS 'independent | fleet — money destination policy key; journal branch uses org payout flag.';



CREATE MATERIALIZED VIEW "rides"."driver_directory_stats" AS
 WITH "trips" AS (
         SELECT "ride_requests"."assigned_driver_user_id" AS "driver_user_id",
            ("count"(*))::integer AS "total_trips",
            ("count"(*) FILTER (WHERE ("ride_requests"."status" = 'completed'::"text")))::integer AS "completed_trips",
            ("count"(*) FILTER (WHERE ("ride_requests"."status" = 'cancelled'::"text")))::integer AS "cancelled_trips",
            "max"("ride_requests"."created_at") AS "last_ride_at",
            (COALESCE("sum"(COALESCE("ride_requests"."fare_final_minor", "ride_requests"."fare_estimate_minor")) FILTER (WHERE ("ride_requests"."status" = 'completed'::"text")), (0)::numeric))::bigint AS "lifetime_earnings_minor",
            (COALESCE("sum"(COALESCE("ride_requests"."fare_final_minor", "ride_requests"."fare_estimate_minor")) FILTER (WHERE (("ride_requests"."status" = 'completed'::"text") AND ("ride_requests"."payment_method" = 'cash'::"text"))), (0)::numeric))::bigint AS "lifetime_cash_earnings_minor",
            (COALESCE("sum"(COALESCE("ride_requests"."fare_final_minor", "ride_requests"."fare_estimate_minor")) FILTER (WHERE (("ride_requests"."status" = 'completed'::"text") AND ("ride_requests"."payment_method" = 'card'::"text"))), (0)::numeric))::bigint AS "lifetime_digital_earnings_minor"
           FROM "rides"."ride_requests"
          WHERE ("ride_requests"."assigned_driver_user_id" IS NOT NULL)
          GROUP BY "ride_requests"."assigned_driver_user_id"
        ), "offers" AS (
         SELECT "driver_offers"."driver_user_id",
            ("count"(*))::integer AS "offers_sent",
            ("count"(*) FILTER (WHERE ("driver_offers"."status" = 'accepted'::"text")))::integer AS "offers_accepted",
            ("count"(*) FILTER (WHERE ("driver_offers"."status" = 'declined'::"text")))::integer AS "offers_declined"
           FROM "rides"."driver_offers"
          GROUP BY "driver_offers"."driver_user_id"
        )
 SELECT "dp"."user_id" AS "driver_user_id",
    COALESCE("t"."total_trips", 0) AS "total_trips",
    COALESCE("t"."completed_trips", 0) AS "completed_trips",
    COALESCE("t"."cancelled_trips", 0) AS "cancelled_trips",
    COALESCE("o"."offers_sent", 0) AS "offers_sent",
    COALESCE("o"."offers_accepted", 0) AS "offers_accepted",
    COALESCE("o"."offers_declined", 0) AS "offers_declined",
        CASE
            WHEN (COALESCE("o"."offers_sent", 0) > 0) THEN "round"(((100.0 * (COALESCE("o"."offers_accepted", 0))::numeric) / ("o"."offers_sent")::numeric), 1)
            ELSE NULL::numeric
        END AS "acceptance_rate_pct",
        CASE
            WHEN (COALESCE("t"."total_trips", 0) > 0) THEN "round"(((100.0 * (COALESCE("t"."completed_trips", 0))::numeric) / ("t"."total_trips")::numeric), 1)
            ELSE NULL::numeric
        END AS "completion_rate_pct",
    "t"."last_ride_at",
    COALESCE("t"."lifetime_earnings_minor", (0)::bigint) AS "lifetime_earnings_minor",
    COALESCE("t"."lifetime_cash_earnings_minor", (0)::bigint) AS "lifetime_cash_earnings_minor",
    COALESCE("t"."lifetime_digital_earnings_minor", (0)::bigint) AS "lifetime_digital_earnings_minor",
    "dl"."updated_at" AS "last_online_at"
   FROM ((("public"."driver_profiles" "dp"
     LEFT JOIN "trips" "t" ON (("t"."driver_user_id" = "dp"."user_id")))
     LEFT JOIN "offers" "o" ON (("o"."driver_user_id" = "dp"."user_id")))
     LEFT JOIN "rides"."driver_locations" "dl" ON (("dl"."user_id" = "dp"."user_id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "rides"."driver_directory_stats" OWNER TO "postgres";


