    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "driver_vehicles_ownership_type_check" CHECK (("ownership_type" = ANY (ARRAY['owned'::"text", 'rented'::"text", 'financed'::"text", 'leased'::"text"]))),
    CONSTRAINT "driver_vehicles_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'maintenance'::"text", 'decommissioned'::"text"]))),
    CONSTRAINT "driver_vehicles_year_check" CHECK ((("year" >= 1990) AND ("year" <= 2100)))
);


ALTER TABLE "public"."driver_vehicles" OWNER TO "postgres";


