);


ALTER TABLE "public"."engine_family" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organizations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid",
    "name" "text" NOT NULL,
    "slug" "text",
    "product_line" "text" DEFAULT 'fleet'::"text" NOT NULL,
    "business_type" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "contact_email" "text",
    "contact_phone" "text",
    "address_line1" "text",
    "address_line2" "text",
    "city" "text",
    "state_province" "text",
    "postal_code" "text",
    "country" "text" DEFAULT 'US'::"text",
    "billing_email" "text",
    "stripe_customer_id" "text",
    "subscription_tier" "text" DEFAULT 'free'::"text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "fleet_org_payout_enabled" boolean DEFAULT false NOT NULL,
    "enabled_modules" "jsonb",
    "subscribed_products" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "is_external" boolean DEFAULT false NOT NULL,
    "created_by_org_id" "uuid",
    "external_contact" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "service_lines" "text"[] DEFAULT ARRAY['rideshare'::"text"] NOT NULL,
    "fleet_tag" "text",
    "fleet_tag_internal_id" "text",
    "require_owner_mfa" boolean DEFAULT false NOT NULL,
    CONSTRAINT "organizations_business_type_check" CHECK ((("business_type" IS NULL) OR ("business_type" = ANY (ARRAY['rideshare'::"text", 'delivery'::"text", 'taxi'::"text", 'trucking'::"text", 'shipping'::"text", 'freight_forwarding'::"text", 'warehouse'::"text", 'other'::"text"])))),
    CONSTRAINT "organizations_external_owner_check" CHECK (((("is_external" = false) AND ("owner_id" IS NOT NULL)) OR (("is_external" = true) AND ("created_by_org_id" IS NOT NULL) AND ("owner_id" IS NULL)))),
    CONSTRAINT "organizations_fleet_tag_format" CHECK ((("fleet_tag" IS NULL) OR (("char_length"("fleet_tag") >= 3) AND ("char_length"("fleet_tag") <= 24) AND ("fleet_tag" ~ '^[a-z0-9_]+$'::"text")))),
    CONSTRAINT "organizations_product_line_check" CHECK (("product_line" = ANY (ARRAY['fleet'::"text", 'enterprise'::"text"]))),
    CONSTRAINT "organizations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'suspended'::"text", 'pending_approval'::"text", 'deactivated'::"text"]))),
    CONSTRAINT "organizations_subscription_tier_check" CHECK (("subscription_tier" = ANY (ARRAY['free'::"text", 'starter'::"text", 'professional'::"text", 'enterprise'::"text"])))
);


ALTER TABLE "public"."organizations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organizations"."fleet_org_payout_enabled" IS 'When TRUE, matched Roam trip fares credit org payment accounts (tips stay with driver). Default OFF — pilot per org.';



COMMENT ON COLUMN "public"."organizations"."enabled_modules" IS 'Per-org module overrides (boolean map). null inherits platform:settings:enterprise.enabledModules. Effective = product-line ∩ org (explicit false wins).';



COMMENT ON COLUMN "public"."organizations"."subscribed_products" IS 'JSON array of product keys, e.g. ["courier","warehouse"]. Empty = infer from business_type.';



COMMENT ON COLUMN "public"."organizations"."is_external" IS 'Placeholder partner with no login. Visible only to the org that created it (and platform staff).';



COMMENT ON COLUMN "public"."organizations"."service_lines" IS 'Operational service lines: rideshare, rush_delivery. Primary business_type kept for backward compat.';



COMMENT ON COLUMN "public"."organizations"."fleet_tag" IS 'Public Fleet Tag handle (no @). Drivers/couriers use this to request join.';



COMMENT ON COLUMN "public"."organizations"."fleet_tag_internal_id" IS 'Opaque FT-… id for ops; never returned to clients.';



CREATE OR REPLACE VIEW "public"."enterprise_rideshare_orgs_audit" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "owner_id",
    "business_type",
    "product_line",
    "created_at"
   FROM "public"."organizations"
  WHERE (("product_line" = 'enterprise'::"text") AND ("business_type" = 'rideshare'::"text"));


ALTER VIEW "public"."enterprise_rideshare_orgs_audit" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."evidence_files" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "bucket_id" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "evidence_type" "text" NOT NULL,
    "retention_class" "text" DEFAULT 'ephemeral'::"text" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "text" NOT NULL,
    "org_id" "text",
    "public_url" "text",
    "uploaded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "delete_after" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "evidence_files_evidence_type_check" CHECK (("evidence_type" = ANY (ARRAY['fuel_receipt'::"text", 'toll_receipt'::"text", 'odometer_proof'::"text", 'maintenance_invoice'::"text"]))),
    CONSTRAINT "evidence_files_retention_class_check" CHECK (("retention_class" = ANY (ARRAY['ephemeral'::"text", 'permanent'::"text"]))),
    CONSTRAINT "evidence_files_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'pending_hold'::"text", 'scheduled'::"text", 'deleted'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."evidence_files" OWNER TO "postgres";


COMMENT ON TABLE "public"."evidence_files" IS 'Tracks ephemeral scan evidence with scheduled deletion after parent record resolution. Daily purge via evidence-cleanup.';



