CREATE TABLE IF NOT EXISTS "public"."fuel_flag_disposition" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "entry_id" "text" NOT NULL,
    "flag_code" "text" NOT NULL,
    "action" "text" NOT NULL,
    "note" "text",
    "period_id" "text",
    "actor_id" "uuid" NOT NULL,
    "at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fuel_flag_disposition_action_check" CHECK (("action" = ANY (ARRAY['accepted'::"text", 'corrected'::"text", 'escalated'::"text"])))
);


ALTER TABLE "public"."fuel_flag_disposition" OWNER TO "postgres";


COMMENT ON TABLE "public"."fuel_flag_disposition" IS 'Current disposition per fill flag_code. SELECT: org JWT. INSERT/UPDATE: service role / edge only. Audit trail via fuel_period_audit.flag_disposition.';



