ALTER SEQUENCE "public"."fuel_period_audit_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "public"."fuel_period_audit_id_seq" OWNED BY "public"."fuel_period_audit"."id";



CREATE TABLE IF NOT EXISTS "public"."fuel_period_job" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "period_id" "text" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "period_version" bigint NOT NULL,
    "progress_done" integer DEFAULT 0 NOT NULL,
    "progress_total" integer DEFAULT 0 NOT NULL,
    "cursor" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "failures" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fuel_period_job_kind_check" CHECK (("kind" = ANY (ARRAY['finalize'::"text", 'reopen'::"text", 'recompute'::"text"]))),
    CONSTRAINT "fuel_period_job_state_check" CHECK (("state" = ANY (ARRAY['queued'::"text", 'running'::"text", 'succeeded'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."fuel_period_job" OWNER TO "postgres";


