CREATE TABLE IF NOT EXISTS "public"."fuel_reconciliation_period" (
    "id" "text" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "week_end" "date" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "current_step" "text",
    "version" bigint DEFAULT 1 NOT NULL,
    "vehicle_count" integer DEFAULT 0 NOT NULL,
    "driver_count" integer DEFAULT 0 NOT NULL,
    "total_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "gas_card_spend" numeric(14,2) DEFAULT 0 NOT NULL,
    "cash_from_earnings" numeric(14,2) DEFAULT 0 NOT NULL,
    "company_share" numeric(14,2) DEFAULT 0 NOT NULL,
    "driver_share" numeric(14,2) DEFAULT 0 NOT NULL,
    "unexplained" numeric(14,2) DEFAULT 0 NOT NULL,
    "counts" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "leakage_reviewed_at" timestamp with time zone,
    "leakage_reviewed_by" "uuid",
    "leakage_review_note" "text",
    "locked_at" timestamp with time zone,
    "locked_by" "uuid",
    "reopened_at" timestamp with time zone,
    "reopened_by" "uuid",
    "reopen_reason" "text",
    "computed_at" timestamp with time zone,
    "computed_from_hash" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fuel_seal_error" "text",
    "degraded_inputs" boolean DEFAULT false NOT NULL,
    "odometer_chain_reviewed_at" timestamp with time zone,
    "odometer_chain_reviewed_by" "text",
    "odometer_chain_review_note" "text",
    "unattributed_reviewed_at" timestamp with time zone,
    "unattributed_reviewed_by" "text",
    "unattributed_review_note" "text",
    "data_quality_vehicle_reviews" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "stop_to_stop_gap_accepts" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "service_line" "text" DEFAULT 'rideshare'::"text" NOT NULL,
    "close_receipt" "jsonb",
    "leftover_split_override" "jsonb",
    "implausible_fills_reviewed_at" timestamp with time zone,
    "implausible_fills_review_note" "text",
    CONSTRAINT "fuel_reconciliation_period_service_line_check" CHECK (("service_line" = ANY (ARRAY['rideshare'::"text", 'rush_delivery'::"text"]))),
    CONSTRAINT "fuel_reconciliation_period_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_review'::"text", 'ready'::"text", 'locked'::"text", 'reopened'::"text"])))
);


ALTER TABLE "public"."fuel_reconciliation_period" OWNER TO "postgres";


COMMENT ON TABLE "public"."fuel_reconciliation_period" IS 'Fuel recon period SoT. Writes: service role only. Authenticated: SELECT (org-scoped).';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."fuel_seal_error" IS 'N-7: last sealFuelWeek failure message; cleared on successful seal';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."degraded_inputs" IS 'True when wizard money-bearing inputs timed out or were missing (trips/deadhead/PA/brain/cards).';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."odometer_chain_reviewed_at" IS 'R-2: operator acknowledged timing cannot be measured (thin odometer chain).';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."unattributed_reviewed_at" IS 'R-1: operator accepted fills-without-odometer spend beyond gate.';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."data_quality_vehicle_reviews" IS 'Array of { vehicleId, at, by?, note? } — operator marked flagged DQ vehicles reviewed for Continue gate.';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."stop_to_stop_gap_accepts" IS 'Accepted stop-to-stop OVER-LOG windows for this period: [{bucketId,vehicleId,startOdometer,endOdometer,startDate,endDate,note,disposition,at,by}]. Cleared on reopen. Never accepts chain anomalies.';



COMMENT ON COLUMN "public"."fuel_reconciliation_period"."close_receipt" IS 'Statement ids and posted ledger line ids written when a week locks.';



