CREATE OR REPLACE VIEW "public"."fuel_weeks_missing_period" AS
 SELECT "organization_id",
    ("date_trunc"('week'::"text", ("date")::timestamp with time zone))::"date" AS "week_start",
    "count"(*) AS "fill_count",
    "sum"("amount") AS "total_amount"
   FROM "fleet"."fuel_entries" "e"
  WHERE (("amount" > (0)::numeric) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."fuel_reconciliation_period" "p"
          WHERE ((("p"."org_id")::"text" = "e"."organization_id") AND ("p"."week_start" = ("date_trunc"('week'::"text", ("e"."date")::timestamp with time zone))::"date"))))))
  GROUP BY "organization_id", (("date_trunc"('week'::"text", ("date")::timestamp with time zone))::"date");


ALTER VIEW "public"."fuel_weeks_missing_period" OWNER TO "postgres";


