CREATE OR REPLACE VIEW "public"."ledger_scoped_driver" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."organization_id",
    "e"."idempotency_key",
    "e"."entry_type",
    "e"."product",
    "e"."debit_account_id",
    "e"."credit_account_id",
    "e"."amount_minor",
    "e"."currency",
    "e"."request_hash",
    "e"."effective_at",
    "e"."reference_type",
    "e"."reference_id",
    "e"."metadata",
    "e"."created_by_user_id",
    "e"."created_at"
   FROM ("ledger"."entries" "e"
     JOIN "ledger"."accounts" "a" ON ((("a"."id" = "e"."credit_account_id") OR ("a"."id" = "e"."debit_account_id"))))
  WHERE (("a"."owner_user_id" = "auth"."uid"()) AND ("a"."owner_role" = 'driver'::"text"));


ALTER VIEW "public"."ledger_scoped_driver" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."ledger_scoped_fleet" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "idempotency_key",
    "entry_type",
    "product",
    "debit_account_id",
    "credit_account_id",
    "amount_minor",
    "currency",
    "request_hash",
    "effective_at",
    "reference_type",
    "reference_id",
    "metadata",
    "created_by_user_id",
    "created_at"
   FROM "ledger"."entries" "e"
  WHERE (("organization_id" IS NOT NULL) AND ("public"."rbac_is_platform_user"("auth"."uid"()) OR (EXISTS ( SELECT 1
           FROM "public"."organizations" "o"
          WHERE (("o"."id" = "e"."organization_id") AND ("o"."owner_id" = "auth"."uid"()))))));


ALTER VIEW "public"."ledger_scoped_fleet" OWNER TO "postgres";


