CREATE TABLE IF NOT EXISTS "public"."maintenance_task_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vehicle_catalog_id" "uuid",
    "task_name" "text" NOT NULL,
    "description" "text",
    "interval_miles" integer,
    "interval_months" integer,
    "priority" "text" DEFAULT 'standard'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "frequency_kind" "text" DEFAULT 'recurring'::"text" NOT NULL,
    "frequency_label" "text",
    "template_scope" "text" DEFAULT 'catalog'::"text" NOT NULL,
    "task_code" "text",
    "interval_miles_max" integer,
    "icon_key" "text" DEFAULT 'wrench'::"text" NOT NULL,
    "due_kind" "text" DEFAULT 'service_package'::"text" NOT NULL,
    "archived_at" timestamp with time zone,
    "applicable_vehicle_classes" "text"[] DEFAULT ARRAY['car'::"text"] NOT NULL,
    "component_id" "uuid",
    "platform_id" "uuid",
    "engine_family_id" "uuid",
    CONSTRAINT "maintenance_task_templates_applicable_vehicle_classes_check" CHECK ((("cardinality"("applicable_vehicle_classes") >= 1) AND ("applicable_vehicle_classes" <@ ARRAY['car'::"text", 'motorcycle'::"text"]))),
    CONSTRAINT "maintenance_task_templates_due_kind_check" CHECK (("due_kind" = ANY (ARRAY['service_package'::"text", 'statutory_inspection'::"text"]))),
    CONSTRAINT "maintenance_task_templates_frequency_kind_check" CHECK (("frequency_kind" = ANY (ARRAY['recurring'::"text", 'once_milestone'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "maintenance_task_templates_interval_miles_range_check" CHECK ((("interval_miles_max" IS NULL) OR ("interval_miles" IS NULL) OR ("interval_miles_max" >= "interval_miles"))),
    CONSTRAINT "maintenance_task_templates_priority_check" CHECK (("priority" = ANY (ARRAY['critical'::"text", 'standard'::"text", 'optional'::"text"]))),
    CONSTRAINT "maintenance_task_templates_scope_check" CHECK (((("template_scope" = 'variant'::"text") AND ("vehicle_catalog_id" IS NOT NULL) AND ("platform_id" IS NULL) AND ("engine_family_id" IS NULL)) OR (("template_scope" = 'platform'::"text") AND ("platform_id" IS NOT NULL) AND ("vehicle_catalog_id" IS NULL) AND ("engine_family_id" IS NULL)) OR (("template_scope" = 'engine_family'::"text") AND ("engine_family_id" IS NOT NULL) AND ("vehicle_catalog_id" IS NULL) AND ("platform_id" IS NULL)) OR (("template_scope" = 'global'::"text") AND ("vehicle_catalog_id" IS NULL) AND ("platform_id" IS NULL) AND ("engine_family_id" IS NULL)))),
    CONSTRAINT "maintenance_task_templates_template_scope_check" CHECK (("template_scope" = ANY (ARRAY['variant'::"text", 'platform'::"text", 'engine_family'::"text", 'global'::"text"])))
);


ALTER TABLE "public"."maintenance_task_templates" OWNER TO "postgres";


COMMENT ON COLUMN "public"."maintenance_task_templates"."interval_miles" IS 'Lower bound / nominal miles between services (used for next-due odometer math).';



COMMENT ON COLUMN "public"."maintenance_task_templates"."frequency_kind" IS 'recurring = repeat by interval; once_milestone = single due then fulfilled; manual_only = no auto next due.';



COMMENT ON COLUMN "public"."maintenance_task_templates"."frequency_label" IS 'Optional display label (e.g. A-service); does not change scheduling math.';



COMMENT ON COLUMN "public"."maintenance_task_templates"."template_scope" IS 'variant overrides platform, then engine_family, then global.';



COMMENT ON COLUMN "public"."maintenance_task_templates"."task_code" IS 'Optional stable slug for merge at bootstrap (catalog wins over global on same code or name).';



COMMENT ON COLUMN "public"."maintenance_task_templates"."interval_miles_max" IS 'Optional upper bound (e.g. 7500 when lower is 5000). Null means a single mileage interval. Scheduling uses interval_miles for calculations.';



COMMENT ON COLUMN "public"."maintenance_task_templates"."due_kind" IS 'service_package = Basic/Major style; statutory_inspection = e.g. 車検-style due (platform).';



COMMENT ON COLUMN "public"."maintenance_task_templates"."applicable_vehicle_classes" IS 'Vehicle classes this template may apply to (global bootstrap filters on catalog vehicle_class).';



