    "default_driver_offer_timeout_seconds" integer DEFAULT 15 NOT NULL,
    "driver_location_max_age_minutes" integer DEFAULT 10 NOT NULL,
    "quote_driver_radius_km" numeric DEFAULT 15 NOT NULL,
    "body_type_filtering_enabled" boolean DEFAULT true NOT NULL,
    "body_type_tier_mode" "text" DEFAULT 'expand'::"text" NOT NULL,
    "require_body_type_for_offers" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "independent_only_matching" boolean DEFAULT true NOT NULL,
    "trip_location_interval_seconds" integer DEFAULT 4 NOT NULL,
    "pickup_geofence_radius_m" integer DEFAULT 80 NOT NULL,
    "dropoff_geofence_radius_m" integer DEFAULT 100 NOT NULL,
    "arrival_dwell_seconds" integer DEFAULT 15 NOT NULL,
    "max_speed_mps_for_arrival" numeric DEFAULT 4 NOT NULL,
    "auto_en_route_on_accept" boolean DEFAULT true NOT NULL,
    "auto_arrive_enabled" boolean DEFAULT true NOT NULL,
    "auto_complete_suggest_enabled" boolean DEFAULT true NOT NULL,
    "no_show_cancel_minutes" integer DEFAULT 5 NOT NULL,
    "gps_max_accuracy_m_for_arrival" integer DEFAULT 50 NOT NULL,
    "no_show_auto_cancel_enabled" boolean DEFAULT false NOT NULL,
    "max_matching_duration_minutes" integer DEFAULT 15 NOT NULL,
    "wait_time_grace_minutes" integer DEFAULT 2 NOT NULL,
    "wait_time_rate_per_min_minor" integer DEFAULT 50 NOT NULL,
    "wait_time_charge_enabled" boolean DEFAULT false NOT NULL,
    "wait_time_max_minutes" integer DEFAULT 15 NOT NULL,
    "pin_verification_enabled" boolean DEFAULT false NOT NULL,
    "pin_verification_required_for_start" boolean DEFAULT false NOT NULL,
    "toll_detection_enabled" boolean DEFAULT false NOT NULL,
    "toll_geofence_radius_m" integer DEFAULT 100 NOT NULL,
    "route_toll_estimation_enabled" boolean DEFAULT false NOT NULL,
    "roam_platform_fee_bps" integer DEFAULT 0 NOT NULL,
    "toll_round_trip_cooldown_ms" integer DEFAULT 300000 NOT NULL,
    CONSTRAINT "dispatch_settings_arrival_dwell_seconds_check" CHECK ((("arrival_dwell_seconds" >= 0) AND ("arrival_dwell_seconds" <= 120))),
    CONSTRAINT "dispatch_settings_body_type_tier_mode_check" CHECK (("body_type_tier_mode" = ANY (ARRAY['expand'::"text", 'strict'::"text"]))),
    CONSTRAINT "dispatch_settings_default_driver_offer_timeout_seconds_check" CHECK ((("default_driver_offer_timeout_seconds" >= 5) AND ("default_driver_offer_timeout_seconds" <= 120))),
    CONSTRAINT "dispatch_settings_driver_location_max_age_minutes_check" CHECK ((("driver_location_max_age_minutes" >= 1) AND ("driver_location_max_age_minutes" <= 30))),
    CONSTRAINT "dispatch_settings_dropoff_geofence_radius_m_check" CHECK ((("dropoff_geofence_radius_m" >= 20) AND ("dropoff_geofence_radius_m" <= 500))),
    CONSTRAINT "dispatch_settings_gps_max_accuracy_m_for_arrival_check" CHECK ((("gps_max_accuracy_m_for_arrival" >= 10) AND ("gps_max_accuracy_m_for_arrival" <= 200))),
    CONSTRAINT "dispatch_settings_id_check" CHECK (("id" = 1)),
    CONSTRAINT "dispatch_settings_max_match_waves_check" CHECK ((("max_match_waves" >= 1) AND ("max_match_waves" <= 5))),
    CONSTRAINT "dispatch_settings_max_matching_duration_minutes_check" CHECK ((("max_matching_duration_minutes" >= 2) AND ("max_matching_duration_minutes" <= 120))),
    CONSTRAINT "dispatch_settings_max_offers_per_wave_check" CHECK ((("max_offers_per_wave" >= 1) AND ("max_offers_per_wave" <= 20))),
    CONSTRAINT "dispatch_settings_max_speed_mps_for_arrival_check" CHECK ((("max_speed_mps_for_arrival" >= (0)::numeric) AND ("max_speed_mps_for_arrival" <= (20)::numeric))),
    CONSTRAINT "dispatch_settings_no_show_cancel_minutes_check" CHECK ((("no_show_cancel_minutes" >= 0) AND ("no_show_cancel_minutes" <= 60))),
    CONSTRAINT "dispatch_settings_pickup_geofence_radius_m_check" CHECK ((("pickup_geofence_radius_m" >= 20) AND ("pickup_geofence_radius_m" <= 500))),
    CONSTRAINT "dispatch_settings_quote_driver_radius_km_check" CHECK ((("quote_driver_radius_km" > (0)::numeric) AND ("quote_driver_radius_km" <= (50)::numeric))),
    CONSTRAINT "dispatch_settings_toll_geofence_radius_m_check" CHECK ((("toll_geofence_radius_m" >= 50) AND ("toll_geofence_radius_m" <= 500))),
    CONSTRAINT "dispatch_settings_toll_round_trip_cooldown_ms_check" CHECK ((("toll_round_trip_cooldown_ms" >= 0) AND ("toll_round_trip_cooldown_ms" <= 3600000))),
    CONSTRAINT "dispatch_settings_trip_location_interval_seconds_check" CHECK ((("trip_location_interval_seconds" >= 2) AND ("trip_location_interval_seconds" <= 30))),
    CONSTRAINT "dispatch_settings_wait_time_grace_minutes_check" CHECK ((("wait_time_grace_minutes" >= 0) AND ("wait_time_grace_minutes" <= 10))),
    CONSTRAINT "dispatch_settings_wait_time_max_minutes_check" CHECK ((("wait_time_max_minutes" >= 1) AND ("wait_time_max_minutes" <= 60))),
    CONSTRAINT "dispatch_settings_wait_time_rate_per_min_minor_check" CHECK (("wait_time_rate_per_min_minor" >= 0))
);


ALTER TABLE "rides"."dispatch_settings" OWNER TO "postgres";


COMMENT ON TABLE "rides"."dispatch_settings" IS 'DEPRECATED: Use matching.policies for dispatch configuration. This table is retained for backward compatibility during matching brain rollout. Will be removed after stable production operation.';



COMMENT ON COLUMN "rides"."dispatch_settings"."independent_only_matching" IS 'When true, only independent drivers receive offers and can go online for Roam passenger dispatch.';



COMMENT ON COLUMN "rides"."dispatch_settings"."max_matching_duration_minutes" IS 'Auto-cancel matching rides older than this (system, cancel_reason matching_timeout).';



COMMENT ON COLUMN "rides"."dispatch_settings"."wait_time_grace_minutes" IS 'Minutes after driver arrival before wait time charges begin (default 2)';



COMMENT ON COLUMN "rides"."dispatch_settings"."wait_time_rate_per_min_minor" IS 'Per-minute rate for wait time in minor units (default 50 JMD cents)';



COMMENT ON COLUMN "rides"."dispatch_settings"."wait_time_charge_enabled" IS 'Whether to charge riders for wait time (disabled by default for rollout)';



COMMENT ON COLUMN "rides"."dispatch_settings"."wait_time_max_minutes" IS 'Maximum wait time before system auto-cancels (default 15 minutes)';



COMMENT ON COLUMN "rides"."dispatch_settings"."pin_verification_enabled" IS 'Enable PIN generation and display for rides (feature flag)';



COMMENT ON COLUMN "rides"."dispatch_settings"."pin_verification_required_for_start" IS 'When enabled, driver cannot start trip without entering correct PIN';



COMMENT ON COLUMN "rides"."dispatch_settings"."toll_detection_enabled" IS 'Enable real-time toll detection via geofence crossing during trips';



COMMENT ON COLUMN "rides"."dispatch_settings"."toll_geofence_radius_m" IS 'Radius around toll plaza for geofence detection (default 100m)';



COMMENT ON COLUMN "rides"."dispatch_settings"."route_toll_estimation_enabled" IS 'When enabled, fare quotes use route polyline intersection with toll plazas instead of static fare-rule estimated_tolls_minor';



COMMENT ON COLUMN "rides"."dispatch_settings"."roam_platform_fee_bps" IS 'Roam take-rate in basis points (100 = 1%). Tips excluded. Default 0.';



COMMENT ON COLUMN "rides"."dispatch_settings"."toll_round_trip_cooldown_ms" IS 'Min ms between charging the same plaza again on one trip (round-trip / dwell guard).';



