    "arrival_dwell_seconds",
    "max_speed_mps_for_arrival",
    "auto_en_route_on_accept",
    "auto_arrive_enabled",
    "auto_complete_suggest_enabled",
    "no_show_cancel_minutes",
    "gps_max_accuracy_m_for_arrival",
    "no_show_auto_cancel_enabled",
