CREATE OR REPLACE VIEW "rides"."rider_directory_stats" AS
 SELECT "rider_user_id",
    ("count"(*))::integer AS "total_trips",
    ("count"(*) FILTER (WHERE ("status" = 'completed'::"text")))::integer AS "completed_trips",
    ("count"(*) FILTER (WHERE ("status" = 'cancelled'::"text")))::integer AS "cancelled_trips",
    "max"("created_at") AS "last_ride_at",
    (COALESCE("sum"(COALESCE("fare_final_minor", "fare_estimate_minor")), (0)::numeric))::bigint AS "lifetime_spend_minor"
   FROM "rides"."ride_requests"
  GROUP BY "rider_user_id";


ALTER VIEW "rides"."rider_directory_stats" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."rides_rider_directory_stats" WITH ("security_invoker"='true') AS
 SELECT "rider_user_id",
    "total_trips",
    "completed_trips",
    "cancelled_trips",
    "last_ride_at",
    "lifetime_spend_minor"
   FROM "rides"."rider_directory_stats";


ALTER VIEW "public"."rides_rider_directory_stats" OWNER TO "postgres";


