    CONSTRAINT "brain_policies_same_day_pad_days_check" CHECK ((("same_day_pad_days" >= 0) AND ("same_day_pad_days" <= 3))),
    CONSTRAINT "brain_policies_variance_threshold_check" CHECK (("variance_threshold" >= (0)::numeric)),
