CREATE OR REPLACE VIEW "public"."week_fuel_fills" AS
 SELECT "organization_id",
    "vehicle_id",
    "date" AS "fill_date",
    (NULLIF(("payload_json" ->> 'odometer'::"text"), ''::"text"))::numeric AS "odometer",
    "max"("amount") AS "amount",
    "max"("liters") AS "litres",
    "max"("id") FILTER (WHERE (COALESCE("type", ("payload_json" ->> 'type'::"text")) = 'Card_Transaction'::"text")) AS "card_tx_id",
    "max"("id") FILTER (WHERE (COALESCE("type", ("payload_json" ->> 'type'::"text")) = ANY (ARRAY['Manual_Entry'::"text", 'Fuel_Manual_Entry'::"text"]))) AS "manual_entry_id"
   FROM "fleet"."fuel_entries" "e"
  WHERE ((COALESCE(("payload_json" ->> 'importSource'::"text"), ("payload_json" ->> 'entrySource'::"text"), ''::"text") <> ALL (ARRAY['jaa_raw'::"text", 'jaa_statement_details'::"text", 'fuel_statement'::"text"])) AND ("amount" > (0)::numeric))
  GROUP BY "organization_id", "vehicle_id", "date", (NULLIF(("payload_json" ->> 'odometer'::"text"), ''::"text"))::numeric, "amount";


ALTER VIEW "public"."week_fuel_fills" OWNER TO "postgres";


