CREATE OR REPLACE VIEW "rush_money"."runtime_flags" AS
 SELECT "key",
    COALESCE(( SELECT ("sv"."value" = 'true'::"jsonb")
           FROM "rush_config"."setting_values" "sv"
          WHERE (("sv"."key" = "m"."setting_key") AND ("sv"."scope" = 'platform'::"text") AND ("sv"."scope_id" = '00000000-0000-0000-0000-000000000000'::"uuid"))), "default_on") AS "enabled",
    'Shim over rush_config — do not write'::"text" AS "note"
   FROM ( VALUES ('wallet_live'::"text",'customer.payment.wallet'::"text",true), ('device_linking'::"text",'money.device_linking'::"text",true), ('payout_export'::"text",'money.payout_export'::"text",true), ('risk_controls'::"text",'money.risk_controls'::"text",true)) "m"("key", "setting_key", "default_on");


ALTER VIEW "rush_money"."runtime_flags" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "rush_money"."runtime_flags_retired" (
    "key" "text",
    "enabled" boolean,
    "note" "text"
);


ALTER TABLE "rush_money"."runtime_flags_retired" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_captures_missing_journal" AS
 SELECT "id",
    "amount",
    "order_id"
   FROM "payments"."transactions" "t"
  WHERE (("status" = 'completed'::"text") AND ("order_id" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "rush_money"."journals" "j"
          WHERE ("j"."idempotency_key" = ('capture:'::"text" || ("t"."id")::"text"))))));


ALTER VIEW "rush_money"."v_captures_missing_journal" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_journal_imbalance" AS
 SELECT "journal_id",
    "sum"("amount_minor") AS "sum_minor"
   FROM "rush_money"."lines"
  GROUP BY "journal_id"
 HAVING ("sum"("amount_minor") <> (0)::numeric);


ALTER VIEW "rush_money"."v_journal_imbalance" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_order_clearing_stale" AS
 SELECT "a"."party_id" AS "order_id",
    "a"."balance_minor"
   FROM ("rush_money"."accounts" "a"
     JOIN "delivery"."orders" "o" ON (("o"."id" = "a"."party_id")))
  WHERE (("a"."kind" = 'order_clearing'::"text") AND ("a"."balance_minor" <> 0) AND ("o"."status" = ANY (ARRAY['delivered'::"text", 'completed'::"text", 'cancelled'::"text"])) AND (COALESCE("o"."updated_at", "o"."created_at") < ("now"() - '24:00:00'::interval)));


ALTER VIEW "rush_money"."v_order_clearing_stale" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_orders_missing_settle" AS
 SELECT "id",
    "merchant_id",
    "order_number"
   FROM "delivery"."orders" "o"
  WHERE (("status" = ANY (ARRAY['delivered'::"text", 'completed'::"text"])) AND ("money_state" = ANY (ARRAY['captured'::"text", 'partially_refunded'::"text", 'collected'::"text", 'short_collected'::"text", 'settled'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "rush_money"."journals" "j"
          WHERE ("j"."idempotency_key" = ('settle:'::"text" || ("o"."id")::"text"))))));


ALTER VIEW "rush_money"."v_orders_missing_settle" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_party_held" AS
 SELECT "a"."party_id",
    ((- COALESCE("sum"("l"."amount_minor"), (0)::numeric)))::bigint AS "held_minor"
   FROM (("rush_money"."lines" "l"
     JOIN "rush_money"."accounts" "a" ON (("a"."id" = "l"."account_id")))
     JOIN "rush_money"."payout_batches" "b" ON (("b"."id" = "l"."payout_batch_id")))
  WHERE (("a"."kind" = 'merchant_payable'::"text") AND ("b"."status" <> ALL (ARRAY['paid'::"text", 'returned'::"text"])))
  GROUP BY "a"."party_id";


ALTER VIEW "rush_money"."v_party_held" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_party_net" AS
 SELECT "party_id",
    "party_type",
    (COALESCE("sum"("balance_minor") FILTER (WHERE ("kind" = 'merchant_payable'::"text")), (0)::numeric))::bigint AS "payable_minor",
    (COALESCE("sum"("balance_minor") FILTER (WHERE ("kind" = 'merchant_receivable'::"text")), (0)::numeric))::bigint AS "receivable_minor",
    ((- COALESCE("sum"("balance_minor") FILTER (WHERE ("kind" = ANY (ARRAY['merchant_payable'::"text", 'merchant_receivable'::"text"]))), (0)::numeric)))::bigint AS "net_owed_minor"
   FROM "rush_money"."accounts" "a"
  WHERE (("party_id" IS NOT NULL) AND ("kind" = ANY (ARRAY['merchant_payable'::"text", 'merchant_receivable'::"text"])))
  GROUP BY "party_id", "party_type";


ALTER VIEW "rush_money"."v_party_net" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_provider_recon_exceptions" AS
 SELECT "id",
    "source",
    "reference",
    "detail",
    "created_at"
   FROM "rush_money"."recon_exceptions"
  WHERE ("resolved_at" IS NULL);


ALTER VIEW "rush_money"."v_provider_recon_exceptions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "rush_money"."v_wallet_drift" AS
 SELECT "a"."id",
    "a"."balance_minor",
    COALESCE("sum"("l"."amount_minor"), (0)::numeric) AS "lines_sum"
   FROM ("rush_money"."accounts" "a"
     LEFT JOIN "rush_money"."lines" "l" ON (("l"."account_id" = "a"."id")))
  WHERE ("a"."kind" = 'customer_wallet'::"text")
  GROUP BY "a"."id", "a"."balance_minor"
 HAVING (("a"."balance_minor")::numeric <> COALESCE("sum"("l"."amount_minor"), (0)::numeric));


ALTER VIEW "rush_money"."v_wallet_drift" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "toll"."settlement_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "legacy_public_id" "uuid",
    "source_type" "text" NOT NULL,
    "source_id" "text" NOT NULL,
    "toll_id" "text" NOT NULL,
