CREATE POLICY "Courier manages own push subscriptions" ON "delivery"."courier_push_subscriptions" USING (("courier_user_id" = "auth"."uid"())) WITH CHECK (("courier_user_id" = "auth"."uid"()));



CREATE POLICY "Couriers can insert own profile" ON "delivery"."courier_profiles" FOR INSERT TO "authenticated" WITH CHECK ((("auth"."uid"() = "user_id") AND ("status" = 'pending'::"text") AND ("onboarding_complete" = false) AND ("background_check_status" IS NULL) AND ("approved_at" IS NULL) AND ("suspended_at" IS NULL) AND ("deactivated_at" IS NULL)));



CREATE POLICY "Couriers can manage own documents" ON "delivery"."courier_documents" USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Couriers can manage own vehicles" ON "delivery"."courier_vehicles" USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Couriers can update own profile" ON "delivery"."courier_profiles" FOR UPDATE TO "authenticated" USING (("auth"."uid"() = "user_id")) WITH CHECK ((("auth"."uid"() = "user_id") AND (NOT ("status" IS DISTINCT FROM ( SELECT "c"."status"
   FROM "delivery"."courier_profiles" "c"
  WHERE ("c"."user_id" = "courier_profiles"."user_id")))) AND (NOT ("background_check_status" IS DISTINCT FROM ( SELECT "c"."background_check_status"
   FROM "delivery"."courier_profiles" "c"
  WHERE ("c"."user_id" = "courier_profiles"."user_id")))) AND (NOT ("approved_at" IS DISTINCT FROM ( SELECT "c"."approved_at"
   FROM "delivery"."courier_profiles" "c"
  WHERE ("c"."user_id" = "courier_profiles"."user_id")))) AND (NOT ("suspended_at" IS DISTINCT FROM ( SELECT "c"."suspended_at"
   FROM "delivery"."courier_profiles" "c"
  WHERE ("c"."user_id" = "courier_profiles"."user_id")))) AND (NOT ("deactivated_at" IS DISTINCT FROM ( SELECT "c"."deactivated_at"
   FROM "delivery"."courier_profiles" "c"
