CREATE POLICY "orders_courier_select" ON "delivery"."orders" FOR SELECT TO "authenticated" USING ((("courier_id" = ( SELECT "auth"."uid"() AS "uid")) OR (("status" = 'ready'::"text") AND ("courier_id" IS NULL) AND (EXISTS ( SELECT 1
   FROM "delivery"."courier_profiles" "cp"
  WHERE (("cp"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("cp"."status" = 'active'::"text")))))));



CREATE POLICY "orders_courier_update" ON "delivery"."orders" FOR UPDATE TO "authenticated" USING ((("courier_id" = ( SELECT "auth"."uid"() AS "uid")) OR (("status" = 'ready'::"text") AND ("courier_id" IS NULL) AND (EXISTS ( SELECT 1
   FROM "delivery"."courier_profiles" "cp"
  WHERE (("cp"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("cp"."status" = 'active'::"text"))))))) WITH CHECK ((("courier_id" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT ("total" IS DISTINCT FROM ( SELECT "o2"."total"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("subtotal" IS DISTINCT FROM ( SELECT "o2"."subtotal"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("tax" IS DISTINCT FROM ( SELECT "o2"."tax"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("tip" IS DISTINCT FROM ( SELECT "o2"."tip"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("discount" IS DISTINCT FROM ( SELECT "o2"."discount"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("platform_fee" IS DISTINCT FROM ( SELECT "o2"."platform_fee"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("delivery_fee" IS DISTINCT FROM ( SELECT "o2"."delivery_fee"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("payment_status" IS DISTINCT FROM ( SELECT "o2"."payment_status"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("merchant_id" IS DISTINCT FROM ( SELECT "o2"."merchant_id"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id")))) AND (NOT ("customer_id" IS DISTINCT FROM ( SELECT "o2"."customer_id"
   FROM "delivery"."orders" "o2"
  WHERE ("o2"."id" = "orders"."id"))))));



