           FROM "delivery"."customers" "c"
          WHERE (("c"."id" = "o"."customer_id") AND ("c"."user_id" = "auth"."uid"()))))) OR (("order_messages"."pair" = ANY (ARRAY['customer_merchant'::"text", 'merchant_courier'::"text", 'support'::"text"])) AND ((EXISTS ( SELECT 1
           FROM "delivery"."merchants" "m"
          WHERE (("m"."id" = "o"."merchant_id") AND ("m"."owner_id" = "auth"."uid"())))) OR (EXISTS ( SELECT 1
           FROM "delivery"."merchant_team_members" "tm"
          WHERE (("tm"."merchant_id" = "o"."merchant_id") AND ("tm"."user_id" = "auth"."uid"()) AND ('orders'::"text" = ANY ("tm"."permissions"))))))) OR (("order_messages"."pair" = ANY (ARRAY['customer_courier'::"text", 'merchant_courier'::"text", 'support'::"text"])) AND ("order_messages"."courier_user_id" IS NOT NULL) AND ("order_messages"."courier_user_id" = "auth"."uid"())))))));



