CREATE POLICY "rides_offers_select" ON "rides"."driver_offers" FOR SELECT TO "authenticated" USING ((("driver_user_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "rides"."ride_requests" "r"
  WHERE (("r"."id" = "driver_offers"."ride_request_id") AND ("r"."rider_user_id" = "auth"."uid"()))))));



CREATE POLICY "rides_requests_passenger_select" ON "rides"."ride_requests" FOR SELECT TO "authenticated" USING ((("rider_user_id" = "auth"."uid"()) OR ("assigned_driver_user_id" = "auth"."uid"()) OR ("passenger_user_id" = "auth"."uid"())));



CREATE POLICY "rides_rider_profiles_own_insert" ON "rides"."rider_profiles" FOR INSERT TO "authenticated" WITH CHECK (("user_id" = "auth"."uid"()));



CREATE POLICY "rides_rider_profiles_own_select" ON "rides"."rider_profiles" FOR SELECT TO "authenticated" USING (("user_id" = "auth"."uid"()));



CREATE POLICY "rides_rider_profiles_own_update" ON "rides"."rider_profiles" FOR UPDATE TO "authenticated" USING (("user_id" = "auth"."uid"())) WITH CHECK ((("user_id" = "auth"."uid"()) AND (NOT ("account_status" IS DISTINCT FROM ( SELECT "r"."account_status"
   FROM "rides"."rider_profiles" "r"
  WHERE ("r"."user_id" = "rider_profiles"."user_id")))) AND (NOT ("suspended_at" IS DISTINCT FROM ( SELECT "r"."suspended_at"
   FROM "rides"."rider_profiles" "r"
  WHERE ("r"."user_id" = "rider_profiles"."user_id")))) AND (NOT ("suspended_by" IS DISTINCT FROM ( SELECT "r"."suspended_by"
   FROM "rides"."rider_profiles" "r"
  WHERE ("r"."user_id" = "rider_profiles"."user_id")))) AND (NOT ("suspended_reason" IS DISTINCT FROM ( SELECT "r"."suspended_reason"
   FROM "rides"."rider_profiles" "r"
  WHERE ("r"."user_id" = "rider_profiles"."user_id"))))));



CREATE POLICY "rides_service_body_types_read" ON "rides"."service_body_types" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "rides_surge_select" ON "rides"."surge_cells" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "rides_vehicle_types_read" ON "rides"."vehicle_types" FOR SELECT TO "authenticated" USING (true);



